// Parachord Desktop App - Electron Version

// Diagnostic log ring buffer — see issue #769.
//
// Every console.log / console.warn / console.info call is appended to a
// fixed-size ring buffer. In dev builds (window.electron.isDev === true)
// the call is also forwarded to the real console so live debugging works
// normally. In packaged prod builds, console.log and console.info are
// routed ONLY to the buffer — no DevTools serialization, no string
// formatting cost. console.warn always passes through (warnings are
// useful even in prod). console.error is unmodified.
//
// The buffer is exposed via window.copyDiagnosticLog() — wired into a
// "Copy Diagnostic Log" button in Settings → About so bug reporters can
// paste a recent-history dump. The buffer holds the last 2000 entries.
//
// IMPORTANT: this block runs BEFORE any other code can call console.log,
// so every subsequent console call is captured. Don't move it.
(() => {
  const MAX_ENTRIES = 2000;
  const buffer = [];
  // Snapshot the originals BEFORE we overwrite them. Order matters: any
  // call site that already captured `console.log` (rare in renderer code,
  // but defensive) keeps the original behavior; new sites get the wrapper.
  const orig = {
    log: console.log.bind(console),
    warn: console.warn.bind(console),
    info: (console.info || console.log).bind(console),
    error: console.error.bind(console),
  };
  // window.electron is set up by preload.js; isDev is synchronous (read
  // from __dirname at preload time). If preload hasn't run yet (test
  // harness, etc.), default to dev mode so logs aren't silently dropped.
  const isDev = (typeof window !== 'undefined' && window.electron) ? !!window.electron.isDev : true;

  const push = (level, args) => {
    buffer.push({ t: Date.now(), level, args });
    if (buffer.length > MAX_ENTRIES) buffer.shift();
  };

  console.log = (...args) => { push('log', args); if (isDev) orig.log(...args); };
  console.info = (...args) => { push('info', args); if (isDev) orig.info(...args); };
  // warn always passes through — even in prod, warnings should surface
  // when DevTools is open or when the OS log is being captured.
  console.warn = (...args) => { push('warn', args); orig.warn(...args); };
  // error: never wrap, never silence. Errors are signal at any tier.

  // Format a buffer entry for clipboard / file dump. JSON-stringifies
  // object args so structured state survives the round-trip.
  const formatArg = (a) => {
    if (a == null) return String(a);
    if (typeof a === 'string') return a;
    if (a instanceof Error) return `${a.name}: ${a.message}\n${a.stack || ''}`;
    try { return JSON.stringify(a); } catch { return String(a); }
  };

  // Dump the buffer to clipboard. Returns the dump as a string and the
  // entry count, in case a caller wants to also save to file.
  window.copyDiagnosticLog = async () => {
    const lines = buffer.map(e => {
      const ts = new Date(e.t).toISOString();
      const args = e.args.map(formatArg).join(' ');
      return `[${ts}] [${e.level}] ${args}`;
    });
    const header = [
      `Parachord Diagnostic Log`,
      `Captured: ${new Date().toISOString()}`,
      `Entries: ${lines.length}/${MAX_ENTRIES}`,
      `Build: ${isDev ? 'dev' : 'packaged'}`,
      `Platform: ${(typeof window !== 'undefined' && window.electron?.platform) || 'unknown'}`,
      ``.padEnd(60, '-'),
      ``,
    ].join('\n');
    const text = header + lines.join('\n');
    try {
      await navigator.clipboard.writeText(text);
    } catch (err) {
      orig.error('copyDiagnosticLog: clipboard write failed', err);
    }
    return { text, count: lines.length };
  };

  // Expose getter (no clipboard side-effect) for in-app rendering.
  window.getDiagnosticLog = () => buffer.slice();
})();

const { useState, useEffect, useRef, useCallback, useMemo } = React;

// Platform detection: only macOS uses a hidden title bar (titleBarStyle: 'hidden'),
// so only macOS needs the drag class and title bar spacer. Windows and Linux use the
// native title bar with a visible menu bar.
const isMac = window.electron?.platform === 'darwin';

// The one queue every iTunes request goes through (~20 req/min/IP): spacing,
// lanes, and a circuit that answers at once while iTunes is refusing instead
// of grinding through retries (src/renderer/lib/itunes-rate-limiter.js).
window.iTunesRateLimiter = require('./lib/itunes-rate-limiter').createITunesRateLimiter();

// SSRF guard (isPublicHttpUrl), hosted-playlist fetch limits, playlist-URL
// classification (classifyPlaylistUrl / isProviderPlaylistUrl /
// isProviderImportedPlaylist), and buildPlaylistSavePayload live in
// protocol-url.js — loaded by index.html before app.js (window.* exposure,
// jest-requireable; tests/helpers re-export it).

// Album name for a track that may have none on its own record (tracks played
// from search, chat cards, playlists, radio and Last.fm top tracks often
// arrive with album ''): the track's field, else any resolved source's album
// (a placeholder like 'Single' or the service's own name doesn't count),
// else the mapper's canonical release name. Pure; used by the playbar's
// album-art click so it always has something to open.
window.pickAlbumNameForTrack = (track, mapperResult) => {
  const clean = (s) => (typeof s === 'string' ? s.trim() : '');
  if (!track) return '';
  const own = clean(track.album);
  if (own && !isPlaceholderAlbum(own, track.sources)) return own;
  const sources = track.sources && typeof track.sources === 'object' ? Object.values(track.sources) : [];
  for (const s of sources) {
    const a = clean(s && s.album);
    if (a && !isPlaceholderAlbum(a, track.sources) && !s.noMatch) return a;
  }
  return clean(mapperResult && mapperResult.release_name);
};

// Choose which MusicBrainz release-group search result to open for a track's
// album (album-catalog.js's pickReleaseGroupForAlbum: the album's title and
// artist decide, a joint credit written differently by the source counts, and
// a studio edition of that album wins between its editions).
window.pickReleaseGroupForAlbum = (results, artist, title = '') =>
  pickReleaseGroupForAlbum(results, { artist, title });



// Coalesce bursts of per-key state writes into one setState. The whole UI is
// one React component, so every setState re-renders every view; while the
// user scrolls Fresh Drops or Recommendations, per-track source writes and
// per-artist image writes each cost a full render, which is the scroll
// stutter. queue() records an op per key and flushes all of them in one
// apply() after `delayMs`; ops for the same key apply in order, so a
// whole-entry write after a merge replaces, and a merge after a write merges.
// flush() applies pending ops synchronously (call it before a direct write
// that must observe or supersede queued ones).
window.createCoalescedUpdater = (apply, delayMs = 100) => {
  let pending = new Map();
  let timer = null;
  const flush = () => {
    if (timer !== null) { clearTimeout(timer); timer = null; }
    if (pending.size === 0) return;
    const batch = pending;
    pending = new Map();
    apply(batch);
  };
  return {
    queue(key, value, opts) {
      const op = { value, merge: !!(opts && opts.merge) };
      const ops = pending.get(key);
      if (ops) ops.push(op); else pending.set(key, [op]);
      if (opts && opts.immediate) { flush(); return; }
      if (timer === null) timer = setTimeout(flush, delayMs);
    },
    flush,
    pendingCount: () => pending.size
  };
};
// Reduce a key's queued ops onto its previous value (used by apply()).
window.applyCoalescedOps = (previous, ops) => ops.reduce(
  (acc, op) => (op.merge ? { ...(acc === undefined ? (previous || {}) : (acc || {})), ...op.value } : op.value),
  undefined
);

// Hero-header collapse on scroll, with hysteresis and a content guard. Collapse
// past `collapseAt`, expand only back at or under `expandAt`, and never collapse
// when the content is too short to stay scrolled once the header shrinks by
// `headerDelta` (otherwise collapsing clamps scrollTop under expandAt, which
// expands, which re-collapses: a flip-flop that re-renders and re-animates on
// every scroll event). Returns true (collapse), false (expand) or null (no change).
// A Cover Art Archive release-group URL that was written down without ever
// being requested. Fresh Drops used to assign
// `coverartarchive.org/release-group/<id>/front-250` to every release and
// persist it as a cache hit; a release with no CAA art (most brand-new ones)
// then showed the placeholder for 90 days and the iTunes/Deezer fallbacks never
// ran. A verified hit stores the final redirected URL (archive.org), which this
// does not match, so the shape alone identifies the poisoned entries.
window.isUnverifiedCoverArtUrl = (url) =>
  typeof url === 'string' && /^https?:\/\/coverartarchive\.org\/release-group\/[0-9a-f-]{36}\/front(-\d+)?\/?$/i.test(url);

// A release with art from the cache, or with no art. Never a guessed URL: a
// guessed one on the release (persisted by older builds in cache_new_releases)
// or in the cache is treated as missing so the art pass verifies it.
window.hydrateReleaseArt = (release, albumArtCache) => {
  if (release.albumArt && !window.isUnverifiedCoverArtUrl(release.albumArt)) return release;
  const cached = albumArtCache && albumArtCache[release.id];
  if (cached && cached.url && !window.isUnverifiedCoverArtUrl(cached.url)) return { ...release, albumArt: cached.url };
  if (release.albumArt) return { ...release, albumArt: null };
  return release;
};

window.headerCollapseDecision = ({ scrollTop, scrollHeight, clientHeight, collapsed, collapseAt = 100, expandAt = 50, headerDelta = 240, slack = 60 }) => {
  if (!collapsed && scrollTop > collapseAt) {
    const enough = (scrollHeight - clientHeight) > (headerDelta + slack);
    return enough ? true : null;
  }
  if (collapsed && scrollTop <= expandAt) return false;
  return null;
};

// Resolver match validation + minimum confidence threshold.
//
// Canonical source: sync-providers/confidence-scoring.js (loaded by index.html
// before app.js; exposed as window.ConfidenceScoring). The old inline trio —
// plus a third drifted copy inside the resolver pipeline — is gone; one
// source now serves the renderer, jest (tests/helpers re-exports the module),
// and the main process. Cross-platform invariant: the function bodies must
// still match parachord-mobile ResolverModels.kt / ResolverScoring.kt so
// desktop and Android pick the same source for the same track.
const { normalizeStr, validateResolvedTrack, MIN_CONFIDENCE_THRESHOLD } = window.ConfidenceScoring;

// Yield the renderer thread to the browser's idle scheduler. Used by the
// sync push loops (parachord#798) to interleave per-playlist IPCs with user
// input handling, scroll/animation frames, and other React work. Without
// this, a sync touching 50+ playlists × ~250ms per iteration ties up the
// renderer for tens of seconds even though the `await breathe()` already
// yields the event loop — React's commit work that would otherwise be
// scheduled during a sync run gets perpetually deferred behind the next
// iteration's microtask queue. requestIdleCallback explicitly tells the
// browser "let other queued work go first."
//
// The `timeout` ensures sync still makes forward progress when the renderer
// is genuinely busy (active interaction, large reflow). 2000ms is generous
// enough to never feel like sync is stalled, tight enough that a totally-
// pegged renderer doesn't completely block sync.
//
// Falls back to `setTimeout(r, 16)` (~1 frame) on rare platforms where
// requestIdleCallback is unavailable. Current Electron has it natively.
const yieldToIdle = (timeoutMs = 2000) => new Promise(resolve => {
  if (typeof window !== 'undefined' && typeof window.requestIdleCallback === 'function') {
    window.requestIdleCallback(resolve, { timeout: timeoutMs });
  } else {
    setTimeout(resolve, 16);
  }
});

// Debug flags. Render-path / resolution-path logs are gated on these so they
// don't fire dozens-to-hundreds of times per page load in normal operation.
// Flip to true locally when troubleshooting that subsystem; do NOT commit a
// `true` value. See issue #763.
const DEBUG_RESOLUTION = false;


// Extension-aware "this file's format isn't supported" message used by both
// HTML5-audio error handlers (local-file playback + post-play catch blocks).
//
// Chromium decodes FLAC and PCM WAV at every common bit depth and sample
// rate: 16- and 24-bit FLAC from 44.1 to 192 kHz, 32-bit FLAC, multichannel
// FLAC, and 16-bit, 24-bit and 32-bit float WAV all play through the
// local-audio: handler (verified on Electron 39 and 44, parachord#792). An
// earlier version of this message blamed bit depth and told users to
// downsample with ffmpeg, which was wrong advice: a FLAC or WAV that fails
// here is damaged, truncated, or an unusual variant, not "too hi-res".
// AIFF, WMA, ALAC, APE and DSD genuinely have no decoder.

// Subsonic auth is a token+salt in the query string, replayable until the
// password changes. Search must not return those URLs. This drops any an
// older resolve already wrote onto a track or source record so a play does
// not copy them onto the saved queue.


// Exact ISRC → recording-MBID lookup via MusicBrainz core (/ws/2/isrc/{isrc}).
// Mobile parity (parachord-mobile@51c6cc1, design doc
// `docs/plans/2026-06-16-isrc-mbid-fallback.md` in that repo) — added after
// `mapper.listenbrainz.org` returned 502 for 2+ days (2026-06-14/15) and
// scrobble-time MBID enrichment stopped covering Achordion submits even
// for trivially-mappable tracks like "Radiohead – Creep".
//
// MusicBrainz core is independent infrastructure from the LB mapper, so
// /ws/2/isrc/ keeps returning 200s during a mapper outage. ISRC identifies
// the SPECIFIC recording the user streamed — no fuzzy-match risk of
// returning a live/remix variant the way a Lucene title+artist search can.
// Returns the recording MBID or null. ISRC format per spec:
// 2-letter country code + 3-char alphanumeric registrant + 7-digit numeric.
//
// Callers MUST NOT cache this result the same way they cache mapper hits:
// /ws/2/isrc/ returns only the recording itself (no canonical artist/release
// MBIDs, no canonical names), so a cached ISRC-only entry would block a
// richer mapper entry once the mapper recovers (parachord#887).
window.resolveMbidViaIsrc = async (isrc, opts) => {
  if (!isrc || typeof isrc !== 'string') return null;
  const trimmed = isrc.trim().toUpperCase();
  if (!/^[A-Z]{2}[A-Z0-9]{3}\d{7}$/.test(trimmed)) return null;
  try {
    const url = `https://musicbrainz.org/ws/2/isrc/${encodeURIComponent(trimmed)}?fmt=json`;
    const resp = await fetch(url, {
      mbBackground: !!(opts && opts.background),
      headers: {
        'User-Agent': 'Parachord/0.9.3 (https://github.com/Parachord/parachord)',
        'Accept': 'application/json',
      },
    });
    if (!resp.ok) return null;
    const data = await resp.json();
    const recordings = Array.isArray(data?.recordings) ? data.recordings : [];
    if (recordings.length === 0) return null;
    const id = recordings[0]?.id;
    if (typeof id === 'string' && /^[a-f0-9-]{36}$/i.test(id)) return id;
    return null;
  } catch (e) {
    return null;
  }
};

// Pick an ISRC from a track. ISRC is per-recording, not per-service, so
// any valid match anywhere on the track object is authoritative.
//
// Checks top-level `track.isrc` first (where the native MusicKit AM path
// and the iTunes-Search-fallback put it), then walks each
// `track.sources[*].isrc` (where Spotify writes it after parachord#893,
// and where Apple Music's source record carries it because the resolver
// result is spread into the source). Validates the canonical ISRC format
// (2-letter country + 3-char alphanumeric registrant + 7 digits) and
// normalizes (trim + uppercase) before returning.
//
// Returns null when no source carries a usable one. Skips sources with
// `noMatch` set — those are dropped resolutions, not real source links.
//
// Mirrors the achordion.axe `resolveIsrc` helper (parachord#892) — same
// rules so the two stay byte-equivalent across desktop's two ISRC sites.
window.pickTrackIsrc = function(track) {
  if (!track) return null;
  const isValidIsrc = (s) => typeof s === 'string' && /^[A-Z]{2}[A-Z0-9]{3}\d{7}$/.test(s);
  if (typeof track.isrc === 'string' && track.isrc) {
    const norm = track.isrc.trim().toUpperCase();
    if (isValidIsrc(norm)) return norm;
  }
  if (track.sources) {
    for (const id of Object.keys(track.sources)) {
      const s = track.sources[id];
      if (!s || s.noMatch) continue;
      if (typeof s.isrc === 'string' && s.isrc) {
        const norm = s.isrc.trim().toUpperCase();
        if (isValidIsrc(norm)) return norm;
      }
    }
  }
  return null;
};

// Resolve a track to a recording MBID for ListenBrainz love submission.
// Four tiers:
//   1. Cached track.mbid (instant)
//   2. MBID Mapper at mapper.listenbrainz.org (~4ms, broad coverage)
//   3. Exact ISRC → MBID via MusicBrainz core (parachord#887) — runs only
//      when track.isrc is present. Exact-match guarantee (vs tier 4's
//      fuzzy Lucene), and crucially keeps working when the mapper is down
//      (independent infrastructure).
//   4. Direct MusicBrainz recording search (~200-500ms, slower but works
//      when the mapper is down OR hasn't yet indexed a newly-released
//      recording — the "Starting Line – All Them Witches" case where
//      the mapper was returning 502 AND the recording was only days old)
// Returns the MBID string or null. See
// docs/plans/2026-05-03-loved-tracks-scrobbler-push-design.md.
//
// Tier 4 only fires when tiers 2 and 3 both come up empty — safety net
// for transient mapper outages and freshly-released recordings the mapper
// hasn't ingested. pushLoveToScrobblers queues retries when even tier 4
// returns null, so love-pushes that fail today eventually catch up when
// the mapper comes back or MB ingests the new recording.
window.resolveMbidForLove = async (track) => {
  if (track?.mbid && /^[a-f0-9-]{36}$/i.test(track.mbid)) return track.mbid;
  if (!track?.artist || !track?.title) return null;

  // Tier 2: MBID Mapper via mbid-lookup.js, which falls back to the labs
  // acr-lookup dataset while mapper.listenbrainz.org is down (parachord#991).
  // Calling the mapper directly here logged a certificate error on every
  // scrobble and love push for nothing: tiers 3 and 4 picked up the slack
  // but the noise hid real problems.
  try {
    if (typeof window.resolveRecordingMbid === 'function') {
      const { status, result } = await window.resolveRecordingMbid(track.artist, track.title, track.album, { background: true });
      if (status === 'hit' && result.confidence >= 0.7 && /^[a-f0-9-]{36}$/i.test(result.recording_mbid || '')) {
        return result.recording_mbid;
      }
      // Hit below the confidence floor, a miss, or unreachable: fall through
      // to tier 3 (ISRC) and tier 4 (MusicBrainz search).
    }
  } catch (e) {
    // Fall through to tier 3.
  }

  // Tier 3: Exact ISRC → MBID. Fires whenever ISRC is present anywhere
  // on the track — top-level `track.isrc` OR on any `track.sources[*]`.
  // The latter case matters: Spotify (after parachord#893) writes ISRC
  // onto its source record, never to top-level, so a pure-`track.isrc`
  // check would miss Spotify-resolved tracks. SoundCloud / local files /
  // iTunes no-auth search still don't expose ISRC and are filtered out
  // naturally. Runs against MB core, which stays up when the LB mapper
  // doesn't.
  const isrc = window.pickTrackIsrc(track);
  if (isrc) {
    const isrcMbid = await window.resolveMbidViaIsrc(isrc, { background: true });
    if (isrcMbid) {
      console.log(`[resolveMbidForLove] ISRC fallback resolved "${track.artist} – ${track.title}" via ${isrc}`);
      return isrcMbid;
    }
  }

  // Tier 4: Direct MusicBrainz recording search.
  // MB's /ws/2/recording/?query=... returns recordings sorted by Lucene
  // score (0-100). We require ≥ 90, roughly equivalent to the mapper's
  // 0.7 confidence floor — "this is almost certainly the right recording."
  // MB rate-limits to 1 req/sec/IP via User-Agent identification, so we
  // send a real UA per their etiquette policy.
  try {
    // Quote-escape inside the Lucene query to avoid injection / broken
    // syntax on titles or artists with double quotes.
    const escapedArtist = String(track.artist).replace(/"/g, '\\"');
    const escapedTitle = String(track.title).replace(/"/g, '\\"');
    const query = `artist:"${escapedArtist}" AND recording:"${escapedTitle}"`;
    const url = `https://musicbrainz.org/ws/2/recording/?query=${encodeURIComponent(query)}&fmt=json&limit=3`;
    const resp = await fetch(url, {
      mbBackground: true,
      headers: {
        'User-Agent': 'Parachord/0.9.3 (https://github.com/Parachord/parachord)',
        'Accept': 'application/json',
      },
    });
    if (!resp.ok) return null;
    const data = await resp.json();
    const recordings = Array.isArray(data?.recordings) ? data.recordings : [];
    if (recordings.length === 0) return null;
    const top = recordings[0];
    if (typeof top.score === 'number' && top.score >= 90 && /^[a-f0-9-]{36}$/i.test(top.id || '')) {
      console.log(`[resolveMbidForLove] MB fallback found MBID for "${track.artist} – ${track.title}" (score ${top.score})`);
      return top.id;
    }
  } catch (e) {
    // MB down or rate-limited — return null; caller's retry queue will try again.
  }

  return null;
};

// Resolve a recording MBID to names for the loved-tracks import
// (parachord#1071): ListenBrainz feedback whose MBID the mapping cache
// doesn't know carries no track_metadata, so the import resolves names from
// the recording itself. `/ws/2/recording/{mbid}?inc=artist-credits+releases`
// through the app's wrapped fetch on the background lane (the ~1.1s MusicBrainz
// spacing — a big library of metadata-less loves takes minutes, which #1071
// accepts; the button shows a "Looking up names…" phase). Artist-credit
// joinphrases are kept so "Simon & Garfunkel" doesn't come back as
// "SimonGarfunkel", and the FIRST release's title is the album. On a merged
// MBID MusicBrainz answers with the target recording, so `data.id` replaces
// the stale MBID the candidate carried. No User-Agent header: Chromium strips
// it from renderer fetches anyway, and the main process stamps the canonical
// `Parachord/<version>` on every MetaBrainz request.
//
// Returns { status: 'ok', artist, title, album, mbid } | { status: 'missing' }
// (the recording is gone: a real 404 or 400, or no usable names) | { status:
// 'transient' } (throttled or unreachable after the fetch layer's retries —
// the caller counts that differently and holds the cursor, because a missed
// recording and an unreachable server must not read the same). Never throws.
window.lookupRecordingTitle = async (mbid) => {
  if (!mbid || !/^[a-f0-9-]{36}$/i.test(mbid)) return { status: 'missing' };
  try {
    const url = `https://musicbrainz.org/ws/2/recording/${encodeURIComponent(mbid)}?fmt=json&inc=artist-credits+releases`;
    const resp = await fetch(url, {
      mbBackground: true,
      headers: {
        'Accept': 'application/json',
      },
    });
    if (resp.status === 404 || resp.status === 400) return { status: 'missing' };
    if (!resp.ok) return { status: 'transient' };
    const data = await resp.json();
    const title = typeof data?.title === 'string' ? data.title.trim() : '';
    const credit = Array.isArray(data?.['artist-credit']) ? data['artist-credit'] : [];
    let artist = '';
    for (const c of credit) {
      if (c?.name) artist += c.name;
      if (c?.joinphrase) artist += c.joinphrase;
    }
    artist = artist.trim();
    const releases = Array.isArray(data?.releases) ? data.releases : [];
    const album = typeof releases[0]?.title === 'string' ? releases[0].title.trim() : '';
    const resolvedMbid = /^[a-f0-9-]{36}$/i.test(data?.id || '') ? data.id : mbid;
    if (!title || !artist) return { status: 'missing' };
    return { status: 'ok', artist, title, album, mbid: resolvedMbid };
  } catch (e) {
    return { status: 'transient' };
  }
};

// Resolve an album to a release MBID via the MBID Mapper, given the artist
// and any recording from the album. Achordion's entity-link endpoint
// accepts release MBIDs and maps them to the canonical release-group page
// server-side, so this is sufficient for share-link generation. The mapper
// is recording-keyed (no album-name lookup), so we feed it any track from
// the album and read the `release_mbid` field off the response. Used by
// publishCollectionSmartLink as a fallback when none of the upstream data
// shapes (context-menu data, share-dropdown release object) carries an MBID.
window.resolveAlbumMbidViaMapper = async (artist, anyRecordingTitle) => {
  if (!artist || !anyRecordingTitle) return null;
  try {
    const url = `https://mapper.listenbrainz.org/mapping/lookup?artist_credit_name=${encodeURIComponent(artist)}&recording_name=${encodeURIComponent(anyRecordingTitle)}`;
    const resp = await fetch(url);
    if (!resp.ok) return null;
    const data = await resp.json();
    if (data?.confidence >= 0.7 && /^[a-f0-9-]{36}$/i.test(data.release_mbid || '')) {
      return data.release_mbid;
    }
  } catch (e) { /* mapper down or rate-limited */ }
  return null;
};

// Decode a base64 string as UTF-8 → JSON. The naive
// `JSON.parse(atob(s))` is wrong for any payload containing non-ASCII
// characters: atob returns a Latin-1 binary string, so UTF-8 sequences
// like the U+2019 right single quote (bytes E2 80 99) get parsed as the
// three Latin-1 chars `â€™` — visible as mangled titles in the queue.
// Routes the bytes through TextDecoder('utf-8') first to round-trip
// non-ASCII text correctly. Throws on invalid base64 or invalid JSON.

// `createLimiter` and `wrapResolverSearchesWithLimiter` live in
// resolver-limiter.js (loaded via <script> ahead of app.js in index.html)
// and are exposed as `window.createLimiter` /
// `window.wrapResolverSearchesWithLimiter`. We instantiate the two
// limiters this file uses below, and reference the wrap helper at every
// resolver-load site.

// Global rate limiter for native MusicKit catalog calls (api.music.apple.com).
// Apple throttles /v1/catalog/{storefront}/search aggressively when fan-out is
// high — e.g. background source enrichment for a 200-track queue used to fire
// 200 parallel searches and hit a 429 cliff that also broke playback (because
// /v1/catalog/songs/{id} fetches behind musicKit.play() got throttled too).
// Cap concurrency, min-gap between starts, and back off on transient errors.
window.nativeMusicKitLimiter = window.createLimiter({
  name: 'nativeMusicKitLimiter',
  maxConcurrency: 3,
  minGapMs: 150,        // ~6-7 req/sec sustained at full concurrency
  cooldownMs: 8000,     // pause everything after a burst of errors
  errorThreshold: 3,    // consecutive errors before tripping cooldown
  isThrottleError: (err) => {
    const msg = (err?.message || String(err || '')).toLowerCase();
    return msg.includes('429')
      || msg.includes('rate')
      || msg.includes('musicdatarequest')
      || msg.includes('error 1'); // generic MusicKit data-request failure, often transient throttle
  }
});

// MusicBrainz request throttle (parachord#971). MusicBrainz rate-limits at
// 1 request/sec/IP, and MetaBrainz's 2026-08 bot-mitigation blocks IPs that
// burst past it. Our global search fires THREE parallel /ws/2/ queries per
// (debounced) search — artist + release + recording — and ~50 other paths hit
// /ws/2/ too (discography, album lookups, artist page, cover-art release
// search…), all sharing the single per-IP budget. Firing them in parallel
// guarantees 2 of every 3 get 429/503'd, and the callers render a throttled
// response as an empty result set. Rather than thread a limiter through ~55
// call sites, install ONE fetch interceptor: every musicbrainz.org/ws/2/
// request goes through one limiter (starts >=1.1s apart) and retries
// 429/503 and dropped connections with backoff (a longer Retry-After is
// honored); every other request passes straight through to the original
// fetch, untouched.
//
// Two in flight, one of them always free for the foreground (2026-11-01).
// With one permit, a click waited for whatever was already running, however
// slow MusicBrainz was answering: an artist page's lookup sat 4s behind a
// cover search that had started a moment before it. The rate MusicBrainz
