// Global rate limiter for non-AM resolver search fan-out (parachord#797).
// Covers YouTube, SoundCloud, Bandcamp (and any future search-capable
// resolver that hits a CDN-backed search endpoint).
//
// Why a single SHARED limiter across resolvers rather than per-resolver:
// these resolvers share the renderer's network thread pool, the Chromium
// per-origin socket pool (some share CDN origins), and the CPU budget for
// JSON parsing + match validation. Per-resolver limiters at concurrency
// 4 each could blow through 12+ concurrent requests, defeating the point.
//
// What's NOT throttled here:
//   - applemusic: has its own dedicated limiter above (different
//     rate-limit profile)
//   - spotify: has its own per-token budget, not currently a burst issue
//   - localfiles: in-process, no network
//   - Spotify-search-via-/v1/search: covered by Spotify's own rate budget
//
// The 4 concurrency cap + 100ms gap maps to ~10 req/sec sustained at full
// concurrency across the three resolvers combined. That's well below the
// CDN edge thresholds we've seen drop connections (the `net_error -100`
// SSL handshake floods in main-process logs).
window.globalResolverLimiter = window.createLimiter({
  name: 'globalResolverLimiter',
  maxConcurrency: 4,
  minGapMs: 100,
  cooldownMs: 5000,
  errorThreshold: 3,
  isThrottleError: (err) => {
    const msg = (err?.message || String(err || '')).toLowerCase();
    return msg.includes('429')
      || msg.includes('rate limit')
      || msg.includes('connection closed')
      || msg.includes('econnreset')
      || msg.includes('timeout');
  }
});

// The MusicKit developer token. A token saved in Settings (its copy in
// localStorage) comes first, as it always has, while it hasn't expired: a
// user who saved one keeps using it, and the Apple Music sign-in made with
// it. Otherwise the main process picks one (environment > generated at
// launch > saved in Settings, skipping any that has expired;
// main-process/musickit-token.js). An expired saved token used to be used
// anyway, while a fresh generated one sat unused, and MusicKit refused it
// ("Initialized with an expired token").
const { isTokenExpired: isMusicKitTokenExpired } = require('../../main-process/musickit-token');
async function getMusicKitDeveloperToken() {
  const saved = localStorage.getItem('musickit_developer_token') || '';
  if (saved && !isMusicKitTokenExpired(saved)) return saved;
  if (window.electron?.config?.get) {
    try {
      return await window.electron.config.get('MUSICKIT_DEVELOPER_TOKEN') || '';
    } catch (e) {
      console.log('[MusicKit] Could not get the developer token:', e.message);
      return '';
    }
  }
  return '';
}

// Which stored Apple Music user token Apple still accepts (2026-11). Asks
// /v1/me/storefront with each token on hand (the app's copy, the harvested
// sign-in cookie, MusicKit JS's own copy, then `extraTokens`), and adopts the
// first that works as the app's copy in localStorage and electron-store, so a
// working sign-in is never lost behind a dead one. Returns the verdict from
// findWorkingUserToken: ok / rejected (sign in again) / unknown / none.
const AppleMusicUserToken = require('./lib/apple-music-user-token');
async function checkAppleMusicUserToken(developerToken, extraTokens = []) {
  if (!developerToken) return { verdict: 'unknown', token: null, status: null };
  const candidates = AppleMusicUserToken.userTokenCandidates(localStorage, extraTokens);
  const { probeUserToken, probeDeveloperToken } = AppleMusicUserToken.makeAppleProbes(window.fetch.bind(window), developerToken);
  const result = await AppleMusicUserToken.findWorkingUserToken(candidates, probeUserToken, probeDeveloperToken);
  if (result.verdict === 'ok') {
    const current = localStorage.getItem(AppleMusicUserToken.APP_TOKEN_KEY);
    if (result.token !== current) {
      console.log('🍎 Stored Apple Music user token was refused; adopting another token Apple accepts');
      try { localStorage.setItem(AppleMusicUserToken.APP_TOKEN_KEY, result.token); } catch (_e) { /* ignore */ }
      if (window.electron?.store) {
        await window.electron.store.set('applemusic_user_token', result.token).catch(() => {});
      }
    }
  } else if (result.verdict === 'rejected') {
    console.warn(`🍎 Apple refuses every stored Apple Music user token (HTTP ${result.status}); sign-in needed`);
  }
  return result;
}

// The Apple Music plugin's personal recommendations (its getRecommendations):
// GET /v1/me/recommendations with the developer token and the app's user token
// of record (musickit_user_token, see checkAppleMusicUserToken). Narrow on
// purpose: the one account call the plugin needs, never a general proxy.
// Returns Apple's JSON. Throws an error with notReady set when there is no
// developer token, no user token, or Apple refuses every stored token (after
// adopting one it still accepts, if any), so the Recommendations page never
// caches a refusal as "nothing for you"; any other failure throws plainly.
window.appleMusicPersonalRecommendations = async (limit = 30) => {
  const notReady = (code, message) => Object.assign(new Error(message), { notReady: true, code });
  const developerToken = await getMusicKitDeveloperToken();
  if (!developerToken) throw notReady('no-developer-token', 'Apple Music developer token unavailable');
  const n = Math.max(1, Math.min(30, Number(limit) || 30));
  const url = `https://api.music.apple.com/v1/me/recommendations?limit=${n}`;
  const ask = (userToken) => fetch(url, { headers: { Authorization: `Bearer ${developerToken}`, 'Music-User-Token': userToken } });
  let userToken = localStorage.getItem(AppleMusicUserToken.APP_TOKEN_KEY) || '';
  if (!userToken) throw notReady('not-signed-in', 'Not signed in to Apple Music');
  let res = await ask(userToken);
  if (res.status === 401 || res.status === 403) {
    const check = await checkAppleMusicUserToken(developerToken);
    if (check.verdict !== 'ok' || !check.token || check.token === userToken) {
      throw notReady('token-refused', `Apple Music refused the sign-in (HTTP ${res.status})`);
    }
    userToken = check.token;
    res = await ask(userToken);
    if (res.status === 401 || res.status === 403) throw notReady('token-refused', `Apple Music refused the sign-in (HTTP ${res.status})`);
  }
  if (!res.ok) throw new Error(`Apple Music recommendations failed: ${res.status}`);
  return res.json();
};

// MusicKit-enabled Apple Music search wrapper
// Falls back to iTunes API if MusicKit is not configured/authorized
// opts.lane: the resolver lane the plugin's caller asked for ('priority' for a
// play click, 'background' for a cover lookup; see laneRunOptions in
// resolver-limiter.js), applied to the MusicKit and iTunes queues.
window.appleMusicSearchWithMusicKit = async (query, storefront = 'us', limit = 20, opts = {}) => {
  const laneRun = window.laneRunOptions ? window.laneRunOptions({ __lane: opts && opts.lane }) : undefined;
  // 1. Try native MusicKit (macOS) — no developer token needed, uses system Apple Music auth.
  // All calls go through nativeMusicKitLimiter so a parallel fan-out (e.g. background
  // source enrichment for a 200-track queue) can't blow past Apple's catalog rate limit.
  if (window.electron?.musicKit?.search) {
    try {
      const authStatus = await window.electron.musicKit.checkAuth();
      if (authStatus.success && authStatus.authorized) {
        console.log('[AppleMusicSearch] Using native MusicKit for:', query);
        const result = await window.nativeMusicKitLimiter.run(
          () => window.electron.musicKit.search(query, limit),
          laneRun
        );
        if (result.success && Array.isArray(result.songs)) {
          return result.songs.map(song => ({
            id: 'applemusic-' + song.id,
            title: song.title,
            artist: song.artist,
            album: song.album || 'Unknown Album',
            duration: typeof song.duration === 'number' ? Math.floor(song.duration) : 0,
            sources: ['applemusic'],
            appleMusicId: String(song.id),
            appleMusicUrl: song.url || `https://music.apple.com/${storefront}/song/${song.id}`,
            albumArt: song.artworkUrl || null,
            previewUrl: song.previewUrl || null,
            isrc: song.isrc || null
          }));
        }
      }
    } catch (e) {
      console.log('[AppleMusicSearch] Native MusicKit search failed:', e.message);
    }
  }

  // 2. Try MusicKit JS (cross-platform, needs developer token)
  const musicKitWeb = window.getMusicKitWeb ? window.getMusicKitWeb() : null;
  if (musicKitWeb) {
    let status = musicKitWeb.getAuthStatus();

    // If not configured, try to configure with the developer token
    if (!status.configured) {
      const developerToken = await getMusicKitDeveloperToken();

      // Configure MusicKit if we have a token
      if (developerToken) {
        try {
          console.log('[AppleMusicSearch] Configuring MusicKit');
          await musicKitWeb.configure(developerToken, 'Parachord', '1.0.0');
          status = musicKitWeb.getAuthStatus();
        } catch (configError) {
          console.log('[AppleMusicSearch] Failed to configure MusicKit:', configError.message);
        }
      }
    }

    // Use MusicKit search if configured
    if (status.configured) {
      try {
        console.log('[AppleMusicSearch] Using MusicKit JS for:', query);
        const results = await musicKitWeb.search(query, limit);
        // Map MusicKit results to iTunes-compatible format
        return results.map(song => ({
          id: 'applemusic-' + song.id,
          title: song.title,
          artist: song.artist,
          album: song.album || 'Unknown Album',
          duration: song.duration || 0,
          sources: ['applemusic'],
          appleMusicId: String(song.id),
          appleMusicUrl: song.url || `https://music.apple.com/${storefront}/song/${song.id}`,
          albumArt: song.artworkUrl,
          previewUrl: song.previewUrl || null,
          isrc: song.isrc,
          audioTraits: song.audioTraits || []
        }));
      } catch (mkError) {
        console.log('[AppleMusicSearch] MusicKit JS search failed, falling back to iTunes:', mkError.message);
      }
    }
  }

  // 3. Fall back to iTunes Search API with rate limiting
  console.log('[AppleMusicSearch] Using iTunes API for:', query);
  const response = await window.iTunesRateLimiter.fetch(
    'https://itunes.apple.com/search?term=' + encodeURIComponent(query) +
    '&media=music&entity=song&limit=' + limit + '&country=' + storefront, laneRun);

  if (!response.ok) {
    // Throw, never "no results": an empty answer is cached as Apple Music
    // having no match for the track, and a refusal (403/429, or the limiter's
    // open circuit) says nothing about the catalog. resolveTrack caches
    // nothing for a resolver that threw, so it is asked again later.
    const err = new Error(`iTunes search failed: ${response.status}`);
    err.name = 'AppleMusicSearchUnavailable';
    err.status = response.status;
    throw err;
  }

  const data = await response.json();
  if (!data.results || data.results.length === 0) {
    return [];
  }

  return data.results.map(track => ({
    id: 'applemusic-' + track.trackId,
    title: track.trackName,
    artist: track.artistName,
    album: track.collectionName || '',
    duration: Math.floor((track.trackTimeMillis || 0) / 1000),
    sources: ['applemusic'],
    appleMusicId: String(track.trackId),
    appleMusicUrl: track.trackViewUrl,
    albumArt: track.artworkUrl100 ? track.artworkUrl100.replace('100x100', '500x500') : null,
    previewUrl: track.previewUrl,
    genre: track.primaryGenreName,
    releaseDate: track.releaseDate,
    artistId: track.artistId,
    collectionId: track.collectionId,
    isStreamable: track.isStreamable
  }));
};

// MusicKit-enabled Apple Music song lookup (by catalog ID)
// Falls back to iTunes Lookup API if MusicKit is not available
window.appleMusicLookupSong = async (songId, storefront = 'us') => {
  const musicKitWeb = window.getMusicKitWeb ? window.getMusicKitWeb() : null;
  if (musicKitWeb) {
    let status = musicKitWeb.getAuthStatus();
    if (!status.configured) {
      const developerToken = await getMusicKitDeveloperToken();
      if (developerToken) {
        try {
          await musicKitWeb.configure(developerToken, 'Parachord', '1.0.0');
          status = musicKitWeb.getAuthStatus();
        } catch (e) {}
      }
    }
    if (status.configured && musicKitWeb.musicKit) {
      try {
        console.log('[AppleMusic] Catalog song lookup via MusicKit:', songId);
        const result = await window.nativeMusicKitLimiter.run(
          () => musicKitWeb.musicKit.api.music(`/v1/catalog/${storefront}/songs/${songId}`)
        );
        const song = result.data.data?.[0];
        if (song) {
          return {
            id: 'applemusic-' + song.id,
            title: song.attributes.name,
            artist: song.attributes.artistName,
            album: song.attributes.albumName || '',
            duration: Math.floor((song.attributes.durationInMillis || 0) / 1000),
            sources: ['applemusic'],
            appleMusicId: String(song.id),
            appleMusicUrl: song.attributes.url,
            albumArt: song.attributes.artwork?.url?.replace('{w}', '500').replace('{h}', '500') || null,
            previewUrl: song.attributes.previews?.[0]?.url || null,
            genre: song.attributes.genreNames?.[0],
            isrc: song.attributes.isrc,
            audioTraits: song.attributes.audioTraits || []
          };
        }
      } catch (e) {
        console.log('[AppleMusic] MusicKit song lookup failed, falling back to iTunes:', e.message);
      }
    }
  }
  // Fallback: iTunes Lookup API
  const response = await window.iTunesRateLimiter.fetch('https://itunes.apple.com/lookup?id=' + songId + '&entity=song&country=' + storefront);
  if (!response.ok) return null;
  const data = await response.json();
  const track = data.results?.find(r => r.wrapperType === 'track') || data.results?.[0];
  if (!track) return null;
  return {
    id: 'applemusic-' + track.trackId,
    title: track.trackName,
    artist: track.artistName,
    album: track.collectionName || '',
    duration: Math.floor((track.trackTimeMillis || 0) / 1000),
    sources: ['applemusic'],
    appleMusicId: String(track.trackId),
    appleMusicUrl: track.trackViewUrl,
    albumArt: track.artworkUrl100 ? track.artworkUrl100.replace('100x100', '500x500') : null,
    previewUrl: track.previewUrl,
    genre: track.primaryGenreName
  };
};

// MusicKit-enabled Apple Music album lookup (by catalog ID)
// Falls back to iTunes Lookup API if MusicKit is not available
window.appleMusicLookupAlbum = async (albumId, storefront = 'us') => {
  const musicKitWeb = window.getMusicKitWeb ? window.getMusicKitWeb() : null;
  if (musicKitWeb) {
    let status = musicKitWeb.getAuthStatus();
    if (!status.configured) {
      const developerToken = await getMusicKitDeveloperToken();
      if (developerToken) {
        try {
          await musicKitWeb.configure(developerToken, 'Parachord', '1.0.0');
          status = musicKitWeb.getAuthStatus();
        } catch (e) {}
      }
    }
    if (status.configured && musicKitWeb.musicKit) {
      try {
        console.log('[AppleMusic] Catalog album lookup via MusicKit:', albumId);
        const result = await window.nativeMusicKitLimiter.run(
          () => musicKitWeb.musicKit.api.music(
            `/v1/catalog/${storefront}/albums/${albumId}`,
            { include: 'tracks' }
          )
        );
        const album = result.data.data?.[0];
        if (album) {
          const albumArt = album.attributes.artwork?.url?.replace('{w}', '500').replace('{h}', '500') || null;
          const albumAudioTraits = album.attributes.audioTraits || [];
          const tracks = (album.relationships?.tracks?.data || []).map((song, idx) => ({
            id: 'applemusic-' + song.id,
            title: song.attributes.name,
            artist: song.attributes.artistName,
            album: album.attributes.name,
            duration: Math.floor((song.attributes.durationInMillis || 0) / 1000),
            sources: ['applemusic'],
            appleMusicId: String(song.id),
            appleMusicUrl: song.attributes.url,
            albumArt: albumArt,
            previewUrl: song.attributes.previews?.[0]?.url || null,
            trackNumber: song.attributes.trackNumber || (idx + 1),
            discNumber: song.attributes.discNumber || 1,
            audioTraits: song.attributes.audioTraits || albumAudioTraits
          }));
          tracks.sort((a, b) => a.discNumber !== b.discNumber ? a.discNumber - b.discNumber : a.trackNumber - b.trackNumber);
          return {
            id: 'applemusic-album-' + albumId,
            name: album.attributes.name,
            artist: album.attributes.artistName,
            albumArt: albumArt,
            releaseDate: album.attributes.releaseDate,
            trackCount: album.attributes.trackCount || tracks.length,
            tracks: tracks,
            url: album.attributes.url
          };
        }
      } catch (e) {
        console.log('[AppleMusic] MusicKit album lookup failed, falling back to iTunes:', e.message);
      }
    }
  }
  // Fallback: iTunes Lookup API
  const response = await window.iTunesRateLimiter.fetch('https://itunes.apple.com/lookup?id=' + albumId + '&entity=song&limit=200&country=' + storefront);
  if (!response.ok) return null;
  const data = await response.json();
  if (!data.results || data.results.length === 0) return null;
  const albumInfo = data.results.find(r => r.wrapperType === 'collection');
  const trackResults = data.results.filter(r => r.wrapperType === 'track');
  const tracks = trackResults.map(track => ({
    id: 'applemusic-' + track.trackId,
    title: track.trackName,
    artist: track.artistName,
    album: track.collectionName,
    duration: Math.floor((track.trackTimeMillis || 0) / 1000),
    sources: ['applemusic'],
    appleMusicId: String(track.trackId),
    appleMusicUrl: track.trackViewUrl,
    albumArt: track.artworkUrl100 ? track.artworkUrl100.replace('100x100', '500x500') : null,
    previewUrl: track.previewUrl,
    trackNumber: track.trackNumber,
    discNumber: track.discNumber
  }));
  tracks.sort((a, b) => a.discNumber !== b.discNumber ? a.discNumber - b.discNumber : a.trackNumber - b.trackNumber);
  return {
    id: 'applemusic-album-' + albumId,
    name: albumInfo ? albumInfo.collectionName : 'Unknown Album',
    artist: albumInfo ? albumInfo.artistName : (tracks[0] ? tracks[0].artist : 'Unknown Artist'),
    albumArt: albumInfo?.artworkUrl100 ? albumInfo.artworkUrl100.replace('100x100', '500x500') : null,
    releaseDate: albumInfo ? albumInfo.releaseDate : null,
    trackCount: albumInfo ? albumInfo.trackCount : tracks.length,
    tracks: tracks
  };
};

// MusicKit-enabled Apple Music album search, for applemusic.axe's searchAlbums
// (the album pages' catalog fallback). iTunes Search lags new releases by days
// or weeks, so the catalog answers first. Returns null when MusicKit isn't
// available or the request fails, and the plugin then asks iTunes itself.
window.appleMusicSearchAlbumsWithMusicKit = async (term, storefront = 'us', limit = 10) => {
  const musicKitWeb = window.getMusicKitWeb ? window.getMusicKitWeb() : null;
  if (!musicKitWeb) return null;
  let status = musicKitWeb.getAuthStatus();
  if (!status.configured) {
    const developerToken = await getMusicKitDeveloperToken();
    if (developerToken) {
      try {
        await musicKitWeb.configure(developerToken, 'Parachord', '1.0.0');
        status = musicKitWeb.getAuthStatus();
      } catch (e) {}
    }
  }
  if (!status.configured || !musicKitWeb.musicKit) return null;
  try {
    console.log('[AppleMusic] Catalog album search via MusicKit:', term);
    const result = await window.nativeMusicKitLimiter.run(
      () => musicKitWeb.musicKit.api.music(
        `/v1/catalog/${storefront}/search`,
        { types: 'albums', term, limit: Math.min(limit, 25) }
      )
    );
    const albums = result.data.results?.albums?.data || [];
    return albums
      .filter(a => a.attributes?.name && a.attributes?.url)
      .map(a => ({
        id: 'applemusic-album-' + a.id,
        name: a.attributes.name,
        artist: a.attributes.artistName || '',
        albumArt: a.attributes.artwork?.url?.replace('{w}', '500').replace('{h}', '500') || null,
        releaseDate: a.attributes.releaseDate || null,
        trackCount: a.attributes.trackCount || null,
        url: a.attributes.url
      }));
  } catch (e) {
    console.log('[AppleMusic] MusicKit album search failed, falling back to iTunes:', e.message);
    return null;
  }
};

// MusicKit-enabled Apple Music playlist lookup (by catalog playlist ID)
window.appleMusicLookupPlaylist = async (playlistId, storefront = 'us') => {
  const musicKitWeb = window.getMusicKitWeb ? window.getMusicKitWeb() : null;
  if (!musicKitWeb) return null;

  let status = musicKitWeb.getAuthStatus();
  if (!status.configured) {
    const developerToken = await getMusicKitDeveloperToken();
    if (developerToken) {
      try {
        await musicKitWeb.configure(developerToken, 'Parachord', '1.0.0');
        status = musicKitWeb.getAuthStatus();
      } catch (e) {}
    }
  }

  if (!status.configured || !musicKitWeb.musicKit) return null;

  try {
    console.log('[AppleMusic] Catalog playlist lookup via MusicKit:', playlistId);
    const result = await musicKitWeb.musicKit.api.music(
      `/v1/catalog/${storefront}/playlists/${playlistId}`,
      { include: 'tracks' }
    );
    const playlist = result.data.data?.[0];
    if (!playlist) return null;

    const playlistArt = playlist.attributes.artwork?.url?.replace('{w}', '500').replace('{h}', '500') || null;
    const curatorName = playlist.attributes.curatorName || '';

    // Get all tracks — the initial response includes the first page
    let allTracks = playlist.relationships?.tracks?.data || [];

    // Paginate if there are more tracks
    let nextUrl = playlist.relationships?.tracks?.next;
    while (nextUrl) {
      try {
        const pageResult = await musicKitWeb.musicKit.api.music(nextUrl);
        const pageTracks = pageResult.data.data || [];
        allTracks = allTracks.concat(pageTracks);
        nextUrl = pageResult.data.next || null;
        if (nextUrl) {
          await new Promise(resolve => setTimeout(resolve, 100));
        }
      } catch (e) {
        console.log('[AppleMusic] Playlist pagination error:', e.message);
        break;
      }
    }

    const tracks = allTracks.map(song => ({
      id: 'applemusic-' + song.id,
      title: song.attributes.name,
      artist: song.attributes.artistName,
      album: song.attributes.albumName,
      duration: Math.floor((song.attributes.durationInMillis || 0) / 1000),
      sources: ['applemusic'],
      appleMusicId: String(song.id),
      appleMusicUrl: song.attributes.url,
      // Only the track's OWN artwork — never the playlist's cover (that is
      // `albumArt` on the playlist result below; a playlist cover stamped on
      // a track masquerades as the track's album art — the 4×-tiled-mosaic
      // bug).
      albumArt: song.attributes.artwork?.url?.replace('{w}', '500').replace('{h}', '500') || null,
      previewUrl: song.attributes.previews?.[0]?.url || null
    }));

    return {
      id: 'applemusic-playlist-' + playlistId,
      name: playlist.attributes.name,
      owner: curatorName,
      albumArt: playlistArt,
      trackCount: tracks.length,
      tracks: tracks,
      url: playlist.attributes.url
    };
  } catch (e) {
    console.log('[AppleMusic] MusicKit playlist lookup failed:', e.message);
    return null;
  }
};

// Check if MusicKit is currently configured and available (no rate limiting needed)
window.isMusicKitAvailable = () => {
  // Native MusicKit (macOS) doesn't need a developer token
  if (window.electron?.musicKit?.search) return true;
  // MusicKit JS needs developer token
  const musicKitWeb = window.getMusicKitWeb ? window.getMusicKitWeb() : null;
  if (!musicKitWeb) return false;
  const status = musicKitWeb.getAuthStatus();
  return status.configured && !!musicKitWeb.musicKit;
};

