  const authPort = authServerStatus?.port || 8888;

  // Meta Services state (Last.fm, ListenBrainz, etc.)
  const [metaServices, setMetaServices] = useState([]); // Loaded meta service plug-ins
  const metaServicesRef = useRef([]); // Ref for async paths (the recommendations provider list)
  useEffect(() => { metaServicesRef.current = metaServices; }, [metaServices]);
  const [metaServiceConfigs, setMetaServiceConfigs] = useState({}); // { lastfm: { username, apiKey }, listenbrainz: { username, userToken } }

  // ListenBrainz state

  // Scrobbler settings state
  const [scrobblersInitialized, setScrobblersInitialized] = useState(false);
  const [scrobblerConfigs, setScrobblerConfigs] = useState({});
  // Loved-tracks push (opt-in per service). See
  // docs/plans/2026-05-03-loved-tracks-scrobbler-push-design.md.
  const [scrobblerLovePushEnabled, setScrobblerLovePushEnabled] = useState({});
  const scrobblerLovePushEnabledRef = useRef({});
  const lovePushedKeysRef = useRef({}); // { [trackId]: { lastfm?: ts, listenbrainz?: ts | { at, mbid } } }
  const [loveBackfillRunning, setLoveBackfillRunning] = useState({}); // { [service]: boolean }
  const loveBackfillRunningRef = useRef({});
  const [loveBackfillProgress, setLoveBackfillProgress] = useState({}); // { [service]: { done, total } }
  // Loved-tracks IMPORT (parachord#1071): the inbound half of the
  // loved-tracks scrobbler sync. One run per service, manual button in
  // the scrobbler's card; the cursor makes later runs only fetch new loves.
  const [loveImportRunning, setLoveImportRunning] = useState({}); // { [service]: boolean }
  const loveImportRunningRef = useRef({});
  const [loveImportProgress, setLoveImportProgress] = useState({}); // { [service]: { done, total, phase? } }
  const loveImportCursorRef = useRef({}); // { [service]: loved-at seconds — newest seen }
  // In-memory retry queue for love-pushes that failed transiently (mapper
  // 5xx/502, LB API 5xx/429, network errors). Walked by a periodic runner
  // that re-attempts pushLoveToScrobblers on each entry. Max 5 attempts,
  // then drop with a warning log. Not persisted across restarts — that's
  // a deliberate scope choice; the user can hit the backfill button to
  // catch up after a long mapper outage. Entries are auto-removed when
  // pushLoveToScrobblers succeeds for all enabled services on a given
  // track. Map keyed by trackId so re-loving a track doesn't stack
  // entries. parachord (Starting Line incident, 2026-06).
  const loveRetryQueueRef = useRef(new Map()); // Map<trackId, { track, attempts }>
  const [scrobblingEnabled, setScrobblingEnabled] = useState(true);

  const [showUrlImportDialog, setShowUrlImportDialog] = useState(false);
  const [urlImportValue, setUrlImportValue] = useState('');
  // The import dialog's "keep it updated / snapshot" choice for a link.
  const [urlImportMode, setUrlImportMode] = useState('auto');
  // The question asked when a playlist link is dropped or opened from a
  // parachord://import link: { url, isService, sourceLabel, description, resolve }.
  const [updateModeAsk, setUpdateModeAsk] = useState(null);
  const [urlImportLoading, setUrlImportLoading] = useState(false);

  // Collection page state
  const [collectionTab, setCollectionTab] = useState('tracks'); // 'artists' | 'albums' | 'tracks' | 'friends'
  const [collectionHeaderCollapsed, setCollectionHeaderCollapsed] = useState(false);
  const [collectionSearchOpen, setCollectionSearchOpen] = useState(false);
  const [collectionSearch, setCollectionSearch] = useState('');
  const [collectionSort, setCollectionSort] = useState({
    artists: 'alpha-asc',
    albums: 'recent',
    tracks: 'recent',
    friends: 'alpha-asc'
  });

  // Resolver sync settings
  const [resolverSyncSettings, setResolverSyncSettings] = useState({});
  // Services whose last sign-in check definitely failed ({ [id]: true }): the
  // Sync menu shows their switch off ("Signed out"), whatever `enabled` says,
  // since nothing syncs until they sign in again. Fed only by the checks the
  // app already makes (no extra calls); a check that couldn't reach the
  // service changes nothing.
  const [syncSignedOut, setSyncSignedOut] = useState({});
  // A sync service's rate-limit cooldown, { [providerId]: until ms }, for the
  // Sync menu's "Paused until …" (#909). Spotify's comes from its pause and
  // sync breaker (installSpotifyPause's `parachord:spotify-cooldown`); it is
  // cleared when it runs out, so the label goes without a re-check.
  const [syncPausedUntil, setSyncPausedUntil] = useState({});
  useEffect(() => {
    let timer = null;
    const apply = (until) => {
      clearTimeout(timer);
      const left = (Number(until) || 0) - Date.now();
      if (left <= 0) { setSyncPausedUntil(prev => (prev.spotify ? {} : prev)); return; }
      setSyncPausedUntil(prev => (prev.spotify === until ? prev : { ...prev, spotify: until }));
      timer = setTimeout(() => apply(0), Math.min(left + 500, 2147483647));
    };
    const onCooldown = (event) => apply(event && event.detail && event.detail.until);
    apply(window.spotifyCooldownUntil);
    window.addEventListener('parachord:spotify-cooldown', onCooldown);
    return () => { clearTimeout(timer); window.removeEventListener('parachord:spotify-cooldown', onCooldown); };
  }, []);
  const noteSyncAuth = (providerId, authStatus) => {
    if (!authStatus) return;
    let out = null;
    if (authStatus.authenticated) out = false;
    else if (authStatus.status === 401 || authStatus.status === 403 || authStatus.tokenRejected
      || /no token|token configured|not connected/i.test(authStatus.error || '')) out = true;
    if (out === null) return;
    setSyncSignedOut(prev => (!!prev[providerId] === out ? prev : { ...prev, [providerId]: out }));
  };
  const [syncStatus, setSyncStatus] = useState({});
  const pendingSyncSetupRef = useRef(null); // Track pending sync setup after Spotify auth redirect
  const spotifyAuthSucceededAtRef = useRef(0); // Last Spotify auth success; guards the sync flow against re-auth loops (parachord#986)
  const openListenBrainzSettingsRef = useRef(null); // Settings → Plugins, on ListenBrainz (read from stale closures)
  const openSyncSetupModalRef = useRef(null); // Ref for openSyncSetupModal to avoid stale closures


  // Sync setup modal state
  const [syncSetupModal, setSyncSetupModal] = useState({
    open: false,
    providerId: null,
    step: 'options', // 'options' | 'playlists' | 'syncing' | 'complete'
    playlists: [],
    folders: [],
    selectedPlaylists: [],
    playlistFilter: 'all', // 'all' | 'owned' | 'following'
    settings: {
      syncTracks: true,
      syncAlbums: true,
      syncArtists: true,
      syncPlaylists: true
    },
    progress: null,
    results: null,
    error: null
  });

  // Sync status modal state (quick view from collection)
  const [syncStatusModal, setSyncStatusModal] = useState({ open: false });

  // Stop sync confirmation dialog state
  const [stopSyncDialog, setStopSyncDialog] = useState({
    open: false,
    providerId: null
  });

  // Duplicate playlist cleanup state
  const [cleanupDuplicatesState, setCleanupDuplicatesState] = useState({
    loading: false,
    providerId: null
  });

  const handleCleanupDuplicatePlaylists = async (providerId) => {
    setCleanupDuplicatesState({ loading: true, providerId });
    try {
      const result = await window.electron.sync.cleanupDuplicatePlaylists(providerId);
      if (result.success) {
        const ambiguousCount = result.ambiguous?.length || 0;
        const relinkedCount = result.relinked?.length || 0;
        const repairedEmpty = result.repairedEmptyLinks || 0;
        const unsupportedCount = result.unsupported || 0;
        const relinkedShellCount = result.relinkedFromShell || 0;
        const providerName = syncProviderConfig[providerId]?.name || providerId;
        const parts = [];

        if (relinkedCount > 0) {
          parts.push(`Linked ${relinkedCount} orphaned playlist${relinkedCount > 1 ? 's' : ''} to existing ${providerName} copies`);
        }
        if (relinkedShellCount > 0) {
          parts.push(`re-pointed ${relinkedShellCount} local playlist${relinkedShellCount > 1 ? 's' : ''} away from empty ${providerName} shells to populated copies`);
        }
        if (repairedEmpty > 0) {
          parts.push(`flagged ${repairedEmpty} empty ${providerName} playlist${repairedEmpty > 1 ? 's' : ''} to populate on next sync`);
        }
        if (result.deleted > 0) {
          const names = result.groups.map(g => `"${g.name}" (${g.deleted} removed)`).join(', ');
          parts.push(`removed ${result.deleted} duplicate${result.deleted > 1 ? 's' : ''}: ${names}`);
        }
        if (unsupportedCount > 0) {
          const names = (result.unsupportedManualRemoval || []).map(u => `"${u.name}"`).join(', ');
          parts.push(`${unsupportedCount} duplicate${unsupportedCount > 1 ? 's' : ''} (${names}) must be removed manually in the ${providerName} app — its public API doesn't allow playlist deletion`);
        }
        if (ambiguousCount > 0) {
          const ambNames = result.ambiguous.map(a => `"${a.name}"`).join(', ');
          parts.push(`skipped ${ambiguousCount} ambiguous group${ambiguousCount > 1 ? 's' : ''} (${ambNames}) — multiple local playlists linked to different copies`);
        }
        // #937: redundant LB re-imports of followed playlists + the owned
        // Spotify/Apple Music copies they spawned (the followed playlist's real
        // LB mirror is kept). Only the ListenBrainz cleanup runs this phase.
        const reimportDupes = result.reimportDupesRemoved || 0;
        const reimportManual = result.reimportDupesManual || [];
        if (reimportDupes > 0) {
          parts.push(`removed ${reimportDupes} re-import duplicate${reimportDupes > 1 ? 's' : ''} of followed playlists and their owned streaming copies`);
        }
        if (reimportManual.length > 0) {
          parts.push(`${reimportManual.length} re-export ${reimportManual.length > 1 ? 'copies' : 'copy'} (${reimportManual.join(', ')}) must be removed manually in the provider's app`);
        }

        if (parts.length === 0) {
          showToast('No orphaned or duplicate playlists found', 'info');
        } else {
          const tone = ambiguousCount > 0 && result.deleted === 0 && unsupportedCount === 0 && relinkedCount === 0 && repairedEmpty === 0 && relinkedShellCount === 0 ? 'warning' : 'success';
          showToast(parts.join('. '), tone);
        }

        // Reload playlists so UI reflects newly-populated syncedTo / locallyModified flags
        if (relinkedCount > 0 || repairedEmpty > 0 || reimportDupes > 0) {
          try {
            const loaded = await window.electron.playlists.load();
            setPlaylists(prev => {
              const loadedUrls = new Set(loaded.map(p => p.sourceUrl).filter(Boolean));
              const hostedOnly = prev.filter(p => p.sourceUrl && !loadedUrls.has(p.sourceUrl));
              return [...loaded, ...hostedOnly];
            });
          } catch (e) {
            console.warn('[Cleanup] Failed to reload playlists after relink:', e);
          }
        }
      } else {
        console.error('Cleanup failed:', result.error);
        showToast('Couldn’t finish the cleanup. Try again.', 'error');
      }
    } catch (err) {
      console.error('Cleanup failed:', err);
      showToast('Couldn’t finish the cleanup. Try again.', 'error');
    }
    setCleanupDuplicatesState({ loading: false, providerId: null });
  };

  // The welcome tour (#1493): overview screens only; setup is Home's.
  const [firstRunTutorial, setFirstRunTutorial] = useState({
    open: false,
    step: 'welcome' // a screen id from first-run-tutorial.js TOUR_SCREENS
  });
  // Home's getting-started layout (#1493, lib/getting-started.js):
  // { active, played } from the store key 'home_getting_started'; null
  // until the store answers.
  const [homeGettingStarted, setHomeGettingStarted] = useState(null);
  const saveHomeGettingStarted = (next) => {
    setHomeGettingStarted(next);
    if (window.electron?.store) window.electron.store.set('home_getting_started', next);
  };

  // Background sync timer (every 15 minutes)
  // Use a ref so the sync callback always reads the latest settings
  // without re-firing the effect (which would reset the timers).
  const resolverSyncSettingsRef = useRef(resolverSyncSettings);
  useEffect(() => { resolverSyncSettingsRef.current = resolverSyncSettings; }, [resolverSyncSettings]);

  // Per-provider mutex to prevent concurrent playlist creation for the same
  // (local, provider) pair across the background-sync push loop and the
  // post-wizard IIFE push loop. Without this, both paths can load playlists
  // simultaneously, both see a playlist without syncedTo[providerId], and
  // both call sync.createPlaylist on the same provider — producing duplicates.
  //
  // Previously a single boolean ref — too coarse. When one provider's push
  // loop held it (e.g. an LB hosted-mirror push marathon taking minutes due
  // to per-track MBID resolution + clear-and-add), every other provider's
  // playlist phase that fired during that window got skipped entirely.
  // Spotify's Daily Brew snapshot-diff check was starved that way (see
  // parachord#831). The race the mutex actually needs to prevent is
  // per-(local, provider) concurrent create — different providers' push
  // loops touching different remote spaces don't race with each other.
  const playlistSyncInProgressRef = useRef(new Set());

  // Cancel-on-focus infrastructure (parachord#799).
  //
  // `backgroundSyncInFlightRef` tracks which provider IDs currently have an
  // in-flight `sync.start` IPC fired from `runBackgroundSync`. The
  // foreground handler reads this to know which providers to send
  // `sync.cancel` to — the wizard's manual sync path doesn't touch this
  // ref, so wizard syncs are exempt from focus-cancel as designed.
  //
  // `backgroundSyncCancelledRef` is the within-renderer flag that the
  // background sync provider-loop AND its push-loop iterations check
  // between iterations. Foreground sets it true; the next iteration sees
  // it and bails. Reset to false at the start of each new background sync
  // run.
  const backgroundSyncInFlightRef = useRef(new Set());
  const backgroundSyncCancelledRef = useRef(false);

  useEffect(() => {
    const SYNC_INTERVAL = 15 * 60 * 1000; // 15 minutes — timer cadence + default staleness gate
    const BACKGROUND_MIN_STALENESS = 5 * 60 * 1000; // tighter staleness for background-triggered runs
    const BACKGROUND_DELAY = 30 * 1000; // wait 30s after blur before syncing — cancels if user returns
    const INITIAL_DELAY = 60 * 1000; // 60 seconds — let the app fully load first

    const runBackgroundSync = async (opts = {}) => {
      // Reset cancellation state for this run. The foreground handler
      // flips this true to interrupt long-running background syncs —
      // see parachord#799 + `backgroundSyncCancelledRef` declaration.
      backgroundSyncCancelledRef.current = false;
      const minStaleness = typeof opts.minStaleness === 'number' ? opts.minStaleness : SYNC_INTERVAL;
      const currentSettings = resolverSyncSettingsRef.current;
      // Check each enabled provider
      for (const [providerId, settings] of Object.entries(currentSettings)) {
        // Honor cancel-on-focus: skip remaining providers if the user came back.
        if (backgroundSyncCancelledRef.current) {
          console.log('[Sync] Background sync cancelled on foreground — skipping remaining providers');
          break;
        }
        if (settings.enabled) {
          // Skip if last sync was recent (within the staleness threshold for this run)
          if (settings.lastSyncAt && (Date.now() - settings.lastSyncAt) < minStaleness) {
            console.log(`[Sync] Skipping background sync for ${providerId} — last sync was ${Math.round((Date.now() - settings.lastSyncAt) / 60000)}m ago`);
            continue;
          }
          try {
            const authStatus = await window.electron.sync.checkAuth(providerId);
            noteSyncAuth(providerId, authStatus);
            if (authStatus.authenticated) {
              console.log(`[Sync] Starting background sync for ${providerId}`);
              // Track this provider as in-flight so the foreground handler
              // knows to send sync.cancel for it. Cleared in `finally`
              // regardless of how the sync resolves.
              backgroundSyncInFlightRef.current.add(providerId);
              let result;
              try {
                result = await window.electron.sync.start(providerId, { settings });
              } finally {
                backgroundSyncInFlightRef.current.delete(providerId);
              }
              if (result?.cancelled) {
                console.log(`[Sync] ${providerId} sync cancelled mid-flight — stopping run`);
                break;
              }
              if (result.success) {
                if (result.collection) {
                  // Compare incoming collection against current state before updating UI.
                  // If the sync result has significantly fewer tracks, the API likely
                  // returned incomplete results (pagination timeout, rate limit).
                  // Skip the UI update to avoid a visible flicker; the data on disk
                  // was already saved by the sync engine with its mass-removal safeguard.
                  const incoming = {
                    tracks: result.collection.tracks || [],
                    albums: result.collection.albums || [],
                    artists: result.collection.artists || []
                  };
                  setCollectionData(prev => {
                    const netLoss = (prev.tracks?.length || 0) - incoming.tracks.length;
                    const lossRatio = prev.tracks?.length > 0 ? netLoss / prev.tracks.length : 0;

                    if (netLoss > 50 && lossRatio > 0.1) {
                      console.warn(`[Sync] Skipping UI update: sync result has ${incoming.tracks.length} tracks vs current ${prev.tracks?.length || 0} (net loss ${netLoss}, ${Math.round(lossRatio * 100)}%). Likely incomplete API response.`);
                      return prev;
                    }
                    return incoming;
                  });
                }
                // Reload playlists to pick up what the sync pulled (and any
                // conflict it flagged)
                if (settings.syncPlaylists) {
                  try {
                    const loadedPlaylists = await window.electron.playlists.load();
                    // Preserve in-memory hosted playlists not yet persisted to disk
                    setPlaylists(prev => {
                      const loadedUrls = new Set(loadedPlaylists.map(p => p.sourceUrl).filter(Boolean));
                      const hostedOnly = prev.filter(p => p.sourceUrl && !loadedUrls.has(p.sourceUrl));
                      return [...loadedPlaylists, ...hostedOnly];
                    });
                    showPulledOpenPlaylist(loadedPlaylists);
                  } catch (e) {
                    console.warn('[Sync] Failed to reload playlists after background sync:', e);
                  }
                }
              // Auto-sync local playlists to this provider
              // Guard with per-provider mutex to prevent concurrent creation
              // across background + manual sync paths for the same provider.
              // A different provider's in-flight push doesn't gate this one.
              // N-way mutual exclusion (parachord#911): in 'new' mode N-way owns
              // playlist sync, so the legacy push loop stands down. main.js's
              // create/push IPC handlers also gate this as the authoritative
              // chokepoint; skipping here avoids the wasted resolution work.
              const engineMode = await window.electron.store.get('sync_engine_mode');
              if (engineMode === 'new') {
                console.log(`[Sync] sync_engine_mode=new — N-way owns playlists; skipping legacy playlist push for ${providerId}`);
              } else if (playlistSyncInProgressRef.current.has(providerId)) {
                console.log(`[Sync] Playlist sync already in progress for ${providerId}, skipping background playlist sync`);
              } else {
              playlistSyncInProgressRef.current.add(providerId);
              try {
                const allPlaylists = await window.electron.playlists.load();
                // Per-playlist LB re-export opt-in map { localId: ['spotify','applemusic'] }.
                // A `listenbrainz-*` playlist re-exports to streaming ONLY when the
                // user opted it into that provider — see the gate in the create branch.
                const channelOverrides = await window.electron.store.get('sync_playlist_channels') || {};
                let playlistsChanged = false;
                // Track which specific playlists mutated so we save only those
                // at the end. Saving all 142 sequentially used to pinwheel the
                // app for tens of seconds — one .save() IPC per playlist, even
                // for ones we didn't touch.
                const modifiedPlaylistIds = new Set();
                // Inter-IPC delay so a sync of dozens of playlists doesn't
                // monopolize the main process and starve UI-related IPCs of
                // service time. 250ms × ~10 changed playlists = 2.5s spread,
                // which is fine for a 15-min background loop.
                const SYNC_IPC_DELAY_MS = 250;
                const breathe = () => new Promise(r => setTimeout(r, SYNC_IPC_DELAY_MS));

                // LB circuit breaker (parachord#868). After 3 consecutive
                // ListenBrainz write failures in this push-loop run, stop — the
                // LB API is rate-limited or unreachable (each call already
                // retried with backoff via lbRequest), so grinding through the
                // rest only wastes calls. Resume next cycle. Counts LB only;
                // resets on any LB success; other providers are unaffected.
                let lbConsecutiveFailures = 0;
                const noteLbOutcome = (ok) => {
                  if (providerId !== 'listenbrainz') return false;
                  if (ok) { lbConsecutiveFailures = 0; return false; }
                  lbConsecutiveFailures += 1;
                  if (lbConsecutiveFailures >= 3) {
                    console.warn('[Sync] LB circuit breaker tripped (3 consecutive failures) — deferring to next cycle');
                    showToast('ListenBrainz rate-limited or unreachable; will resume next sync cycle', 'warning');
                    return true;
                  }
                  return false;
                };

                for (const playlist of allPlaylists) {
                  // Cancel-on-focus: drop out mid-push if the user returned
                  // (parachord#799). Anything already pushed stays; the
                  // remainder defers to the next sync cycle.
                  if (backgroundSyncCancelledRef.current) {
                    console.log(`[Sync] Push loop cancelled on foreground for ${providerId}`);
                    break;
                  }
                  // Yield to the renderer's idle scheduler before each
                  // iteration so user interactions get responsive frames
                  // even mid-sync. See parachord#798 + the `yieldToIdle`
                  // helper at the top of this file.
                  await yieldToIdle();
                  // Skip playlists that are local-only
                  if (playlist.localOnly) continue;

                  // Skip playlists synced FROM *this* provider — updates flow via
                  // pull, not push, so we don't re-push to the source. Playlists
                  // synced from a *different* provider (e.g. imported from Spotify)
                  // must still be pushable to other providers (e.g. Apple Music),
                  // otherwise multi-provider mirror propagation breaks.
                  //
                  // EXCEPTION — collaborative playlists (e.g. LB-imported playlists
                  // where the local user is a collaborator, not the owner): genuine
                  // local edits MUST round-trip back to the source so other
                  // collaborators see them. Discriminate "real local edits" from
                  // the artificial `locallyModified=true` that handlePull sets for
                  // multi-mirror propagation by comparing `lastModified` against
                  // the source's last syncedAt — handlePull sets both to the same
                  // timestamp so the comparison is false right after a pull; a
                  // subsequent real edit bumps `lastModified` and flips it true.
                  // Same reasoning as the sync banner's push-state check (see
                  // docs/architecture/sync.md "Sync banner's push-state check must discount
                  // pull-induced locallyModified").
                  {
                    const sourceProvider = playlist.syncedFrom?.resolver;
                    if (sourceProvider === providerId) {
                      // Real edits by the tracks fingerprint, never with a
                      // conflict pending (sync-engine/auto-pull.js).
                      if (!shouldPushToSource(playlist, providerId)) continue;
                      // Fall through: push back to source IS warranted (collaborative case).
                    }
                  }

                  // Skip playlists whose ID indicates they originated from this provider
                  // (e.g. "applemusic-p.XXXXX"). Even if syncedFrom was cleared due to
                  // an incomplete API response, we must not re-create these on the same
                  // provider — that would produce duplicates.
                  //
                  // Defense-in-depth twin of the syncedFrom guard above (L~6310). Same
                  // collaborative-push-back exemption applies: if the id implies this
                  // provider but the user has genuine local edits to contribute, let
                  // the push proceed. Without this exemption the id-prefix guard fires
                  // after the syncedFrom refinement and the collaborative path remains
                  // unreachable for imported playlists (e.g. id = `listenbrainz-<mbid>`).
                  {
                    const idImpliesThisProvider = playlist.id?.startsWith(`${providerId}-`);
                    if (idImpliesThisProvider) {
                      // A playlist whose syncedFrom is this provider was decided by
                      // shouldPushToSource above; the timestamp rule here is only for
                      // one whose syncedFrom is missing or points elsewhere.
                      if (playlist.syncedFrom?.resolver !== providerId) {
                        const sourceSyncedAt = playlist.syncSources?.[providerId]?.syncedAt || 0;
                        const hasGenuineLocalEdits = playlist.locallyModified
                          && (playlist.lastModified || 0) > sourceSyncedAt;
                        if (!hasGenuineLocalEdits) continue;
                      }
                      // Fall through: push back to source IS warranted (collaborative case).
                    }
                  }

                  // Skip playlists with pending actions
                  if (playlist.syncedTo?.[providerId]?.pendingAction) continue;

                  const syncInfo = playlist.syncedTo?.[providerId];

                  if (!syncInfo) {
                    // CHANNEL gate (parachord#911). SYNC:
                    // sync-engine/playlist-push-candidate.js channelGateBlocksCreate.
                    // A per-playlist channel override is AUTHORITATIVE — sync only
                    // to the providers the user chose in the Sync menu. With NO
                    // override, only a `listenbrainz-*` playlist is gated from
                    // auto-mirroring to streaming (the no-flood opt-in: enabling
                    // Spotify/AM sync must not push the user's entire pulled LB
                    // library). Already-linked playlists (syncedTo[provider]) are
                    // NOT gated here — they push updates via the `else if
                    // (locallyModified)` branch.
                    {
                      const chOverride = channelOverrides[playlist.id];
                      if (Array.isArray(chOverride)) {
                        if (!chOverride.includes(providerId)) continue;
                      } else if (
                        playlist.id?.startsWith('listenbrainz-')
                        && (providerId === 'spotify' || providerId === 'applemusic')
                      ) {
                        continue;
                      } else if (playlist.id?.startsWith('hosted-') && providerId === 'listenbrainz') {
                        // Hosted XSPF → LB is opt-in (read-only mirror, no MBIDs →
                        // empty create). SYNC: playlist-push-candidate.js channelGateBlocksCreate.
                        continue;
                      }
                    }
                    // LB-specific opt-in. Without this gate, enabling LB sync
                    // would auto-create one LB playlist per non-localOnly local
                    // playlist on first run — potentially 100+ private LB
                    // playlists the user never asked for. Default off; the
                    // wizard exposes a "Push my Parachord playlists to LB"
                    // checkbox to opt in. Spotify/AM are unaffected (their
                    // wizard doesn't render the checkbox and the setting
                    // defaults to true for them, preserving existing behavior).
                    // Already-linked playlists (those with syncedTo[lb]) are
                    // NOT gated here — they still get update pushes via the
                    // `else if (playlist.locallyModified)` branch below.
                    // An explicit per-playlist channel override that INCLUDES
                    // listenbrainz is an intentional opt-in (e.g. the user toggled
                    // LB on for a hosted XSPF in the Sync menu) and bypasses the
                    // global pushLocalPlaylists flood-guard.
                    {
                      const lbOptedInByOverride = Array.isArray(channelOverrides[playlist.id])
                        && channelOverrides[playlist.id].includes('listenbrainz');
                      if (providerId === 'listenbrainz'
                        && currentSettings[providerId]?.pushLocalPlaylists !== true
                        && !lbOptedInByOverride) {
                        continue;
                      }
                    }
                    // Playlist not yet created on this provider — create it
                    console.log(`[Sync] Creating playlist "${playlist.title}" on ${providerId}`);
                    let createOk = false;
                    try {
                      const result = await window.electron.sync.createPlaylist(
                        providerId,
                        playlist.title,
                        playlist.description || '',
                        playlist.tracks || [],
                        playlist.id
                      );
                      if (result.success) {
                        playlist.syncedTo = {
                          ...playlist.syncedTo,
                          [providerId]: {
                            externalId: result.externalId,
                            snapshotId: result.snapshotId,
                            syncedAt: Date.now(),
                            unresolvedTracks: result.unresolvedTracks || [],
                            pendingAction: null
                          }
                        };
                        // Linked to (and pushed to) the playlist's own source.
                        Object.assign(playlist, recordPushToSource(playlist, providerId, { externalId: result.externalId, snapshotId: result.snapshotId, tracks: playlist.tracks || [], now: Date.now() }));
                        playlistsChanged = true;
                        modifiedPlaylistIds.add(playlist.id);
                        createOk = true;
                        console.log(result.linkedToExisting
                          ? `[Sync] Linked playlist "${playlist.title}" to its existing ${providerId} playlist ${result.externalId} (via ${result.linkSource}); nothing created`
                          : `[Sync] Created playlist "${playlist.title}" on ${providerId}: ${result.externalId}`);
                      }
                    } catch (err) {
                      console.warn(`[Sync] Failed to create playlist "${playlist.title}" on ${providerId}:`, err.message);
                    }
                    if (noteLbOutcome(createOk)) break;
                    await breathe();
                  } else if (playlist.locallyModified || shouldPushToSource(playlist, providerId)) {
                    // CHANNEL gate for the EDIT branch (parachord#911). SYNC:
                    // sync-engine/playlist-push-candidate.js channelOverrideExcludes.
                    // An already-linked mirror must STOP receiving edits the moment
                    // the user excludes its provider from the override — even if a
                    // detach hasn't landed yet (this cycle snapshotted allPlaylists
                    // before the user disabled the channel). The override is the
                    // source of truth; without it, existing mirrors keep syncing.
                    {
                      const chOverride = channelOverrides[playlist.id];
                      if (Array.isArray(chOverride) && !chOverride.includes(providerId)) continue;
                    }
                    // Playlist exists remotely and has local changes — push updates
                    console.log(`[Sync] Pushing updates for "${playlist.title}" to ${providerId}`);
                    let pushOk = false;
                    try {
                      // Resolve tracks to provider-specific URIs before pushing
                      let tracksForPush = playlist.tracks || [];
                      try {
                        const resolveResult = await window.electron.sync.resolveTracks(providerId, tracksForPush);
                        if (resolveResult.success) {
                          tracksForPush = resolveResult.resolved;
                          playlist.syncedTo[providerId].unresolvedTracks = resolveResult.unresolved;
                        }
                      } catch (resolveErr) {
                        console.warn(`[Sync] Track resolution failed for "${playlist.title}" on ${providerId}:`, resolveErr.message);
                      }

                      const pushResult = await window.electron.sync.pushPlaylist(
                        providerId,
                        syncInfo.externalId,
                        tracksForPush,
                        { name: playlist.title, description: playlist.description || '' }
                      );
                      if (pushResult?.success) {
                        playlist.syncedTo[providerId] = {
                          ...playlist.syncedTo[providerId],
                          snapshotId: pushResult.snapshotId,
                          syncedAt: Date.now()
                        };
                        // Pushed to the playlist's own source: record the source's new
                        // snapshot and these tracks as agreed, or the next sync reads our
                        // own push as a conflict (sync-engine/auto-pull.js).
                        Object.assign(playlist, recordPushToSource(playlist, providerId, { externalId: syncInfo.externalId, snapshotId: pushResult.snapshotId, tracks: playlist.tracks || [], now: Date.now() }));
                        playlistsChanged = true;
                        modifiedPlaylistIds.add(playlist.id);
                        pushOk = true;
                      } else if (pushResult?.error === 'PLAYLIST_NOT_FOUND' || pushResult?.error?.includes('404')) {
                        // Remote playlist was deleted
                        playlist.syncedTo[providerId].pendingAction = 'remote-deleted';
                        playlistsChanged = true;
                        modifiedPlaylistIds.add(playlist.id);
                        pushOk = true; // definitive outcome, not a rate-limit failure
                        console.warn(`[Sync] Remote playlist "${playlist.title}" was deleted on ${providerId}`);
                      }
                    } catch (err) {
                      if (err.message?.includes('404') || err.message?.includes('Not Found')) {
                        playlist.syncedTo[providerId].pendingAction = 'remote-deleted';
                        playlistsChanged = true;
                        modifiedPlaylistIds.add(playlist.id);
                        pushOk = true; // remote gone — definitive, not a rate-limit failure
                      }
                      console.warn(`[Sync] Failed to push playlist "${playlist.title}" to ${providerId}:`, err.message);
                    }
                    if (noteLbOutcome(pushOk)) break;
                    await breathe();
                  }
                }

                // Reset locallyModified when every outbound mirror is up to
                // date. A provider is "up to date" if the playlist's
                // syncedTo[provider].syncedAt >= lastModified. We only check
                // enabled providers that this playlist actually has a
                // syncedTo entry for — we don't require a pulled-only
                // playlist (syncedFrom but no syncedTo) to gain a syncedTo
                // entry before we can clear the flag.
                if (playlistsChanged) {
                  const enabledProviders = Object.entries(resolverSyncSettingsRef.current)
                    .filter(([, s]) => s.enabled)
                    .map(([id]) => id);

                  for (const playlist of allPlaylists) {
                    if (playlist.locallyModified && playlist.syncedTo) {
                      // Exclude the source provider: we pulled from it, we
                      // don't push to it (see the syncedFrom guard above), so
                      // its syncedTo[].syncedAt will never catch up to
                      // lastModified via the push loop. Keeping it in the
                      // check would leave locallyModified stuck forever.
                      const sourceProvider = playlist.syncedFrom?.resolver;
                      const relevantMirrors = enabledProviders.filter(pid =>
                        playlist.syncedTo[pid]?.externalId && pid !== sourceProvider
                      );
                      if (relevantMirrors.length === 0) {
                        // No outbound mirrors — the flag has no effect, clear
                        // it for consistency.
                        playlist.locallyModified = false;
                        modifiedPlaylistIds.add(playlist.id);
                      } else {
                        const allSynced = relevantMirrors.every(pid =>
                          (playlist.syncedTo[pid]?.syncedAt || 0) >= (playlist.lastModified || 0)
                        );
                        if (allSynced) {
                          playlist.locallyModified = false;
                          modifiedPlaylistIds.add(playlist.id);
                        }
                      }
                    }
                  }

                  // Save only the playlists that actually changed, with a
                  // small breath between writes so the main-process disk-IO
                  // queue doesn't starve UI-related IPCs (the pinwheel
                  // pattern). Previously this loop awaited save() on every
                  // playlist regardless of whether it mutated. Also yields
                  // to the renderer idle scheduler before each save so
                  // user interactions get responsive frames during the
                  // save burst (parachord#798).
                  let saveCount = 0;
                  for (const playlist of allPlaylists) {
                    if (!modifiedPlaylistIds.has(playlist.id)) continue;
                    // Cancel-on-focus also drops out of the save loop
                    // (parachord#799). Already-saved playlists stick;
                    // remaining defer to the next cycle.
                    if (backgroundSyncCancelledRef.current) {
                      console.log(`[Sync] Save loop cancelled on foreground for ${providerId} (saved ${saveCount} so far)`);
                      break;
                    }
                    await yieldToIdle();
                    await window.electron.playlists.save(playlist);
                    saveCount++;
                    if (saveCount % 5 === 0) {
                      await new Promise(r => setTimeout(r, 50));
                    }
                  }
                  console.log(`[Sync] Saved ${saveCount} modified playlist(s) of ${allPlaylists.length} total`);
                  // Preserve in-memory hosted playlists not yet persisted to disk
                  setPlaylists(prev => {
                    const diskIds = new Set(allPlaylists.map(p => p.id));
                    const hostedOnly = prev.filter(p => p.sourceUrl && !diskIds.has(p.id));
                    return [...allPlaylists, ...hostedOnly];
                  });
                }
              } catch (err) {
                console.warn(`[Sync] Local playlist sync failed for ${providerId}:`, err.message);
              } finally {
                playlistSyncInProgressRef.current.delete(providerId);
              }
              } // end mutex guard

              // Push locally-added collection items to this provider
              try {
                const collection = await window.electron.collection.load();
                let collectionChanged = false;

                // Push tracks that have manual source but not this provider
                const unpushedTracks = (collection.tracks || []).filter(t =>
                  t.syncSources?.manual && !t.syncSources?.[providerId] &&
                  (t.spotifyId || t.appleMusicId || t.sources?.spotify?.spotifyId || t.sources?.applemusic?.appleMusicId)
                );

                if (unpushedTracks.length > 0) {
                  // Get provider-specific IDs
                  if (providerId === 'spotify') {
                    const spotifyIds = unpushedTracks
                      .map(t => t.spotifyId || t.sources?.spotify?.spotifyId)
                      .filter(Boolean);
                    if (spotifyIds.length > 0) {
                      const saveResult = await window.electron.sync.saveTracks('spotify', spotifyIds);
                      if (saveResult.success) {
                        console.log(`[Sync] Pushed ${spotifyIds.length} local tracks to Spotify`);
                        // Update syncSources on pushed tracks
                        for (const track of unpushedTracks) {
                          if (track.spotifyId || track.sources?.spotify?.spotifyId) {
                            track.syncSources = { ...track.syncSources, [providerId]: { addedAt: track.addedAt, syncedAt: Date.now() } };
                            collectionChanged = true;
                          }
                        }
                      }
                    }
                  } else if (providerId === 'applemusic') {
                    const amIds = unpushedTracks
                      .map(t => t.appleMusicId || t.sources?.applemusic?.appleMusicId)
                      .filter(Boolean);
                    if (amIds.length > 0) {
                      const saveResult = await window.electron.sync.saveTracks('applemusic', amIds);
                      if (saveResult.success) {
                        console.log(`[Sync] Pushed ${amIds.length} local tracks to Apple Music`);
                        for (const track of unpushedTracks) {
                          if (track.appleMusicId || track.sources?.applemusic?.appleMusicId) {
                            track.syncSources = { ...track.syncSources, [providerId]: { addedAt: track.addedAt, syncedAt: Date.now() } };
                            collectionChanged = true;
                          }
                        }
                      }
                    }
                  }
                }

                // Push albums
                const unpushedAlbums = (collection.albums || []).filter(a =>
                  a.syncSources?.manual && !a.syncSources?.[providerId] &&
                  (a.spotifyId || a.appleMusicId || a.sources?.spotify?.spotifyId || a.sources?.applemusic?.appleMusicId)
                );

                if (unpushedAlbums.length > 0) {
                  if (providerId === 'spotify') {
                    const spotifyIds = unpushedAlbums.map(a => a.spotifyId || a.sources?.spotify?.spotifyId).filter(Boolean);
                    if (spotifyIds.length > 0) {
                      const saveResult = await window.electron.sync.saveAlbums('spotify', spotifyIds);
                      if (saveResult.success) {
                        console.log(`[Sync] Pushed ${spotifyIds.length} local albums to Spotify`);
                        for (const album of unpushedAlbums) {
                          if (album.spotifyId || album.sources?.spotify?.spotifyId) {
                            album.syncSources = { ...album.syncSources, [providerId]: { addedAt: album.addedAt, syncedAt: Date.now() } };
                            collectionChanged = true;
                          }
                        }
                      }
                    }
                  } else if (providerId === 'applemusic') {
                    const amIds = unpushedAlbums.map(a => a.appleMusicId || a.sources?.applemusic?.appleMusicId).filter(Boolean);
                    if (amIds.length > 0) {
                      const saveResult = await window.electron.sync.saveAlbums('applemusic', amIds);
                      if (saveResult.success) {
                        console.log(`[Sync] Pushed ${amIds.length} local albums to Apple Music`);
                        for (const album of unpushedAlbums) {
                          if (album.appleMusicId || album.sources?.applemusic?.appleMusicId) {
                            album.syncSources = { ...album.syncSources, [providerId]: { addedAt: album.addedAt, syncedAt: Date.now() } };
                            collectionChanged = true;
                          }
                        }
                      }
                    }
                  }
                }

                // Push artists (Spotify only — Apple Music doesn't support following)
                if (providerId === 'spotify') {
                  const unpushedArtists = (collection.artists || []).filter(a =>
                    a.syncSources?.manual && !a.syncSources?.spotify &&
                    (a.spotifyId || a.sources?.spotify?.spotifyId)
                  );
                  if (unpushedArtists.length > 0) {
                    const spotifyIds = unpushedArtists.map(a => a.spotifyId || a.sources?.spotify?.spotifyId).filter(Boolean);
                    if (spotifyIds.length > 0) {
                      const followResult = await window.electron.sync.followArtists('spotify', spotifyIds);
                      if (followResult.success) {
                        console.log(`[Sync] Followed ${spotifyIds.length} local artists on Spotify`);
                        for (const artist of unpushedArtists) {
                          if (artist.spotifyId || artist.sources?.spotify?.spotifyId) {
                            artist.syncSources = { ...artist.syncSources, spotify: { addedAt: artist.addedAt, syncedAt: Date.now() } };
                            collectionChanged = true;
                          }
                        }
                      }
                    }
                  }
                }

                if (collectionChanged) {
                  await window.electron.collection.save(collection);
                  setCollectionData(collection);
                }
              } catch (err) {
                console.warn(`[Sync] Background collection push failed for ${providerId}:`, err.message);
              }
              } else {
                console.warn(`[Sync] Background sync for ${providerId} returned unsuccessful:`, result.error);
              }
            }
          } catch (error) {
            console.error(`[Sync] Background sync failed for ${providerId}:`, error);
          }
        }
      }
    };

    // Delay initial sync to let the app fully load and become interactive
    const initialSyncTimeout = setTimeout(() => runBackgroundSync(), INITIAL_DELAY);

    // Set up interval
    const intervalId = setInterval(() => runBackgroundSync(), SYNC_INTERVAL);

    // Background-triggered refresh: when the window LOSES focus, schedule
    // a sync for BACKGROUND_DELAY seconds later. If the user comes back
    // before then, cancel — they didn't actually leave. Net effect: heavy
    // sync work runs while the user is away, never on resume.
    //
    // Rationale: an earlier iteration triggered sync on FOREGROUND, which
    // produced visible pinwheel + CPU spike right when the user wanted the
    // app responsive (~35s of IPC churn for users with hundreds of
    // playlists). User feedback was unambiguous: "I want more work done
    // while I'm not using the app, not when I want it to feel most
    // responsive." Inverted accordingly.
    //
    // Notes:
    //   - The 15-min timer (above) still runs regardless of focus state.
    //     This handler is purely additive: it catches the case where the
    //     user backgrounds the app mid-cycle, so sync can happen during
    //     their absence rather than at the next idle timer tick.
    //   - Per-provider `lastSyncAt < minStaleness` gate inside
    //     runBackgroundSync prevents double-fetching when the timer
    //     already synced recently.
    //   - We DON'T cancel an already-running sync on focus — too risky
    //     (could leave half-written state). We only cancel the *pending*
    //     setTimeout. If the user returns mid-sync, they may still see
    //     residual IPC activity for a few seconds — accept that vs the
    //     complexity of safe cancellation.
    let pendingBackgroundSync = null;
    // parachord#821: gate cancel-on-focus on actual blur → focus transitions.
    // Electron's `browser-window-focus` (the underlying signal behind
    // onForeground) fires for many in-app interactions on macOS Chromium —
    // clicking the sidebar, switching panels, opening DevTools, etc. Without
    // this flag, every such interaction calls sync.cancel on the in-flight
    // background sync, effectively starving sync for any user who actively
    // uses the app while it runs (the reporter on #821 measured 5 focus
    // events in 2 minutes of normal usage). We only want to fire the
    // cancel-on-focus path when the user genuinely returned from elsewhere
    // — i.e. a blur preceded the focus.
    let parachordBlurred = false;
    const handleBackground = () => {
      parachordBlurred = true;
      if (pendingBackgroundSync) clearTimeout(pendingBackgroundSync);
      pendingBackgroundSync = setTimeout(() => {
        pendingBackgroundSync = null;
        runBackgroundSync({ minStaleness: BACKGROUND_MIN_STALENESS });
      }, BACKGROUND_DELAY);
    };
    const handleForeground = () => {
      // Ignore spurious focus events that don't follow a blur (#821). In the
      // not-actually-blurred state there can't be a pending blur-triggered
      // sync (it's set in handleBackground), and there's no "user just
      // returned" semantics to honor on the cancel-in-flight path either.
      if (!parachordBlurred) return;
      parachordBlurred = false;
      // Cancel any pending blur-triggered sync that hasn't fired yet.
      if (pendingBackgroundSync) {
        clearTimeout(pendingBackgroundSync);
        pendingBackgroundSync = null;
      }
      // Cancel any in-flight background sync (parachord#799). The wizard's
      // manual sync path doesn't add to `backgroundSyncInFlightRef`, so
      // user-initiated syncs run to completion regardless of focus state.
      //
      // Two-layer cancellation:
      //   1. Flip the renderer-side ref so the provider loop + push loop
      //      bail at their next iteration check (cheap, no IPC).
      //   2. Fire sync.cancel for each in-flight provider so the main
      //      process can short-circuit its phase-by-phase inbound sync
      //      and save partial progress.
      if (backgroundSyncInFlightRef.current.size > 0) {
        const inFlight = [...backgroundSyncInFlightRef.current];
        backgroundSyncCancelledRef.current = true;
        console.log(`[Sync] Cancelling in-flight background sync on focus: ${inFlight.join(', ')}`);
        for (const pid of inFlight) {
          if (window.electron?.sync?.cancel) {
            window.electron.sync.cancel(pid).catch(() => {});
          }
        }
      }
    };
    if (window.electron?.app?.onBackground) {
      window.electron.app.onBackground(handleBackground);
    }
    if (window.electron?.app?.onForeground) {
      window.electron.app.onForeground(handleForeground);
    }

    return () => {
      clearTimeout(initialSyncTimeout);
      clearInterval(intervalId);
      if (pendingBackgroundSync) clearTimeout(pendingBackgroundSync);
      // No unsubscribe path on app.onForeground/onBackground in preload
      // (multi-listener safe); they detach when the renderer tears down.
    };
  }, []); // Stable effect — reads settings from ref

  // (Slow-trickle cross-resolver enrichment moved past the `cacheLoaded`
  // useState declaration to avoid the deps-array TDZ. See below near L9720.)

  // Friends state
  const [friends, setFriends] = useState([]);
  const [pinnedFriendIds, setPinnedFriendIds] = useState([]);
  const [autoPinnedFriendIds, setAutoPinnedFriendIds] = useState([]); // Friends auto-pinned due to being on-air
  // Hidden friend keys — `${service}:${username_lowercase}` strings for friends
  // the user has explicitly removed. Prevents the next inbound sync pull from
  // re-adding them. Load-bearing for Last.fm (whose friend API is deprecated
  // and can't accept unfollow writes); belt-and-suspenders for ListenBrainz.
  const [hiddenFriendKeys, setHiddenFriendKeys] = useState([]);
  const hiddenFriendKeysRef = useRef([]);
  useEffect(() => { hiddenFriendKeysRef.current = hiddenFriendKeys; }, [hiddenFriendKeys]);
  // Sync in progress flag for manual button UX
  const [friendSyncInProgress, setFriendSyncInProgress] = useState(false);
  const [newlyPinnedFriendIds, setNewlyPinnedFriendIds] = useState(new Set()); // Track newly added friends for animation
  const [movedFriendIds, setMovedFriendIds] = useState(new Set()); // Track friends that moved position for animation
  const [currentFriend, setCurrentFriend] = useState(null);
  const [friendHistoryTab, setFriendHistoryTab] = useState('recent');
  const [friendHistoryData, setFriendHistoryData] = useState({
    recent: [],
    topTracks: [],
    topAlbums: [],
    topArtists: []
  });
  const [friendHistoryPeriod, setFriendHistoryPeriod] = useState('7day');
