  const sortPlaylists = useCallback((items) => {
    const sorted = [...items];
    switch (playlistsSort) {
      case 'added':
        // Sort by addedAt descending (newest first), fallback to createdAt
        return sorted.sort((a, b) => {
          const aTime = Number(a.addedAt) || Number(a.createdAt) || 0;
          const bTime = Number(b.addedAt) || Number(b.createdAt) || 0;
          return bTime - aTime;
        });
      case 'created':
        // Sort by createdAt descending (newest first), fallback to addedAt, then by title for stability
        return sorted.sort((a, b) => {
          const aTime = Number(a.createdAt) || Number(a.addedAt) || 0;
          const bTime = Number(b.createdAt) || Number(b.addedAt) || 0;
          if (aTime !== bTime) return bTime - aTime;
          // Tie-breaker: sort by title alphabetically
          return (a.title || '').localeCompare(b.title || '');
        });
      case 'modified':
        // Sort by lastModified descending, fallback to addedAt
        return sorted.sort((a, b) => {
          const aTime = Number(a.lastModified) || Number(a.addedAt) || 0;
          const bTime = Number(b.lastModified) || Number(b.addedAt) || 0;
          return bTime - aTime;
        });
      case 'alpha-asc': return sorted.sort((a, b) => (a.title || '').localeCompare(b.title || ''));
      case 'alpha-desc': return sorted.sort((a, b) => (b.title || '').localeCompare(a.title || ''));
      default: return sorted;
    }
  }, [playlistsSort]);

  // Filter artist releases by search query
  const filterArtistReleases = useCallback((releases) => {
    if (!artistSearch.trim()) return releases;
    const query = artistSearch.toLowerCase();
    return releases.filter(r => r.title.toLowerCase().includes(query));
  }, [artistSearch]);

  // Sort artist releases
  const sortArtistReleases = useCallback((releases) => {
    const sorted = [...releases];
    switch (artistSort) {
      case 'date-desc': return sorted.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
      case 'date-asc': return sorted.sort((a, b) => (a.date || '').localeCompare(b.date || ''));
      case 'alpha-asc': return sorted.sort((a, b) => a.title.localeCompare(b.title));
      case 'alpha-desc': return sorted.sort((a, b) => b.title.localeCompare(a.title));
      default: return sorted;
    }
  }, [artistSort]);

  // Memoized (constant): a prop of the memo'd ArtistPage, and an array
  // literal rebuilt on every render would change that prop every time.
  const artistSortOptions = useMemo(() => [
    { value: 'date-desc', label: 'Newest first' },
    { value: 'date-asc', label: 'Oldest first' },
    { value: 'alpha-asc', label: 'A–Z' },
    { value: 'alpha-desc', label: 'Z–A' }
  ], []);

  // The release-type filter belongs to one artist. Its default ('all', the
  // complete discography) is set once, when an artist's page starts loading
  // (startReleaseTypeFilterFor, from fetchArtistData and the back button);
  // data arriving afterwards (the services' discography, MusicBrainz's first
  // batch, the end of the load) calls setSmartReleaseTypeFilter, which never
  // overwrites a type the user picked for this artist. It used to reset the
  // filter on every batch, so Singles clicked during a load jumped back to
  // All when the albums landed. Leaving the artist view resets it.
  const releaseTypeFilterOwnerRef = useRef({ artist: null, picked: false });
  const startReleaseTypeFilterFor = useCallback((artistName) => {
    const artist = String(artistName || '').trim().toLowerCase();
    if (releaseTypeFilterOwnerRef.current.artist === artist) return;
    releaseTypeFilterOwnerRef.current = { artist, picked: false };
    setReleaseTypeFilter('all');
  }, []);
  const pickReleaseTypeFilter = useCallback((value) => {
    releaseTypeFilterOwnerRef.current.picked = true;
    setReleaseTypeFilter(value);
  }, []);
  const resetReleaseTypeFilter = useCallback(() => {
    releaseTypeFilterOwnerRef.current = { artist: null, picked: false };
    setReleaseTypeFilter('all');
  }, []);
  const setSmartReleaseTypeFilter = useCallback((releases) => {
    if (releaseTypeFilterOwnerRef.current.picked) return;
    setReleaseTypeFilter('all');
  }, []);

  // Filter and sort charts
  const filterCharts = useCallback((items) => {
    if (!chartsSearch.trim()) return items;
    const query = chartsSearch.toLowerCase();
    return items.filter(c =>
      c.title.toLowerCase().includes(query) ||
      c.artist.toLowerCase().includes(query)
    );
  }, [chartsSearch]);

  // Filter and sort critics picks
  const filterCriticsPicks = useCallback((items) => {
    if (!criticsSearch.trim()) return items;
    const query = criticsSearch.toLowerCase();
    return items.filter(c =>
      c.title.toLowerCase().includes(query) ||
      c.artist.toLowerCase().includes(query)
    );
  }, [criticsSearch]);

  const sortCriticsPicks = useCallback((items) => {
    const sorted = [...items];
    switch (criticsSort) {
      case 'recent': return sorted; // Keep original order (date added)
      case 'artist': return sorted.sort((a, b) => a.artist.localeCompare(b.artist));
      default: return sorted;
    }
  }, [criticsSort]);

  // Filter and sort history
  const filterHistory = useCallback((items) => {
    if (!historySearch.trim()) return items;
    const query = historySearch.toLowerCase();
    return items.filter(t =>
      t.title.toLowerCase().includes(query) ||
      t.artist.toLowerCase().includes(query) ||
      (t.album && t.album.toLowerCase().includes(query))
    );
  }, [historySearch]);

  const sortHistory = useCallback((items) => {
    const sorted = [...items];
    switch (historySort) {
      case 'recent': return sorted; // Keep original order (most recent first)
      case 'artist': return sorted.sort((a, b) => a.artist.localeCompare(b.artist));
      case 'title': return sorted.sort((a, b) => a.title.localeCompare(b.title));
      default: return sorted;
    }
  }, [historySort]);

  // Sort friend history
  const sortFriendHistory = useCallback((items) => {
    const sorted = [...items];
    switch (friendHistorySort) {
      case 'recent': return sorted; // Keep original order (most recent first)
      case 'artist': return sorted.sort((a, b) => a.artist.localeCompare(b.artist));
      case 'title': return sorted.sort((a, b) => a.title.localeCompare(b.title));
      default: return sorted;
    }
  }, [friendHistorySort]);

  // Track when persistent cache is loaded. Moved up beside the local-files
  // hook (its watch-folder effect reads it), which sits above the queue hook
  // that reads it too (its saved-queue effect; its old home sat BELOW
  // deps-array uses of the hook's returned names).
  const [cacheLoaded, setCacheLoaded] = useState(false);

  // Late-function bridges for useLocalFiles: showToast, showConfirmDialog,
  // confirmAsync, enrichTrackWithMbid and fetchArtworkViaMbid are declared
  // below the hook call, so the hook reads them through refs synced in the
  // per-render block beside the engine's (same shape as
  // enrichTracksWithMbidsRef). showToastRef is the engine's too; it moved up
  // from the engine's bridge block.
  const showToastRef = useRef(null);
  const showConfirmDialogRef = useRef(null);
  const confirmAsyncRef = useRef(null);
  const enrichTrackWithMbidRef = useRef(null);
  const fetchArtworkViaMbidRef = useRef(null);

  // Local Files state domain, extracted to src/renderer/hooks/use-local-files.js
  // (parachord#1487). The destructured names are the ones that lived here
  // inline, so no use below changes. Call position: the first render-time
  // read of a returned name is `library` in collectionSongsSorted's deps just
  // below, so the call can sit no lower than this. Its two effects (the scan
  // listeners and the watch-folder load) now run here, ahead of the effects
  // between this line and their old homes; that is safe because neither
  // reads state another effect writes in the same commit, and both only start
  // IPC work whose answers arrive after the commit (the hook's header has the
  // full note). The startup effect that loads the library stays where it was
  // and calls loadLocalFilesLibrary / applyLibraryChanges from here.
  const {
    library, setLibrary,
    libraryFilePathsRef, libraryPathsVersion,
    forgetMissingLocalFile,
    libraryLoading, localLibraryVersion,
    localFilesStats, setLocalFilesStats,
    watchFolders, setWatchFolders,
    isScanning, scanProgress,
    loadLocalFilesLibrary, applyLibraryChanges,
    handleAddWatchFolder, handleRemoveWatchFolder, handleRescanFolder,
    handleRemoveMissingFiles, handleRescanAll,
  } = useLocalFiles({
    cacheLoaded,
    showToastRef,
    showConfirmDialogRef,
    confirmAsyncRef,
    enrichTrackWithMbidRef,
    fetchArtworkViaMbidRef,
  });

  // ID3 Tag Editor state
  const [id3EditorOpen, setId3EditorOpen] = useState(false);
  const [id3EditorTrack, setId3EditorTrack] = useState(null);
  const [id3EditorValues, setId3EditorValues] = useState({
    title: '',
    artist: '',
    album: '',
    trackNumber: '',
    year: ''
  });
  const [id3EditorSaving, setId3EditorSaving] = useState(false);
  const [id3ArtSuggestions, setId3ArtSuggestions] = useState([]);
  const [id3ArtLoading, setId3ArtLoading] = useState(false);
  const [id3SelectedArt, setId3SelectedArt] = useState(null);
  const [id3ArtFetchKey, setId3ArtFetchKey] = useState(''); // Track last fetch to avoid duplicates

  // Add to Playlist panel state
  const [addToPlaylistPanel, setAddToPlaylistPanel] = useState({
    open: false,
    tracks: [], // Tracks to add
    sourceName: '', // Name of source (track title, album name, or playlist name)
    sourceType: '' // 'track', 'album', 'playlist'
  });
  const [selectedPlaylistsForAdd, setSelectedPlaylistsForAdd] = useState([]); // Selected playlist IDs for multi-select
  const [newPlaylistFormOpen, setNewPlaylistFormOpen] = useState(false); // Accordion state for new playlist form
  const [newPlaylistName, setNewPlaylistName] = useState(''); // Input value for new playlist name
  const [draggingTrackForPlaylist, setDraggingTrackForPlaylist] = useState(null); // Track being dragged that could be dropped on playlist
  const [toast, setToast] = useState(null); // { message: string, type: 'success' | 'error' | 'info', action?: { label: string, onClick: () => void } }
  const [collectionData, setCollectionData] = useState({ tracks: [], albums: [], artists: [] });
  const collectionDataRef = useRef(collectionData);
  const [collectionLoading, setCollectionLoading] = useState(true);
  const collectionLoadingRef = useRef(true);

  // Collection → Songs list: the local library merged with collection tracks
  // (deduplicated by id), then filtered and sorted. This used to be built
  // inline in the render, so every state change anywhere in the app (a full
  // re-render, see CLAUDE.md "coalesce bursts") re-merged the whole library,
  // copied every track object and re-sorted it while the tab was open: tens
  // of thousands of objects per render on a big local library. Memoized on
  // its real inputs. Tracks that already have an id are kept as the SAME
  // object, not copied: the MBID/artwork enrichment mutates library tracks in
  // place (enrichTrackWithMbid, enrichLocalTracksWithArtwork), and a memoized
  // copy would keep serving the pre-enrichment fields.
  //
  // #1532: a saved song with a matching local file is ONE row (the saved
  // record plus the file's Local Files source; lib/local-albums.js has the
  // rules), so collectionSongs is the merged, unsorted list every Collection
  // consumer reads (the Songs tab, its resolution, Collection Radio, the
  // albums' tracklists).
  const collectionSongs = useMemo(
    () => mergeCollectionSongs(library, collectionData.tracks),
    [library, collectionData.tracks]
  );
  const collectionSongsSorted = useMemo(() => {
    const trackMap = new Map();
    for (const track of collectionSongs) {
      const trackId = track.id || generateTrackId(track.artist, track.title, track.album);
      if (!trackMap.has(trackId)) {
        trackMap.set(trackId, track.id ? track : { ...track, id: trackId });
      }
    }
    const filtered = filterCollectionItems(Array.from(trackMap.values()), 'tracks');
    return sortCollectionItems(filtered, 'tracks');
  }, [collectionSongs, filterCollectionItems, sortCollectionItems]);

  // Collection → Albums: the saved albums plus the albums of the local
  // library (#1532, src/renderer/lib/local-albums.js). Derived on every
  // library change, never written into collectionData.albums or persisted as
  // albums, so a rescan or a removed folder updates the tab by itself. A
  // local album that is also saved (same artist and title, store suffix
  // dropped) is one card: the saved record, with the union of its saved songs
  // and its files as `tracks`. Removing a local album only hides it: its
  // album key goes into hiddenLocalAlbumKeys (persisted as
  // collection_hidden_local_albums); the files and the library stay, and
  // adding the album to the Collection clears the hide.
  const [hiddenLocalAlbumKeys, setHiddenLocalAlbumKeys] = useState([]);
  const collectionLocalAlbums = useMemo(() => deriveLocalAlbums(library), [library]);
  // Read by removeAlbumFromCollection (a stable useCallback the context-menu
  // listener closes over), so it never re-registers on a library change.
  const collectionLocalAlbumKeysRef = useRef(new Set());
  collectionLocalAlbumKeysRef.current = useMemo(() => new Set(collectionLocalAlbums.map(a => a.key)), [collectionLocalAlbums]);
  const collectionAlbums = useMemo(
    () => mergeCollectionAlbums(collectionData.albums, collectionLocalAlbums, hiddenLocalAlbumKeys, collectionSongs),
    [collectionData.albums, collectionLocalAlbums, hiddenLocalAlbumKeys, collectionSongs]
  );
  // Read by the artist page's local-library fallback (fetchArtistFromLocalLibrary).
  const collectionLocalAlbumsRef = useRef([]);
  collectionLocalAlbumsRef.current = collectionLocalAlbums;

  // Collection → Artists: the saved (followed) artists plus the artists of
  // the local library (album artist, else track artist), one card per artist
  // (same generateArtistId id or folded name). Showing is not saving: a
  // local-only artist is never written into collectionData.artists, so the
  // star, the menus and the follow push (all read collectionData.artists)
  // see them as not followed. Following one is the normal add; unfollowing
  // leaves them listed, unstarred.
  const collectionLocalArtists = useMemo(() => deriveLocalArtists(library), [library]);
  const collectionArtists = useMemo(
    () => mergeCollectionArtists(collectionData.artists, collectionLocalArtists),
    [collectionData.artists, collectionLocalArtists]
  );

  // Auto-select a populated collection tab when entering the library view
  // This fixes the issue where sidebar navigation lands on an empty tab
  // (e.g., 'artists' tab with no data) while other tabs have synced content
  useEffect(() => {
    if (activeView !== 'library' || collectionLoading) return;

    const currentTabHasData = (() => {
      switch (collectionTab) {
        case 'artists': return collectionArtists.length > 0;
        case 'albums': return collectionAlbums.length > 0;
        case 'tracks': return collectionSongs.length > 0;
        case 'friends': return friends.length > 0;
        default: return false;
      }
    })();

    if (currentTabHasData) return;

    // Current tab is empty - switch to the first tab that has data
    const tabsWithData = [
      { key: 'albums', hasData: collectionAlbums.length > 0 },
      { key: 'tracks', hasData: collectionSongs.length > 0 },
      { key: 'artists', hasData: collectionArtists.length > 0 },
      { key: 'friends', hasData: friends.length > 0 }
    ];

    const bestTab = tabsWithData.find(t => t.hasData);
    if (bestTab) {
      setCollectionTab(bestTab.key);
    }
  }, [activeView, collectionLoading, collectionTab, collectionArtists, collectionAlbums, collectionSongs, friends]);

  const handleThemeChange = async (newPref) => {
    setThemePref(newPref);
    await window.electron?.store?.set('theme_preference', newPref);
    // setNative answers with the resolved theme: one round trip, and the
    // class can't disagree with the native theme source.
    const resolved = await window.electron?.theme?.setNative(newPref);
    setEffectiveTheme(resolved || (newPref === 'dark' ? 'dark' : 'light'));
  };

  const [collectionDropHighlight, setCollectionDropHighlight] = useState(false);
  const [playlistDropHighlight, setPlaylistDropHighlight] = useState(false);
  const [dropTargetPlaylistId, setDropTargetPlaylistId] = useState(null); // Playlist being hovered during drag
  const [dropTargetNewPlaylist, setDropTargetNewPlaylist] = useState(false); // Hovering over "+ NEW" button during drag
  const [droppedTrackForNewPlaylist, setDroppedTrackForNewPlaylist] = useState(null); // Track dropped on "+ NEW" to be added after creating playlist
  const [addToPlaylistSort, setAddToPlaylistSort] = useState('added'); // Sort option for add-to-playlist panel
  const [addToPlaylistSearch, setAddToPlaylistSearch] = useState(''); // Search filter for add-to-playlist panel
  const [addToPlaylistSearchOpen, setAddToPlaylistSearchOpen] = useState(false); // Search input expanded state
  const closeAddToPlaylistPanel = () => {
    setAddToPlaylistPanel(prev => ({ ...prev, open: false }));
    setSelectedPlaylistsForAdd([]);
    setNewPlaylistFormOpen(false);
    setNewPlaylistName('');
    setAddToPlaylistSearch('');
    setAddToPlaylistSearchOpen(false);
  };

  // Confirmation dialog state
  const [confirmDialog, setConfirmDialog] = useState({
    show: false,
    type: 'success', // 'success' | 'error' | 'info'
    title: '',
    message: '',
    onConfirm: null,
    actionButton: null, // optional: { label: string, onClick: () => void }
    onCancel: null, // optional — a two-button dialog (confirmLabel set) fires it on Cancel/backdrop
  });

  // Helper to show styled confirmation dialogs.
  // options.actionButton (optional): { label, onClick } — renders an extra
  // button alongside OK. Useful for "fix this" dialogs (e.g. "No Enabled
  // Source" → "Open Resolver Settings"). The action also closes the dialog
  // before invoking onClick so the user is taken straight to the target.
  // options.onCancel (optional, used with confirmLabel): firing Cancel.
  // A dialog REPLACED while open (any later showConfirmDialog) also counts as
  // cancelled — otherwise a caller awaiting the dialog's answer (the
  // love-import confirm, parachord#1071) would hang forever with no dialog
  // left to answer.
  const pendingConfirmCancelRef = useRef(null);
  const showConfirmDialog = (options) => {
    const superseded = pendingConfirmCancelRef.current;
    pendingConfirmCancelRef.current = options.onCancel || null;
    setConfirmDialog({
      show: true,
      type: options.type || 'info',
      title: options.title || '',
      message: options.message || '',
      onConfirm: options.onConfirm || null,
      confirmLabel: options.confirmLabel || null,
      // Shows a Cancel button; destructive shows one too and makes the
      // confirm button red (components/modal.js ConfirmModal).
      cancelLabel: options.cancelLabel || null,
      destructive: !!options.destructive,
      onCancel: options.onCancel || null,
      dontShowAgain: options.dontShowAgain || null,
      actionButton: options.actionButton || null,
    });
    if (superseded) superseded();
  };

  // Closes the dialog and hands back its pending onCancel (unfired) — the
  // caller decides whether this dismissal is a cancel.
  const closeConfirmDialog = () => {
    const pending = pendingConfirmCancelRef.current;
    pendingConfirmCancelRef.current = null;
    setConfirmDialog(prev => ({ ...prev, show: false }));
    return pending;
  };

  // A confirm dialog as a promise: resolves true on the confirm button,
  // false on Cancel, the close X, Escape or the backdrop. Replaces
  // window.confirm (#1385): same question, the app's dialog.
  const confirmAsync = (options) => new Promise((resolve) => {
    showConfirmDialog({
      cancelLabel: 'Cancel',
      ...options,
      onConfirm: () => resolve(true),
      onCancel: () => resolve(false),
    });
  });
  window.confirmAsync = confirmAsync;

  // When copying to the clipboard fails: show the text to copy by hand
  // (it replaced a window.prompt).
  const showCopyFallback = (title, text) => {
    showConfirmDialog({ type: 'info', title, message: text, confirmLabel: 'Done' });
  };

  // Synced playlist delete dialog state
  const [syncDeleteDialog, setSyncDeleteDialog] = useState({ show: false, playlist: null });
  // "Stop syncing to <service>?" prompt when a user disables a live Sync channel
  // (parachord#911). { show, playlistId, playlistName, providerId, providerLabel }
  const [syncChannelDisableDialog, setSyncChannelDisableDialog] = useState({ show: false });

  // N-way migration preview (parachord#911). The "Use new sync" dev toggle opens
  // this: run a compute-only reconcile, render the named diff, and only on Accept
  // flip sync_engine_mode to 'new'. { show, loading, summary, error, recomputed }.
  const [nwayMigrationDialog, setNwayMigrationDialog] = useState({ show: false });
  // Current per-client sync engine ('legacy' | 'shadow' | 'new'), for the
  // Settings row (offer Preview when not on new, Switch-back when on new).
  const [nwayEngineMode, setNwayEngineMode] = useState('legacy');
  useEffect(() => {
    (async () => {
      try { const m = await window.electron.store.get('sync_engine_mode'); if (m) setNwayEngineMode(m); } catch {}
    })();
  }, []);

  // Open the preview: forced dry-run reconcile → render model.
  const startNwayMigration = async () => {
    setNwayMigrationDialog({ show: true, loading: true });
    try {
      const out = await window.electron.nway.preview();
      if (!out || out.error) {
        setNwayMigrationDialog({ show: true, loading: false, error: (out && out.error) || 'Preview failed' });
        return;
      }
      if (out.skipped) {
        setNwayMigrationDialog({ show: true, loading: false, error: `Preview unavailable (${out.skipped})` });
        return;
      }
      setNwayMigrationDialog({ show: true, loading: false, summary: window.summarizeMigrationPlan(out) });
    } catch (e) {
      setNwayMigrationDialog({ show: true, loading: false, error: (e && e.message) || 'Preview failed' });
    }
  };

  // Accept: recompute first (the remote may have drifted since preview). If the
  // removal count changed, re-show the fresh diff instead of committing blind.
  const acceptNwayMigration = async () => {
    setNwayMigrationDialog((d) => ({ ...d, loading: true }));
    let fresh = null;
    try { const out = await window.electron.nway.preview(); if (out && !out.error && !out.skipped) fresh = window.summarizeMigrationPlan(out); } catch {}
    const shown = nwayMigrationDialog.summary;
    if (fresh && shown && fresh.totalRemoves !== shown.totalRemoves) {
      setNwayMigrationDialog({ show: true, loading: false, summary: fresh, recomputed: true });
      showToast('The remote changed — review the updated diff before switching', 'info');
      return;
    }
    try { await window.electron.store.set('sync_engine_mode', 'new'); } catch {}
    setNwayEngineMode('new');
    setNwayMigrationDialog({ show: false });
    showToast('Switched to new sync on this device');
    // Kick an immediate armed reconcile (REAL writes) so the switch takes effect
    // now instead of waiting for the next cadence tick.
    try { window.electron.nway.run().catch(() => {}); } catch {}
  };

  // Revert to legacy (parachord#911). 'new' mode stands legacy down, so without
  // this a user who switched would have no way back. Flips the mode and resumes
  // legacy sync on the next cycle.
  const revertNwayMigration = async () => {
    try { await window.electron.store.set('sync_engine_mode', 'legacy'); } catch {}
    setNwayEngineMode('legacy');
    showToast('Switched back to the classic sync engine');
  };

  // Report: copy the full diff (GitHub truncates long prefilled bodies) and open a
  // prefilled issue. Does not switch.
  const reportNwayMigration = async () => {
    const report = window.buildMigrationReport(nwayMigrationDialog.summary, { appVersion });
    try { await navigator.clipboard.writeText(report.body); } catch {}
    if (window.electron?.shell?.openExternal) window.electron.shell.openExternal(report.githubUrl);
    setNwayMigrationDialog({ show: false });
    showToast('Diff copied to clipboard — opening a GitHub issue');
  };

  // Remove a playlist from ALL local persistence. A hosted XSPF lives in BOTH
  // the hosted_playlists URL list AND local_playlists (handleImportPlaylistFromUrl
  // persists it there so sync can pick it up) — removing only one lets the
  // load+merge re-import it (the "instant recreation" bug). Also drops the
  // per-playlist sync prefs + state.
  const deletePlaylistLocally = async (playlist) => {
    if (!playlist?.id) return;
    if (playlist.sourceUrl) {
      try {
        const hosted = await window.electron?.store?.get('hosted_playlists') || [];
        const filtered = hosted.filter(hp => hp.id !== playlist.id && hp.url !== playlist.sourceUrl);
        await window.electron?.store?.set('hosted_playlists', filtered);
      } catch (e) { console.warn('hosted_playlists cleanup failed:', e); }
    }
    try { await window.electron.playlists.delete(playlist.id); } catch (e) { console.warn('local_playlists delete failed:', e); }
    setPlaylists(prev => prev.filter(p => p.id !== playlist.id));
    delete playlistCoverCache.current[playlist.id];
    setAllPlaylistCovers(prev => { const u = { ...prev }; delete u[playlist.id]; return u; });
  };

  const handleDeleteSyncedPlaylist = async (action) => {
    const playlist = syncDeleteDialog.playlist;
    if (!playlist) return;
    setSyncDeleteDialog({ show: false, playlist: null });

    if (action !== 'stop-syncing' && action !== 'delete-from-source') return;

    const targets = getPlaylistMirrorTargets(playlist);

    // Suppress future re-sync of the source so it doesn't reimport.
    if (playlist.syncedFrom?.resolver && playlist.syncedFrom?.externalId) {
      await window.electron.playlists.suppressSync(playlist.syncedFrom.resolver, playlist.syncedFrom.externalId);
    }

    // Delete from every mirror/source if requested (best-effort; surface the
    // Apple-Music-can't-delete case so the user removes it manually).
    if (action === 'delete-from-source') {
      const manual = [];
      for (const t of targets) {
        try {
          const result = await window.electron.playlists.deleteFromSource(t.providerId, t.externalId);
          if (result && result.success === false) {
            manual.push(PROVIDER_LABEL[t.providerId] || t.providerId);
          }
        } catch (e) {
          manual.push(PROVIDER_LABEL[t.providerId] || t.providerId);
        }
      }
      if (manual.length) {
        showToast(`Deleted locally — remove it manually from ${[...new Set(manual)].join(', ')} (the app can't delete library playlists there).`, 'info');
      }
    }

    await deletePlaylistLocally(playlist);

    // Exit edit mode and navigate back
    setPlaylistEditMode(false);
    setEditedPlaylistData(null);
    setSelectedPlaylist(null);
    setPlaylistTracks([]);
    setPlaylistCoverArt([]);
    navigateTo('playlists');
  };

  const [refreshingPlaylist, setRefreshingPlaylist] = useState(null); // Track which playlist is refreshing

  // Drag & drop URL state
  const [isDraggingUrl, setIsDraggingUrl] = useState(false);
  const [dropZoneTarget, setDropZoneTarget] = useState(null); // 'now-playing' | 'queue' | null
  const queueAnimationRef = useRef(null);
  const queueContentRef = useRef(null); // Ref for queue content scrolling
  const resolverLoaderRef = useRef(null);
  // Resolves when initResolvers finishes (mount-effect). Hosted-playlist
  // reload must wait on it: dispatching an import depends on
  // findResolverForUrl, which returns null until resolvers are loaded.
  const resolversInitRef = useRef(null);

  // Browser extension state (null = unknown/checking, false = not connected, true = connected)
  const [extensionConnected, setExtensionConnected] = useState(null);
  // (browser/extension playback session states moved into use-playback-engine)
  const pendingCloseTabIdRef = useRef(null);
  const streamingPlaybackActiveRef = useRef(false); // Track when playing via Spotify/streaming to ignore browser events
