  const removeFromQueueRef = useRef(removeFromQueue);
  removeFromQueueRef.current = removeFromQueue;
  const moveInQueueRef = useRef(moveInQueue);
  moveInQueueRef.current = moveInQueue;

  // The one door for turning shuffle on or off on the current queue (#1319):
  // the playbar button, the app menu, MPRIS, parachord://control/shuffle and
  // the DJ tool (chat and MCP) all come through here. During a spinoff or
  // Listen Along it is refused (shuffleAllowed), not only greyed out on the
  // button. A change goes through toggleShuffle, which shuffles the queue or
  // restores its order; the menu, MPRIS and the link used to flip the flag
  // alone and leave the queue in its old order. `want` is true, false or
  // 'toggle'. Returns whether shuffle is now as asked.
  const requestShuffle = (want, { toast = true } = {}) => {
    if (!shuffleAllowed({ spinoff: spinoffModeRef.current, listenAlong: !!listenAlongFriendRef.current })) {
      if (toast) showToast(SHUFFLE_UNAVAILABLE_MESSAGE);
      return false;
    }
    const enabled = want === 'toggle' ? !shuffleModeRef.current : !!want;
    if (enabled !== shuffleModeRef.current) toggleShuffle();
    return true;
  };
  const requestShuffleRef = useRef(null);
  requestShuffleRef.current = requestShuffle;

  // The one door for repeat (#1319): the playbar button and MPRIS. Like
  // shuffle, it can't be changed during a spinoff or Listen Along (the mobile
  // apps' rule). `want` is 'off', 'all', 'one' or 'cycle' (off, all, one,
  // off). The mode is a player setting, saved whether or not the queue is
  // remembered. Returns whether the mode is now as asked.
  const requestRepeat = (want, { toast = true } = {}) => {
    if (!shuffleAllowed({ spinoff: spinoffModeRef.current, listenAlong: !!listenAlongFriendRef.current })) {
      if (toast) showToast(REPEAT_UNAVAILABLE_MESSAGE);
      return false;
    }
    const mode = want === 'cycle' ? nextRepeatMode(repeatModeRef.current) : normalizeRepeatMode(want);
    setRepeatMode(mode);
    if (window.electron?.store) {
      Promise.resolve(window.electron.store.set('repeat_mode', mode)).catch(() => {});
    }
    return true;
  };
  const requestRepeatRef = useRef(null);
  requestRepeatRef.current = requestRepeat;

  const holdPlaybarArt = holdPreviousPlaybarArt(currentTrack, playbarArtMissKey);

  // Handle album art crossfade transitions in playbar
  useEffect(() => {
    const newArt = currentTrack?.albumArt || null;
    const prevArt = playbarAlbumArtRef.current;

    if (newArt !== prevArt) {
      // No new art yet: keep the previous cover while one may still be on the way,
      // so a placeholder doesn't flash between tracks. Not once none is coming, or
      // the track would show the previous track's cover.
      if (!newArt && prevArt && holdPlaybarArt) {
        return;
      }

      // Album art changed - trigger crossfade
      setPlaybarAlbumArt({
        current: newArt,
        previous: prevArt,
        isLoaded: !newArt // If no new art, mark as loaded immediately
      });
      playbarAlbumArtRef.current = newArt;

      // Clear previous art after transition completes to free memory
      if (prevArt) {
        const clearPrevious = setTimeout(() => {
          setPlaybarAlbumArt(prev => ({ ...prev, previous: null }));
        }, 400); // Slightly longer than transition duration
        return () => clearTimeout(clearPrevious);
      }
    }
  }, [currentTrack?.albumArt, holdPlaybarArt]);

  // Check if spinoff is available for the current track
  useEffect(() => {
    // Reset availability when track changes
    setSpinoffAvailable(null);

    if (!currentTrack?.artist || !currentTrack?.title) {
      return;
    }

    // Don't check while in spinoff mode (we already know it works)
    if (spinoffMode) {
      setSpinoffAvailable(true);
      return;
    }

    let cancelled = false;
    const checkAvailability = async () => {
      const available = await checkSpinoffAvailability(currentTrack.artist, currentTrack.title);
      if (!cancelled) {
        setSpinoffAvailable(available);
      }
    };

    checkAvailability();
    return () => { cancelled = true; };
  }, [currentTrack?.artist, currentTrack?.title, spinoffMode]);

  // Scroll queue to bottom when opened (so track 1 is visible at the bottom)
  useEffect(() => {
    if (queueDrawerOpen && queueContentRef.current) {
      // Small delay to ensure the drawer has animated open
      setTimeout(() => {
        if (queueContentRef.current) {
          queueContentRef.current.scrollTop = queueContentRef.current.scrollHeight;
        }
      }, 50);
    }
  }, [queueDrawerOpen]);

  // Artist page scroll handler for header collapse
  const artistCollapseLockedRef = useRef(false);
  const artistLastScrollTopRef = useRef(0);
  const handleArtistPageScroll = useCallback((e) => {
    const scrollTop = e.target.scrollTop;
    const lastScrollTop = artistLastScrollTopRef.current;
    const isScrollingUp = scrollTop < lastScrollTop;
    artistLastScrollTopRef.current = scrollTop;

    // If locked (during transition), ignore scroll events
    if (artistCollapseLockedRef.current) return;

    // Collapse when scrolled down past threshold
    if (scrollTop > 50 && !isHeaderCollapsed && !isScrollingUp) {
      artistCollapseLockedRef.current = true;
      setIsHeaderCollapsed(true);
      // Unlock after transition completes
      setTimeout(() => { artistCollapseLockedRef.current = false; }, 350);
    }
    // Expand when scrolling up near the top (within 100px) or at very top
    else if (isHeaderCollapsed && isScrollingUp && scrollTop < 100) {
      artistCollapseLockedRef.current = true;
      setIsHeaderCollapsed(false);
      setTimeout(() => { artistCollapseLockedRef.current = false; }, 350);
    }
  }, [isHeaderCollapsed]);

  // Search detail page scroll handler for header collapse and infinite scroll
  const handleSearchDetailScroll = useCallback((e) => {
    const { scrollTop, scrollHeight, clientHeight } = e.target;
    // Header collapse
    setSearchHeaderCollapsed(scrollTop > 100);
    // Infinite scroll - load more when within 200px of bottom
    if (scrollHeight - scrollTop - clientHeight < 200 && searchDetailCategory) {
      handleLoadMore(searchDetailCategory);
    }
  }, [searchDetailCategory]);

  // Reset search header collapse when leaving detail view
  useEffect(() => {
    if (!searchDetailCategory) {
      setSearchHeaderCollapsed(false);
    }
  }, [searchDetailCategory]);

  // Reset header collapse and tab when navigating to a new artist (but not when opening a release or restoring state)
  useEffect(() => {
    // The related-artists source filter belongs to one artist. It used to
    // carry over: ListenBrainz picked on an artist with an MBID, then an
    // artist without one (no chips to switch back) showed "No artists from
    // ListenBrainz." A second update of the same artist (its full data
    // arriving) keeps the pick.
    const relatedFilterArtist = (currentArtist?.name || '').trim().toLowerCase();
    if (relatedFilterArtistRef.current !== relatedFilterArtist) {
      relatedFilterArtistRef.current = relatedFilterArtist;
      setRelatedArtistsSourceFilter('all');
    }
    // Don't reset header if we're opening a release - it should stay collapsed
    if (openingReleaseRef.current) {
      openingReleaseRef.current = false;
    } else {
      setIsHeaderCollapsed(false);
    }
    // Don't reset tab or clear data if we're restoring saved state
    if (restoringStateRef.current) {
      restoringStateRef.current = false;
    } else if (pendingProtocolTabRef.current) {
      // Deep link requested a specific tab - apply it instead of resetting to 'music'
      const pendingTab = pendingProtocolTabRef.current;
      // Only clear the ref once we have full artist data (with mbid) so the tab
      // persists across both the initial and full artist data loads in the non-cached path
      if (currentArtist?.mbid) {
        pendingProtocolTabRef.current = null;
      }
      setArtistPageTab(pendingTab);
      setArtistBio(null);
      setArtistExtendedInfo(null);
      setRelatedArtists([]);
    } else {
      setArtistPageTab('music');
      setArtistBio(null);
      setArtistExtendedInfo(null);
      setRelatedArtists([]);
    }
    // Reset and proactively load artist concerts for the On Tour tab
    setArtistConcerts([]);
    setArtistConcertsLoaded(false);
    if (currentArtist?.name) {
      loadArtistConcerts(currentArtist.name);
    }
  }, [currentArtist]);

  // Fetch tab data when restored to biography or related artists tab
  useEffect(() => {
    if (!currentArtist) return;

    if (artistPageTab === 'biography') {
      // Fetch bio if not already loaded
      if (artistBio === null && !loadingBio) {
        setLoadingBio(true); // Set loading immediately before async call
        (async () => {
          const bioData = await getArtistBio(currentArtist.name, currentArtist.mbid);
          setArtistBio(bioData === null ? false : bioData); // Use false to indicate "fetched but no bio"
        })();
      }

      // Fetch extended info if not already loaded
      if (artistExtendedInfo === null && !loadingExtendedInfo && currentArtist.mbid) {
        (async () => {
          const extInfo = await fetchArtistExtendedInfo(currentArtist.mbid);
          setArtistExtendedInfo(extInfo === null ? false : extInfo);
        })();
      }
    }

    if (artistPageTab === 'related' && relatedArtists.length === 0 && !loadingRelated) {
      (async () => {
        const related = await getRelatedArtists(currentArtist.name, currentArtist.mbid);
        if (related.length > 0) {
          setRelatedArtists(related);
          resolveRelatedArtistImages(related);
        }
      })();
    }
  }, [artistPageTab, currentArtist]);

  // Load local files data when resolver modal is opened
  useEffect(() => {
    if (isLocalResolver(selectedResolver?.id) && window.electron?.localFiles) {
      window.electron.localFiles.getStats().then(setLocalFilesStats);
      window.electron.localFiles.getWatchFolders().then(setWatchFolders);
    }
  }, [selectedResolver]);

  // Fetch dynamic models when a resolver with dynamic-select is selected
  useEffect(() => {
    if (selectedResolver) {
      const resolver = metaServices.find(s => s.id === selectedResolver.id) || selectedResolver;
      const modelSetting = resolver.settings?.configurable?.model || resolver.configurable?.model;
      if (modelSetting?.type === 'dynamic-select') {
        fetchDynamicModels(resolver, metaServiceConfigs[resolver.id]);
      }
    }
  }, [selectedResolver?.id]);

  // URL drag & drop helpers
  const isValidUrl = (string) => {
    try {
      const url = new URL(string);
      return url.protocol === 'http:' || url.protocol === 'https:' || string.startsWith('spotify:');
    } catch {
      return false;
    }
  };

  const extractUrlFromDrop = (dataTransfer) => {
    // Try text/uri-list first (standard for URL drops)
    let url = dataTransfer.getData('text/uri-list');
    if (url && isValidUrl(url.split('\n')[0])) {
      return url.split('\n')[0].trim();
    }

    // Fallback to text/plain
    url = dataTransfer.getData('text/plain');
    if (url && isValidUrl(url.trim())) {
      return url.trim();
    }

    return null;
  };

  const getUrlDomain = (url) => {
    try {
      if (url.startsWith('spotify:')) return 'spotify.com';
      const urlObj = new URL(url);
      return urlObj.hostname.replace(/^www\./, '');
    } catch {
      return 'unknown';
    }
  };

  // Convert raw track metadata to a proper track object with sources
  const createTrackFromMeta = (trackMeta, resolverId, sourceUrl = null) => {
    // No album is no album: a placeholder would reach scrobbles and art and
    // album lookups as if it were real. The id keeps its 'Single' so it stays
    // the same as for tracks opened before this.
    const album = isPlaceholderAlbum(trackMeta.album, [resolverId]) ? '' : trackMeta.album;
    const trackId = `${trackMeta.artist}-${trackMeta.title}-${album || 'Single'}`.toLowerCase().replace(/[^a-z0-9]/g, '-');
    const track = {
      id: trackId,
      status: 'ready',
      title: trackMeta.title,
      artist: trackMeta.artist,
      album,
      // Unknown is null, never a made-up length a track list would show.
      duration: trackMeta.duration > 0 ? trackMeta.duration : null,
      albumArt: trackMeta.albumArt,
      sourceUrl: sourceUrl,
      sources: {}
    };

    // Add source-specific data
    const sourceData = {};
    if (trackMeta.spotifyId) sourceData.spotifyId = trackMeta.spotifyId;
    if (trackMeta.spotifyUri) sourceData.spotifyUri = trackMeta.spotifyUri;
    if (trackMeta.youtubeId) sourceData.youtubeId = trackMeta.youtubeId;
    if (trackMeta.bandcampUrl) sourceData.bandcampUrl = trackMeta.bandcampUrl;
    if (trackMeta.bandcampTrackId) sourceData.bandcampTrackId = trackMeta.bandcampTrackId;
    if (trackMeta.bandcampAlbumId) sourceData.bandcampAlbumId = trackMeta.bandcampAlbumId;
    if (trackMeta.appleMusicId) sourceData.appleMusicId = trackMeta.appleMusicId;
    if (trackMeta.soundcloudId) sourceData.soundcloudId = trackMeta.soundcloudId;
    if (trackMeta.soundcloudUrl) sourceData.soundcloudUrl = trackMeta.soundcloudUrl;
    if (trackMeta.previewUrl) sourceData.previewUrl = trackMeta.previewUrl;

    // The link's own source names the track too: sources are rescored by
    // title and artist, and one without them falls under the floor. Without
    // a sign-in, a SoundCloud link's source is the only one SoundCloud gets.
    // A purchase-only answer (`streamable: false`, a buy-only Bandcamp track)
    // stays purchase-only on the track's source (lib/playable-source.js).
    if (Object.keys(sourceData).length > 0 && trackMeta.streamable === false) sourceData.streamable = false;
    if (Object.keys(sourceData).length > 0) {
      track.sources[resolverId] = {
        ...sourceData,
        title: trackMeta.title,
        artist: trackMeta.artist,
        confidence: 1.0
      };
    }

    return track;
  };

  // Handle drag end for playlist panel — onDrop doesn't fire in Electron for
  // dynamically-shown elements, so we check drop targets in onDragEnd as a fallback.
  const handlePlaylistDragEnd = () => {
    const wasOverNewPlaylist = dropTargetNewPlaylist;

    // If drag ended while hovering over "New Playlist" row, treat it as a drop
    if (wasOverNewPlaylist && draggingTrackForPlaylist) {
      setDroppedTrackForNewPlaylist(draggingTrackForPlaylist);
      setNewPlaylistFormOpen(true);
      setNewPlaylistName('');
    }

    setDraggingTrackForPlaylist(null);
    setDropTargetPlaylistId(null);
    setDropTargetNewPlaylist(false);

    // Only auto-close the panel if no drop was handled
    if (addToPlaylistPanel.open && selectedPlaylistsForAdd.length === 0 && !wasOverNewPlaylist) {
      setAddToPlaylistPanel(prev => ({ ...prev, open: false }));
    }
  };

  // Handle URL drop - main entry point
  const handleUrlDrop = async (url, zone) => {
    console.log(`🔗 URL dropped on ${zone}:`, url);

    // Find resolver for this URL
    const resolverId = resolverLoaderRef.current?.findResolverForUrl(url);
    if (!resolverId) {
      console.error('❌ No resolver found for URL:', url);
      return;
    }

    console.log(`📎 Matched resolver: ${resolverId}`);

    // Detect URL type (track, album, or playlist)
    const urlType = resolverLoaderRef.current.getUrlType(url);
    console.log(`📎 URL type: ${urlType}`);

    // Handle album/playlist URLs
    if (urlType === 'album' || urlType === 'playlist') {
      await handleCollectionUrlDrop(url, resolverId, urlType, zone);
      return;
    }

    // Handle single track URL (existing logic)
    await handleSingleTrackUrlDrop(url, zone, resolverId);
  };

  // Handle album or playlist URL drop
  const handleCollectionUrlDrop = async (url, resolverId, urlType, zone) => {
    console.log(`📀 Loading ${urlType} from URL (zone: ${zone}):`, url);
    console.log(`📀 Resolver ID: ${resolverId}`);

    try {
      const config = await getResolverConfig(resolverId);
      console.log(`📀 Config has token: ${!!config.token}`);
      let result;

      if (urlType === 'album') {
        console.log(`📀 Calling lookupAlbum...`);
        result = await resolverLoaderRef.current.lookupAlbum(url, config);
        console.log(`📀 lookupAlbum result:`, result);
        if (!result || !result.album) {
          throw new Error('Could not load album');
        }
      } else {
        // Check if resolver has lookupPlaylist
        const resolver = resolverLoaderRef.current.getResolver(resolverId);
        console.log(`📀 Resolver has lookupPlaylist: ${!!resolver?.lookupPlaylist}`);
        console.log(`📀 Calling lookupPlaylist...`);
        result = await resolverLoaderRef.current.lookupPlaylist(url, config);
        console.log(`📀 lookupPlaylist result:`, result);
        if (!result || !result.playlist) {
          throw new Error('Could not load playlist');
        }
      }

      const collection = result.album || result.playlist;
      const collectionResolverId = result.resolverId;
      const tracks = collection.tracks || [];

      if (tracks.length === 0) {
        console.error(`❌ ${urlType} has no tracks`);
        return;
      }

      console.log(`✅ ${urlType} "${collection.name}" loaded with ${tracks.length} tracks`);

      // Create context for this collection (include source URL for external navigation)
      const context = urlType === 'album'
        ? { type: 'album', id: collection.id, name: collection.name, artist: collection.artist, url: url }
        : { type: 'playlist', id: collection.id, name: collection.name, url: url };

      // Convert all tracks to proper track objects with context
      const resolvedTracks = tracks.map(trackMeta => ({
        ...createTrackFromMeta(trackMeta, collectionResolverId, url),
        _playbackContext: context
      }));

      const hasCurrentTrack = currentTrackRef.current !== null;

      // If dropped on now-playing zone, play first track immediately
      // and add remaining tracks to the BEGINNING of the queue (play next)
      if (zone === 'now-playing') {
        const firstTrack = resolvedTracks[0];
        const remainingTracks = resolvedTracks.slice(1);

        // Show toast notification
        showToast(`Playing "${collection.name}" (${countOf(tracks.length, 'track')})`);

        // Add remaining tracks to the BEGINNING of the queue (so they play next)
        if (remainingTracks.length > 0) {
          setCurrentQueue(prev => [...remainingTracks, ...prev]);
        }

        // Set context and play first track immediately
        setPlaybackContext(context);
        setCurrentTrack(firstTrack);
        handlePlay(firstTrack);

        // Trigger queue animation if we added tracks
        if (remainingTracks.length > 0) {
          triggerQueueAnimation();
        }
      } else {
        // Default behavior: insert tracks at beginning of queue (play next)
        showToast(`Playing "${collection.name}" next (${countOf(tracks.length, 'track')})`);

        setCurrentQueue(prev => {
          return [...resolvedTracks, ...prev];
        });
        triggerQueueAnimation();

        // If nothing is playing, start the first track
        if (!hasCurrentTrack && resolvedTracks.length > 0) {
          const firstTrack = resolvedTracks[0];
          // Remove from queue and set as current
          setCurrentQueue(prev => prev.slice(1));
          setPlaybackContext(context);
          setCurrentTrack(firstTrack);
          handlePlay(firstTrack);
        }
      }

      // Background resolution: resolve all tracks across all enabled resolvers
      // This happens asynchronously so tracks are playable immediately but will
      // have all sources available for priority-based playback
      resolveTracksInBackground(resolvedTracks);

    } catch (error) {
      console.error(`❌ ${urlType} lookup failed:`, error);
      showToast(errorText(error, `Couldn’t open that ${urlType}. Check the link and try again.`), 'error');
    }
  };

  // Resolve tracks across all enabled resolvers in the background
  const resolveTracksInBackground = async (tracks) => {
    console.log(`🔍 Background resolution: resolving ${tracks.length} tracks across all sources...`);

    // Background-enrich all tracks with MBIDs in parallel (non-blocking)
    enrichTracksWithMbids(tracks);

    // Use refs to avoid stale closure issues
    const currentResolvers = loadedResolversRef.current;
    const currentActiveResolvers = activeResolversRef.current;
    const currentResolverOrder = resolverOrderRef.current;
    const orderedIds = currentResolverOrder.filter(id => currentActiveResolvers.includes(id));
    const unorderedIds = currentActiveResolvers.filter(id => !orderedIds.includes(id));
    const enabledResolvers = [...orderedIds, ...unorderedIds]
      .map(id => currentResolvers.find(r => r.id === id))
      .filter(r => r && r.capabilities.resolve);

    // Whether a track already has this plug-in's answer: a source, or a miss
    // from the plug-in version loaded now (lib/cached-miss.js, #1535). A
    // stale miss is asked again; if the plug-in still finds nothing, the miss
    // is renewed with the current version so it isn't asked again.
    const startedAt = Date.now();
    const hasAnswer = (track, resolver) => {
      const saved = track.sources[resolver.id];
      return !!saved && !isStaleMiss(saved, resolver.version, startedAt, CACHE_TTL.persistedSources);
    };
    const renewStaleMiss = (track, resolver) => {
      if (isMiss(track.sources[resolver.id])) track.sources[resolver.id] = newMiss(resolver);
    };
    // Saved entries that still answer (every key but a stale miss).
    const answeredCount = (track) => Object.entries(track.sources).filter(([id, saved]) =>
      !isStaleMiss(saved, currentResolvers.find(r => r.id === id)?.version, startedAt, CACHE_TTL.persistedSources)).length;

    // Helper: flush resolved sources to the queue state so the UI updates incrementally
    const flushToQueue = () => {
      setCurrentQueue(prev => prev.map(queueTrack => {
        const resolvedTrack = tracks.find(t => t.id === queueTrack.id);
        if (resolvedTrack && Object.keys(resolvedTrack.sources).length > Object.keys(queueTrack.sources || {}).length) {
          return {
            ...queueTrack,
            sources: { ...queueTrack.sources, ...resolvedTrack.sources },
            album: queueTrack.album || resolvedTrack.album,
            albumArt: queueTrack.albumArt || resolvedTrack.albumArt
          };
        }
        return queueTrack;
      }));
    };

    // Apple Music's catalog API (api.music.apple.com) IS rate-limited — Apple
    // throttles aggressively on parallel fan-out and the throttle leaks into
    // playback (musicKit.play() also reads the catalog). The native MusicKit
    // path self-throttles via nativeMusicKitLimiter inside
    // appleMusicSearchWithMusicKit, so we can safely run applemusic alongside
    // the parallel resolvers regardless of whether MusicKit is active. The
    // iTunes-fallback path inside that wrapper goes through iTunesRateLimiter.
    // This branch used to special-case applemusic into a sequential queue when
    // MusicKit wasn't active; that's no longer necessary because the limiter
    // covers both paths. Kept for clarity in case anyone re-introduces a
    // pre-throttle codepath.
    const rateLimitedResolvers = [];
    const normalResolvers = enabledResolvers;

    // Resolve all tracks across normal resolvers in parallel (no batching needed)
    const normalPromise = Promise.all(tracks.map(async (track) => {
      if (answeredCount(track) >= enabledResolvers.length) return;

      await Promise.all(normalResolvers.map(async (resolver) => {
        if (hasAnswer(track, resolver)) return;
        try {
          const config = await getResolverConfig(resolver.id);
          const result = await resolver.resolve(track.artist, track.title, track.album, config);
          if (!result) renewStaleMiss(track, resolver);
          if (result) {
            // Score before stamping. Wrong-artist matches collapse to 0.50
            // and the source-selection floor will drop them — but skip the
            // attach entirely to keep `track.sources` clean and to avoid
            // polluting album/art fallbacks with the wrong recording's data.
            const confidence = calculateConfidence(track, result);
            if (confidence < MIN_CONFIDENCE_THRESHOLD) {
              console.warn(`  ⚠️ ${resolver.name}: Rejecting "${result.title}" by "${result.artist}" — does not match "${track.title}" by "${track.artist}"`);
              renewStaleMiss(track, resolver);
              return;
            }
            track.sources[resolver.id] = { ...result, confidence };
            if (!track.album && result.album) track.album = result.album;
            if (!track.albumArt && result.albumArt) track.albumArt = result.albumArt;
            console.log(`  ✅ ${resolver.name}: Found "${track.title}"`);
            flushToQueue();
          }
        } catch (error) {
          // Silently fail - background resolution is best-effort
        }
      }));
    }));

    // Run rate-limited resolvers (Apple Music via iTunes API only) concurrently
    // with normal resolvers, but sequentially within themselves
    const ITUNES_DELAY_MS = 500;
    const rateLimitedPromise = (async () => {
      for (const resolver of rateLimitedResolvers) {
        for (const track of tracks) {
          if (hasAnswer(track, resolver)) continue;
          if (answeredCount(track) >= enabledResolvers.length) continue;
          try {
            const config = await getResolverConfig(resolver.id);
            const result = await resolver.resolve(track.artist, track.title, track.album, config);
            if (!result) renewStaleMiss(track, resolver);
            if (result) {
              const confidence = calculateConfidence(track, result);
              if (confidence < MIN_CONFIDENCE_THRESHOLD) {
                console.warn(`  ⚠️ ${resolver.name}: Rejecting "${result.title}" by "${result.artist}" — does not match "${track.title}" by "${track.artist}"`);
                renewStaleMiss(track, resolver);
              } else {
                track.sources[resolver.id] = { ...result, confidence };
                if (!track.album && result.album) track.album = result.album;
                if (!track.albumArt && result.albumArt) track.albumArt = result.albumArt;
                console.log(`  ✅ ${resolver.name}: Found "${track.title}"`);
                flushToQueue();
              }
            }
          } catch (error) {
            // Silently fail
          }
          await new Promise(resolve => setTimeout(resolve, ITUNES_DELAY_MS));
        }
      }
    })();

    // Wait for everything to finish, then do a final flush
    await Promise.all([normalPromise, rateLimitedPromise]);
    flushToQueue();

    console.log(`✅ Background resolution complete for ${tracks.length} tracks`);
  };

  // Handle single track URL drop (original handleUrlDrop logic)
  const handleSingleTrackUrlDrop = async (url, zone, resolverId) => {
    // Create context for this URL drop
    const context = { type: 'url', url: url, name: getUrlDomain(url) };

    // Create placeholder track
    const placeholderId = `pending-${Date.now()}`;
    const placeholder = {
      id: placeholderId,
      status: 'loading',
      sourceUrl: url,
      sourceDomain: getUrlDomain(url),
      title: null,
      artist: null,
      album: null,
      duration: null,
      albumArt: null,
      sources: {},
      errorMessage: null,
      _playbackContext: context
    };

    // Determine where to insert - use refs to avoid stale closure issues
    // (especially when called from extension message handler in useEffect)
    const hasQueue = currentQueueRef.current.length > 0;
    const hasCurrentTrack = currentTrackRef.current !== null;
    // Play immediately only if explicitly requested OR if nothing is playing/queued
    const shouldPlayImmediately = zone === 'now-playing' || (!hasQueue && !hasCurrentTrack);
    console.log(`📍 handleUrlDrop: hasQueue=${hasQueue}, hasCurrentTrack=${hasCurrentTrack}, shouldPlayImmediately=${shouldPlayImmediately}`);

    if (shouldPlayImmediately) {
      // Set as current track (loading state)
      setCurrentTrack(placeholder);
    } else {
      // Add to queue - insert at position 1 if queue has items, otherwise at position 0
      setCurrentQueue(prev => {
        const newQueue = [...prev];
        const insertPosition = prev.length > 0 ? 1 : 0;
        newQueue.splice(insertPosition, 0, placeholder);
        return newQueue;
      });
      // Trigger queue icon animation
      triggerQueueAnimation();
    }

    // Look up track metadata
    try {
      // Pass resolver config so Spotify has access to token
      const config = await getResolverConfig(resolverId);
      const result = await resolverLoaderRef.current.lookupUrl(url, config);

      if (!result || !result.track) {
        throw new Error('Could not load track metadata');
      }

      const { track: trackMeta, resolverId: lookupResolverId } = result;
      console.log(`✅ URL lookup success:`, trackMeta.title, '-', trackMeta.artist);

      // Create proper track object with playback context
      const resolvedTrack = {
        ...createTrackFromMeta(trackMeta, lookupResolverId, url),
        _playbackContext: context
      };

      // Now resolve across all enabled resolvers for playable sources
      console.log(`🔍 Resolving playable sources...`);
      // Use refs to avoid stale closure issues when called from extension message handler
      const currentResolvers = loadedResolversRef.current;
      const currentActiveResolvers = activeResolversRef.current;
      const currentResolverOrder = resolverOrderRef.current;
      const orderedIds = currentResolverOrder.filter(id => currentActiveResolvers.includes(id));
      const unorderedIds = currentActiveResolvers.filter(id => !orderedIds.includes(id));
      const enabledResolvers = [...orderedIds, ...unorderedIds]
        .map(id => currentResolvers.find(r => r.id === id))
        .filter(r => r && r.capabilities.resolve);

      // Update the placeholder with metadata immediately (before resolver resolution)
      if (shouldPlayImmediately) {
        setCurrentTrack(prev => prev?.id === placeholderId ? resolvedTrack : prev);
      } else {
        setCurrentQueue(prev => prev.map(t => t.id === placeholderId ? resolvedTrack : t));
      }

      const resolvePromises = enabledResolvers.map(async (resolver) => {
        try {
          const config = await getResolverConfig(resolver.id);
          const result = await resolver.resolve(trackMeta.artist, trackMeta.title, trackMeta.album, config);
          if (result) {
            const confidence = calculateConfidence(trackMeta, result);
            if (confidence < MIN_CONFIDENCE_THRESHOLD) {
              console.warn(`  ⚠️ ${resolver.name}: Rejecting "${result.title}" by "${result.artist}" — does not match "${trackMeta.title}" by "${trackMeta.artist}"`);
              return;
            }
            resolvedTrack.sources[resolver.id] = {
              ...result,
              confidence
            };
            console.log(`  ✅ ${resolver.name}: Found match`);
            // Flush incrementally so each resolved source appears immediately
            if (shouldPlayImmediately) {
              setCurrentTrack(prev => prev?.id === resolvedTrack.id
                ? { ...prev, sources: { ...prev.sources, ...resolvedTrack.sources } }
                : prev);
            } else {
              setCurrentQueue(prev => prev.map(t => t.id === resolvedTrack.id
                ? { ...t, sources: { ...t.sources, ...resolvedTrack.sources } }
                : t));
            }
          }
        } catch (error) {
          console.error(`  ❌ ${resolver.name} resolve error:`, error);
        }
      });

      await Promise.all(resolvePromises);

      // Final update with all sources + trigger playback
      if (shouldPlayImmediately) {
        setCurrentTrack(prev => prev?.id === resolvedTrack.id ? resolvedTrack : prev);
        setPlaybackContext(context);
        handlePlay(resolvedTrack);
      } else {
        setCurrentQueue(prev => prev.map(t =>
          t.id === resolvedTrack.id ? resolvedTrack : t
        ));
      }

    } catch (error) {
      console.error('❌ URL lookup failed:', error);

      // Update placeholder to error state
      const errorTrack = {
        ...placeholder,
        status: 'error',
        errorMessage: error.message || 'Could not load track'
      };

      if (shouldPlayImmediately) {
        setCurrentTrack(prev => {
          if (prev?.id === placeholderId) {
            return errorTrack;
          }
          return prev;
        });
      } else {
        setCurrentQueue(prev => prev.map(t =>
          t.id === placeholderId ? errorTrack : t
        ));
      }
    }
  };

  // Queue animation trigger
  const triggerQueueAnimation = () => {
    setQueueAnimating(true);
    if (queueAnimationRef.current) {
      clearTimeout(queueAnimationRef.current);
    }
    queueAnimationRef.current = setTimeout(() => {
      setQueueAnimating(false);
    }, 300);
  };

  // Drag event handlers for URL drops
  const handleDragEnter = (e, zone) => {
    e.preventDefault();
    e.stopPropagation();

    const url = extractUrlFromDrop(e.dataTransfer);
    if (!url) return;

    // Check if any resolver can handle this URL
    const resolverId = resolverLoaderRef.current?.findResolverForUrl(url);
    if (resolverId) {
      setIsDraggingUrl(true);
      setDropZoneTarget(zone);
    }
  };

  const handleDragOver = (e, zone) => {
    e.preventDefault();
    e.stopPropagation();

    // Update target if moving between zones
    if (isDraggingUrl && dropZoneTarget !== zone) {
      setDropZoneTarget(zone);
    }
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    e.stopPropagation();

    // Only clear if leaving the app entirely
    const relatedTarget = e.relatedTarget;
    if (!relatedTarget || !e.currentTarget.contains(relatedTarget)) {
      setIsDraggingUrl(false);
      setDropZoneTarget(null);
    }
  };

  const handleDrop = (e, zone) => {
    e.preventDefault();
    e.stopPropagation();

    setIsDraggingUrl(false);
    setDropZoneTarget(null);

    // First, try to parse as internal JSON object (track, album, playlist)
    const plainText = e.dataTransfer.getData('text/plain');
    if (plainText) {
      try {
        const data = JSON.parse(plainText);
        if (data.type === 'track' && data.track) {
          console.log(`🎵 Internal track dropped on ${zone}:`, data.track.title);
          if (zone === 'now-playing') {
            // Play immediately
            setCurrentTrack(data.track);
            handlePlay(data.track);
          } else {
            // Add to queue
            setCurrentQueue(prev => [...prev, data.track]);
            triggerQueueAnimation();
          }
          return;
        }
        if (data.type === 'album' && data.album) {
          console.log(`📀 Internal album dropped on ${zone}:`, data.album.title);
          // Fetch album tracks and handle like a collection drop
          handleInternalAlbumDrop(data.album, zone);
          return;
        }
        if (data.type === 'playlist' && data.playlist) {
          console.log(`📋 Internal playlist dropped on ${zone}:`, data.playlist.title);
          // Handle playlist tracks
          handleInternalPlaylistDrop(data.playlist, zone);
          return;
        }
      } catch (parseError) {
        // Not JSON, continue to URL handling
      }
    }

    // Fall back to URL drop handling
    const url = extractUrlFromDrop(e.dataTransfer);
    if (!url) {
      console.log('No valid URL or internal object in drop');
      return;
    }

    handleUrlDrop(url, zone);
  };

  // Handle internal album drop (from within the app)
  const handleInternalAlbumDrop = async (album, zone) => {
    // If album has tracks array, use it directly
    if (album.tracks && album.tracks.length > 0) {
      const tracks = album.tracks;
      const context = { type: 'album', id: album.id, name: album.title, artist: album.artist };
      const taggedTracks = tracks.map(t => ({ ...t, _playbackContext: context }));
      if (zone === 'now-playing') {
        showToast(`Playing "${album.title}" (${countOf(tracks.length, 'track')})`);
        const firstTrack = taggedTracks[0];
        const remainingTracks = taggedTracks.slice(1);
        // Add remaining tracks to BEGINNING of queue (play next)
        if (remainingTracks.length > 0) {
          setCurrentQueue(prev => [...remainingTracks, ...prev]);
        }
        setPlaybackContext(context);
        setCurrentTrack(firstTrack);
        handlePlay(firstTrack);
        if (remainingTracks.length > 0) {
          triggerQueueAnimation();
        }
      } else {
        setCurrentQueue(prev => [...prev, ...taggedTracks]);
        triggerQueueAnimation();
      }
      return;
    }

    // Otherwise, need to fetch the album tracks (e.g., from release page cache)
    const releaseId = album.id;
    const cachedRelease = prefetchedReleasesRef.current[releaseId];
    if (cachedRelease && cachedRelease.tracks) {
      const tracks = cachedRelease.tracks;
      const context = { type: 'album', id: album.id, name: album.title, artist: album.artist };
      const taggedTracks = tracks.map(t => ({ ...t, _playbackContext: context }));
      if (zone === 'now-playing') {
        showToast(`Playing "${album.title}" (${countOf(tracks.length, 'track')})`);
        const firstTrack = taggedTracks[0];
        const remainingTracks = taggedTracks.slice(1);
        // Add remaining tracks to BEGINNING of queue (play next)
        if (remainingTracks.length > 0) {
          setCurrentQueue(prev => [...remainingTracks, ...prev]);
        }
        setPlaybackContext(context);
        setCurrentTrack(firstTrack);
        handlePlay(firstTrack);
        if (remainingTracks.length > 0) {
          triggerQueueAnimation();
        }
      } else {
        setCurrentQueue(prev => [...prev, ...taggedTracks]);
        triggerQueueAnimation();
      }
    } else {
      showToast(`Could not load tracks for "${album.title}"`, 'error');
    }
  };

  // Handle internal playlist drop (from within the app)
  const handleInternalPlaylistDrop = async (playlist, zone) => {
    const tracks = playlist.tracks || [];
    if (tracks.length === 0) {
      showToast(`Playlist "${playlist.title}" has no tracks`, 'error');
      return;
    }

    const context = { type: 'playlist', id: playlist.id, name: playlist.title };
    const taggedTracks = tracks.map(t => ({ ...t, _playbackContext: context }));

    if (zone === 'now-playing') {
      showToast(`Playing "${playlist.title}" (${countOf(tracks.length, 'track')})`);
      const firstTrack = taggedTracks[0];
      const remainingTracks = taggedTracks.slice(1);
      // Add remaining tracks to BEGINNING of queue (play next)
      if (remainingTracks.length > 0) {
        setCurrentQueue(prev => [...remainingTracks, ...prev]);
      }
      setPlaybackContext(context);
      setCurrentTrack(firstTrack);
      handlePlay(firstTrack);
      if (remainingTracks.length > 0) {
        triggerQueueAnimation();
      }
    } else {
      setCurrentQueue(prev => [...prev, ...taggedTracks]);
      triggerQueueAnimation();
    }
  };

  // Drop zone overlay component

  // Resolver plugin system
  const resolverLoader = useRef(null);
  const [loadedResolvers, setLoadedResolvers] = useState([]);
  const loadedResolversRef = useRef([]);

  // Capability lookups for the shared HTML5 audio element. A resolver that
  // declares capabilities.html5Stream (with getStreamUrl in its .axe) plays an
  // http(s) URL through that element without the host naming it: Subsonic
  // today, any self-hosted server tomorrow. Local files and SoundCloud
  // share the element but have their own play paths.
  const findLoadedResolver = (id) => (id ? (loadedResolversRef.current || []).find(r => r.id === id) : undefined);
  // A plug-in's display name, from the registry (lib/plugin-names.js, #1521):
  // playback plug-ins, then meta services (Last.fm, ListenBrainz, concert
  // sellers), then anything else the loader holds. Read at call time, so
  // handing it over on every render costs nothing.
  setPluginLookup((id) => findLoadedResolver(id)
    || (metaServicesRef.current || []).find(s => s.id === id)
    || (resolverLoaderRef.current?.getAllResolvers?.() || []).find(r => r.id === id));
  // The same lookup on window for engine-side labels/toasts, never
  // === 'service' arms (capability-not-id rule).
  window.resolverLabelById = (id) => (id ? pluginName(id) : 'Stream');
  // DevTools accessor for a loaded resolver INSTANCE (its plugin methods).
  // The plugin owns every service surface since #1356 — sign-in flows ask
  // `window.__parachordResolver('amazonmusic').signIn()` through the loaded
  // registry, and the plugin's diagnostic capture (debugCaptureGql) is
  // reached the same way from the console (docs/architecture/amazon-music.md,
  // "gql capture"). Null while the resolvers load or for an unknown id.
  window.__parachordResolver = (id) => {
    const loader = resolverLoaderRef.current;
    return (loader && typeof loader.getResolver === 'function') ? (loader.getResolver(id) || null) : null;
  };
  const isHtml5StreamResolver = (id) => !!findLoadedResolver(id)?.capabilities?.html5Stream;
  // Widevine resolvers (capabilities.widevine: Amazon Music today) play
  // encrypted adaptive streams through Shaka on the SAME shared element —
  // manifest/license bytes come from main via window.electron.widevine.
  const isWidevineResolver = (id) => !!findLoadedResolver(id)?.capabilities?.widevine;
  // Local-library resolvers (capabilities.local: Local Files today) play files
  // on disk through the shared element's local-audio: path, need no network,
  // and a source whose file has left the library is a miss (#1520). Asked
  // before the registry loads too (a restored track, a page's first
  // resolutions), when the bundled copy answers: lib/resolver-capabilities.js.
  const isLocalResolver = (id) => isLocalResolverIn(id, loadedResolversRef.current, FALLBACK_RESOLVERS);
  const usesSharedAudio = (id) => isLocalResolver(id) || isHtml5StreamResolver(id) || isWidevineResolver(id);
  // Embedded-player resolvers play in the service's own player, outside the
  // shared element: `capabilities.embedPlayer: true`, with the host adapter
  // (lib/embed-players.js) named by the .axe's top-level
  // `embedPlayer.adapter` (SoundCloud's widget today). The name stays out of
  // `capabilities`, which mobile clients decode as booleans.
  const embedPlayerKind = (id) => {
    const resolver = findLoadedResolver(id);
    if (!resolver?.capabilities?.embedPlayer) return null;
    const kind = resolver.embedPlayer?.adapter;
    // A plugin can name an adapter this build doesn't have (a newer plugin in an
    // older app): it isn't an embedded player here, and its play() still works.
    return typeof kind === 'string' && EMBED_PLAYER_KINDS.includes(kind) ? kind : null;
  };
  // Audio Parachord plays itself, through either path (volume support, the
  // Spotify poll skip).
  const playsInApp = (id) => usesSharedAudio(id) || !!embedPlayerKind(id);
  // The element a resolver's in-app audio plays through, for seek, volume and
  // play/pause: an embedded player's HTMLMediaElement-shaped facade, else the
  // shared <audio>.
  const mediaElementFor = (id) => {
    const kind = embedPlayerKind(id);
    if (kind) {
      const player = window.__parachordEmbedPlayer ? window.__parachordEmbedPlayer(kind) : null;
      return player ? player.element : null;
    }
    return usesSharedAudio(id) ? audioRef.current : null;
  };

  // Cleanup polling interval, external track timeout, and stop playback on unmount
  useEffect(() => {
    // Also handle beforeunload for when window closes
    const handleBeforeUnload = () => {
      // Flush any pending source updates before the window closes
      if (flushCollectionSourcesRef.current) {
        flushCollectionSourcesRef.current();
      }
      if (flushPlaylistSourcesRef.current) {
        flushPlaylistSourcesRef.current();
      }

      if (spotifyTokenRef.current) {
        // Use sendBeacon for reliable delivery during page unload
        const url = 'https://api.spotify.com/v1/me/player/pause';
        // sendBeacon doesn't support PUT, so fall back to fetch with keepalive
        fetch(url, {
          method: 'PUT',
          headers: { 'Authorization': `Bearer ${spotifyTokenRef.current}` },
          keepalive: true
        }).catch(() => {});
      }
    };

    window.addEventListener('beforeunload', handleBeforeUnload);

    return () => {
      window.removeEventListener('beforeunload', handleBeforeUnload);
      // Flush any pending source updates on component unmount
      if (flushCollectionSourcesRef.current) {
        flushCollectionSourcesRef.current();
      }
      if (flushPlaylistSourcesRef.current) {
        flushPlaylistSourcesRef.current();
      }
      if (playbackPollerRef.current) {
        clearInterval(playbackPollerRef.current);
        playbackPollerRef.current = null;
      }
      if (pollingRecoveryRef.current) {
        clearInterval(pollingRecoveryRef.current);
        pollingRecoveryRef.current = null;
      }
      // Also stop main process polling on cleanup
      if (window.electron?.spotify?.polling) {
        window.electron.spotify.polling.stop();
      }
      if (externalTrackTimeoutRef.current) {
        clearTimeout(externalTrackTimeoutRef.current);
        externalTrackTimeoutRef.current = null;
      }
      // Stop Spotify playback on app shutdown
      if (spotifyTokenRef.current) {
        fetch('https://api.spotify.com/v1/me/player/pause', {
          method: 'PUT',
          headers: { 'Authorization': `Bearer ${spotifyTokenRef.current}` },
          keepalive: true
        }).catch(() => {}); // Ignore errors on shutdown
      }
    };
  }, []);


  // Sign in to Amazon Music inside Parachord. Playback uses the shared
  // Widevine player and the CDM built into this Electron build; the session
  // itself is the plugin's since #1356 M10 — the flow below is the renderer's
  // prompt UX (the consent dialog, single-flight, the decline quiet, the
  // hiccup retry) over the plugin's methods: getStatus (the CDM verdict and
  // the signed-in fact), signInPromptDecision (the hiccup rule) and signIn
  // (the visible window with the plugin's own decide rule). The desktop app
  // is not launched. explicit:true always shows the dialog (play button,
  // settings). explicit:false is the background-resolve prompt: one at a
  // time, skipped during radio/auto-advance, and not repeated for 10 minutes
  // after a decline. A second caller shares the in-flight promise so it
  // cannot overwrite onResolve.
  const manageAmazonMusic = async (opts = {}) => {
    const loaded = resolverLoaderRef.current && typeof resolverLoaderRef.current.getResolver === 'function'
      ? resolverLoaderRef.current.getResolver('amazonmusic')
      : null;
    // No prompt without the plugin (not loaded, or an old .axe with no
    // session surface): the prompt IS the plugin's UX.
    if (!loaded || typeof loaded.signIn !== 'function') return false;
    const explicit = opts.explicit !== false;
    if (!explicit && Date.now() < amazonManageDeclinedUntilRef.current) return false;
    // Settings → Sign in passes explicit:true. Radio must not swallow that.
    if (!explicit && (isAdvancingTrackRef.current || spinoffModeRef.current)) {
      console.log('Skipping Amazon connect prompt during auto-advance');
      return false;
    }
    if (!explicit && typeof document !== 'undefined' && document.hidden) return false;
    if (amazonManageInFlightRef.current) return amazonManageInFlightRef.current;

    let finishInFlight;
    const inFlight = new Promise((resolve) => { finishInFlight = resolve; });
    amazonManageInFlightRef.current = inFlight;

    const run = (async () => {
      // The plugin's status reply: the signed-in fact and this build's CDM
      // verdict (the plugin's EME probe — the old host read died with the IPC
      // status). Feeds the tile/settings row on the way by; a read that fails
      // outright (the loader itself) is no verdict, like the old IPC catch.
      const status = await refreshPluginStatus('amazonmusic').catch(() => null);
      if (status && status.cdm === false) {
        showToast('This Parachord build has no Widevine CDM, so Amazon Music cannot play.', 'error');
        return false;
      }
      // A not-signed-in while the auth cookies say the session is live is
      // usually Amazon's periodic session-token refresh catching a page load:
      // retry quietly instead of prompting. Only a streak lasting a minute
      // (most likely the profile picker) prompts. Settings' Sign in button
      // passes forcePrompt and always gets the window. The rule is the
      // plugin's (signInPromptDecision); an old .axe without the method
      // prompts at once, the pre-#1172 behavior.
      if (!opts.forcePrompt) {
        const verdict = typeof loaded.signInPromptDecision === 'function'
          ? loaded.signInPromptDecision({
              reason: opts.reason,
              cookiesSignedIn: !!(status && status.signedIn),
              streak: amazonSignInHiccupRef.current,
              now: Date.now()
            })
          : { prompt: true, streak: { firstAt: 0, lastAt: 0 } };
        amazonSignInHiccupRef.current = verdict.streak;
        if (!verdict.prompt) {
          console.log('[Amazon] not signed in, but the session cookies are live: retrying quietly instead of prompting');
          await new Promise(r => setTimeout(r, 2000));
          return true;
        }
      }
      const granted = await new Promise((resolve) => {
        setAmazonManageDialog({ show: true, onResolve: resolve, relaunching: false });
      });
      if (!granted) {
        amazonManageDeclinedUntilRef.current = Date.now() + 10 * 60 * 1000;
        return false;
      }
      setAmazonManageDialog({ show: true, onResolve: null, relaunching: true });
      const login = await loaded.signIn();
      setAmazonManageDialog({ show: false, onResolve: null, relaunching: false });
      refreshPluginStatus('amazonmusic');
      if (login && login.signedIn) {
        amazonSignInHiccupRef.current = { firstAt: 0, lastAt: 0 };
        showToast('Signed in to Amazon Music', 'success');
        if (typeof window.__parachordClearAmazonNoMatch === 'function') window.__parachordClearAmazonNoMatch();
        return true;
      }
      // The sign-in window closed without a session: the same quiet period as
      // declining the prompt. Without it the next background search's
      // not-signed-in reopened the prompt at once, and again after every close.
      amazonManageDeclinedUntilRef.current = Date.now() + 10 * 60 * 1000;
      return false;
    })().catch((error) => {
      setAmazonManageDialog({ show: false, onResolve: null, relaunching: false });
      console.error('Amazon Music sign-in failed:', error);
      return false;
    });

    try {
      const ok = await run;
      finishInFlight(ok);
      return ok;
    } finally {
      amazonManageInFlightRef.current = null;
    }
  };
  window.__parachordManageAmazonMusic = manageAmazonMusic;

  // The playback engine's "this plug-in needs sign-in" prompt (#1523): a play
  // refused with reason 'not-signed-in' asks the plug-in that refused,
  // routed by the registry, never by name. Only a plug-in on the status
  // surface (capabilities.status) with a signIn method can be prompted. A
  // plug-in whose sign-in carries host UX of its own runs that flow (Amazon's
  // consent dialog, hiccup rule and CDM gate, manageAmazonMusic above, which
  // the plug-in dialog's Sign in and connectPlugin also use); any other runs
  // its own signIn() and reports whether it ended signed in.
  const hostSignInFlows = { amazonmusic: manageAmazonMusic };
  const promptablePlugin = (resolverId) => {
    const plugin = resolverLoaderRef.current && typeof resolverLoaderRef.current.getResolver === 'function'
      ? resolverLoaderRef.current.getResolver(resolverId)
      : null;
    return plugin && plugin.capabilities && plugin.capabilities.status && typeof plugin.signIn === 'function' ? plugin : null;
  };
  const promptPluginSignIn = async (resolverId, opts = {}) => {
    const plugin = promptablePlugin(resolverId);
    if (!plugin) return false;
    const flow = hostSignInFlows[resolverId];
    if (flow) return flow(opts);
    try {
      const login = await plugin.signIn();
      return !!(login && login.signedIn);
    } catch (error) {
      console.error(`${plugin.name} sign-in failed:`, error);
      return false;
    } finally {
      refreshPluginStatus(resolverId).catch(() => {});
    }
  };
  promptPluginSignIn.canPrompt = (resolverId) => !!promptablePlugin(resolverId);
  window.__parachordPromptPluginSignIn = promptPluginSignIn;

  // The generic plugin-status surface (capabilities.status, #1356): a plugin
  // that can report its sign-in/playback-limit state implements getStatus,
  // and the renderer asks it through the resolver registry (resolver-loader.js
  // getStatusResolvers/getStatus — direct, renderer-side, no new IPC). Amazon
  // is on this surface since #1356 M10: its tile's "Setup required"/
  // "Prime: no playback", its settings row and its limit-map entry all read
  // the plugin's reply, and the prompt flow above reads the same reply for
  // the CDM gate and the hiccup rule.

  // One plugin's status read. The loader logs and swallows a throwing or
  // hung getStatus and bounds the read (STATUS_BUDGET_MS — a status outage
  // must not unplug playback, and one hung read must not stall the sweep
  // below), so the reply here is a verdict, the loader's failed marker, or
  // null; each is stored as-is — a failure is no verdict for the limit map
  // (lib/playback-limits.js pluginStatusLimit) and the honest error row
  // (pluginStatusRow), and a null (never asked) stays "Checking…".
  // Returns the reply's promise (manageAmazonMusic reads it for the CDM gate),
  // so a caller can both await the verdict and let it feed the map.
  const refreshPluginStatus = (resolverId) => {
    const loader = resolverLoaderRef.current;
    if (!loader || typeof loader.getStatus !== 'function') return Promise.resolve(null);
    return loader.getStatus(resolverId).then((status) => {
      setPluginStatuses(prev => ({ ...prev, [resolverId]: status }));
      return status;
    });
  };

  // Read every ACTIVE status-capable plugin. Only active ones: a disabled
  // plugin's status has no reader (its tile is inactive, and playback never
  // asks it). One sweep is ONE setPluginStatuses, the whole batch landing
  // together (every setState is a full-app render — coalesce the burst); a
  // throwing or hung getStatus never rejects it, because the loader has
  // already logged the throw and answers its failed marker (a hung one
  // settles at the read budget, STATUS_BUDGET_MS — one plugin's hang can't
  // stall the batch, which is why the reads can be batched at all), stored
  // as-is like the single read above (a real rejection is the loader itself
  // failing, and that resolver gets no entry). The reads in flight are held
  // per resolver (pluginStatusReadsRef), so a re-run while one is still
  // pending — a startup dep changed — reads only what nothing is reading: no
  // pending call is re-issued.
  const pluginStatusReadsRef = useRef(new Set());
  const refreshPluginStatuses = () => {
    const loader = resolverLoaderRef.current;
    if (!loader || typeof loader.getStatusResolvers !== 'function') return;
    const ids = loader.getStatusResolvers()
      .filter(r => activeResolvers.includes(r.id))
      .map(r => r.id)
      .filter(id => !pluginStatusReadsRef.current.has(id));
    if (!ids.length) return;
    ids.forEach(id => pluginStatusReadsRef.current.add(id));
    Promise.allSettled(ids.map(id => loader.getStatus(id))).then((replies) => {
      ids.forEach(id => pluginStatusReadsRef.current.delete(id));
      // A sweep in flight when an uninstall lands must not write the
      // uninstalled plugin's entry back: the reads started before the
      // uninstall, so their replies are a dead plugin's. Re-check the loaded
      // set HERE, when the batch lands — not only the set the sweep fired
      // with — and through the ref (loadedResolversRef, kept current by the
      // effect), not this render's loadedResolvers: the landing happens
      // after the render the uninstall committed (the uninstall drops the
      // entry itself; this keeps the drop held).
      const stillLoaded = new Set((loadedResolversRef.current || []).map(r => r.id));
      const statuses = {};
      ids.forEach((id, i) => {
        if (!stillLoaded.has(id)) return;
        if (replies[i].status === 'fulfilled') statuses[id] = replies[i].value;
      });
      setPluginStatuses(prev => ({ ...prev, ...statuses }));
    });
  };

