    flushTrackSources(); // apply queued per-track writes before the bulk rewrite
    setTrackSources(prev => {
      let changed = false;
      const next = { ...prev };
      for (const key of Object.keys(next)) {
        if (!next[key]?.[resolverId]?.noMatch) continue;
        const copy = { ...next[key] };
        delete copy[resolverId];
        if (copy.__noMatchAll) delete copy.__noMatchAll;
        next[key] = copy;
        changed = true;
      }
      return changed ? next : prev;
    });
