  // per resolver across restarts: the upgrade can happen while the app is
  // closed (lib/playback-limits.js, #1220).
  useEffect(() => {
    for (const [resolverId, limit] of Object.entries(playbackLimits)) {
      const key = PlaybackLimits.limitStorageKey(resolverId);
      let last = null;
      try { last = localStorage.getItem(key); } catch (e) {}
      const { reresolve, store } = PlaybackLimits.limitTransition(last, limit);
      if (reresolve) {
        console.log(`[Playback limits] ${resolverId} can play now (${limit.planKey}); searching it again`);
        clearResolverMisses(resolverId);
      }
      if (store !== null && store !== last) {
        try { localStorage.setItem(key, store); } catch (e) {}
      }
    }
  }, [playbackLimits]);

  // The engine's plan refusal (reason 'plan-ineligible') reports here: record
  // the plan the service just told us, and return the wording to show (null:
  // the refusal's own message is shown). A plugin checks this hook exists
  // before throwing plan-ineligible (docs/architecture/plugins.md).
  window.__parachordNotePlanRefusal = (resolverId, planKey) => {
    // A status-capable plugin's refusal says its reported status is stale:
    // re-read it. The refusal itself already carries the wording to show (the
    // plugin's own plan message), so the reply only refreshes the map, the
    // tile and the Settings row. Amazon is a status-capable plugin since
    // #1356 M10, so the same path covers it.
    const statusLoader = resolverLoaderRef.current;
    if (statusLoader?.getStatusResolvers && statusLoader.getStatusResolvers().some(r => r.id === resolverId)) {
      refreshPluginStatus(resolverId);
    }
    return null;
  };


  // Cache for artist images from Last.fm (artistName -> { url, timestamp })
  const artistImageCache = useRef({});

  // Cache for artist extended info from MusicBrainz (mbid -> { info, timestamp })
  const artistExtendedInfoCache = useRef({});

  // Cache for MBID Mapper lookups (artist|title -> { result: { recording_mbid, artist_credit_mbids, ... }, timestamp })
  // Uses ListenBrainz MBID Mapper v2.0 for fast metadata-to-MBID resolution (~4ms)
  const mbidMapperCache = useRef({});
  const releaseDetailsCache = useRef({}); // MB release details (tracklist + artist credits) by release ID; persisted as cache_release_details
  // The MusicBrainz release group each album lookup settled on, by artist and
  // album, for the session: opening an album that was just queued needs no
  // search (src/renderer/lib/release-open.js).
  const releaseGroupPicksRef = useRef(null);
  if (!releaseGroupPicksRef.current) releaseGroupPicksRef.current = createReleaseGroupPicks();

  // Cache for playlist cover art (playlistId -> { covers: [url1, url2, url3, url4], timestamp })
  const playlistCoverCache = useRef({});

  // API keys loaded from environment via IPC (fallback)
