  // Calculate confidence score for a resolver match (0-1).
  //
  // SYNC: tests/helpers/confidence-scoring.js — keep byte-identical with the
  // body in that file. Cross-platform invariant: must match
  // parachord-mobile/shared/.../resolver/ResolverModels.kt#scoreConfidence
  // so desktop and Android pick the same source for the same track.
  //
  // Both axes (title AND artist) must containment-match the target, else the
  // score collapses to 0.50 and the source-selection floor (0.6) drops it.
  // Title-only or artist-only matches are wrong-song candidates and must not
  // be allowed to outrank correct matches from lower-priority resolvers.
  // Canonical copy: sync-providers/confidence-scoring.js (window.ConfidenceScoring).
  const calculateConfidence = window.ConfidenceScoring.calculateConfidence;

  // Library localfiles rows identify the recording by path and often omit
  // artist/title. calculateConfidence then returns 0.5, and the selection
  // floor drops a file that is on disk — Collection click shows "No Enabled
  // Source" for a track whose badge is the local resolver. Keep the stored
  // score in that case; only rescore sources that actually carry names.
  const confidenceForSource = (target, source) => {
    if (source?.filePath && (!source.artist || !source.title)) {
      return typeof source.confidence === 'number' ? source.confidence : 1.0;
    }
    return calculateConfidence(target, source);
  };

  // Fetch album art suggestions from MusicBrainz/Cover Art Archive
  const fetchAlbumArtSuggestions = async (artist, album) => {
    if (!artist || !album) {
      setId3ArtSuggestions([]);
      return;
    }

    setId3ArtLoading(true);
    setId3ArtSuggestions([]);

    try {
      // Search MusicBrainz for releases matching artist and album
      const query = encodeURIComponent(`artist:"${artist}" AND release:"${album}"`);
      const searchUrl = `https://musicbrainz.org/ws/2/release?query=${query}&fmt=json&limit=5`;

      console.log('🎨 Searching MusicBrainz for album art:', artist, '-', album);

      const response = await fetch(searchUrl, {
        headers: {
          'User-Agent': 'Parachord/1.0.0 (https://github.com/parachord)'
        }
      });

      if (!response.ok) {
        throw new Error(`MusicBrainz search failed: ${response.status}`);
      }

      const data = await response.json();
      const releases = data.releases || [];

      console.log(`🎨 Found ${releases.length} releases`);

      // For each release, check if Cover Art Archive has artwork
      const artPromises = releases.slice(0, 5).map(async (release) => {
        try {
          const artUrl = `https://coverartarchive.org/release/${release.id}`;
          const artResponse = await fetch(artUrl, {
            headers: {
              'User-Agent': 'Parachord/1.0.0 (https://github.com/parachord)'
            }
          });

          if (artResponse.ok) {
            const artData = await artResponse.json();
            const frontArt = artData.images?.find(img => img.front) || artData.images?.[0];

            if (frontArt) {
              return {
                releaseId: release.id,
                releaseName: release.title,
                artistName: release['artist-credit']?.[0]?.name || artist,
                year: release.date?.split('-')[0] || '',
                thumbnailUrl: frontArt.thumbnails?.small || frontArt.thumbnails?.['250'] || frontArt.image,
                fullUrl: frontArt.image
              };
            }
          }
          return null;
        } catch (err) {
          // Silently fail for individual releases
          return null;
        }
      });

      const artResults = (await Promise.all(artPromises)).filter(Boolean);
      console.log(`🎨 Found ${artResults.length} releases with artwork`);

      setId3ArtSuggestions(artResults);
    } catch (error) {
      console.error('Error fetching album art suggestions:', error);
      setId3ArtSuggestions([]);
    } finally {
      setId3ArtLoading(false);
    }
  };

  // Auto-fetch album art suggestions when artist or album changes in ID3 editor
  useEffect(() => {
    // Only run when editor is open
    if (!id3EditorOpen) return;

    const artist = id3EditorValues.artist?.trim();
    const album = id3EditorValues.album?.trim();

    // Need both artist and album
    if (!artist || !album) {
      return;
    }

    // Create a key to track what we've already fetched
    const fetchKey = `${artist}|${album}`;
    if (fetchKey === id3ArtFetchKey) {
      return; // Already fetched for this combination
    }

    // Clear selection when search criteria change
    setId3SelectedArt(null);

    // Debounce the fetch
    const timer = setTimeout(() => {
      setId3ArtFetchKey(fetchKey);
      fetchAlbumArtSuggestions(artist, album);
    }, 500);

    return () => clearTimeout(timer);
  }, [id3EditorOpen, id3EditorValues.artist, id3EditorValues.album]);

  // Reset fetch key when editor closes
  useEffect(() => {
    if (!id3EditorOpen) {
      setId3ArtFetchKey('');
    }
  }, [id3EditorOpen]);

  // Reorder album art queue to prioritize visible albums
  const reprioritizeAlbumArtQueue = () => {
    const queue = albumArtQueue.current;
    if (queue.length === 0) return;

    const visible = [];
    const nonVisible = [];

    for (const item of queue) {
      if (visibleAlbumIds.current.has(item.id)) {
        visible.push(item);
      } else {
        nonVisible.push(item);
      }
    }

    albumArtQueue.current = [...visible, ...nonVisible];
  };

  // Cover for one release on the artist page: getAlbumArt, THE album-art
  // pipeline, with the release group's id (a MusicBrainz artist page's
  // releases are release groups) and its MusicBrainz search, if any, in the
  // background lane. This used to be a fetcher of its own: the Cover Art
  // Archive's release-group JSON, then for every release without one a
  // FOREGROUND MusicBrainz lookup of the group's first release (one a second,
  // ahead of the user's next click, for a cover the release-group endpoint
  // already looks across every release for), then a resolver search.
  const fetchSingleAlbumArt = async (release) => {
    // release.artist: tagged when queued (withArtArtist); currentArtist here
    // can be a render behind
    const artistName = (typeof release.artist === 'string' ? release.artist : release.artist?.name)
      || currentArtist?.name;
    if (!release.title) return null;
    return getAlbumArt(artistName, release.title, {
      ...(isMusicBrainzId(release.id) ? { releaseGroupId: release.id } : {}),
      background: true
    });
  };

  // Process album art queue with viewport prioritization
  const processAlbumArtQueue = async () => {
    if (isAlbumArtFetching.current) return;
    isAlbumArtFetching.current = true;

    // Increment fetch ID to detect stale loops (navigation away)
    albumArtFetchId.current++;
    const currentFetchId = albumArtFetchId.current;

    console.log('🎨 Starting viewport-prioritized album art loading...');
    let loadedCount = 0;
    let consecutiveFailures = 0;
    let batchSize = 4;

    while (albumArtQueue.current.length > 0 && albumArtFetchId.current === currentFetchId) {
      // Reprioritize queue based on current viewport
      reprioritizeAlbumArtQueue();

      // Check how many visible items are at the front
      const visibleBatch = [];
      for (let i = 0; i < Math.min(batchSize, albumArtQueue.current.length); i++) {
        const item = albumArtQueue.current[i];
        if (visibleAlbumIds.current.has(item.id)) {
          visibleBatch.push(item);
        } else {
          break; // Stop at first non-visible item
        }
      }

      if (visibleBatch.length > 0) {
        // Parallel fetch for visible items
        albumArtQueue.current = albumArtQueue.current.slice(visibleBatch.length);

        const results = await Promise.all(
          visibleBatch.map(async (release) => {
            try {
              // Skip if already cached (race condition check)
              if (albumArtCache.current[release.id]) {
                return { release, url: albumArtCache.current[release.id].url, cached: true };
              }

              const url = await fetchSingleAlbumArt(release);
              return { release, url, cached: false };
            } catch (error) {
              console.warn(`Failed to fetch art for ${release.title}:`, error);
              return { release, url: null, error: true };
            }
          })
        );

        // Process results
        for (const { release, url, cached, error } of results) {
          if (cached) continue;

          if (error) {
            consecutiveFailures++;
            if (consecutiveFailures >= 3) {
              batchSize = Math.max(2, batchSize - 1);
              consecutiveFailures = 0;
            }
          } else {
            consecutiveFailures = 0;
            if (loadedCount > 10 && batchSize < 4) {
              batchSize = 4; // Restore batch size after successes
            }
          }

          if (url) {
            albumArtCache.current[release.id] = { url, timestamp: Date.now() };
            loadedCount++;
          }

          // Update state for this release
          setArtistReleases(prev =>
            prev.map(r =>
              r.id === release.id
                ? { ...r, albumArt: url }
                : r
            )
          );
        }
      } else {
        // Sequential fetch for non-visible items (background loading)
        const release = albumArtQueue.current.shift();

        // Skip if already cached
        if (albumArtCache.current[release.id]) {
          continue;
        }

        try {
          const url = await fetchSingleAlbumArt(release);

          if (url) {
            albumArtCache.current[release.id] = { url, timestamp: Date.now() };
            loadedCount++;
          }

          setArtistReleases(prev =>
            prev.map(r =>
              r.id === release.id
                ? { ...r, albumArt: url }
                : r
            )
          );

          consecutiveFailures = 0;
        } catch (error) {
          setArtistReleases(prev =>
            prev.map(r =>
              r.id === release.id
                ? { ...r, albumArt: null }
                : r
            )
          );
          consecutiveFailures++;
        }

        // Delay for non-visible items to avoid hammering API
        await new Promise(resolve => setTimeout(resolve, 100));
      }
    }

    console.log(`🎨 Album art loading complete: ${loadedCount} loaded`);
    isAlbumArtFetching.current = false;

    // Save cache after loading
    if (loadedCount > 0) {
      saveCacheToStore();
    }
  };


  // Remove a resolver's sources from all track data (trackSources, playlistTracks, queue, library)
  const removeResolverSources = (resolverId) => {
    console.log(`🧹 Removing sources for disabled/uninstalled resolver: ${resolverId}`);

    // Remove from trackSources (release/album view)
    flushTrackSources(); // queued writes first, so none re-adds the resolver after this
    setTrackSources(prev => {
      const updated = {};
      for (const [trackKey, sources] of Object.entries(prev)) {
        const { [resolverId]: removed, ...remainingSources } = sources;
        if (Object.keys(remainingSources).length > 0) {
          updated[trackKey] = remainingSources;
        }
      }
      return updated;
    });

    // Remove from playlistTracks
    setPlaylistTracks(prev =>
      prev.map(track => {
        if (track.sources && track.sources[resolverId]) {
          const { [resolverId]: removed, ...remainingSources } = track.sources;
          return { ...track, sources: remainingSources };
        }
        return track;
      })
    );

    // Remove from currentQueue
    setCurrentQueue(prev =>
      prev.map(track => {
        if (track.sources && track.sources[resolverId]) {
          const { [resolverId]: removed, ...remainingSources } = track.sources;
          return { ...track, sources: remainingSources };
        }
        return track;
      })
    );

    // Remove from library
    setLibrary(prev =>
      prev.map(track => {
        if (track.sources && track.sources[resolverId]) {
          const { [resolverId]: removed, ...remainingSources } = track.sources;
          return { ...track, sources: remainingSources };
        }
        return track;
      })
    );

    // Also clean up the cache
    if (trackSourcesCache.current) {
      for (const [cacheKey, cacheEntry] of Object.entries(trackSourcesCache.current)) {
        if (cacheEntry.sources && cacheEntry.sources[resolverId]) {
          const { [resolverId]: removed, ...remainingSources } = cacheEntry.sources;
          markTrackSourcesDirty();
          trackSourcesCache.current[cacheKey] = {
            ...cacheEntry,
            sources: remainingSources
          };
        }
      }
    }
  };

  const toggleResolver = (resolverId) => {
    const isCurrentlyActive = activeResolvers.includes(resolverId);

    // If disabling, remove the resolver's sources from all tracks
    if (isCurrentlyActive) {
      removeResolverSources(resolverId);
    }

    setActiveResolvers(prev =>
      prev.includes(resolverId)
        ? prev.filter(id => id !== resolverId)
        : [...prev, resolverId]
    );

    if (isCurrentlyActive) {
      // Disabling: remove from resolverOrder (only active resolvers get a priority slot)
      setResolverOrder(prev => prev.filter(id => id !== resolverId));
    } else {
      // Enabling: add to resolverOrder in canonical position
      setResolverOrder(prev => {
        if (!prev.includes(resolverId)) {
          return insertRemembered(prev, resolverId, savedResolverOrderRef.current);
        }
        return prev;
      });
    }
  };

  // Drag and drop handlers for resolver reordering
  const handleResolverDragStart = (e, resolverId) => {
    setDraggedResolver(resolverId);
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/html', e.target);
  };

  const handleResolverDragOver = (e) => {
    if (e.preventDefault) {
      e.preventDefault();
    }
    e.dataTransfer.dropEffect = 'move';
    return false;
  };

  const handleResolverDragEnter = (e, resolverId) => {
    e.preventDefault();
    if (draggedResolver && draggedResolver !== resolverId) {
      setDragOverResolver(resolverId);
    }
  };

  const handleResolverDragLeave = (e) => {
    e.preventDefault();
    // Only clear if we're leaving the card entirely (not entering a child)
    const relatedTarget = e.relatedTarget;
    if (!relatedTarget || !e.currentTarget.contains(relatedTarget)) {
      setDragOverResolver(null);
    }
  };

  const handleResolverDrop = (e, targetResolverId) => {
    if (e.stopPropagation) {
      e.stopPropagation();
    }

    if (draggedResolver !== targetResolverId) {
      setResolverOrder(prev => {
        const newOrder = [...prev];
        const draggedIndex = newOrder.indexOf(draggedResolver);
        const targetIndex = newOrder.indexOf(targetResolverId);
        if (draggedIndex === -1 || targetIndex === -1) return prev;

        // Remove dragged item and insert at target position
        newOrder.splice(draggedIndex, 1);
        newOrder.splice(targetIndex, 0, draggedResolver);

        console.log('Resolver order updated:', newOrder);
        return newOrder;
      });
    }

    setDraggedResolver(null);
    setDragOverResolver(null);
    return false;
  };

  const handleResolverDragEnd = () => {
    setDraggedResolver(null);
    setDragOverResolver(null);
  };

  // Install new resolver from .axe file (hot-reload, no restart)
  const handleInstallResolver = async () => {
    if (!window.electron?.resolvers?.pickFile) {
      showConfirmDialog({
        type: 'error',
        title: 'Not available',
        message: 'File picker not available. Make sure you are running in Electron.'
      });
      return;
    }

    console.log('📦 Opening file picker for resolver...');

    try {
      const result = await window.electron.resolvers.pickFile();

      if (!result) {
        console.log('User cancelled file picker');
        return;
      }

      if (result.error) {
        showConfirmDialog({
          type: 'error',
          title: 'File error',
          message: result.error
        });
        return;
      }
      
      const { content, filename } = result;
      
      // Parse to validate and get info
      const axe = JSON.parse(content);
      const resolverName = axe.manifest.name;
      const resolverId = axe.manifest.id;
      
      // Check if already installed
      const existing = allResolvers.find(r => r.id === resolverId);
      if (existing) {
        const shouldOverwrite = await confirmAsync({
          title: `Replace ${resolverName}?`,
          message: `${resolverName} is already installed. Replace it with this file?`,
          confirmLabel: 'Replace',
        });
        if (!shouldOverwrite) {
          return;
        }
      }
      
      console.log(`Installing resolver: ${resolverName}`);
      
      // Install via IPC
      const installResult = await window.electron.resolvers.install(content, filename);
      
      if (!installResult.success) {
        showConfirmDialog({
          type: 'error',
          title: 'Installation failed',
          message: installResult.error
        });
        return;
      }
      
      console.log(`✅ Installed ${resolverName}`);
      
      // Hot-reload: Load the new resolver without restarting
      try {
                axe._filename = filename;
        // The hostBridges hide rule, same as the main load path (#1432 review,
        // note 7): the install itself is NOT gated (the .axe runs where the
        // host has its bridges — a file-installed plugin may target another
        // host), but this host does not LOAD one whose bridges it lacks.
        if (hideAxesLackingHostBridges([axe]).length === 0) {
          showToast(`${resolverName} installed but hidden on this host (it needs bridges this app doesn't supply)`, 'info');
          return;
        }
        const newResolverInstance = await resolverLoader.current.loadResolver(axe);
        // Wrap the newly-loaded resolver's search through the global limiter
        // (parachord#797) — same treatment as the primary load path.
        window.wrapResolverSearchesWithLimiter([newResolverInstance]);
        // And its play reporting, same as the primary load path (#1546).
        await initPlaybackTelemetry(resolverLoader.current, [newResolverInstance], (id) => getResolverConfigRef.current ? getResolverConfigRef.current(id) : {});

        if (existing) {
          // Replace existing resolver
          setLoadedResolvers(prev => prev.map(r =>
            r.id === resolverId ? newResolverInstance : r
          ));
          console.log(`🔄 Updated resolver: ${resolverName}`);
          showToast(`${resolverName} updated`, 'success');
        } else {
          // Add new resolver
          setLoadedResolvers(prev => [...prev, newResolverInstance]);

          // Add to resolver order
          setResolverOrder(prev => appendUniqueId(prev, resolverId));

          // Enable by default
          setActiveResolvers(prev => appendUniqueId(prev, resolverId));

          console.log(`➕ Added resolver: ${resolverName}`);
          showToast(`${resolverName} installed`, 'success');
        }
      } catch (error) {
        console.error('Failed to hot-load resolver:', error);
        showConfirmDialog({
          type: 'error',
          title: 'Restart to finish',
          message: 'The plug-in was installed but didn’t load. Restart Parachord to finish.'
        });
      }
    } catch (error) {
      console.error('Error installing resolver:', error);
      showConfirmDialog({
        type: 'error',
        title: 'Couldn’t install the plug-in',
        message: errorText(error, 'Try again. If it keeps failing, restart Parachord.')
      });
    }
  };

  // Uninstall resolver (remove from state and optionally delete from disk)
  const handleUninstallResolver = async (resolverId) => {
    console.log('=== handleUninstallResolver called ===');
    console.log('  Resolver ID:', resolverId);
    console.log('  Loaded resolvers count (ref):', loadedResolversRef.current.length);
    console.log('  Loaded resolver IDs (ref):', loadedResolversRef.current.map(r => r.id));

    // Check both content resolvers and meta-services
    const resolver = loadedResolversRef.current.find(r => r.id === resolverId)
      || metaServices.find(s => s.id === resolverId);
    const isMetaService = !loadedResolversRef.current.find(r => r.id === resolverId) && !!resolver;

    const resolverName = resolver?.name || resolverId;

    console.log('  Found resolver:', resolverName, isMetaService ? '(meta-service)' : resolver ? '(content)' : '(not in state)');

    // Check if this plugin is available in the marketplace (can be reinstalled easily)
    const isInMarketplace = marketplaceManifest?.plugins?.some(r => r.id === resolverId);

    // Use simpler confirmation for marketplace plugins since they can be easily reinstalled
    const confirmMessage = isInMarketplace
      ? 'You can install it again from the marketplace.'
      : 'It isn’t in the marketplace, so you can’t install it again from there.';

    const shouldUninstall = await confirmAsync({ title: `Remove ${resolverName}?`, message: confirmMessage, confirmLabel: 'Remove', destructive: true });

    if (!shouldUninstall) {
      return;
    }

    console.log(`🗑️ Uninstalling resolver: ${resolverName}`);

    try {
      // Try to delete the resolver file from disk
      const result = await window.electron.resolvers.uninstall(resolverId);

      if (!result.success && result.error !== 'Plugin not found') {
        console.error('Plug-in removal failed:', result.error);
        showToast(`Couldn’t remove ${resolverName}. Restart Parachord and try again.`, 'error');
        return;
      }

      // Use name from backend result if we didn't have it in state
      const displayName = result.name || resolverName;
      console.log(`✅ Uninstalled ${displayName}`);

      // Remove the resolver's sources from all displayed tracks
      removeResolverSources(resolverId);

      // Hot-reload: Remove from state without restarting
      if (isMetaService) {
        setMetaServices(prev => prev.filter(s => s.id !== resolverId));
        // Clear the service's config so dependent features (recommendations, weekly jams) stop
        await clearMetaServiceConfig(resolverId);
        // Clear cached data that depends on this service
        if (resolverId === 'lastfm' || resolverId === 'listenbrainz') {
          setRecommendations({ sections: [], loading: false, error: 'not_configured' });
          recommendationsCache.current = { providers: {}, timestamp: 0 };
          saveRecommendationsCache();
        }
        if (resolverId === 'listenbrainz') {
          setHomeData(prev => ({ ...prev, weeklyJams: null, weeklyExploration: null }));
        }
      } else {
        setLoadedResolvers(prev => prev.filter(r => r.id !== resolverId));
      }
      setResolverOrder(prev => prev.filter(id => id !== resolverId));
      setActiveResolvers(prev => prev.filter(id => id !== resolverId));
      // Drop its status reply too (a status-capable plugin): the entry is
      // the last read's answer, and a reinstalled plugin starts fresh — the
      // entry it left behind is neither its verdict nor anyone else's.
      // (playbackResolverIds filters active ids anyway, so this is honesty,
      // not correctness.)
      setPluginStatuses(prev => {
        if (!(resolverId in prev)) return prev;
        const next = { ...prev };
        delete next[resolverId];
        return next;
      });

      // Save the uninstalled resolver ID so it doesn't reappear on restart
      const uninstalledResolvers = await window.electron.store.get('uninstalled_resolvers') || [];
      if (!uninstalledResolvers.includes(resolverId)) {
        await window.electron.store.set('uninstalled_resolvers', [...uninstalledResolvers, resolverId]);
      }

      showToast(`Removed ${displayName}`, 'success');
    } catch (error) {
      console.error('Error uninstalling resolver:', error);
      showToast(`Couldn’t remove ${resolverName}. Restart Parachord and try again.`, 'error');
    }
  };

  // Marketplace functions
  const loadMarketplaceManifest = async () => {
    if (!window.electron?.resolvers?.getMarketplaceManifest) {
      console.error('Marketplace not available');
      return;
    }

    setMarketplaceLoading(true);

    try {
      const result = await window.electron.resolvers.getMarketplaceManifest();
      setMarketplaceError(!result.success);

      if (result.success) {
        setMarketplaceManifest(result.manifest);
        console.log(`✅ Loaded marketplace with ${result.manifest.plugins.length} plugins`);
      } else {
        console.error('Failed to load marketplace:', result.error);
        setMarketplaceManifest({ version: '1.0.0', plugins: [] });
      }
    } catch (error) {
      console.error('Marketplace load error:', error);
      setMarketplaceError(true);
      setMarketplaceManifest({ version: '1.0.0', plugins: [] });
    } finally {
      setMarketplaceLoading(false);
    }
  };

  // Install resolver from marketplace
  const handleInstallFromMarketplace = async (marketplaceResolver) => {
    const { id, name, downloadUrl, builtin } = marketplaceResolver;

    // Check if already installing
    if (installingResolvers.has(id)) {
      return;
    }

    setInstallingResolvers(prev => new Set(prev).add(id));

    console.log(`📦 Installing ${name} from marketplace...`);

    try {
      // For builtin resolvers, enable them directly if already loaded
      if (builtin) {
        const existing = allResolvers.find(r => r.id === id);
        if (existing) {
          // Already loaded - just enable it
          if (!activeResolvers.includes(id)) {
            setActiveResolvers(prev => appendUniqueId(prev, id));
            if (!resolverOrder.includes(id)) {
              setResolverOrder(prev => appendUniqueId(prev, id));
            }
            showToast(`${name} enabled`, 'success');
          } else {
            showToast(`${name} is already enabled`, 'info');
          }
          return;
        }

        // Bundled meta-services (e.g. Achordion playback-telemetry) are loaded
        // into the metaServices state at app start, not into loadedResolvers.
        // For these, "install" is a no-op — they're already running once bundled
        // and removed from `uninstalled_resolvers`.
        const existingMetaService = metaServices.find(s => s.id === id);
        if (existingMetaService) {
          showToast(`${name} enabled`, 'success');
          return;
        }

        // Check FALLBACK_RESOLVERS
        const fallbackResolver = FALLBACK_RESOLVERS.find(r => r.manifest?.id === id);
        if (fallbackResolver) {
          const instance = { ...fallbackResolver, id, name, enabled: true };
          // Wrap through the global limiter (parachord#797) before mounting.
          window.wrapResolverSearchesWithLimiter([instance]);
          setLoadedResolvers(prev => [...prev, { ...instance, weight: prev.length }]);
          setResolverOrder(prev => appendUniqueId(prev, id));
          setActiveResolvers(prev => appendUniqueId(prev, id));
          showToast(`${name} enabled`, 'success');
          return;
        }

        // Not loaded and not in fallbacks - fall through to download if URL available
        if (!downloadUrl) {
          showConfirmDialog({
            type: 'info',
            title: 'Not available',
            message: `${name} is not available in this build. Please update the app to get this feature.`
          });
          return;
        }
        // Fall through to download logic below
      }

      // Download resolver from URL
      const downloadResult = await window.electron.resolvers.downloadFromMarketplace(downloadUrl);

      if (!downloadResult.success) {
        showConfirmDialog({
          type: 'error',
          title: 'Download failed',
          message: `Failed to download ${name}: ${downloadResult.error}`
        });
        return;
      }

      const { content, filename, resolver: axe } = downloadResult;
      const resolverName = axe.manifest.name;
      const resolverId = axe.manifest.id;

      // Check if already installed (content resolvers or meta-services)
      const existing = allResolvers.find(r => r.id === resolverId)
        || metaServices.find(s => s.id === resolverId);
      if (existing) {
        const shouldOverwrite = await confirmAsync({
          title: `Update ${resolverName}?`,
          message: `Installed: ${existing.version}\nMarketplace: ${axe.manifest.version}`,
          confirmLabel: 'Update',
        });
        if (!shouldOverwrite) {
          return;
        }
      }

      // Install via IPC (reuse existing install handler)
      const installResult = await window.electron.resolvers.install(content, filename);

      if (!installResult.success) {
        showConfirmDialog({
          type: 'error',
          title: 'Installation failed',
          message: `Failed to install ${resolverName}: ${installResult.error}`
        });
        return;
      }

      // Hot-reload
            axe._filename = filename;
      const isMetaService = axe.manifest?.type === 'meta-service';

      // Remove from uninstalled list if it was previously uninstalled
      const uninstalledResolvers = await window.electron.store.get('uninstalled_resolvers') || [];
      if (uninstalledResolvers.includes(resolverId)) {
        await window.electron.store.set('uninstalled_resolvers', uninstalledResolvers.filter(id => id !== resolverId));
      }

      // The hostBridges hide rule, same as the main load path (#1432 review,
      // note 7): installed but not LOADED on a host that lacks its bridges —
      // the marketplace download itself is not gated (hiding is a load-time
      // decision, not a download-time one), so the install completes and the
      // plugin runs on hosts that supply its bridges.
      if (hideAxesLackingHostBridges([axe]).length === 0) {
        showConfirmDialog({
          type: 'info',
          title: 'Hidden on this host',
          message: `${resolverName} is installed, but this app doesn't supply the host bridges it needs. It stays available on hosts that do.`
        });
        return;
      }

      if (isMetaService) {
        // Load meta-service implementation into resolver loader
        await resolverLoader.current.loadResolver(axe);

        // Add to metaServices state
        const metaServiceData = metaServiceFromAxe(axe, filename);

        const existingMeta = metaServices.find(s => s.id === resolverId);
        if (existingMeta) {
          setMetaServices(prev => prev.map(s =>
            s.id === resolverId ? metaServiceData : s
          ));
          showConfirmDialog({
            type: 'success',
            title: 'Updated',
            message: resolverName
          });
        } else {
          setMetaServices(prev => [...prev, metaServiceData]);
          showConfirmDialog({
            type: 'success',
            title: 'Installed',
            message: resolverName
          });
        }
      } else {
        const newResolverInstance = await resolverLoader.current.loadResolver(axe);
        // Wrap content-resolver search through the global limiter
        // (parachord#797). Idempotent.
        window.wrapResolverSearchesWithLimiter([newResolverInstance]);
        // And its play reporting, same as the primary load path (#1546).
        await initPlaybackTelemetry(resolverLoader.current, [newResolverInstance], (id) => getResolverConfigRef.current ? getResolverConfigRef.current(id) : {});

        if (existing) {
          setLoadedResolvers(prev => prev.map(r =>
            r.id === resolverId ? newResolverInstance : r
          ));
          showToast(`${resolverName} updated`, 'success');
        } else {
          setLoadedResolvers(prev => [...prev, newResolverInstance]);
          setResolverOrder(prev => appendUniqueId(prev, resolverId));
          setActiveResolvers(prev => appendUniqueId(prev, resolverId));
          showConfirmDialog({
            type: 'success',
            title: 'Installed',
            message: resolverName
          });
        }
      }
    } catch (error) {
      console.error('Marketplace install error:', error);
      showConfirmDialog({
        type: 'error',
        title: 'Couldn’t install the plug-in',
        message: errorText(error, 'Try again. If it keeps failing, restart Parachord.')
      });
    } finally {
      setInstallingResolvers(prev => {
        const next = new Set(prev);
        next.delete(id);
        return next;
      });
    }
  };

  // Load marketplace manifest when settings page opens to plugins tab
  useEffect(() => {
    if (activeView === 'settings' && settingsTab === 'plugins' && !marketplaceManifest) {
      loadMarketplaceManifest();
    }
  }, [activeView, settingsTab, marketplaceManifest]);

  // Playlist functions
  const parseXSPF = (xspfString) => {
    try {
      const parser = new DOMParser();
      const xml = parser.parseFromString(xspfString, 'text/xml');

      // Parse date from XSPF (ISO 8601 format)
      const dateStr = xml.querySelector('playlist > date')?.textContent;
      const parsedDate = dateStr ? new Date(dateStr).getTime() : null;

      const playlist = {
        title: xml.querySelector('playlist > title')?.textContent || 'Untitled Playlist',
        creator: xml.querySelector('playlist > creator')?.textContent || 'Unknown',
        date: parsedDate, // Original creation date from XSPF
        tracks: []
      };
      // The playlist's own cover: the <image> directly under <playlist>, never
      // a track's, and only a public http(s) URL (lib/xspf-image.js, #1410).
      // The import paths already carry parsed.coverArt onto the saved record.
      const coverArt = playlistImageUrl(xml.documentElement && xml.documentElement.children, window.isPublicHttpUrl);
      if (coverArt) playlist.coverArt = coverArt;
      
      const trackElements = xml.querySelectorAll('track');
      trackElements.forEach(trackEl => {
        const track = {
          title: trackEl.querySelector('title')?.textContent || 'Unknown Track',
          artist: trackEl.querySelector('creator')?.textContent || 'Unknown Artist',
          album: trackEl.querySelector('album')?.textContent || '',
          duration: parseInt(trackEl.querySelector('duration')?.textContent || '0') / 1000, // Convert ms to seconds
          location: trackEl.querySelector('location')?.textContent || ''
        };
        playlist.tracks.push(track);
      });
      
      return playlist;
    } catch (error) {
      console.error('Error parsing XSPF:', error);
      return null;
    }
  };

  // Generate XSPF content from playlist object
  const generateXSPF = (playlist) => {
    const escapeXml = (str) => {
      if (!str) return '';
      return str
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&apos;');
    };

    const tracks = (playlist.tracks || []).map(track => `    <track>
      <title>${escapeXml(track.title)}</title>
      <creator>${escapeXml(track.artist)}</creator>
      <album>${escapeXml(track.album || '')}</album>
      <duration>${Math.round((track.duration || 0) * 1000)}</duration>
    </track>`).join('\n');

    const date = playlist.createdAt ? new Date(playlist.createdAt).toISOString() : new Date().toISOString();

    return `<?xml version="1.0" encoding="UTF-8"?>
<playlist version="1" xmlns="http://xspf.org/ns/0/">
  <title>${escapeXml(playlist.title)}</title>
  <creator>${escapeXml(playlist.creator || 'Parachord')}</creator>
${playlistImageXml(playlist.coverArt, window.isPublicHttpUrl)}  <date>${date}</date>
  <trackList>
${tracks}
  </trackList>
</playlist>`;
  };

  // Save playlist to local storage (electron-store)
  const savePlaylistToStore = async (playlist) => {
    if (!playlist || !playlist.id) return;

    // Hosted XSPF: title and creator overrides also go on the reload list, so
    // the launch reload keeps them. Track edits are saved like any playlist's
    // (below): Parachord can't write the XSPF back to its server, but an edit
    // here stays, and reaches the playlist's mirrors, until the link's
    // tracklist changes (lib/hosted-refresh.js).
    // A provider URL import is a snapshot. It also has sourceUrl, but it must
    // not be written into hosted_playlists (that list is what re-imported the
    // Amazon page at launch and showed "Failed to parse XSPF").
    if (playlist.sourceUrl && !window.isProviderImportedPlaylist(playlist, resolverLoaderRef.current)) {
      try {
        const hostedPlaylists = await window.electron?.store?.get('hosted_playlists') || [];
        const updatedHosted = hostedPlaylists.map(item =>
          item.url === playlist.sourceUrl
            ? { ...item, title: playlist.title, creator: playlist.creator }
            : item
        );
        await window.electron?.store?.set('hosted_playlists', updatedHosted);
        console.log(`💾 Saved metadata for hosted playlist: ${playlist.title}`);
      } catch (error) {
        console.error(`❌ Error saving hosted playlist metadata:`, error);
      }
    }

    // Freshness (Home's "Your playlists, freshest first" and its "+N"):
    // stamp tracksChangedAt / lastChangeAdded against the copy in state when
    // the tracks changed, and put the stamp in state so Home sees it without
    // a reload. Most callers save from inside a setPlaylists updater (or
    // right after one), so playlistsRef still holds the version before this
    // edit; when it doesn't, the split store still stamps the write. It
    // compares against disk and keeps a stamp made here.
    const stateCopy = (playlistsRef.current || []).find(p => p.id === playlist.id) || null;
    const stamped = stampPlaylist(stateCopy, playlist, Date.now());
    if (stamped.tracksChangedAt != null && stamped.tracksChangedAt !== stateCopy?.tracksChangedAt) {
      const { id, tracksChangedAt, lastChangeAdded } = stamped;
      // After the current updater, never inside it. Only ever moves forward.
      // Two edits before the playlistsRef effect commits are both diffed
      // against the pre-edit copy, so lastChangeAdded can over-count by the
      // first edit's additions. Acceptable for a "+N" badge.
      Promise.resolve().then(() => setPlaylists(prev => {
        const i = prev.findIndex(p => p.id === id);
        if (i < 0 || prev[i].tracksChangedAt >= tracksChangedAt) return prev;
        const next = prev.slice();
        next[i] = { ...prev[i], tracksChangedAt, lastChangeAdded };
        return next;
      }));
    }
    playlist = stamped;

    // Invalidate playlist cover cache when tracks change
    // This ensures the 2x2 cover grid regenerates with new tracks
    if (playlistCoverCache.current[playlist.id]) {
      delete playlistCoverCache.current[playlist.id];
      // Also clear from UI state so it re-fetches
      setAllPlaylistCovers(prev => {
        const updated = { ...prev };
        delete updated[playlist.id];
        return updated;
      });
    }

    try {
      // Generate XSPF content for the playlist
      const xspfContent = generateXSPF(playlist);

      // Whole playlist plus the computed fields (filename, xspf, timestamps).
      // Never a hand-picked field list: the store replaces the record, so a
      // field left out here is deleted (that is how localOnly was lost).
      const playlistData = window.buildPlaylistSavePayload(playlist, xspfContent, Date.now());

      const result = await window.electron.playlists.save(playlistData);

      if (result.success) {
        console.log(`💾 Saved playlist: ${playlist.title}`);
      } else {
        console.error(`❌ Failed to save playlist: ${result.error}`);
      }
    } catch (error) {
      console.error(`❌ Error saving playlist:`, error);
    }
  };

  // Parse Critic's Picks RSS feed
  const parseCriticsPicksRSS = (rssString) => {
    try {
      const parser = new DOMParser();
      const xml = parser.parseFromString(rssString, 'text/xml');

      const items = xml.querySelectorAll('item');
      const albums = [];

      items.forEach(item => {
        const titleText = item.querySelector('title')?.textContent || '';
        const link = item.querySelector('link')?.textContent || '';
        const descriptionRaw = item.querySelector('description')?.textContent || '';
        const pubDate = item.querySelector('pubDate')?.textContent || '';

        // Strip HTML tags and fully decode HTML entities (the RSS CDATA content may
        // contain double-encoded entities like &amp;amp; so we decode in a loop until stable)
        let description = descriptionRaw;
        let prev;
        do {
          prev = description;
          const descDoc = new DOMParser().parseFromString(description, 'text/html');
          description = (descDoc.body.textContent || '').trim();
        } while (description !== prev);
        // Scrub any Spotify album URL out of the synopsis — the Achordion feed
        // (parachord#962) appends a bare URL to the blurb, and we deliberately do
        // NOT surface a Spotify link in Critical Darlings, so it must not render.
        description = description.replace(/https:\/\/open\.spotify\.com\/album\/\S+/g, '').trim();

        // Parse "Album by Artist" format
        // Examples: "Valentine by Courtney Marie Andrews", "Tragic Magic by Julianna Barwick & Mary Lattimore"
        let artist = '';
        let album = '';

        const byMatch = titleText.trim().match(/^(.+?)\s+by\s+(.+)$/is);
        if (byMatch) {
          album = byMatch[1].trim();
          artist = byMatch[2].trim();
        } else {
          // Fallback: use full title as album name
          artist = 'Unknown Artist';
          album = titleText;
        }

        if (album) {
          albums.push({
            id: `critics-${artist}-${album}`.toLowerCase().replace(/[^a-z0-9-]/g, '-'),
            artist: artist,
            title: album,
            link: link,
            description: description,
            pubDate: pubDate ? new Date(pubDate) : null,
            albumArt: undefined // undefined = loading, null = no art found, string = art URL
          });
        }
      });

      return albums;
    } catch (error) {
      console.error('Error parsing Critic\'s Picks RSS:', error);
      return [];
    }
  };

  // Parse Apple Music Charts JSON feed
  // A chart album's release year, from Apple's date text, else the UTC year
  // of the Date an older cached chart kept.
  const chartAlbumYear = (item) => {
    if (item.releaseDate) return String(item.releaseDate).slice(0, 4);
    const d = item.pubDate;
    if (!d) return '';
    if (typeof d === 'string') return d.slice(0, 4);
    return d instanceof Date && !isNaN(d) ? String(d.getUTCFullYear()) : '';
  };

  // Persist the Critical Darlings union base (parachord#962) — ref + disk cache,
  // so the section survives restart and seeds the next fetch's union.
  const persistCriticsPicksCache = (albums) => {
    criticsPicksCache.current = { albums, timestamp: Date.now() };
    try { window.electron?.store?.set?.('cache_critics_picks', criticsPicksCache.current); } catch (e) { /* best-effort */ }
  };

  // Case-insensitive "title|artist" identity for a pick — the union dedup key
  // (equivalent to Achordion's "Album by Artist" title dedup). Must match
  // parachord-mobile's key so both clients merge identically.
  const criticsPickKey = (a) => `${(a.title || '').toLowerCase()}|${(a.artist || '').toLowerCase()}`;

  // Load Critic's Picks from RSS feed
  const loadCriticsPicks = async (forceRefresh = false) => {
    if (criticsPicksLoading) return;
    if (criticsPicksLoaded && !forceRefresh) return;

    setCriticsPicksLoading(true);
    setCriticsPicksError(null);
    console.log('📰 Loading Critic\'s Picks...');

    try {
      // Achordion is the source of truth for Critical Darlings (parachord#962).
      // Byte-compatible with the prior feed's item shape, so parseCriticsPicksRSS
      // is unchanged. Public/no-auth; items carry no cover URLs — cover art is
      // resolved below via MusicBrainz + Cover Art Archive as before.
      const response = await fetch('https://achordion.xyz/api/critical-darlings/feed.xml', {
        headers: { 'User-Agent': 'Parachord/0.9.5 (Critical Darlings; +https://github.com/Parachord/parachord)' }
      });
      if (!response.ok) {
        throw new Error(`Failed to fetch RSS: ${response.status}`);
      }

      const rssText = await response.text();
      const freshAlbums = parseCriticsPicksRSS(rssText);

      console.log(`📰 Parsed ${freshAlbums.length} albums from Critic's Picks`);

      // Union-with-cache fallback (parachord#962, mirrors parachord-mobile #346).
      // The Achordion feed backfills over time and each fetch REPLACES the list,
      // so right after cutover it may return only a couple of picks. Keep EVERY
      // fresh pick, then top up to TARGET_ALBUM_COUNT with recent cached picks not
      // already present (dedup by case-insensitive title|artist). Never truncates
      // the fresh feed, so it converges to feed-only once the feed has >= TARGET.
      const TARGET_ALBUM_COUNT = 25; // must match parachord-mobile
      const cachedAlbums = criticsPicksCache.current.albums || [];
      const cacheByKey = new Map(cachedAlbums.map(a => [criticsPickKey(a), a]));
      // Carry already-resolved album art over to fresh picks that were cached,
      // so a re-appearing pick doesn't flash a shimmer while art re-resolves.
      const freshWithArt = freshAlbums.map(a => {
        const prev = cacheByKey.get(criticsPickKey(a));
        return (prev && prev.albumArt && a.albumArt === undefined) ? { ...a, albumArt: prev.albumArt } : a;
      });
      // Fill up to TARGET from the local cache (dedup by title|artist). The legacy
      // third-party feed that used to top it up is gone (parachord#964): the
      // Achordion feed now carries TARGET or more picks on its own.
      const seen = new Set(freshWithArt.map(criticsPickKey));
      const fill = [];
      const addFill = (arr) => {
        for (const a of (arr || [])) {
          if (freshWithArt.length + fill.length >= TARGET_ALBUM_COUNT) return;
          const k = criticsPickKey(a);
          if (seen.has(k)) continue;
          seen.add(k);
          fill.push(a);
        }
      };
      addFill(cachedAlbums);
      const merged = freshWithArt.concat(fill);

      setCriticsPicks(merged);
      setCriticsPicksLoaded(true);
      setCriticsPicksLastFetched(Date.now());
      persistCriticsPicksCache(merged);

      // Unread badge tracks the FRESH feed only — a cached-only fill (or it
      // shrinking as the feed grows) must not re-flag the section as new.
      const hash = generateDiscoveryHash(freshWithArt);
      checkDiscoveryUnread('criticsPicks', hash);

      // Resolve art for the full merged list (cached-only entries re-resolve
      // instantly from albumArtCache) and re-persist with art when done.
      fetchCriticsPicksAlbumArt(merged);

    } catch (error) {
      console.error('Failed to load Critic\'s Picks:', error);
      // Show the cached picks if there are any; only an empty cache (a first run
      // with the Achordion feed unreachable) shows the error.
      const fallback = criticsPicksCache.current.albums || [];
      if (fallback.length > 0) {
        const capped = fallback.slice(0, 25); // TARGET_ALBUM_COUNT
        setCriticsPicks(capped);
        setCriticsPicksLoaded(true);
        persistCriticsPicksCache(capped);
        console.log(`📰 Achordion feed failed — showing ${capped.length} cached picks`);
      } else {
        setCriticsPicksError('Couldn’t load Critical Darlings. Check your connection and try again.');
      }
    } finally {
      setCriticsPicksLoading(false);
    }
  };

  // Load Charts from Apple Music JSON feed
  // The Albums tab's chart (also Home's Pop of the Tops cards): the picked
  // plug-in's, else the first in the user's order that answers
  // (loadChartFor). Nothing loads until a plug-in with charts is loaded; the
  // page's effect asks again once one is.
  const loadCharts = async (forceRefresh = false) => {
    if (chartsLoading) return;
    if (chartsLoaded && !forceRefresh) return;

    setChartsLoading(true);
    setChartsError(null);
    console.log('📊 Loading the albums chart…');
    try {
      const result = await loadChartFor('albums', { forceReload: forceRefresh });
      if (!result) return;
      setChartsShown(prev => ({ ...prev, albums: { source: result.source, region: result.region } }));
      if (result.error) {
        console.error('Failed to load the albums chart:', result.error);
        setCharts([]);
        setChartsError(errorText(result.error, `${pluginName(result.source)}’s chart didn’t load. Try again, or pick another source.`));
        return;
      }
      const albums = result.items;
      setCharts(albums);
      setChartsLoaded(true);
      setChartsLastFetched(Date.now());

      // Check for new content (unread badge)
      checkDiscoveryUnread('charts', generateDiscoveryHash(albums));

      // Wait for cache to be loaded before fetching album art
      if (cacheLoaded) {
        fetchChartsAlbumArt(albums);
      } else {
        const waitForCache = setInterval(() => {
          if (cacheLoaded) {
            clearInterval(waitForCache);
            fetchChartsAlbumArt(albums);
          }
        }, 100);
      }
    } finally {
      setChartsLoading(false);
    }
  };

  // Fetch album art for Charts in background
  const fetchChartsAlbumArt = async (albums) => {
    const albumsNeedingFetch = [];
    const cachedUpdates = [];

    for (const album of albums) {
      // Skip albums that already have artwork from the JSON feed
      if (album.albumArt) continue;

      // getCachedAlbumArt covers every cache shape (MB ids in either form,
      // resolver:/catalog: hits). A miss goes to getAlbumArt, including when
      // MusicBrainz had no match (albumToReleaseIdCache null): that only means
      // MB lacks the release, and getAlbumArt carries on to the resolvers and
      // the iTunes/Deezer catalogs. Skipping those left new and small releases
      // without art for good.
      const cachedArt = getCachedAlbumArt(album.artist, album.title);
      if (cachedArt) {
        cachedUpdates.push({ id: album.id, albumArt: cachedArt });
      } else {
        albumsNeedingFetch.push(album);
      }
    }

    if (cachedUpdates.length > 0) {
      console.log(`📊 Using cached art for ${cachedUpdates.length} Charts albums`);
      setCharts(prev => prev.map(a => {
        const cached = cachedUpdates.find(u => u.id === a.id);
        return cached ? { ...a, albumArt: cached.albumArt } : a;
      }));
    }

    for (const album of albumsNeedingFetch) {
      try {
        const artUrl = await getAlbumArt(album.artist, album.title);
        if (artUrl) {
          setCharts(prev => prev.map(a =>
            a.id === album.id ? { ...a, albumArt: artUrl } : a
          ));
        }
      } catch (error) {
        console.log(`Could not fetch art for: ${album.artist} - ${album.title}`);
      }
      // MusicBrainz rate limit: 1 request per second
      await new Promise(resolve => setTimeout(resolve, 1100));
    }
  };

  // Pop of the Tops' sources for a tab (lib/charts.js, #1539 step 3): every
  // installed plug-in with charts for that kind, turned on or not, minus one
  // switched off; in the user's order.
  const chartProvidersFor = (tab) => chartProviders(resolverLoaderRef.current, chartKind(tab), {
    activeIds: activeResolversRef.current || [],
    order: resolverOrderRef.current || [],
    isOff: pluginSwitchedOff
  });

  // Load one tab's chart. The picked source only; with no pick (or a pick
  // that's gone), each source in order until one has a chart, so a failing
  // first source never leaves the page empty. A source that fails with a
  // cached chart shows that (with a toast saying how old). Resolves to
  // { source, region, items } or { source, region, error }, or null when no
  // plug-in with charts is loaded yet.
  const loadChartFor = async (tab, { forceReload = false } = {}) => {
    const kind = chartKind(tab);
    const providers = chartProvidersFor(tab);
    if (providers.length === 0) return null;
    const pick = chartsPicksRef.current[tab] || {};
    const picked = pick.source && providers.find(p => p.id === pick.source);
    const queue = picked ? [picked] : providers;
    let failure = null;
    for (const provider of queue) {
      const region = pickRegion(provider, kind, pick.region);
      if (region == null) continue;
      const key = chartCacheKey(kind, provider.id, region);
      const cached = chartsCache.current[key];
      const now = Date.now();
      if (!forceReload && cached?.items && (now - cached.timestamp) < CACHE_TTL.charts) {
        console.log(`📦 Using cached ${pluginName(provider.id)} ${kind} chart (${region || 'global'})`);
        return { source: provider.id, region, items: cached.items };
      }
      try {
        const raw = await resolverLoaderRef.current.getCharts(provider.id, {
          kind,
          country: region || null,
          countryName: region ? (CHARTS_COUNTRIES.find(c => c.code === region)?.name || '') : '',
          limit: 50
        }, await configForSimilar(provider.id));
        if (raw == null) continue;
        const items = chartItems(kind, provider.id, region, raw);
        // An empty chart when there's another source to try: try it.
        if (items.length === 0 && !picked) continue;
        chartsCache.current[key] = { items, timestamp: Date.now() };
        console.log(`📊 ${items.length} ${kind} from ${pluginName(provider.id)}'s chart (${region || 'global'})`);
        return { source: provider.id, region, items };
      } catch (error) {
        console.warn(`📊 ${pluginName(provider.id)}'s ${kind} chart failed:`, error?.message || error);
        if (cached?.items?.length) {
          const hours = Math.round((now - cached.timestamp) / (60 * 60 * 1000));
          showToast(`Couldn’t refresh ${pluginName(provider.id)}’s chart. Showing the one from ${countOf(hours, 'hour')} ago.`, 'info');
          return { source: provider.id, region, items: cached.items };
        }
        if (!failure) failure = { source: provider.id, region, error };
      }
    }
    const first = picked || providers[0];
    return failure || { source: first.id, region: pickRegion(first, kind, pick.region), error: userError('No chart came back. Try again in a moment.') };
  };

  // Pick a tab's source or region (the page's menus): the next load uses it.
  const pickChart = (tab, change) => {
    setChartsPicks(prev => ({ ...prev, [tab]: { ...prev[tab], ...change } }));
    chartsPicksRef.current = { ...chartsPicksRef.current, [tab]: { ...chartsPicksRef.current[tab], ...change } };
    if (tab === 'albums') {
      setChartsError(null);
      setChartsLoaded(false);
    } else {
      setSongsChartsError(null);
      setSongsChartsLoaded(false);
    }
  };

  // The Tracks tab's chart; the page's effect starts it once it can.
  const loadSongsCharts = async ({ forceReload = false } = {}) => {
    if (songsChartsLoading) return;
    if (songsChartsLoaded && !forceReload) return;
    setSongsChartsLoading(true);
    setSongsChartsLoaded(false);
    setSongsChartsError(null);
    setSongsChartsScrollContainerReady(false); // Reset to re-trigger observer setup
    try {
      const result = await loadChartFor('songs', { forceReload });
      if (!result) return;
      setChartsShown(prev => ({ ...prev, songs: { source: result.source, region: result.region } }));
      if (result.error) {
        // Nothing to fall back on: the Tracks tab shows ErrorState with Try again.
        setSongsCharts([]);
        setSongsChartsError(result.error);
        return;
      }
      setSongsCharts(result.items);
      setSongsChartsLoaded(true);
      fetchSongsChartsAlbumArt(result.items);
    } finally {
      setSongsChartsLoading(false);
    }
  };

  // Covers for the Tracks tab's rows that came without one, through the
  // album-art pipeline (the track's album when the chart names it).
  const fetchSongsChartsAlbumArt = async (tracks) => {
    for (const track of tracks) {
      if (track.albumArt) continue;
      try {
        const artUrl = await getAlbumArt(track.artist, track.album || track.title);
        if (artUrl) {
          setSongsCharts(prev => prev.map(t =>
            t.id === track.id ? { ...t, albumArt: artUrl } : t
          ));
        }
      } catch (error) {
        console.log(`Could not fetch art for: ${track.artist} - ${track.title}`);
      }
      // MusicBrainz rate limit: 1 request per second
      await new Promise(resolve => setTimeout(resolve, 1100));
    }
  };

  // Navigate to a Charts album release page
  const openChartsAlbum = async (album) => {
    console.log(`🎵 Opening Chart Album: ${album.artist} - ${album.title}`);

    // Navigate before the lookup, not after. Every MusicBrainz request goes
    // through the 1 req/s limiter, so the release lookup below is at least a
    // second away (more behind queued hover prefetches). Waiting on it before
    // changing views left the click with no visible effect for that long.
    // Same pattern as the collection-album opener: artist + loading state +
    // navigate, then search, then fetchReleaseData fills the page in.
    const placeholderId = album.releaseGroupId || album.id;
    // MusicBrainz failed or doesn't have it: the services' catalogs
    // (loadAlbumFromCatalogs) before the artist page or the error.
    const openFromCatalogs = async () => {
      const found = await loadAlbumFromCatalogs({ artist: album.artist, title: album.title });
      return !!found && showCatalogRelease({
        found,
        requested: { id: placeholderId, title: album.title, albumArt: album.albumArt, date: album.date, releaseType: album.releaseType },
        artist: { id: null, name: album.artist },
        canApply: (prev) => !!prev && prev.id === placeholderId && !prev.tracks
      });
    };
    showReleasePlaceholder({
      id: placeholderId,
      artist: album.artist,
      title: album.title,
      albumArt: album.albumArt,
      date: album.date,
      releaseType: album.releaseType
    });

    try {
      let release;
      const mbHeaders = { 'User-Agent': 'Parachord/1.0.0 (https://parachord.app)' };

      // A release-group opened before resolves with no requests at all: the
      // alias cache maps it to the release, whose details (title, date,
      // artist credit) are in the release-details cache.
      const aliasEntry = album.releaseGroupId && releaseDetailsCache.current[album.releaseGroupId];
      const aliasedRelease = hasCurrentAlias(aliasEntry) && releaseDetailsCache.current[aliasEntry.alias]?.data;
      if (aliasedRelease && (Date.now() - aliasEntry.timestamp) < CACHE_TTL.releaseDetails) {
        release = aliasedRelease;
      }

      if (!release && album.releaseGroupId) {
        // Direct lookup by release-group ID (Fresh Drops — much more reliable than string search)
        // through the shared lookup, so it picks the same edition as every other
        // album page (pickRelease, #1288) and caches its track list.
        const rgResponse = await fetchReleaseGroupDetails(album.releaseGroupId);
        if (rgResponse.ok) {
          release = await rgResponse.json();
        }
      }

      if (!release) {
        // Fallback: search by title + artist string (Charts, Critic's Picks,
        // or the release-group lookup failed). The shared search retries
        // with the first artist of a "A & B" credit.
        const releases = await searchMusicBrainzRelease(album.title, album.artist);

        if (releases.length === 0) {
          if (await openFromCatalogs()) return;
          // Fallback: just navigate to artist page
          console.log('Release not found in MusicBrainz or the catalogs, navigating to artist page');
          setCurrentRelease(null);
          setLoadingRelease(false);
          fetchArtistData(album.artist);
          return;
        }

        release = releases[0];
        // Art loaded on the album page can be reused by the chart card.
        albumToReleaseIdCache.current[`${album.artist}-${album.title}`.toLowerCase()] = release.id;
      }

      if (album.releaseGroupId) rememberReleaseGroupAlias(album.releaseGroupId, release.id);

      const artistCredit = release['artist-credit']?.[0];

      // Create artist object for the release page
      const artist = {
        id: artistCredit?.artist?.id,
        name: artistCredit?.artist?.name || album.artist
      };

      // Create release object matching the expected format
      const releaseObj = {
        id: release.id,
        title: release.title,
        date: release.date,
        releaseType: release['release-group']?.['primary-type']?.toLowerCase() || album.releaseType || 'album',
        albumArt: album.albumArt
      };

      // The view is already open; fill in the real artist and tracks.
      // Keep the header collapsed across the artist change.
      openingReleaseRef.current = true;
      setCurrentArtist(artist);
      fetchReleaseData(releaseObj, artist);

    } catch (error) {
      console.error('Error opening chart album:', error);
      // Stay on the album page: the catalogs' track list, else the reason and
      // a retry (not found, above, still goes to the artist page; this is a
      // lookup that failed).
      try {
        if (await openFromCatalogs()) return;
      } catch (catalogError) {
        console.warn('Album catalog fallback failed:', catalogError);
      }
      showReleaseLoadError(placeholderId, error, { kind: 'chartsAlbum', album });
    }
  };

  // Hover prefetch waits for the pointer to rest on a card (AlbumCard's 250ms
  // dwell, components/album-card.js): cards passing under a still pointer
  // while a grid scrolls used to each queue a MusicBrainz lookup and a full
  // render (the Fresh Drops / charts scroll stutter).
  // id -> the running fetch's promise (it resolves to the tracks)
  const prefetchInFlightRef = useRef(new Map());
  // One fetch per album id: the tracks already prefetched, else the fetch
  // already running, else a new one (run resolves to the tracks or null).
  const sharedReleasePrefetch = (id, run) => {
    const have = prefetchedReleasesRef.current[id]?.tracks || prefetchedReleases[id]?.tracks;
    if (have?.length) return Promise.resolve(have);
    const running = prefetchInFlightRef.current.get(id);
    if (running) return running;
    const p = Promise.resolve().then(run).finally(() => prefetchInFlightRef.current.delete(id));
    prefetchInFlightRef.current.set(id, p);
    return p;
  };

  // Resolves to the album's tracks (null if MusicBrainz has none), so a
  // click can play them: a caller that awaited this and then read
  // prefetchedReleases read the render before the fetch, found nothing, and
  // the album only played on a second click. A fetch already running (a
  // hover prefetch) is joined, not skipped.
  const prefetchChartsTracks = (album) => sharedReleasePrefetch(album.id, async () => {
    try {
      // Background lane of the MusicBrainz limiter: a prefetch must never make
      // a click's lookup wait behind it (two requests per hovered card did).
      const bgFetch = (url, init) => fetch(url, { ...(init || {}), mbBackground: true });
      const searchQuery = encodeURIComponent(`release:"${album.title}" AND artist:"${album.artist}"`);
      const mbResponse = await bgFetch(
        `https://musicbrainz.org/ws/2/release/?query=${searchQuery}&fmt=json&limit=1`,
        { headers: { 'User-Agent': 'Parachord/1.0.0 (https://github.com/harmonix)' } }
      );

      if (!mbResponse.ok) return null;

      const mbData = await mbResponse.json();
      if (!mbData.releases || mbData.releases.length === 0) return null;

      const releaseId = mbData.releases[0].id;

      // Fetch release details with tracks
      const releaseDetailsResponse = await fetchReleaseDetails(releaseId, bgFetch);

      if (!releaseDetailsResponse.ok) return null;

      const releaseData = await releaseDetailsResponse.json();
      const tracks = [];

      releaseData.media?.forEach(medium => {
        medium.tracks?.forEach(track => {
          tracks.push({
            id: track.recording?.id || track.id,
            title: track.title,
            artist: album.artist,
            duration: track.length ? Math.round(track.length / 1000) : null,
            albumArt: album.albumArt
          });
        });
      });

      if (tracks.length > 0) {
        setPrefetchedReleases(prev => ({
          ...prev,
          [album.id]: {
            tracks,
            title: album.title,
            albumArt: album.albumArt
          }
        }));
      }
      return tracks.length > 0 ? tracks : null;
    } catch (error) {
      // Silent fail for prefetch
      return null;
    }
  });

  // Add all tracks from a Charts album to the queue
  const addChartsToQueue = async (album) => {
    console.log(`➕ Adding chart album to queue: ${album.artist} - ${album.title}`);

    try {
      const list = await loadAlbumTrackList({ artist: album.artist, title: album.title, albumArt: album.albumArt || null });
      if (!list) {
        showConfirmDialog({
          type: 'error',
          title: 'Album not found',
          message: `Could not find tracks for "${album.title}"`
        });
        return;
      }

      const context = { type: 'album', id: album.id, name: album.title, artist: album.artist };
      addToQueue(list.tracks, context);
      showConfirmDialog({
        type: 'success',
        title: 'Added to Queue',
        message: `Added ${countOf(list.tracks.length, 'track')} from "${album.title}"`
      });
    } catch (error) {
      console.error('Error adding chart album to queue:', error);
      showConfirmDialog({
        type: 'error',
        title: 'Error',
        message: 'Failed to add album to queue. Please try again.'
      });
    }
  };

  // Load New Releases from MusicBrainz for artists in the user's collection and listening history
  const newReleasesCache = useRef({ releases: null, timestamp: 0, lastFullScan: 0 });
  // Gather artists from all sources (collection, library, listening history)
  const gatherNewReleasesArtists = async () => {
    const seen = new Set();
    const collectionArtists = [];
    const libraryArtists = [];
    const historyArtists = [];

    // Source 1: Collection artists
    if (collectionData.artists?.length > 0) {
      collectionData.artists.forEach(a => {
        const key = a.name.trim().toLowerCase();
        if (!seen.has(key)) {
          seen.add(key);
          collectionArtists.push({ name: a.name, source: 'collection' });
        }
      });
    }

    // Source 2: Artists from collection tracks
    if (collectionData.tracks?.length > 0) {
      collectionData.tracks.forEach(t => {
        if (t.artist) {
          const key = t.artist.trim().toLowerCase();
          if (!seen.has(key)) {
            seen.add(key);
            libraryArtists.push({ name: t.artist, source: 'library' });
          }
        }
      });
    }

    // Source 3: Artists from collection albums
    if (collectionData.albums?.length > 0) {
      collectionData.albums.forEach(a => {
        if (a.artist) {
          const key = a.artist.trim().toLowerCase();
          if (!seen.has(key)) {
            seen.add(key);
            libraryArtists.push({ name: a.artist, source: 'library' });
          }
        }
      });
    }

    // Source 4: your top artists, from every plug-in that keeps your
    // listening history (#1539 step 4); a source that fails is left out.
    let historyArtistData = topArtists.artists || [];
    if (historyArtistData.length === 0) {
      const lists = await Promise.all(historySourcesFor().map(source =>
        askTopItems(source.id, { kind: 'artists', period: 'year', limit: 50 }).catch(e => {
          console.log(`✨ Could not fetch ${pluginName(source.id)} top artists for New Releases:`, e.message);
          return [];
        })
      ));
      historyArtistData = mergeArtistNames(lists);
    }

    if (historyArtistData.length > 0) {
      historyArtistData.forEach(a => {
        const key = a.name.trim().toLowerCase();
        if (!seen.has(key)) {
          seen.add(key);
          historyArtists.push({ name: a.name, source: 'history' });
        }
      });
    }

    // Shuffle each source so different artists are checked on each load,
    // allowing releases to accumulate from the full library over time.
    const shuffle = (arr) => {
      for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
      }
      return arr;
    };

    // Interleave sources so each gets fair representation in the artist limit.
    // Kept moderate since merge logic accumulates releases across sessions.
    const maxArtists = 50;
    const buckets = [shuffle(collectionArtists), shuffle(libraryArtists), shuffle(historyArtists)].filter(b => b.length > 0);
    const artistList = [];
    let round = 0;
    while (artistList.length < maxArtists) {
      let added = false;
      for (const bucket of buckets) {
        if (round < bucket.length && artistList.length < maxArtists) {
          artistList.push(bucket[round]);
          added = true;
        }
      }
      if (!added) break;
      round++;
    }

    console.log(`✨ Found ${collectionArtists.length + libraryArtists.length + historyArtists.length} unique artists (${collectionArtists.length} collection, ${libraryArtists.length} library, ${historyArtists.length} history), checking ${artistList.length}`);
    return artistList;
  };

  // Fetch releases from MusicBrainz for a list of artists, filtering by cutoff date
  const fetchReleasesForArtists = async (artistList, cutoffDate, onProgress) => {
    const allNewReleases = [];
    let artistsProcessed = 0;
    const mbHeaders = { 'User-Agent': 'Parachord/1.0.0 (https://parachord.app)' };

    // Upper bound: drop release-groups dated more than 2 weeks out. MB
    // ingests pre-announcement release-groups months ahead (album reveals,
    // pre-orders) — without this cap, Fresh Drops became a "future
    // announcement feed" that pushed actually-fresh releases off the top.
    // 2 weeks is enough to surface upcoming drops the user might want to
    // pre-save without including reveals for things 6 months out.
    // (lib/fresh-drops-releases.js owns the window.)
    const { to: upperCutoffDate } = freshDropsWindow();

    // Fetch with a timeout to prevent a single hanging request from stalling the loop
    const fetchWithTimeout = (url, options, timeoutMs = 10000) => {
      // MusicBrainz requests queue behind the 1 req/s limiter, so the limiter
      // arms the timeout when the request actually starts (see the
      // musicbrainzLimiter fetch wrapper). A signal armed here counted the
      // queue wait and aborted requests that never started.
      if (window.isMusicBrainzWs2Url && window.isMusicBrainzWs2Url(url)) {
        return fetch(url, { ...options, queuedTimeoutMs: timeoutMs, mbBackground: true });
      }
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), timeoutMs);
      return fetch(url, { ...options, signal: controller.signal }).finally(() => clearTimeout(timer));
    };

    for (const artist of artistList) {
      try {
        const cacheKey = artist.name.trim().toLowerCase();
        let mbid = artistDataCache.current[cacheKey]?.artist?.mbid;
        let madeApiCall = false;

        // Check MBID mapper cache before hitting rate-limited MusicBrainz search
        // Each mapper cache hit saves ~1100ms (skips MB artist search + rate limit delay)
        if (!mbid) {
          const mapperMbid = getArtistMbidFromMapperCache(artist.name);
          if (mapperMbid) {
            mbid = mapperMbid;
            console.log(`✨ MBID mapper cache hit for "${artist.name}" → ${mbid} (saved ~1100ms)`);
            // Cache it in artistDataCache too for future non-mapper lookups
            artistDataCache.current[cacheKey] = {
              ...(artistDataCache.current[cacheKey] || {}),
              artist: { ...(artistDataCache.current[cacheKey]?.artist || {}), name: artist.name, mbid },
              timestamp: Date.now()
            };
          }
        }

        if (!mbid) {
          // Fast path: check MBID mapper cache for any previously resolved track by this artist
          mbid = getArtistMbidFromMapperCache(artist.name);
          if (mbid) {
            console.log(`🎯 Fresh Drops: got MBID for "${artist.name}" from mapper cache (skipping MB search)`);
          }
        }

        if (!mbid) {
          const searchResponse = await fetchWithTimeout(
            `https://musicbrainz.org/ws/2/artist?query=${encodeURIComponent(artist.name)}&fmt=json&limit=1`,
            { headers: mbHeaders }
          );
          if (searchResponse.ok) {
            const searchData = await searchResponse.json();
            mbid = searchData.artists?.[0]?.id;
            // Cache the resolved MBID so future fetches skip the search call
            if (mbid) {
              artistDataCache.current[cacheKey] = {
                ...(artistDataCache.current[cacheKey] || {}),
                artist: { ...(artistDataCache.current[cacheKey]?.artist || {}), name: artist.name, mbid },
                timestamp: Date.now()
              };
            }
          }
          madeApiCall = true;
          await new Promise(resolve => setTimeout(resolve, 1100));
        }

        if (!mbid) {
          artistsProcessed++;
          continue;
        }

        const releasesResponse = await fetchWithTimeout(
          `https://musicbrainz.org/ws/2/release-group?artist=${mbid}&fmt=json&limit=100`,
          { headers: mbHeaders }
        );
        madeApiCall = true;

        if (releasesResponse.ok) {
          const releasesData = await releasesResponse.json();
          const releaseGroups = releasesData['release-groups'] || [];

          releaseGroups.forEach(rg => {
            const releaseDate = rg['first-release-date'] || '';
            if (releaseDate && releaseDate >= cutoffDate && releaseDate <= upperCutoffDate) {
              const primaryType = (rg['primary-type'] || '').toLowerCase();
              const secondaryTypes = (rg['secondary-types'] || []).map(t => t.toLowerCase());

              if (primaryType === 'broadcast' || secondaryTypes.includes('compilation') || secondaryTypes.includes('live') || secondaryTypes.includes('broadcast')) return;
              // parachord#1006: a blocked artist or album never shows in Fresh Drops.
              if (window.recommendationBlocklist
                && window.recommendationBlocklist.isBlocked(recommendationBlocklistRef.current, { artist: artist.name, title: rg.title })) return;

              allNewReleases.push({
                id: rg.id,
                title: rg.title,
                artist: artist.name,
                artistSource: artist.source,
                date: releaseDate,
                releaseType: primaryType || 'album',
                secondaryTypes,
                disambiguation: rg.disambiguation,
                albumArt: null
              });
            }
          });
        }

        artistsProcessed++;
        if (onProgress && artistsProcessed % 3 === 0 && allNewReleases.length > 0) {
          onProgress(allNewReleases, artistsProcessed);
        }

        // Only rate-limit after actual API calls (skip delay when MBID was cached
        // and only one API call was made — the release-groups fetch already waited)
        if (madeApiCall) {
          await new Promise(resolve => setTimeout(resolve, 1100));
        }
      } catch (error) {
        console.error(`Error checking releases for ${artist.name}:`, error);
        artistsProcessed++;
      }
    }

    return { releases: allNewReleases, artistsProcessed };
  };

  const loadNewReleases = async (forceRefresh = false) => {
    if (newReleasesLoading || newReleasesLoadInFlightRef.current) return;
    newReleasesLoadInFlightRef.current = true;
    try {
      await waitForBigCaches();
      await loadNewReleasesNow(forceRefresh);
    } finally {
      newReleasesLoadInFlightRef.current = false;
    }
  };

  const loadNewReleasesNow = async (forceRefresh) => {
    // Same rules as loadConcertsNow: a fresh cache in state is used as is, a
    // stale one is shown while it refreshes.
    const newReleasesCacheFresh = (Date.now() - (newReleasesCache.current.timestamp || 0)) < CACHE_TTL.newReleases;
    if (!forceRefresh && newReleases.length > 0 && newReleasesLoaded && newReleasesCacheFresh) {
      console.log(`✨ Using ${newReleases.length} cached new releases from state`);
      return;
    }

    // Check ref cache as fallback
    const now = Date.now();
    if (!forceRefresh && newReleasesCache.current.releases) {
      const cacheAge = now - newReleasesCache.current.timestamp;
      if (cacheAge < CACHE_TTL.newReleases) {
        const cacheAgeMin = Math.round(cacheAge / 60000);
        console.log(`✨ Using ref-cached new releases (${cacheAgeMin}m old)`);
        setNewReleases(newReleasesCache.current.releases);
        setNewReleasesLoaded(true);
        return;
      }
      // Stale cache: show it immediately, then continue to refresh in background
      console.log(`✨ Showing ${newReleasesCache.current.releases.length} stale cached releases while refreshing...`);
      setNewReleases(newReleasesCache.current.releases);
      setNewReleasesLoaded(true);
    }

    // For refresh: if we have existing data and the cache is reasonably fresh,
    // do an incremental update (only look for releases newer than the newest cached one).
    // If the cache is older than 24 hours, fall through to a full 6-month scan instead,
    // which uses shuffled artists and discovers releases from previously unchecked artists.
    // Use lastFullScan (not timestamp) to decide incremental vs full refresh.
    // timestamp gets updated on every incremental check, but lastFullScan only
    // updates after a complete 6-month scan, ensuring we periodically re-scan
    // with shuffled artists to discover releases from previously unchecked artists.
    const lastFullScan = newReleasesCache.current.lastFullScan || 0;
    const cacheIsRecent = (Date.now() - lastFullScan) < 24 * 60 * 60 * 1000; // 24 hours
    if (forceRefresh && newReleases.length > 0 && cacheIsRecent) {
      console.log('✨ Incremental refresh: checking for new releases...');
      setNewReleasesLoading(true);
      setNewReleasesError(null);

      try {
        const artistList = await gatherNewReleasesArtists();
        if (artistList.length === 0) {
          setNewReleasesLoading(false);
          return;
        }

        // Use the newest existing release date as the cutoff (only find newer ones)
        const newestDate = newReleases[0]?.date || '';
        const { releases: freshReleases, artistsProcessed } = await fetchReleasesForArtists(artistList, newestDate);

        // Filter out releases we already have
        const existingIds = new Set(newReleases.map(r => r.id));
        const existingKeys = new Set(newReleases.map(r => `${r.artist.toLowerCase()}-${r.title.toLowerCase()}`));
        const brandNew = freshReleases.filter(r => {
          if (existingIds.has(r.id)) return false;
          const key = `${r.artist.toLowerCase()}-${r.title.toLowerCase()}`;
          if (existingKeys.has(key)) return false;
          return true;
        });

        // Releases that aged out of the window since the last scan leave too,
        // so the list never only grows.
        const inWindow = withinFreshDropsWindow(newReleases);
        if (brandNew.length > 0 || inWindow.length < newReleases.length) {
          console.log(`✨ Found ${brandNew.length} new releases to add; ${newReleases.length - inWindow.length} aged out`);
          // Prepend new releases and re-sort
          const merged = uniqueReleases(withinFreshDropsWindow([...brandNew, ...newReleases])).sort((a, b) => (b.date || '').localeCompare(a.date || ''));
          setNewReleases(merged);
          newReleasesCache.current = { releases: merged, timestamp: Date.now(), lastFullScan: newReleasesCache.current.lastFullScan || 0 };

          // Only new releases light the unread dot, not ones aging out.
          if (brandNew.length > 0) {
            checkDiscoveryUnread('newReleases', generateDiscoveryHash(merged));
            // Fetch art only for the new ones
            fetchNewReleasesAlbumArt(brandNew);
          }
          saveCacheToStore();
        } else {
          console.log(`✨ No new releases found (checked ${artistsProcessed} artists)`);
          newReleasesCache.current.timestamp = Date.now();
        }
      } catch (error) {
        console.error('Failed to refresh New Releases:', error);
      } finally {
        setNewReleasesLoading(false);
      }
      return;
    }

    // Full initial load (or full re-scan when last full scan was >24h ago)
    if (forceRefresh && newReleases.length > 0) {
      console.log(`✨ Full re-scan: last full scan was ${Math.round((Date.now() - lastFullScan) / 3600000)}h ago (>24h threshold)`);
    }
    setNewReleasesLoading(true);
    setNewReleasesError(null);
    console.log('✨ Loading New Releases (full fetch)...');

    try {
      const artistList = await gatherNewReleasesArtists();

      if (artistList.length === 0) {
        // No artists to check is not "no releases": the collection or the
        // listening history may simply not have loaded yet. Keep the
        // releases already on screen (the restored cache) rather than
        // blanking Fresh Drops, and only show the empty state when there
        // were none (2026-11: Home lost Fresh Drops after a stale-cache
        // launch until something re-rendered it).
        const kept = newReleasesCache.current.releases || [];
        console.log(`✨ No artists found in collection or history${kept.length ? `; keeping ${kept.length} cached releases` : ''}`);
        if (kept.length === 0) setNewReleases([]);
        setNewReleasesLoaded(true);
        setNewReleasesLoading(false);
        return;
      }

      const { from: cutoffDate } = freshDropsWindow();

      // Snapshot existing cached releases BEFORE the fetch starts, so the
      // progress callback (which updates the cache ref) can't overwrite them.
      // Only those still in the window carry over: the merge used to keep
      // every release ever found, so the list only grew.
      const priorCachedReleases = withinFreshDropsWindow(newReleasesCache.current.releases || []);

      const { releases: allNewReleases, artistsProcessed } = await fetchReleasesForArtists(
        artistList,
        cutoffDate,
        (results) => {
          // Cached art only during progress; the art pass after the fetch
          // verifies CAA and runs the fallbacks for the rest.
          const withArt = results.map(r => window.hydrateReleaseArt(r, albumArtCache.current));
          // Merge in-progress results with prior cache so user sees all releases during loading
          const progressMerged = [...withArt, ...priorCachedReleases];
          const deduped = uniqueReleases(progressMerged).sort((a, b) => (b.date || '').localeCompare(a.date || ''));
          setNewReleases(deduped);
          // Keep cache ref in sync so periodic saveCacheToStore captures
          // in-progress results (prevents data loss on rebuild/crash)
          newReleasesCache.current = { releases: deduped, timestamp: Date.now(), lastFullScan: Date.now() };
        }
      );

      // Merge with prior cached releases so we don't lose results from
      // artists that weren't in this run's selection (the artist cap means each
      // full fetch only covers a subset of the user's library).
      const merged = [...allNewReleases, ...priorCachedReleases];

      // Sort and deduplicate by release id, then artist + title (fresh
      // results take priority since they come first).
      const uniqueList = uniqueReleases(merged)
        .sort((a, b) => (b.date || '').localeCompare(a.date || ''));

      console.log(`✨ Found ${allNewReleases.length} fresh + ${priorCachedReleases.length} cached → ${uniqueList.length} unique releases from ${artistsProcessed} artists`);

      setNewReleases(uniqueList);
      setNewReleasesLoaded(true);

      newReleasesCache.current = { releases: uniqueList, timestamp: Date.now(), lastFullScan: Date.now() };

      const hash = generateDiscoveryHash(uniqueList);
      checkDiscoveryUnread('newReleases', hash);

      fetchNewReleasesAlbumArt(uniqueList);

      // Persist immediately so data isn't lost if app is rebuilt/killed
      saveCacheToStore();

    } catch (error) {
      console.error('Failed to load New Releases:', error);
      setNewReleasesError('Couldn’t load Fresh Drops. Check your connection and try again.');
    } finally {
      setNewReleasesLoading(false);
    }
  };

  // Assign album art URLs for New Releases instantly using deterministic CAA URLs
  // No HEAD requests needed - the URL format is known, and onError in rendering handles 404s
  // Fresh Drops art. Cached hits are applied at once; the rest go through the
  // album-art pipeline's tail, release-group id first since we have it:
  //   1. Cover Art Archive release-group front, VERIFIED with a request (the
  //      final redirected URL is what gets cached, never the guess),
  //   2. getAlbumArtFromResolvers: enabled resolvers, then iTunes and Deezer.
  // Four releases in flight; results land in state in 250ms batches so a page
  // of 300 releases is a handful of renders, not 300. Misses are remembered
  // for the session only, so the next launch retries them.
  const NEW_RELEASES_ART_CONCURRENCY = 4;
  const newReleasesArtInFlightRef = useRef(new Set());
  const newReleasesArtMissRef = useRef(new Set());
  const newReleasesArtWriterRef = useRef(null);
  if (!newReleasesArtWriterRef.current) {
    newReleasesArtWriterRef.current = window.createCoalescedUpdater((batch) => {
      const applyUpdates = (list) => list.map(r => {
        const ops = batch.get(r.id);
        return ops ? { ...r, albumArt: window.applyCoalescedOps(r.albumArt, ops) } : r;
      });
      setNewReleases(prev => applyUpdates(prev));
      if (newReleasesCache.current.releases) {
        newReleasesCache.current.releases = applyUpdates(newReleasesCache.current.releases);
      }
    }, 250);
  }

  const resolveNewReleaseArt = async (release) => {
    const rgUrl = `https://coverartarchive.org/release-group/${release.id}/front-250`;
    try {
      const response = await fetch(rgUrl, { method: 'HEAD', redirect: 'follow' });
      if (response.ok) {
        // The final redirected URL (archive.org). Should CAA ever answer 200
        // without redirecting, the guess itself is stored and simply gets
        // re-verified next launch.
        const artUrl = response.url || rgUrl;
        albumArtCache.current[release.id] = { url: artUrl, timestamp: Date.now() };
        return artUrl;
      }
    } catch (error) {
      // CAA unreachable: fall through to the other sources, remember nothing
    }
    const fallback = await getAlbumArtFromResolvers(release.artist, release.title);
    if (fallback) {
      albumArtCache.current[release.id] = { url: fallback, timestamp: Date.now() };
      return fallback;
    }
    return null;
  };

  const fetchNewReleasesAlbumArt = (releases) => {
    const cachedUpdates = [];
    const pending = [];
    for (const release of releases) {
      if (release.albumArt && !window.isUnverifiedCoverArtUrl(release.albumArt)) continue;
      const cached = albumArtCache.current[release.id];
      if (cached?.url && !window.isUnverifiedCoverArtUrl(cached.url)) {
        cachedUpdates.push([release.id, cached.url]);
        continue;
      }
      if (newReleasesArtInFlightRef.current.has(release.id) || newReleasesArtMissRef.current.has(release.id)) continue;
      pending.push(release);
    }

    for (const [id, url] of cachedUpdates) newReleasesArtWriterRef.current.queue(id, url);
    if (cachedUpdates.length > 0) newReleasesArtWriterRef.current.flush();
    if (pending.length === 0) return;

    for (const release of pending) newReleasesArtInFlightRef.current.add(release.id);
    const queue = [...pending];
    const worker = async () => {
      while (queue.length > 0) {
        const release = queue.shift();
        try {
          const artUrl = await resolveNewReleaseArt(release);
          if (artUrl) newReleasesArtWriterRef.current.queue(release.id, artUrl);
          else newReleasesArtMissRef.current.add(release.id);
        } catch (error) {
          console.log(`✨ Art lookup failed for ${release.artist} - ${release.title}: ${error.message}`);
        } finally {
          newReleasesArtInFlightRef.current.delete(release.id);
        }
      }
    };
    Promise.all(Array.from({ length: Math.min(NEW_RELEASES_ART_CONCURRENCY, queue.length) }, worker))
      .then(() => newReleasesArtWriterRef.current.flush());
  };

  // Handle scroll for New Releases header collapse
  const handleNewReleasesScroll = (e) => {
    const { scrollTop, scrollHeight, clientHeight } = e.target;
    const decision = window.headerCollapseDecision({ scrollTop, scrollHeight, clientHeight, collapsed: newReleasesHeaderCollapsed });
    if (decision !== null) setNewReleasesHeaderCollapsed(decision);
  };

  // ─── CONCERTS ─────────────────────────────────────────────────────────────

  // Gather artists from user's collection and listening history for concert lookup
  const gatherConcertsArtists = async () => {
    const seen = new Set();
    const collectionArtists = [];
    const libraryArtists = [];
    const historyArtists = [];

    // Source 1: Collection artists
    if (collectionData.artists?.length > 0) {
      collectionData.artists.forEach(a => {
        const key = a.name.trim().toLowerCase();
        if (!seen.has(key)) {
          seen.add(key);
          collectionArtists.push({ name: a.name, source: 'collection' });
        }
      });
    }

    // Source 2: Artists from collection tracks
    if (collectionData.tracks?.length > 0) {
      collectionData.tracks.forEach(t => {
        if (t.artist) {
          const key = t.artist.trim().toLowerCase();
          if (!seen.has(key)) {
            seen.add(key);
            libraryArtists.push({ name: t.artist, source: 'library' });
          }
        }
      });
    }

    // Source 3: Artists from collection albums
    if (collectionData.albums?.length > 0) {
      collectionData.albums.forEach(a => {
        if (a.artist) {
          const key = a.artist.trim().toLowerCase();
          if (!seen.has(key)) {
            seen.add(key);
            libraryArtists.push({ name: a.artist, source: 'library' });
          }
        }
      });
    }

    // Source 4: your top artists, from every plug-in that keeps your
    // listening history (#1539 step 4); a source that fails is left out.
    let historyArtistData = topArtists.artists || [];
    if (historyArtistData.length === 0) {
      const lists = await Promise.all(historySourcesFor().map(source =>
        askTopItems(source.id, { kind: 'artists', period: 'half_year', limit: 40 }).catch(e => {
          console.log(`🎤 Could not fetch ${pluginName(source.id)} top artists for concerts:`, e.message);
          return [];
        })
      ));
      historyArtistData = mergeArtistNames(lists);
    }

    if (historyArtistData.length > 0) {
      historyArtistData.forEach(a => {
        const key = a.name.trim().toLowerCase();
        if (!seen.has(key)) {
          seen.add(key);
          historyArtists.push({ name: a.name, source: 'history' });
        }
      });
    }

    // Interleave sources so each gets fair representation
    const maxArtists = 40;
    const buckets = [collectionArtists, libraryArtists, historyArtists].filter(b => b.length > 0);
    const artistList = [];
    let round = 0;
    while (artistList.length < maxArtists) {
      let added = false;
      for (const bucket of buckets) {
        if (round < bucket.length && artistList.length < maxArtists) {
          artistList.push(bucket[round]);
          added = true;
        }
      }
      if (!added) break;
      round++;
    }

    console.log(`🎤 Found ${collectionArtists.length + libraryArtists.length + historyArtists.length} unique artists for concerts (${collectionArtists.length} collection, ${libraryArtists.length} library, ${historyArtists.length} history), checking ${artistList.length}`);
    return artistList;
  };

  // Haversine distance between two lat/lng points in miles
  const haversineDistance = (lat1, lng1, lat2, lng2) => {
    const R = 3958.8; // Earth radius in miles
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLng = (lng2 - lng1) * Math.PI / 180;
    const a = Math.sin(dLat / 2) ** 2 +
      Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
      Math.sin(dLng / 2) ** 2;
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  };

  // Geocode a location string to coordinates using Nominatim (OpenStreetMap)
  const geocodeLocation = async (query) => {
    const url = `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(query)}&format=json&limit=1`;
    const resp = await fetch(url, {
      headers: { 'User-Agent': 'Parachord/1.0', 'Accept': 'application/json' }
    });
    if (!resp.ok) return null;
    const results = await resp.json();
    if (!results || results.length === 0) return null;
    const r = results[0];
    return {
      lat: parseFloat(r.lat),
      lng: parseFloat(r.lon),
      displayName: r.display_name?.split(',').slice(0, 2).join(',').trim() || query
    };
  };

  // Search Nominatim for location suggestions (returns multiple results)
  const searchLocationSuggestions = async (query) => {
    if (!query || query.trim().length < 2) return [];
    try {
      const url = `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(query)}&format=json&limit=5&addressdetails=1`;
      const resp = await fetch(url, {
        headers: { 'User-Agent': 'Parachord/1.0', 'Accept': 'application/json' }
      });
      if (!resp.ok) return [];
      const results = await resp.json();
      return results.map(r => {
        const addr = r.address || {};
        const name = addr.city || addr.town || addr.village || addr.county || addr.state || r.display_name?.split(',').slice(0, 2).join(',').trim() || query;
        const region = addr.state || addr.country || '';
        return {
          lat: parseFloat(r.lat),
          lng: parseFloat(r.lon),
          name: name,
          region: region && region !== name ? `${name}, ${region}` : name,
          displayName: r.display_name?.split(',').slice(0, 2).join(',').trim() || query
        };
      });
    } catch (e) {
      console.log('📍 Location search error:', e.message);
      return [];
    }
  };

  // Use browser geolocation to get user's current coordinates, with IP-based fallback
  const getBrowserGeolocation = async () => {
    // Try navigator.geolocation first
    try {
      const pos = await new Promise((resolve, reject) => {
        if (!navigator.geolocation) {
          reject(new Error('Geolocation not supported'));
          return;
        }
        navigator.geolocation.getCurrentPosition(
          (pos) => resolve({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
          (err) => reject(err),
          { enableHighAccuracy: false, timeout: 10000 }
        );
      });
      return pos;
    } catch (browserErr) {
      console.log('📍 Browser geolocation failed, trying IP lookup:', browserErr.message);
    }
    // Fallback: IP-based geolocation — try multiple services. HTTPS only:
    // ip-api.com was dropped because its free tier answers over plain HTTP,
    // which would send the lookup (and the user's IP-derived location) in clear.
    const ipServices = [
      {
        url: 'https://ipapi.co/json/',
        parse: (d) => d.latitude && d.longitude ? { lat: d.latitude, lng: d.longitude } : null
      },
      {
        url: 'https://ipwho.is/',
        parse: (d) => d.success !== false && d.latitude && d.longitude ? { lat: d.latitude, lng: d.longitude } : null
      }
    ];
    for (const svc of ipServices) {
      try {
        const resp = await fetch(svc.url, { headers: { 'Accept': 'application/json' } });
        if (resp.ok) {
          const data = await resp.json();
          const pos = svc.parse(data);
          if (pos) return pos;
        }
      } catch (e) {
        console.log(`📍 IP geolocation failed (${svc.url}):`, e.message);
      }
    }
    throw new Error('Could not determine your location');
  };

  // Reverse geocode coordinates to a display name
  const reverseGeocode = async (lat, lng) => {
    const url = `https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lng}&format=json&zoom=10`;
    const resp = await fetch(url, {
      headers: { 'User-Agent': 'Parachord/1.0', 'Accept': 'application/json' }
    });
    if (!resp.ok) return `${lat.toFixed(2)}, ${lng.toFixed(2)}`;
    const data = await resp.json();
    const addr = data.address || {};
    return addr.city || addr.town || addr.village || addr.county || data.display_name?.split(',').slice(0, 2).join(',').trim() || `${lat.toFixed(2)}, ${lng.toFixed(2)}`;
  };

  // Get dedicated concert service plugins (Bandsintown, Songkick, SeatGeek) that are enabled and have auth
  const getConcertServices = () => {
    const allResolvers = resolverLoaderRef.current ? resolverLoaderRef.current.getAllResolvers() : [];
    return allResolvers.filter(r => {
      if (!r.capabilities?.concerts || !r.searchArtistEvents) return false;
      const config = metaServiceConfigs[r.id] || {};
      // Respect explicit disable toggle
      if (config.enabled === false) return false;
      const noKeyNeeded = r.requiresAuth === false || r.settings?.requiresAuth === false;
      // No-auth services require an explicit enabled toggle (same as AI concert services)
      if (noKeyNeeded) return config.enabled === true;
      // Auth-required services: check the plugin's expected auth field (e.g. clientId, appId, apiKey)
      const configurable = r.settings?.configurable || r.configurable || {};
      const authField = Object.keys(configurable).find(k => k !== 'model') || 'apiKey';
      return !!(config[authField] || config.apiKey);
    });
  };

  // Get AI chat services that can suggest concerts
  const getAiConcertServices = () => {
    const allResolvers = resolverLoaderRef.current ? resolverLoaderRef.current.getAllResolvers() : [];
    return allResolvers.filter(r => {
      if (!r.capabilities?.concerts || !r.capabilities?.chat || !r.chat) return false;
      return isServiceEnabled(r);
    });
  };

  // Load concerts for user's favorite artists
  const loadConcerts = async (forceRefresh = false) => {
    if (concertsLoading || concertsLoadInFlightRef.current) return;
    concertsLoadInFlightRef.current = true;
    try {
      await waitForBigCaches();
      await loadConcertsNow(forceRefresh);
    } finally {
      concertsLoadInFlightRef.current = false;
    }
  };

  const loadConcertsNow = async (forceRefresh) => {
    // Data in state from a fresh cache: nothing to do. A stale cache restored
    // at startup falls through to the stale-while-refreshing path below; it
    // used to return here and never refresh until the user pressed refresh.
    const concertsCacheFresh = (Date.now() - (concertsCache.current.timestamp || 0)) < CACHE_TTL.concerts;
    if (!forceRefresh && concerts.length > 0 && concertsLoaded && concertsCacheFresh) {
      console.log(`🎤 Using ${concerts.length} cached concerts from state`);
      return;
    }

    // Check ref cache as fallback
    const now = Date.now();
    if (!forceRefresh && concertsCache.current.events && concertsCache.current.events.length > 0) {
      const cacheAge = now - concertsCache.current.timestamp;
      if (cacheAge < CACHE_TTL.concerts) {
        console.log(`🎤 Using ref-cached concerts (${Math.round(cacheAge / 60000)}m old)`);
        setConcerts(concertsCache.current.events);
        setConcertsLoaded(true);
        return;
      }
      // Stale cache: show it immediately, then continue to refresh in background
      console.log(`🎤 Showing ${concertsCache.current.events.length} stale cached concerts while refreshing...`);
      setConcerts(concertsCache.current.events);
      setConcertsLoaded(true);
    }

    // Check for enabled concert services (dedicated + AI)
    const concertServices = getConcertServices();
    const aiConcertServices = getAiConcertServices();
    if (concertServices.length === 0 && aiConcertServices.length === 0) {
      // Only show the error if we have no cached data to display
      if (!concertsCache.current.events || concertsCache.current.events.length === 0) {
        setConcertsError('no_services');
      }
      setConcertsLoaded(true);
      return;
    }

    setConcertsLoading(true);
    setConcertsError(null);
    // Clear stale data on force refresh so user sees fresh results only
    if (forceRefresh) {
      concertsCache.current = { events: [], timestamp: 0 };
    }
    console.log(`🎤 Loading concerts from ${concertServices.length} dedicated + ${aiConcertServices.length} AI service(s)...`);

    try {
      const artistList = await gatherConcertsArtists();

      // Build a lookup from artist name to their source (collection/library/history)
      const artistSourceMap = {};
      for (const a of artistList) {
        artistSourceMap[a.name.trim().toLowerCase()] = a.source;
      }

      if (artistList.length === 0) {
        console.log('🎤 No artists found in collection or history for concerts');
        setConcerts([]);
        setConcertsLoaded(true);
        setConcertsLoading(false);
        return;
      }

      // Snapshot prior cached events for merging (skip on force refresh to clear stale items)
      const priorCachedEvents = forceRefresh ? [] : [...(concertsCache.current.events || [])];

      const allEvents = [];
      const seenEventKeys = new Set();

      // Normalize a string for dedup comparison: lowercase, strip common
      // suffixes/punctuation, collapse whitespace so "Madison Square Garden"
      // matches "Madison Square Garden, New York" from another source.
      const normalizeForDedup = (str) =>
        (str || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim();

      // Build a dedup key that's resilient to minor venue name differences
      // across providers.  Two events match if same date + same artist AND
      // either (a) venue names share a long common prefix, or (b) both
      // have lat/lng within ~1 km.
      const makeEventKey = (event, artistName) => {
        const date = event.date || '';
        const artist = normalizeForDedup(artistName);
        // Use first 20 chars of normalized venue as the key — long enough
        // to distinguish venues but short enough to collapse minor trailing
        // differences like city/state suffixes.
        const venuePrefix = normalizeForDedup(event.venue?.name).slice(0, 20);
        return `${date}-${artist}-${venuePrefix}`;
      };

      // Secondary dedup: same date + artist + geo-proximity (within ~2 km)
      const geoKey = (event, artistName) => {
        if (!event.venue?.latitude || !event.venue?.longitude) return null;
        const lat = Math.round(event.venue.latitude * 50) / 50; // ~2 km buckets
        const lng = Math.round(event.venue.longitude * 50) / 50;
        return `${event.date || ''}-${normalizeForDedup(artistName)}-${lat},${lng}`;
      };

      const seenGeoKeys = new Set();
      // Map dedup keys to event index in allEvents for merging ticket sources
      const eventKeyToIndex = new Map();
      const geoKeyToEventKey = new Map();

      // Helper to build a ticket source entry from an event
      const makeTicketSource = (event) => ({
        source: event.source,
        aiProvider: event.aiProvider || null,
        aiProviderName: event.aiProviderName || null,
        ticketUrl: event.ticketUrl || event.url || null,
        // The seller's plug-in name; AI-found dates name their AI provider.
        label: event.source === 'ai' ? (event.aiProviderName || 'AI')
          : pluginName(event.source)
      });

      // Helper to add an event with dedup — merges ticket sources on match
      const addEventDeduped = (event, artistName, artistSource) => {
        const key = makeEventKey(event, artistName);
        const gk = geoKey(event, artistName);

        // Check if we already have this event (by text key or geo key)
        let existingKey = eventKeyToIndex.has(key) ? key : null;
        if (!existingKey && gk && geoKeyToEventKey.has(gk)) {
          existingKey = geoKeyToEventKey.get(gk);
        }

        if (existingKey) {
          // Merge: add this source's ticket info to the existing event
          const idx = eventKeyToIndex.get(existingKey);
          const existing = allEvents[idx];
          const newSource = makeTicketSource(event);
          if (newSource.ticketUrl && !existing.ticketSources.some(s => s.source === newSource.source && s.aiProvider === newSource.aiProvider)) {
            existing.ticketSources.push(newSource);
          }
          // Merge lineup if richer
          if (event.lineup && event.lineup.length > (existing.lineup || []).length) {
            existing.lineup = event.lineup;
          }
          return false;
        }

        // New event — initialize ticketSources array and artist source
        event.ticketSources = [makeTicketSource(event)];
        if (artistSource) event.artistSource = artistSource;
        seenEventKeys.add(key);
        if (gk) {
          seenGeoKeys.add(gk);
          geoKeyToEventKey.set(gk, key);
        }
        eventKeyToIndex.set(key, allEvents.length);
        allEvents.push(event);
        return true;
      };

      // Run dedicated service queries and AI queries in parallel.
      // Each service has its own limiter (2 in flight, 400ms between starts,
      // a cooldown after repeated 429s; Ticketmaster needs that pacing), and
      // every artist lookup for a service is queued on it at once, so the
      // services run side by side instead of sharing one queue
      // (src/renderer/lib/concert-limiters.js).
      const dedicatedPromise = (async () => {
        if (!window.__concertLimiters && window.createLimiter) {
          window.__concertLimiters = createConcertLimiters(window.createLimiter);
        }
        const fetchServiceArtist = async (service, limiter, artist) => {
          try {
            const rawConfig = metaServiceConfigs[service.id] || {};
            // Map generic apiKey to the plugin's expected field (e.g. clientId, appId)
            const authField = Object.keys(service.configurable || {}).find(k => k !== 'model');
            const config = (authField && authField !== 'apiKey' && !rawConfig[authField] && rawConfig.apiKey)
              ? { ...rawConfig, [authField]: rawConfig.apiKey }
              : rawConfig;
            const events = limiter
              ? await limiter.run(() => service.searchArtistEvents(artist.name, config))
              : await service.searchArtistEvents(artist.name, config);
            return (events || []).map(e => ({ event: e, artist: artist.name }));
          } catch (e) {
            console.log(`🎤 Error fetching concerts for ${artist.name} from ${service.id}:`, e.message);
            return [];
          }
        };
        const perService = await Promise.all(concertServices.map((service) => {
          const limiter = window.__concertLimiters ? window.__concertLimiters.forService(service.id) : null;
          return Promise.all(artistList.map(artist => fetchServiceArtist(service, limiter, artist)));
        }));
        return perService.flat(2);
      })();

      // AI queries — batch artists in groups of 15, run all batches in parallel
      const aiPromise = (async () => {
        if (aiConcertServices.length === 0) return [];

        let aiService = aiConcertServices[0];
        if (selectedChatProvider) {
          const preferred = aiConcertServices.find(s => s.id === selectedChatProvider);
          if (preferred) aiService = preferred;
        }

        const today = new Date().toISOString().split('T')[0];
        const currentYear = new Date().getFullYear();
        const config = metaServiceConfigs[aiService.id] || {};
        const providerName = aiService.name || aiService.id;

        // Split artists into batches of 15 for better per-artist coverage
        const AI_BATCH_SIZE = 15;
        const artistBatches = [];
        for (let i = 0; i < artistList.length; i += AI_BATCH_SIZE) {
          artistBatches.push(artistList.slice(i, i + AI_BATCH_SIZE));
        }

        // Run all batches in parallel
        const batchResults = await Promise.allSettled(artistBatches.map(async (batch) => {
          const artistNames = batch.map(a => a.name).join(', ');
          const prompt = `What upcoming concerts, tours, or festival appearances do you know about for these artists: ${artistNames}

Today's date is ${today}. Share any concert dates, announced tours, festival lineups, residencies, or live events you know about from ${currentYear} onward for these artists. Include events from known annual festivals (Coachella, Glastonbury, Lollapalooza, etc.) if these artists are on the lineup. If an artist has announced a tour, include the dates you know about. Aim for multiple events per artist where possible.

Return ONLY a JSON array. Each event object should have:
- "artist": artist name
- "title": event title (e.g. "Artist Name at Venue" or "Festival Name ${currentYear}")
- "date": date in YYYY-MM-DD format (use your best estimate if only month is known, e.g. first of the month)
- "venue": object with "name", "city", "region", "country"
- "url": ticket or event URL if known, or empty string
- "description": brief note (e.g. "Part of World Tour ${currentYear}", "Festival headliner")

Return ONLY the JSON array, no other text.`;

          const messages = [
            { role: 'system', content: `You are a knowledgeable music events assistant. Your job is to share what you know about upcoming concerts, tours, and festival appearances. You have extensive knowledge of announced tours, festival lineups, residencies, and live music events. Share all relevant events you know about — include announced tours, festival bookings, and recurring events. Use ${currentYear} dates. Return valid JSON arrays only.` },
            { role: 'user', content: prompt }
          ];

          const response = await aiService.chat(messages, [], config);
          if (!response?.content) return [];

          const jsonMatch = response.content.match(/\[\s*\{[\s\S]*\}\s*\]/);
          const aiEvents = jsonMatch ? JSON.parse(jsonMatch[0]) : JSON.parse(response.content);
          if (!Array.isArray(aiEvents)) return [];

          return aiEvents.map(aiEvent => ({
            id: `ai-${aiService.id}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
            source: 'ai',
            aiProvider: aiService.id,
            aiProviderName: providerName,
            artist: aiEvent.artist || '',
            title: aiEvent.title || `${aiEvent.artist || 'Unknown'} Concert`,
            datetime: aiEvent.date ? new Date(aiEvent.date).toISOString() : '',
            date: aiEvent.date || '',
            venue: {
              name: aiEvent.venue?.name || 'Venue TBA',
              city: aiEvent.venue?.city || '',
              region: aiEvent.venue?.region || '',
              country: aiEvent.venue?.country || ''
            },
            ticketUrl: aiEvent.url || '',
            url: aiEvent.url || '',
            description: aiEvent.description || 'AI-suggested event'
          }));
        }));

        const aiEvents = [];
        for (const result of batchResults) {
          if (result.status === 'fulfilled' && result.value.length > 0) {
            aiEvents.push(...result.value);
          } else if (result.status === 'rejected') {
            console.log(`🎤 AI concert batch failed:`, result.reason?.message || result.reason);
          }
        }
        console.log(`🎤 AI service ${aiService.id} suggested ${aiEvents.length} concert events (${artistBatches.length} parallel batches)`);
        return aiEvents;
      })();

      // Wait for both dedicated and AI queries to complete
      const [dedicatedResults, aiResults] = await Promise.all([dedicatedPromise, aiPromise]);

      // Add dedicated service results
      for (const { event, artist } of dedicatedResults) {
        addEventDeduped(event, artist, artistSourceMap[artist.trim().toLowerCase()]);
      }
      // Add AI results
      for (const aiEvent of aiResults) {
        addEventDeduped(aiEvent, aiEvent.artist, artistSourceMap[(aiEvent.artist || '').trim().toLowerCase()]);
      }

      // Merge fresh results with prior cached events (so we don't lose results
      // from artists that weren't in this run's selection)
      const merged = [...allEvents, ...priorCachedEvents];
      const today = new Date().toISOString().split('T')[0];
      // One row per show (lib/concert-events.js): a show with two of the
      // user's artists on the bill comes back once per artist under one
      // event id, and the list keys its rows by that id. Fresh copies come
      // first, so they win over a stale cached copy; ticket sources and the
      // artists each copy was found under are merged into the kept row.
      const uniqueEvents = uniqueConcerts(merged
        .filter(e => !(e.date && e.date < today)) // Drop past events
        // Ensure ticketSources exists (for legacy cached events)
        .map(e => (e.ticketSources ? e : { ...e, ticketSources: [makeTicketSource(e)] })));
      uniqueEvents.sort((a, b) => (a.date || '').localeCompare(b.date || ''));

      console.log(`🎤 Found ${allEvents.length} fresh + ${priorCachedEvents.length} cached → ${uniqueEvents.length} unique concerts for ${artistList.length} artists`);

      setConcerts(uniqueEvents);
      setConcertsLoaded(true);

      concertsCache.current = { events: uniqueEvents, timestamp: Date.now() };

      const hash = generateDiscoveryHash(uniqueEvents);
      checkDiscoveryUnread('concerts', hash);

      // Persist to store
      try {
        await window.electron.store.set('cache_concerts', { events: uniqueEvents, timestamp: Date.now() });
      } catch (e) {
        console.log('🎤 Could not persist concerts cache:', e.message);
      }

    } catch (error) {
      console.error('Failed to load concerts:', error);
      setConcertsError('Failed to load concerts. Please try again.');
    } finally {
      setConcertsLoading(false);
    }
  };

  // Load concerts for a specific artist (On Tour tab)
  const loadArtistConcerts = async (artistName, forceRefresh = false) => {
    if (!artistName || artistConcertsLoading) return;

    const normalizedName = artistName.trim().toLowerCase();
    const now = Date.now();

    // Check ref cache
    if (!forceRefresh && artistConcertsCache.current[normalizedName]) {
      const cached = artistConcertsCache.current[normalizedName];
      if ((now - cached.timestamp) < CACHE_TTL.concerts) {
        console.log(`🎸 Using cached artist concerts for ${artistName} (${cached.events.length} events)`);
        setArtistConcerts(cached.events);
        setArtistConcertsLoaded(true);
        return;
      }
    }

    const concertServices = getConcertServices();
    if (concertServices.length === 0) {
      // No concert plug-in, or none ready yet: a restored artist page asks
      // before the plug-ins and their settings load. Remember who asked, so
      // the effect below asks again once a concert plug-in is ready.
      // Not an answer, so not "loaded": an open On Tour keeps its tab and
      // skeleton until the real one.
      artistConcertsAskedEarlyRef.current = normalizedName;
      setArtistConcerts([]);
      return;
    }
    artistConcertsAskedEarlyRef.current = null;

    setArtistConcertsLoading(true);
    console.log(`🎸 Loading concerts for ${artistName} from ${concertServices.length} service(s)...`);

    try {
      const allEvents = [];
      const eventKeyToIndex = new Map();
      const geoKeyToEventKey = new Map();

      const normalizeForDedup = (str) =>
        (str || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim();

      const makeEventKey = (event) => {
        const date = event.date || '';
        const artist = normalizeForDedup(artistName);
        const venuePrefix = normalizeForDedup(event.venue?.name).slice(0, 20);
        return `${date}-${artist}-${venuePrefix}`;
      };

      const geoKey = (event) => {
        if (!event.venue?.latitude || !event.venue?.longitude) return null;
        const lat = Math.round(event.venue.latitude * 50) / 50;
        const lng = Math.round(event.venue.longitude * 50) / 50;
        return `${event.date || ''}-${normalizeForDedup(artistName)}-${lat},${lng}`;
      };

      const makeTicketSource = (event) => ({
        source: event.source,
        ticketUrl: event.ticketUrl || event.url || null,
        label: pluginName(event.source)
      });

      const addEventDeduped = (event) => {
        const key = makeEventKey(event);
        const gk = geoKey(event);

        let existingKey = eventKeyToIndex.has(key) ? key : null;
        if (!existingKey && gk && geoKeyToEventKey.has(gk)) {
          existingKey = geoKeyToEventKey.get(gk);
        }

        if (existingKey) {
          const idx = eventKeyToIndex.get(existingKey);
          const existing = allEvents[idx];
          const newSource = makeTicketSource(event);
          if (newSource.ticketUrl && !existing.ticketSources.some(s => s.source === newSource.source)) {
            existing.ticketSources.push(newSource);
          }
          if (event.lineup && event.lineup.length > (existing.lineup || []).length) {
            existing.lineup = event.lineup;
          }
          return;
        }

        event.ticketSources = [makeTicketSource(event)];
        if (gk) geoKeyToEventKey.set(gk, key);
        eventKeyToIndex.set(key, allEvents.length);
        allEvents.push(event);
      };

      // Query all concert services in parallel for this single artist
      const results = await Promise.allSettled(
        concertServices.map(async (service) => {
          const rawConfig = metaServiceConfigs[service.id] || {};
          const authField = Object.keys(service.configurable || service.settings?.configurable || {}).find(k => k !== 'model');
          const config = (authField && authField !== 'apiKey' && !rawConfig[authField] && rawConfig.apiKey)
            ? { ...rawConfig, [authField]: rawConfig.apiKey }
            : rawConfig;
          return service.searchArtistEvents(artistName, config);
        })
      );

      for (const result of results) {
        if (result.status === 'fulfilled' && Array.isArray(result.value)) {
          for (const event of result.value) {
            addEventDeduped(event);
          }
        }
      }

      // Filter to future dates only and sort
      const today = new Date().toISOString().split('T')[0];
      const futureEvents = allEvents
        .filter(e => !e.date || e.date >= today)
        .sort((a, b) => (a.date || '').localeCompare(b.date || ''));

      console.log(`🎸 Found ${futureEvents.length} upcoming concerts for ${artistName}`);

      setArtistConcerts(futureEvents);
      setArtistConcertsLoaded(true);

      // Cache results
      artistConcertsCache.current[normalizedName] = { events: futureEvents, timestamp: Date.now() };
    } catch (error) {
      console.error(`Failed to load concerts for ${artistName}:`, error);
      setArtistConcerts([]);
      setArtistConcertsLoaded(true);
    } finally {
      setArtistConcertsLoading(false);
    }
  };

  // An artist's concerts asked for before a concert plug-in was ready (a
  // restored artist page) read as none; ask again once one is. And On Tour
  // never shows an artist with no upcoming concerts: once the answer is none,
  // the page goes back to Music.
  const concertServiceCount = useMemo(() => getConcertServices().length, [loadedResolvers, metaServiceConfigs]);
  useEffect(() => {
    const name = currentArtist?.name;
    if (!name || concertServiceCount === 0) return;
    if (artistConcertsAskedEarlyRef.current === name.trim().toLowerCase()) {
      artistConcertsAskedEarlyRef.current = null;
      loadArtistConcerts(name);
    }
  }, [concertServiceCount, currentArtist?.name]);
  useEffect(() => {
    if (artistPageTab === 'on-tour' && artistConcertsLoaded && !artistConcertsLoading && artistConcerts.length === 0) {
      setArtistPageTab('music');
    }
  }, [artistPageTab, artistConcertsLoaded, artistConcertsLoading, artistConcerts.length]);

  // Handle scroll for Concerts header collapse
  const handleConcertsScroll = (e) => {
    const scrollTop = e.target.scrollTop;
    const container = e.target;
    if (scrollTop > 100 && !concertsHeaderCollapsed) {
      const hasEnoughContent = container.scrollHeight - container.clientHeight > 300;
      if (hasEnoughContent) {
        setConcertsHeaderCollapsed(true);
      }
    } else if (scrollTop <= 50 && concertsHeaderCollapsed) {
      setConcertsHeaderCollapsed(false);
    }
  };

  // ── Recommendations ────────────────────────────────────────────────────
  // The Recommendations page is provider-driven: every plugin with the
  // `recommendations` capability (content resolvers and meta-services alike)
  // answers getRecommendations with sections of typed items
  // (docs/architecture/plugins.md, "Recommendations"), and the Shuffleupagus
  // (LLM) suggestions blend into the For you rows from
  // homeData.aiRecommendations (the same state Home renders its section
  // from). Providers with the `similarUsers` capability fill the Friends row.
  // loadRecommendations fetches each provider (a per-provider
  // cache in recommendationsCache, saved as cache_recommendations), and
  // refreshMergedRecommendations rebuilds the display model through
  // buildRecommendationPage — the LLM streams into its own state and
  // re-merges without refetching anyone, and the blocklist re-applies on
  // every merge so a block made since a cache was filled takes effect at once
  // (parachord#1006, same rule the flat page had).

  // The providers, in display order: ACTIVE content resolvers in the user's
  // priority order, then meta-services (never in activeIds — orderCatalogResolvers
  // puts them after, in manifest order; a meta-service's own config check
  // decides whether it has anything, and an unconfigured one answers [] with
  // no request).
  const recommendationProviders = () => {
    const loader = resolverLoaderRef.current;
    if (!loader?.getRecommendationResolvers) return [];
    const activeIds = activeResolversRef.current || [];
    const order = resolverOrderRef.current || [];
    const metaIds = new Set((metaServicesRef.current || []).map(s => s.id));
    return orderCatalogResolvers(
      loader.getRecommendationResolvers()
        .filter(r => activeIds.includes(r.id) || metaIds.has(r.id))
        // Its "Recommendations from X" switched off (#1505).
        .filter(r => !recommendationsOffRef.current.includes(r.id)),
      { activeIds, order }
    );
  };

  // The similar-users providers (the Friends row), found by capability and
  // ordered like the recommendation providers. Only those whose id is a
  // friend service (a plug-in with capabilities.friends, isFriendService):
  // Follow looks the person up on the
  // provider's id, so a provider for any other service would be asked for
  // people nobody can follow.
  const similarUsersProviders = () => {
    const loader = resolverLoaderRef.current;
    if (!loader?.getSimilarUsersResolvers) return [];
    const activeIds = activeResolversRef.current || [];
    const order = resolverOrderRef.current || [];
    const metaIds = new Set((metaServicesRef.current || []).map(s => s.id));
    return orderCatalogResolvers(
      loader.getSimilarUsersResolvers()
        .filter(r => isFriendService(r.id))
        .filter(r => activeIds.includes(r.id) || metaIds.has(r.id)),
      { activeIds, order }
    );
  };

  // Who the Friends row leaves out, read at merge time so a follow or a
  // removal made since the similar users were fetched applies at once: people
  // the user follows (same service and username, case-insensitive), people
  // they removed (hidden_friend_keys, already in friendKey form), and the
  // user's own account on each similar-users provider. A provider's id is the
  // friend `service` it speaks for.
  const recommendationExclusions = () => {
    const friendKeys = new Set((friendsRef.current || []).map(f => friendKey(f.service, f.username)));
    for (const key of hiddenFriendKeysRef.current || []) friendKeys.add(key);
    const selfKeys = new Set();
    for (const id of Object.keys(similarUsersRef.current)) {
      const username = metaServiceConfigsRef.current?.[id]?.username;
      if (username) selfKeys.add(friendKey(id, username));
    }
    // The friend services (#1539 step 5): the Friends row offers people only
    // from these.
    const friendServices = new Set(friendProvidersFor().map(r => r.id));
    return { friendKeys, selfKeys, friendServices };
  };

  // Rebuild the display model from the current provider results + the LLM
  // suggestions. Called after every provider fetch and every LLM streaming
  // update — cheap and idempotent. The blocklist applies to EVERY item the
  // page can show, at merge time: the providers' base sections, the items a
  // "load more" fetched (expandedSections — they bypass the base-section
  // filter), and the Shuffleupagus section — so a block made since any of
  // those were filled takes effect immediately (parachord#1006's rule, carried
  // over from the flat page's cached path).
  const refreshMergedRecommendations = () => {
    const blocklist = window.recommendationBlocklist;
    const notBlocked = (items) => blocklist
      ? blocklist.filterBlocked(recommendationBlocklistRef.current, items, blockedItemPick)
      : items;
    const providers = Object.values(providerSectionsRef.current).map(p => ({
      ...p,
      sections: blocklist
        ? p.sections
            .map(s => ({ ...s, items: notBlocked(s.items) }))
            .filter(s => s.items.length > 0)
        : p.sections
    }));
    const expandedSections = blocklist
      ? Object.fromEntries(Object.entries(expandedSectionsRef.current).map(([key, expansion]) => [
          key,
          { ...expansion, items: notBlocked(expansion.items || []) }
        ]))
      : expandedSectionsRef.current;
    // The Shuffleupagus items (the raw LLM albums/artists carry no `type` —
    // blockedItemPick speaks the typed item shape, so the filter runs on the
    // section items, after shuffleupagusSection maps them).
    const rawShuffle = shuffleupagusSection(aiRecommendationsRef.current || {});
    const shuffle = blocklist && rawShuffle
      ? {
          ...rawShuffle,
          sections: rawShuffle.sections
            .map(s => ({ ...s, items: notBlocked(s.items) }))
            .filter(s => s.items.length > 0)
        }
      : rawShuffle;
    // weeklySections is the page before the history-mix exclusion, for the
    // weekly mirror below (buildRecommendationViews).
    const { sections, weeklySections } = buildRecommendationViews({
      providers,
      shuffleupagus: shuffle,
      expandedSections,
      expandableResolverIds: expandableResolverIdsRef.current,
      similarUsers: Object.values(similarUsersRef.current),
      exclude: recommendationExclusions(),
      // Home's history mixes are play history, not recommendations.
      excludePlaylistIds: historyMixIdsRef.current
    });
    recommendationsFriendsShownRef.current = sections.some(s => s.type === 'friend');
    setRecommendations(prev => ({ ...prev, sections }));

    // Home's weekly fields mirror the page's weekly rows (the playlist view's
    // pendingPlaylistLoad lookup and the weekly covers effect read them; they
    // used to be fetched by name for Home). The functional update keeps
    // tracks a card already loaded, and an unchanged week returns `prev`, so
    // the LLM's streamed re-merges cost no render here. Built from the page
    // before the history-mix exclusion: Weekly Jams that are also a history
    // mix leave the page but must stay findable here.
    setHomeData(prev => {
      const weekly = weeklyHomeEntries(weeklySections, prev);
      if (weekly.weeklyJams === prev.weeklyJams && weekly.weeklyExploration === prev.weeklyExploration) return prev;
      return { ...prev, ...weekly };
    });

    // Unread badge (discovery): new content turns the dot on until the page
    // is seen — hashed over item names like the flat page hashed artist names.
    if (sections.length > 0) {
      const hash = generateDiscoveryHash(flattenRecommendationItems(sections), i => i.name);
      checkDiscoveryUnread('recommendations', hash);
    }
  };

  // A follow or a removal re-merges at once (no refetch): the exclusions are
  // read at merge time. Keyed on a digest of the friend keys, not the friends
  // array, which the activity polls replace without changing who's in it.
  const similarExclusionDigest = useMemo(() => [
    ...friends.map(f => `${f.service}:${(f.username || '').toLowerCase()}`),
    ...hiddenFriendKeys
  ].sort().join('|'), [friends, hiddenFriendKeys]);
  useEffect(() => {
    if (Object.keys(similarUsersRef.current).length > 0) refreshMergedRecommendations();
  }, [similarExclusionDigest]);
  // New history mixes re-merge too, so a mix that just arrived leaves the
  // Playlists row at once.
  useEffect(() => {
    if (Object.keys(providerSectionsRef.current).length > 0) refreshMergedRecommendations();
  }, [historyMixIds]);

  // `opts.metaServicesOnly` asks only the meta-service providers (Last.fm,
  // ListenBrainz). Home's old For You preview loaded with it, so a content
  // resolver's recommendation fetches never queued ahead of resolution on a
  // Home visit. The redesigned Home shows every provider's album picks, so it
  // runs the full load, but only after first paint, from an idle callback
  // (home-page.js). Nothing calls it with the option today.
  // Which providers the last full load asked, as recommendationProviderKey.
  // A load that ran before the plugins finished loading (the app reopening on
  // this page) asked none; the effect below loads again once the set changes.
  const recommendationProviderIdsRef = useRef(null);
  // When the last full (not meta-only) load finished: Home's load skips a
  // visit within 10 minutes of it (loadHomeRecommendations).
  const recommendationsFullLoadAtRef = useRef(0);
  // Bumped by every load that fetches; only the latest one puts sections on screen.
  const recommendationsLoadGenRef = useRef(0);
  // Saves the provider answers that have sections and are young enough to show
  // again (CACHE_TTL.recommendationsStale), so the next launch opens on them.
  const saveRecommendationsCache = () => {
    if (!window.electron?.store) return;
    const now = Date.now();
    const providers = {};
    for (const [id, entry] of Object.entries(recommendationsCache.current.providers || {})) {
      if (entry && entry.sections && entry.sections.length > 0 && (now - entry.fetchedAt) < CACHE_TTL.recommendationsStale) providers[id] = entry;
    }
    // Similar users: any answer younger than the stale bound, an empty one
    // too. A successful empty answer is a real answer (a failure throws and
    // stores nothing), so the next launch does not re-run the lookup for it.
    const similarUsers = {};
    for (const [id, entry] of Object.entries(recommendationsCache.current.similarUsers || {})) {
      if (entry && Array.isArray(entry.users) && (now - entry.fetchedAt) < CACHE_TTL.recommendationsStale) similarUsers[id] = entry;
    }
    // Album release dates still inside their week, newest 1500 at most.
    const releaseDates = Object.fromEntries(Object.entries(recommendationReleaseDatesRef.current || {})
      .filter(([, entry]) => entry && typeof entry.at === 'number' && (now - entry.at) < RELEASE_DATE_TTL_MS)
      .sort((a, b) => b[1].at - a[1].at)
      .slice(0, 1500));
    try {
      window.electron.store.set('cache_recommendations', { providers, similarUsers, releaseDates, savedAt: now });
    } catch (e) { /* best-effort: the page refetches next launch */ }
  };
  saveRecommendationsCacheRef.current = saveRecommendationsCache;
  const recommendationProviderKey = (providers) => providers.map(p => p.id).join('|');
  const loadRecommendations = async (opts = {}) => {
    const forceRefresh = opts === true || opts?.forceRefresh === true;
    const metaOnly = opts !== true && !!opts?.metaServicesOnly;
    const metaServiceIds = new Set((metaServicesRef.current || []).map(s => s.id));
    const providers = metaOnly
      ? recommendationProviders().filter(p => metaServiceIds.has(p.id))
      : recommendationProviders();
    // The provider set a full load asked (see the effect that reloads when it changes).
    if (!metaOnly) recommendationProviderIdsRef.current = recommendationProviderKey(providers);
    const chatServices = getChatServices();
    const llmPossible = chatServices.some(isServiceEnabled) && aiIncludeHistoryRef.current;

    // A source is "configured" when it can produce recommendations: a
    // Last.fm/ListenBrainz username, an active recommendations-capable content
    // resolver, or an enabled chat provider with sharing on (Shuffleupagus).
    // A signed-out resolver is configured-but-not-ready:
    // its section simply does not appear.
    const metaConfigs = metaServiceConfigsRef.current || {};
    const hasLastfm = !!metaConfigs.lastfm?.username;
    const hasListenbrainz = !!metaConfigs.listenbrainz?.username;
    const hasActiveResolverProvider = providers.some(p => !metaServiceIds.has(p.id));
    if (!hasLastfm && !hasListenbrainz && !hasActiveResolverProvider && !llmPossible) {
      console.log('⭐ No recommendation source configured, skipping recommendations load');
      setRecommendationsPending([]);
      setRecommendations({ sections: [], loading: false, error: 'not_configured' });
      return;
    }

    // Per-provider session cache: a provider that answered recently is not
    // asked again within the TTL (CACHE_TTL.recommendations, 1h). An EMPTY
    // answer is never SERVED from the cache — the flat page's rule ("Not
    // cached, so the next visit asks again"): a genuine miss re-asks next
    // visit, and a transient network failure never blanks a provider for the
    // whole hour.
    const cache = recommendationsCache.current;
    const now = Date.now();
    // The account an answer belongs to: a meta-service's username (a changed
    // Last.fm/ListenBrainz user must never see the old one's sections); ''
    // for a provider whose account the page can't see.
    const accountFor = (provider) => (metaServiceConfigsRef.current?.[provider.id]?.username) || '';
    const cachedFor = (provider) => {
      const entry = cache.providers[provider.id];
      return entry && (entry.account || '') === accountFor(provider) ? entry : null;
    };
    const fresh = {};
    // Saved answers past the TTL that still show while their provider
    // refreshes (CACHE_TTL.recommendationsStale), so a launch opens on last
    // time's sections instead of a skeleton.
    const stale = {};
    const toFetch = [];
    for (const provider of providers) {
      const cached = cachedFor(provider);
      const hasSections = !!(cached && cached.sections.length > 0);
      if (!forceRefresh && hasSections && (now - cached.fetchedAt) < CACHE_TTL.recommendations) {
        fresh[provider.id] = cached;
        continue;
      }
      if (hasSections && (now - cached.fetchedAt) < CACHE_TTL.recommendationsStale) stale[provider.id] = cached;
      toFetch.push(provider);
    }

    // Similar users (the Friends row): under the providers' account check, a
    // cached answer stays fresh until it is stale (CACHE_TTL.recommendationsStale,
    // 7 days), not the providers' hour: who listens like you changes slowly,
    // and one provider's lookup can be ~60 paced requests. Unlike the
    // providers, an EMPTY answer counts too: a successful empty answer is a
    // real answer (failures throw and store nothing), and re-asking it on
    // every visit re-ran the paced lookup behind a Friends skeleton. Such a
    // provider is quiet (no skeleton) until it answers with people. A forced
    // refresh asks again. Fetched only on a full load: Home's meta-only load
    // shows what's cached and asks no one.
    const similarProviders = similarUsersProviders();
    const similarCachedFor = (provider) => {
      const entry = (recommendationsCache.current.similarUsers || {})[provider.id];
      return entry && Array.isArray(entry.users) && (entry.account || '') === accountFor(provider) ? entry : null;
    };
    // An answer saved in an older shape is shown while a new one is fetched,
    // so a change to what the plugins answer shows without a 7-day wait:
    // 2 added the cards' top artists, 3 dropped inactive listeners.
    const SIMILAR_USERS_SHAPE = 3;
    const similarFresh = {};
    const similarStale = {};
    const similarToFetch = [];
    for (const provider of similarProviders) {
      const cached = similarCachedFor(provider);
      const withinStale = !!(cached && (now - cached.fetchedAt) < CACHE_TTL.recommendationsStale);
      const young = withinStale && cached.shape === SIMILAR_USERS_SHAPE;
      // Old-shape people stay on screen (stale) while the new answer loads.
      const hasUsers = withinStale && cached.users.length > 0;
      if (young && cached.users.length === 0) recommendationsQuietRef.current.add(`friends:${provider.id}`);
      if (!forceRefresh && young) {
        similarFresh[provider.id] = cached;
        continue;
      }
      if (hasUsers) similarStale[provider.id] = cached;
      if (metaOnly) continue;
      similarToFetch.push(provider);
    }

    // A forced refresh also forgets the "load more" pages (their items merge
    // into the refreshed sections; a stale cursor must not survive a re-fetch).
    if (forceRefresh) {
      expandedSectionsRef.current = {};
      setExpandedSections({});
    }

    // A newer load (navigation, the provider-set effect, Home's meta-only
    // load) supersedes this one: its answers still land in the cache, but only
    // the latest load puts sections on screen.
    const generation = ++recommendationsLoadGenRef.current;
    const isLatest = () => recommendationsLoadGenRef.current === generation;

    const applyFresh = () => {
      if (!isLatest()) return;
      // Insertion order = display order (the fetch completion order is not).
      const ordered = {};
      for (const provider of providers) {
        const entry = fresh[provider.id] || stale[provider.id];
        if (entry) ordered[provider.id] = entry;
      }
      providerSectionsRef.current = ordered;
      const orderedUsers = {};
      for (const provider of similarProviders) {
        const entry = similarFresh[provider.id] || similarStale[provider.id];
        if (entry) orderedUsers[provider.id] = { resolverId: provider.id, resolverName: provider.name || provider.id, users: entry.users };
      }
      similarUsersRef.current = orderedUsers;
      expandableResolverIdsRef.current = providers
        .filter(p => typeof p.expandRecommendationSection === 'function')
        .map(p => p.id);
      refreshMergedRecommendations();
    };

    // The sections this load put up (its fresh and stale provider answers),
    // for the Home throttle's stamp below.
    const loadSectionCount = () => providers.reduce((n, p) => {
      const entry = fresh[p.id] || stale[p.id];
      return n + ((entry && entry.sections) ? entry.sections.length : 0);
    }, 0);
    // Home's throttle counts only a full load that answered: one where every
    // asked provider failed, or that left no section, is retried next visit.
    // (`failed` is passed in: its `let` is declared further down.)
    const stampFullLoad = (fetched, failed) => {
      if (!metaOnly && shouldStampHomeRecommendationsLoad({ fetched, failed, sectionCount: loadSectionCount() })) {
        recommendationsFullLoadAtRef.current = Date.now();
      }
    };

    if (toFetch.length === 0 && similarToFetch.length === 0) {
      stampFullLoad(0, 0);
      setRecommendationsPending([]);
      applyFresh();
      // Everything came from cache (or no provider exists): the same empty
      // check the post-fetch path runs, so a return visit to an all-empty
      // page still says why instead of rendering nothing.
      const anySections = Object.values(providerSectionsRef.current).some(p => p.sections.length > 0);
      const llm = aiRecommendationsRef.current;
      const llmHas = !!(llm && ((llm.albums || []).length > 0 || (llm.artists || []).length > 0));
      const anyFriends = recommendationsFriendsShownRef.current;
      setRecommendations(prev => ({
        ...prev,
        loading: false,
        error: (!anySections && !llmHas && !anyFriends) ? emptyRecommendationsMessage({ hasListenbrainz, hasLastfm }) : null
      }));
      return;
    }

    // Last time's sections first (fresh and stale), then the skeleton only
    // covers what has nothing to show.
    applyFresh();
    // A provider that already produced sections keeps them visible while a
    // partial refresh runs; the skeleton only covers a truly empty page.
    setRecommendations(prev => ({ ...prev, loading: prev.sections.length === 0, error: null }));
    // A provider whose sections are on screen (this session's or saved ones)
    // refreshes in place; the rest share one skeleton until each answers.
    setRecommendationsPending(toFetch
      .filter(p => !((providerSectionsRef.current[p.id] || {}).sections || []).length)
      .filter(p => !recommendationsQuietRef.current.has(p.id))
      .map(p => ({ id: p.id, name: p.name || p.id }))
      // A similar-users lookup whose provider has nothing cached to show: the
      // Friends row's skeleton (a cached answer shows while it refreshes, and
      // one whose last answer was empty is quiet, as for the providers).
      // Its own id, so a provider that is both kinds (Last.fm) leaves the
      // list once per answer.
      .concat(similarToFetch
        .filter(p => !similarStale[p.id] && !recommendationsQuietRef.current.has(`friends:${p.id}`))
        .map(p => ({ id: `friends:${p.id}`, name: p.name || p.id, friends: true }))));

    const loader = resolverLoaderRef.current;
    let failed = 0;

    // The usernames a similar-users provider should leave out on its own
    // service: the people followed there and the ones removed (hidden friend
    // keys are `${service}:${lowercased username}`). Last.fm's lookup uses them
    // to skip candidates before paying for their top artists; the merge
    // applies the full exclusion either way.
    const excludeUsernamesFor = (serviceId) => {
      const names = new Set();
      for (const f of friendsRef.current || []) {
        if (f && f.service === serviceId && f.username) names.add(f.username.toLowerCase());
      }
      const prefix = `${serviceId}:`;
      for (const key of hiddenFriendKeysRef.current || []) {
        if (typeof key === 'string' && key.startsWith(prefix)) names.add(key.slice(prefix.length));
      }
      return [...names];
    };
    // One similar-users provider, under the providers' bound and generation
    // guard. A failure keeps the cached answer (even a stale one) and caches
    // nothing; a late answer is applied and saved, as for the providers.
    // A lookup already in flight for this account (an earlier load's) is
    // awaited, not repeated; this load still applies its answer under its own
    // generation. A config whose credential isn't ready yet is "not ready":
    // the plugin would answer a keyless [] that must not replace a good
    // cached answer, so nothing is asked, stored or saved, and the next load
    // tries again.
    const fetchSimilarUsers = async (provider) => {
      try {
        const account = accountFor(provider);
        let inFlight = similarUsersInFlightRef.current[provider.id];
        if (!inFlight || inFlight.account !== account) {
          const run = (async () => {
            const config = await getResolverConfig(provider.id);
            if (config?.credentialsPending) {
              const notReady = new Error('credentials not ready');
              notReady.notReady = true;
              throw notReady;
            }
            return loader.getSimilarUsers(provider.id, { ...config, excludeUsernames: excludeUsernamesFor(provider.id) });
          })();
          inFlight = { account, request: run };
          similarUsersInFlightRef.current[provider.id] = inFlight;
          const settled = inFlight;
          const clear = () => {
            if (similarUsersInFlightRef.current[provider.id] === settled) delete similarUsersInFlightRef.current[provider.id];
          };
          run.then(clear, clear);
        }
        const request = inFlight.request;
        let timer = null;
        const TIMED_OUT = Symbol('timed out');
        const raw = await Promise.race([
          request,
          new Promise(resolve => {
            timer = setTimeout(() => resolve(TIMED_OUT), CACHE_TTL.recommendationProvider);
            if (typeof timer.unref === 'function') timer.unref();
          })
        ]);
        clearTimeout(timer);
        const accept = (users) => {
          similarFresh[provider.id] = { users: Array.isArray(users) ? users : [], fetchedAt: Date.now(), account, shape: SIMILAR_USERS_SHAPE };
          // Stored and saved even when empty: a successful empty answer is a
          // real answer, fresh for the stale bound like any other.
          if (!recommendationsCache.current.similarUsers) recommendationsCache.current.similarUsers = {};
          recommendationsCache.current.similarUsers[provider.id] = similarFresh[provider.id];
          if (similarFresh[provider.id].users.length > 0) recommendationsQuietRef.current.delete(`friends:${provider.id}`);
          else recommendationsQuietRef.current.add(`friends:${provider.id}`);
        };
        if (raw === TIMED_OUT) {
          request.then((late) => {
            accept(late);
            applyFresh();
            saveRecommendationsCache();
            // The round may already have shown the empty message: Friends win.
            if (isLatest() && recommendationsFriendsShownRef.current) {
              setRecommendations(prev => ({ ...prev, loading: false, error: null }));
            }
          }).catch(() => { /* the provider's own failure: nothing to apply */ });
          throw new Error('timed out');
        }
        accept(raw);
      } catch (error) {
        // The message only: the config can carry an API key.
        console.warn(`⭐ Similar users from ${provider.name || provider.id} failed:`, error?.message || error);
        if (similarCachedFor(provider)) similarFresh[provider.id] = similarCachedFor(provider);
      }
      applyFresh();
      if (isLatest()) setRecommendationsPending(prev => prev.filter(p => p.id !== `friends:${provider.id}`));
    };

    await Promise.all([
      ...toFetch.map(async (provider) => {
      try {
        const config = await getResolverConfig(provider.id);
        // Providers are not on an interactive path (the page shows the other
        // sections meanwhile), so the bound is generous — a resolver's page flow
        // alone can take several seconds. The timer is cleared when the
        // provider wins, so it does not linger to the process end.
        let timer = null;
        const request = loader.getRecommendations(provider.id, config);
        const TIMED_OUT = Symbol('timed out');
        const raw = await Promise.race([
          request,
          new Promise(resolve => {
            timer = setTimeout(() => resolve(TIMED_OUT), CACHE_TTL.recommendationProvider);
            if (typeof timer.unref === 'function') timer.unref();
          })
        ]);
        clearTimeout(timer);
        const accept = (answer) => {
          fresh[provider.id] = {
            ...normalizeRecommendationSections(answer, { resolverId: provider.id, resolverName: provider.name }),
            fetchedAt: Date.now(),
            account: accountFor(provider)
          };
          // Stored even when empty (an empty answer is never SERVED: the
          // sections check above), so it replaces an older answer.
          recommendationsCache.current.providers[provider.id] = fresh[provider.id];
          if (fresh[provider.id].sections.length > 0) recommendationsQuietRef.current.delete(provider.id);
          else recommendationsQuietRef.current.add(provider.id);
        };
        if (raw === TIMED_OUT) {
          // The bound only ends this provider's skeleton; its answer is still
          // worth having. A late one goes on screen (if this load is still the
          // latest) and into the cache, instead of being dropped (an Amazon
          // account whose music tab is refused can take 20s+: two home loads).
          request.then((late) => {
            if (late == null) return;
            accept(late);
            applyFresh();
            saveRecommendationsCache();
            // The round may already have shown the empty message: sections win.
            if (isLatest() && fresh[provider.id].sections.length > 0) {
              setRecommendations(prev => ({ ...prev, loading: false, error: null }));
            }
          }).catch(() => { /* the provider's own failure: nothing to apply */ });
          throw new Error('timed out');
        }
        if (raw == null) throw new Error('no answer');
        accept(raw);
      } catch (error) {
        console.warn(`⭐ Recommendations from ${provider.name || provider.id} failed:`, error?.message || error);
        failed++;
        if (error?.notReady) {
          // Not ready is an answer (this account can't get its sections now):
          // the cached sections belong to a session that cannot refresh them,
          // so they are dropped instead of resurrected forever, on screen and
          // on disk.
          recommendationsQuietRef.current.add(provider.id);
          delete stale[provider.id];
          delete recommendationsCache.current.providers[provider.id];
        } else if (cachedFor(provider)) {
          // A transient failure (timeout, network) says nothing: keep the
          // cached result, even an expired one, so it does not blank a section
          // that was on screen.
          fresh[provider.id] = cachedFor(provider);
        }
      }
      // Each answer goes on screen as it lands: a slow provider no longer
      // holds back the others.
      applyFresh();
      if (isLatest()) setRecommendationsPending(prev => prev.filter(p => p.id !== provider.id));
      }),
      ...similarToFetch.map(fetchSimilarUsers)
    ]);

    recommendationsCache.current.timestamp = Date.now();
    saveRecommendationsCache();
    stampFullLoad(toFetch.length, failed);
    if (!isLatest()) return;
    setRecommendationsPending([]);

    const anySections = Object.values(providerSectionsRef.current).some(p => p.sections.length > 0);
    const llm = aiRecommendationsRef.current;
    const llmHas = !!(llm && ((llm.albums || []).length > 0 || (llm.artists || []).length > 0));
    // Friends counts: a page whose only content is the Friends row is not
    // empty (the empty branch below would also clear the row off the page).
    const anyFriends = recommendationsFriendsShownRef.current;
    if (!anySections && !llmHas && !anyFriends) {
      if (failed === toFetch.length && failed > 0) {
        setRecommendations({ sections: [], loading: false, error: 'Failed to load recommendations. Please try again.' });
      } else {
        // Not cached, so the next visit asks again.
        setRecommendations({ sections: [], loading: false, error: emptyRecommendationsMessage({ hasListenbrainz, hasLastfm }) });
      }
      return;
    }
    setRecommendations(prev => ({ ...prev, loading: false, error: null }));
  };

  // ── History mixes ("Made from your listening" on Home) ────────────────
  // Every plugin with the `historyMixes` capability answers getHistoryMixes
  // with the mixes its service makes from the user's own listening (Heavy
  // Rotation, Daily Jams, ...; docs/architecture/plugins.md, "History
  // mixes"). Loaded the way loadRecommendations loads its providers: per
  // provider, in the same order, each bounded at
  // CACHE_TTL.recommendationProvider, served from the cache for
  // CACHE_TTL.recommendations, shown stale up to CACHE_TTL.recommendationsStale
  // while it refreshes, and saved as cache_history_mixes.
  const historyMixProviders = () => {
    const loader = resolverLoaderRef.current;
    if (!loader?.getHistoryMixResolvers) return [];
    const activeIds = activeResolversRef.current || [];
    const order = resolverOrderRef.current || [];
    const metaIds = new Set((metaServicesRef.current || []).map(s => s.id));
    return orderCatalogResolvers(
      loader.getHistoryMixResolvers().filter(r => activeIds.includes(r.id) || metaIds.has(r.id)),
      { activeIds, order }
    );
  };
  // The account a provider's mixes belong to: a meta-service's username (a
  // changed ListenBrainz user must never see the old one's mixes); '' for a
  // provider whose account the app can't see.
  const historyMixAccountFor = (provider) => (metaServiceConfigsRef.current?.[provider.id]?.username) || '';
  // The provider set (and accounts) the last load asked; null before any
  // load. The effect below loads again when it changes.
  const historyMixProviderKey = (providers) => providers.map(p => `${p.id}:${historyMixAccountFor(p)}`).join('|');
  const historyMixProviderKeyRef = useRef(null);
  // When the last load that answered finished: Home's throttle (the
  // recommendations one, shouldLoadHomeRecommendations) skips a visit within
  // 10 minutes of it.
  const historyMixesLoadAtRef = useRef(0);
  // Bumped by every load; only the latest one puts mixes on screen.
  const historyMixesLoadGenRef = useRef(0);
  const historyMixesLoadingRef = useRef(false);
  // Saves the providers' answers that have mixes and are young enough to show
  // again, so the next launch opens on them.
  const saveHistoryMixesCache = () => {
    if (!window.electron?.store) return;
    const now = Date.now();
    const providers = {};
    for (const [id, entry] of Object.entries(historyMixesCache.current.providers || {})) {
      if (entry && Array.isArray(entry.items) && entry.items.length > 0 && (now - entry.fetchedAt) < CACHE_TTL.recommendationsStale) providers[id] = entry;
    }
    try {
      window.electron.store.set('cache_history_mixes', { providers, savedAt: now });
    } catch (e) { /* best-effort: Home refetches next launch */ }
  };
  const loadHistoryMixes = async (opts = {}) => {
    const forceRefresh = opts === true || opts?.forceRefresh === true;
    // A newer load supersedes this one: its answers still land in the cache,
    // but only the latest load puts mixes on screen.
    const generation = ++historyMixesLoadGenRef.current;
    const isLatest = () => historyMixesLoadGenRef.current === generation;
    historyMixesLoadingRef.current = true;
    try {
      // The saved mixes arrive with the big caches, after first paint; a
      // load before them would find the cache empty and refetch everything.
      await waitForBigCaches();
      // The provider list is complete only once the plugins have loaded. A
      // launch onto Home runs this before then, and an empty list there would
      // wipe last session's mixes.
      if (resolversInitRef.current) {
        let initTimer = null;
        await Promise.race([
          resolversInitRef.current,
          new Promise(resolve => { initTimer = setTimeout(resolve, 15000); })
        ]);
        clearTimeout(initTimer);
      }
      const loader = resolverLoaderRef.current;
      if (!loader) {
        // A slow launch: the plugins are still loading after the wait. Clear
        // the key so the provider-set effect loads once they are in.
        historyMixProviderKeyRef.current = '';
        return;
      }
      const providers = historyMixProviders();
      historyMixProviderKeyRef.current = historyMixProviderKey(providers);

      const now = Date.now();
      const cachedFor = (provider) => historyMixCacheEntry(historyMixesCache.current.providers[provider.id], historyMixAccountFor(provider));
      // An EMPTY answer is never served from the cache (the recommendations
      // rule): a genuine miss is asked again next time.
      const fresh = {};
      const stale = {};
      const toFetch = [];
      for (const provider of providers) {
        const cached = cachedFor(provider);
        const hasItems = !!(cached && cached.items.length > 0);
        if (!forceRefresh && hasItems && (now - cached.fetchedAt) < CACHE_TTL.recommendations) {
          fresh[provider.id] = cached;
          continue;
        }
        if (hasItems && (now - cached.fetchedAt) < CACHE_TTL.recommendationsStale) stale[provider.id] = cached;
        toFetch.push(provider);
      }

      // In provider priority order. An apply that changes nothing (every
      // answer served from the cache, the usual return visit) keeps the
      // previous array, so it costs no Recommendations re-merge and no Home
      // render.
      const apply = () => {
        if (!isLatest()) return;
        const entries = historyMixEntriesFor(providers, (p) => fresh[p.id] || stale[p.id]);
        setHistoryMixEntries(prev => (sameHistoryMixEntries(prev, entries) ? prev : entries));
      };
      const mixCount = () => providers.reduce((n, p) => {
        const entry = fresh[p.id] || stale[p.id];
        return n + (entry ? entry.items.length : 0);
      }, 0);
      // Home's throttle counts only a load that answered with mixes (the
      // recommendations rule): one where every provider failed, or that left
      // nothing to show, is retried on the next visit.
      const stamp = (fetched, failed) => {
        if (shouldStampHomeRecommendationsLoad({ fetched, failed, sectionCount: mixCount() })) {
          historyMixesLoadAtRef.current = Date.now();
        }
      };

      // Last time's mixes first; each provider replaces its own as it answers.
      apply();
      if (toFetch.length === 0) {
        stamp(0, 0);
        return;
      }

      let failed = 0;
      await Promise.all(toFetch.map(async (provider) => {
        try {
          const config = await getResolverConfig(provider.id);
          let timer = null;
          const request = loader.getHistoryMixes(provider.id, config);
          const TIMED_OUT = Symbol('timed out');
          const raw = await Promise.race([
            request,
            new Promise(resolve => {
              timer = setTimeout(() => resolve(TIMED_OUT), CACHE_TTL.recommendationProvider);
              if (typeof timer.unref === 'function') timer.unref();
            })
          ]);
          clearTimeout(timer);
          const accept = (mixes) => {
            fresh[provider.id] = {
              resolverId: provider.id,
              resolverName: provider.name || provider.id,
              items: normalizeHistoryMixes(mixes, provider),
              fetchedAt: Date.now(),
              account: historyMixAccountFor(provider)
            };
            // Stored even when empty (an empty answer is never SERVED), so it
            // replaces an older answer.
            historyMixesCache.current.providers[provider.id] = fresh[provider.id];
          };
          if (raw === TIMED_OUT) {
            // The bound only stops waiting; a late answer is still applied
            // (if this load is still the latest) and saved.
            request.then((late) => {
              accept(late);
              apply();
              saveHistoryMixesCache();
            }).catch(() => { /* the provider's own failure: nothing to apply */ });
            throw new Error('timed out');
          }
          accept(raw);
        } catch (error) {
          // The message only: a config can carry a token.
          console.warn(`🎧 History mixes from ${provider.name || provider.id} failed:`, error?.message || error);
          failed++;
          if (error?.notReady) {
            // Not ready (signed out) is an answer: this account can't get its
            // mixes now, so the cached ones are dropped, on screen and on disk.
            delete stale[provider.id];
            delete historyMixesCache.current.providers[provider.id];
          } else if (cachedFor(provider)) {
            // A transient failure says nothing: the provider keeps its cached
            // mixes, even expired ones.
            fresh[provider.id] = cachedFor(provider);
          }
        }
        apply();
      }));

      saveHistoryMixesCache();
      stamp(toFetch.length, failed);
    } finally {
      if (isLatest()) historyMixesLoadingRef.current = false;
    }
  };
  // The throttled load Home's background effect and the Recommendations page
  // run: unless a load is running or one answered within 10 minutes (the
  // recommendations throttle, shouldLoadHomeRecommendations). Each provider
  // that answered within the hour is served from the cache anyway; the
  // throttle skips even that work on quick returns. The loading ref starts
  // false, so no "has a load started" check is needed (the recommendations
  // state's `loading` starts true, which is why theirs has one).
  const loadHomeHistoryMixes = () => {
    if (!shouldLoadHomeRecommendations({
      loading: historyMixesLoadingRef.current,
      loadStarted: true,
      lastFullLoadAt: historyMixesLoadAtRef.current,
      now: Date.now(),
    })) return;
    loadHistoryMixes();
  };
  // The provider set or an account changed after a load ran (the plugins
  // finished loading, a resolver was turned on or off or uninstalled, the
  // ListenBrainz user changed): load again, on the two pages that show or use
  // the mixes.
  useEffect(() => {
    if (!cacheLoaded || historyMixProviderKeyRef.current === null) return;
    if (activeView !== 'home' && activeView !== 'recommendations') return;
    if (historyMixProviderKey(historyMixProviders()) === historyMixProviderKeyRef.current) return;
    loadHistoryMixes();
  }, [activeView, cacheLoaded, loadedResolvers, activeResolvers, metaServices, metaServiceConfigs]);

  // "Load more" for a titled section whose provider can paginate
  // (expandRecommendationSection): fetch the next page and merge it into the
  // section. The fetched items live in expandedSections so a re-merge (the LLM
  // streaming an update) keeps them. The in-flight guard is a REF (the state
  // read is stale in the click closure until a re-render commits, so two quick
  // clicks both passed it), and the append builds from the functional
  // update's `prev` (the ref is only synced post-commit, so a second expansion
  // landing before the re-render would otherwise overwrite the first page).
  // `section` is a subsection (row). The guard and the expansion record are
  // keyed by its PROVIDER section (pagingKey): a mixed section splits into one
  // row per type, the splits share one cursor, and two open splits must never
  // fetch the same page twice.
  const recommendationsLoadingMoreRef = useRef({});
  const loadMoreRecommendationSection = async (section) => {
    const loader = resolverLoaderRef.current;
    if (!section?.resolverId || !section?.sectionId || !section?.pagingKey || !loader) return;
    if (recommendationsLoadingMoreRef.current[section.pagingKey]) return;
    recommendationsLoadingMoreRef.current[section.pagingKey] = true;
    setRecommendationsLoadingMore(prev => ({ ...prev, [section.pagingKey]: true }));
    const key = section.pagingKey;
    try {
      const config = await getResolverConfig(section.resolverId);
      const result = await loader.expandRecommendationSection(section.resolverId, section.sectionId, section.nextCursor, config);
      if (!result || !Array.isArray(result.items) || result.items.length === 0) {
        // Nothing more from the provider: remember the exhaustion so the
        // button goes away (a force-refresh resets it).
        setExpandedSections(prev => ({ ...prev, [key]: { ...(prev[key] || { items: [] }), exhausted: true, lastPageTypes: [], lastPageCategories: [] } }));
      } else {
        // No-advance guard (the same rule paginatePlaylistTracks enforces for
        // playlist pages): a provider answering the very cursor that was sent
        // re-served the same window. A cursor like that would make the
        // self-advancing Show-more effect fetch the identical page forever
        // (the provider's page cache answers instantly, so each loop is an
        // append + full-app render) — treat it as exhausted instead. The page
        // counter carries the same budget to a provider that cycles between
        // cursors or keeps minting new ones: at EXPANSION_PAGE_CAP fetched
        // pages the section is exhausted no matter what the cursor says.
        const noAdvance = result.nextCursor != null && result.nextCursor === section.nextCursor;
        const nextCursor = noAdvance ? null : (result.nextCursor || null);
        setExpandedSections(prev => {
          const prior = prev[key] || { items: [] };
          const pages = (prior.pages || 0) + 1;
          return {
            ...prev,
            [key]: {
              items: [...(prior.items || []), ...result.items],
              nextCursor,
              exhausted: !nextCursor || pages >= EXPANSION_PAGE_CAP,
              pages,
              // Which item types this page brought: every split of the
              // section shares the fetch, and a split whose type the page
              // didn't bring stops showing its loading tail (spec "Paging
              // guards") while the section pages on for the others.
              lastPageTypes: [...new Set(result.items.map(i => i && i.type).filter(Boolean))],
              // Which categories this page brought, typed (`playlist:personal`,
              // `album:new`): a category row whose type and category the page
              // didn't bring stops showing its tail.
              lastPageCategories: [...new Set(result.items.filter(i => i && (i.type === 'playlist' || i.type === 'album')).map(i => `${i.type}:${categoryFor(i.type, i, section.category)}`))]
            }
          };
        });
      }
    } catch (error) {
      console.warn(`⭐ Failed to expand recommendation section ${section.title || key}:`, error?.message || error);
      showToast(`Couldn't load more from ${section.resolverName || 'the service'}`, 'error');
    } finally {
      delete recommendationsLoadingMoreRef.current[section.pagingKey];
      setRecommendationsLoadingMore(prev => ({ ...prev, [section.pagingKey]: false }));
    }
  };

  // Re-merge when a "load more" answered (the merged section keeps the extra
  // items and the cursor) and when the expanded-section set changes.
  useEffect(() => {
    expandedSectionsRef.current = expandedSections;
    if (Object.keys(expandedSections).length > 0) refreshMergedRecommendations();
  }, [expandedSections]);

  // Collapse toggling for the sectioned page: a section shows its first few
  // items until expanded (the user's choice survives re-merges by section key).
  useEffect(() => {
    recommendationsExpandedSectionsRef.current = recommendationsExpandedSections;
  }, [recommendationsExpandedSections]);
  const toggleRecommendationSection = (key) => {
    setRecommendationsExpandedSections(prev => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key); else next.add(key);
      return next;
    });
  };

  // "Show more" is the only section control: expanding a paginated section
  // also drives its page fetches. The effect self-advances — every fetched page
  // re-merges the display model, which re-runs this effect, which fetches the
  // next page while the section stays expanded and the provider still has more
  // (canLoadMore turns false at exhaustion) — so the whole section fills in the
  // background while it is open. A section with no cursor yet is fetching its
  // FIRST page (the see-more route starts at page 1, which overlaps the section
  // base items — the merge dedupes). Collapsing stops the chain (the expanded
  // check), a failed page breaks it (the section state does not change on
  // failure, so the effect does not re-fire), and the ref guard inside
  // loadMoreRecommendationSection keeps one page in flight per provider
  // section. It walks the rows: open state is per row (subsection.key); a
  // blended row pages every provider section it lists in `pageable`, and the
  // in-flight guard is per provider section (pagingKey), which the rows of
  // two types can share.
  useEffect(() => {
    if (activeView !== 'recommendations') return;
    for (const row of recommendations.sections.flatMap(s => s.subsections)) {
      if (!recommendationsExpandedSections.has(row.key)) continue;
      for (const section of row.pageable || []) {
        if (recommendationsLoadingMoreRef.current[section.pagingKey]) continue;
        loadMoreRecommendationSection(section);
      }
    }
  }, [activeView, recommendations.sections, recommendationsExpandedSections]);

  // Measure the Recommendations grids' column count (the card grid is
  // auto-fill minmax(160px, 1fr) and the people grid minmax(150px, 1fr), both
  // with a 16px gap, inside the p-6 content box), so a collapsed section
  // fills exactly one row and See all only adds rows.
  useEffect(() => {
    if (activeView !== 'recommendations') return;
    const el = recommendationsScrollContainerRef.current;
    if (!el || typeof ResizeObserver === 'undefined') return;
    const measure = () => {
      const width = Math.max(0, el.clientWidth - 48);
      const fit = (min) => Math.max(1, Math.floor((width + 16) / (min + 16)));
      const next = { cards: fit(160), friends: fit(150) };
      setRecommendationsGridColumns(prev => (prev.cards === next.cards && prev.friends === next.friends ? prev : next));
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, [activeView, recommendationsScrollContainerReady]);

  // Last.fm and ListenBrainz recommendations now come from their plugins'
  // getRecommendations (plugins-src/{lastfm,listenbrainz}/implementation.js)
  // through the loader capability above — the fetches used to live here.
  // (The Recommendations page's own fetches were the last app.js code that
  // talked to a service by name instead of through a plugin capability.)
  //
  // ListenBrainz fetch helper with retry on 429 rate limits
  const fetchListenBrainz = async (url, maxRetries = 3) => {
    for (let attempt = 0; attempt < maxRetries; attempt++) {
      try {
        const response = await fetch(url);
        if (response.ok) return response;
        if (response.status === 429 || response.status === 503) {
          const delay = Math.pow(2, attempt) * 1500; // 1.5s, 3s, 6s
          console.log(`[ListenBrainz] Rate limited (${response.status}), retrying in ${delay}ms (attempt ${attempt + 1}/${maxRetries})`);
          await new Promise(resolve => setTimeout(resolve, delay));
          continue;
        }
        return response; // Non-retryable error
      } catch (networkError) {
        if (attempt < maxRetries - 1) {
          const delay = Math.pow(2, attempt) * 1500;
          console.log(`[ListenBrainz] Network error, retrying in ${delay}ms:`, networkError.message);
          await new Promise(resolve => setTimeout(resolve, delay));
        } else {
          throw networkError;
        }
      }
    }
    return fetch(url); // Final attempt
  };

  // Load tracks for a specific Weekly Jam playlist
  const loadWeeklyJamTracks = async (playlistId) => {
    try {
      const playlistResponse = await fetchListenBrainz(`https://api.listenbrainz.org/1/playlist/${playlistId}`);
      if (!playlistResponse.ok) return [];

      const playlistData = await playlistResponse.json();
      const tracks = playlistData.playlist?.track || [];

      return tracks.map((track, index) => {
        const ext = track.extension?.['https://musicbrainz.org/doc/jspf#track'];
        const addlMeta = ext?.additional_metadata || {};
        const albumArt = listenBrainzCoverUrl(addlMeta);
        return {
          id: track.identifier?.[0]?.split('/').pop() || `weekly-jam-${playlistId}-${index}`,
          title: track.title || 'Unknown Track',
          artist: track.creator || 'Unknown Artist',
          album: ext?.release_name || addlMeta.release_name || null,
          albumArt: albumArt,
          duration: track.duration ? Math.floor(track.duration / 1000) : null,
          sources: {},
          mbid: track.identifier?.[0]?.split('/').pop() || null
        };
      });
    } catch (error) {
      console.error('Failed to load weekly jam tracks:', error);
      return [];
    }
  };

  // homeData.weeklyJams / weeklyExploration are filled by
  // refreshMergedRecommendations from the page's weekly rows (the plugin's
  // weekly sections), never fetched here by service name.

  // Load covers for weekly jams and weekly exploration when they're available,
  // on Recommendations only: Home's meta-only load fills homeData.weekly* too,
  // but Home shows no weekly cards. (The playlist view's restore path reads
  // homeData, not these covers.)
  useEffect(() => {
    if (activeView !== 'recommendations') return;
    const loadWeeklyPlaylistCoversAsync = async () => {
      const allWeekly = [
        ...(homeData.weeklyJams || []),
        ...(homeData.weeklyExploration || [])
      ];
      if (allWeekly.length === 0) return;

      for (const entry of allWeekly) {
        // Skip if we already have covers for this playlist
        if (weeklyJamCovers[entry.id]) continue;

        // Load tracks first if needed
        let tracks = entry.tracks;
        if (!entry.tracksLoaded || tracks.length === 0) {
          tracks = await loadWeeklyJamTracks(entry.id);
          // Determine which array this entry belongs to and update it
          const isJam = homeData.weeklyJams?.some(j => j.id === entry.id);
          const field = isJam ? 'weeklyJams' : 'weeklyExploration';
          setHomeData(prev => ({
            ...prev,
            [field]: prev[field]?.map(j =>
              j.id === entry.id ? { ...j, tracks, tracksLoaded: true } : j
            )
          }));
        }

        // Get covers using the same function as regular playlists
        if (tracks.length > 0) {
          const covers = await getPlaylistCovers(entry.id, tracks);
          if (covers && covers.length > 0) {
            setWeeklyJamCovers(prev => ({ ...prev, [entry.id]: covers }));
          }
        }
      }
    };
    loadWeeklyPlaylistCoversAsync();
  }, [homeData.weeklyJams, homeData.weeklyExploration, activeView]);

  // Load AI-generated recommendations for the home page
  const loadAiRecommendations = async (onUpdate) => {
    const chatServices = getChatServices();
    const enabledServices = chatServices.filter(isServiceEnabled);

    if (enabledServices.length === 0) return null;

    const provider = selectedChatProvider
      ? enabledServices.find(s => s.id === selectedChatProvider) || enabledServices[0]
      : enabledServices[0];

    if (!provider?.chat) return null;

    // Build listening context for the prompt
    let contextInfo = '';

    // Helper: extract unique artists and albums from collection tracks (songs)
    const extractCollectionTrackContext = () => {
      const tracks = collectionData?.tracks || [];
      if (tracks.length === 0) return { artists: [], albums: [] };
      const seenArtists = new Set();
      const seenAlbums = new Set();
      const artists = [];
      const albums = [];
      for (const t of tracks) {
        const artistKey = (t.artist || '').toLowerCase();
        if (artistKey && !seenArtists.has(artistKey)) {
          seenArtists.add(artistKey);
          artists.push(t.artist);
        }
        const albumKey = `${(t.artist || '').toLowerCase()}|${(t.album || '').toLowerCase()}`;
        if (t.album && !seenAlbums.has(albumKey)) {
          seenAlbums.add(albumKey);
          albums.push({ artist: t.artist, title: t.album });
        }
      }
      return { artists, albums };
    };

    if (aiIncludeHistoryRef.current) {
      try {
        const listeningHistory = await fetchListeningContext();
        if (listeningHistory) {
          const parts = [];
          // Recent listens
          if (listeningHistory.recently_played?.length > 0) {
            parts.push('Recently played: ' + listeningHistory.recently_played.slice(0, 15).map(t => `${t.artist} - ${t.title}`).join(', '));
          }
          // Top artists across all time periods (not just this week)
          if (listeningHistory.top_artists?.length > 0) {
            parts.push('Top artists: ' + listeningHistory.top_artists.slice(0, 25).join(', '));
          }
          // Top tracks across all time periods
          if (listeningHistory.top_tracks?.length > 0) {
            parts.push('Top tracks: ' + listeningHistory.top_tracks.slice(0, 20).map(t => `${t.artist} - ${t.title}`).join(', '));
          }
          // Top albums across all time periods
          if (listeningHistory.top_albums?.length > 0) {
            parts.push('Top albums: ' + listeningHistory.top_albums.slice(0, 15).map(a => `${a.artist} - ${a.title}`).join(', '));
          }
          // Collection bookmarked artists
          const favArtists = (collectionData?.artists || []).slice(0, 15).map(a => a.name || a.artist);
          if (favArtists.length > 0) {
            parts.push('Favorite artists in collection: ' + favArtists.join(', '));
          }
          // Collection bookmarked albums
          const favAlbums = (collectionData?.albums || []).slice(0, 10).map(a => `${a.artist} - ${a.title || a.album}`);
          if (favAlbums.length > 0) {
            parts.push('Favorite albums in collection: ' + favAlbums.join(', '));
          }
          // Artists and albums extracted from collection tracks (songs)
          const trackContext = extractCollectionTrackContext();
          if (trackContext.artists.length > 0) {
            // Filter out artists already mentioned in top_artists or favArtists
            const alreadyMentioned = new Set([
              ...(listeningHistory.top_artists || []).map(a => a.toLowerCase()),
              ...favArtists.map(a => a.toLowerCase())
            ]);
            const newArtists = trackContext.artists.filter(a => !alreadyMentioned.has(a.toLowerCase()));
            if (newArtists.length > 0) {
              parts.push('Artists from saved songs: ' + newArtists.slice(0, 15).join(', '));
            }
          }
          if (trackContext.albums.length > 0) {
            const alreadyMentionedAlbums = new Set([
              ...(listeningHistory.top_albums || []).map(a => `${a.artist.toLowerCase()}|${a.title.toLowerCase()}`),
              ...favAlbums.map(a => a.toLowerCase())
            ]);
            const newAlbums = trackContext.albums.filter(a => !alreadyMentionedAlbums.has(`${a.artist.toLowerCase()}|${a.title.toLowerCase()}`));
            if (newAlbums.length > 0) {
              parts.push('Albums from saved songs: ' + newAlbums.slice(0, 10).map(a => `${a.artist} - ${a.title}`).join(', '));
            }
          }
          contextInfo = parts.join('\n');
        }
      } catch (e) {
        console.log('Could not fetch listening context for AI recommendations:', e.message);
      }
    }

    // Fallback: use collection data if no listening history
    if (!contextInfo) {
      const parts = [];
      const favArtists = (collectionData?.artists || []).slice(0, 15).map(a => a.name || a.artist);
      if (favArtists.length > 0) parts.push('Favorite artists: ' + favArtists.join(', '));
      const favAlbums = (collectionData?.albums || []).slice(0, 10).map(a => `${a.artist} - ${a.title || a.album}`);
      if (favAlbums.length > 0) parts.push('Favorite albums: ' + favAlbums.join(', '));
      // Also mine collection tracks for artists and albums
      const trackContext = extractCollectionTrackContext();
      if (trackContext.artists.length > 0) {
        const alreadyMentioned = new Set(favArtists.map(a => a.toLowerCase()));
        const newArtists = trackContext.artists.filter(a => !alreadyMentioned.has(a.toLowerCase()));
        if (newArtists.length > 0) parts.push('Artists from saved songs: ' + newArtists.slice(0, 20).join(', '));
      }
      if (trackContext.albums.length > 0) {
        const alreadyMentionedAlbums = new Set(favAlbums.map(a => a.toLowerCase()));
        const newAlbums = trackContext.albums.filter(a => !alreadyMentionedAlbums.has(`${a.artist.toLowerCase()}|${a.title.toLowerCase()}`));
        if (newAlbums.length > 0) parts.push('Albums from saved songs: ' + newAlbums.slice(0, 10).map(a => `${a.artist} - ${a.title}`).join(', '));
      }
      contextInfo = parts.join('\n') || 'No listening history available. Recommend diverse, acclaimed music.';
    }

    const config = metaServiceConfigs[provider.id] || {};

    // Build exclusion list from previously suggested albums/artists
    const prevAlbums = previousAiSuggestions.current.albums;
    const prevArtists = previousAiSuggestions.current.artists;
    let exclusionNote = '';
    const suggestionBlocklist = recommendationBlocklistRef.current;
    const blocklistLines = window.recommendationBlocklist ? window.recommendationBlocklist.formatForPrompt(suggestionBlocklist) : [];
    if (prevAlbums.length > 0 || prevArtists.length > 0 || blocklistLines.length > 0) {
      const parts = [];
      if (prevAlbums.length > 0) parts.push('Albums already suggested (DO NOT repeat these): ' + prevAlbums.map(a => `${a.artist} - ${a.title}`).join(', '));
      if (prevArtists.length > 0) parts.push('Artists already suggested (DO NOT repeat these): ' + prevArtists.map(a => a.name).join(', '));
      // parachord#1006: the user's blocklist goes to the model too, and is
      // filtered at the code level below in case the model ignores it.
      parts.push(...blocklistLines.map(l => l.trim()));
      exclusionNote = '\n\n' + parts.join('\n');
    }

    // Variety themes to steer recommendations in different directions each time
    const varietyThemes = [
      'Focus on hidden gems and underrated albums that even dedicated music fans might have missed.',
      'Lean toward albums from different decades — mix classic and contemporary.',
      'Prioritize artists from diverse geographic regions and music scenes around the world.',
      'Recommend albums known for exceptional production quality or sonic experimentation.',
      'Focus on genre-crossing albums that blend unexpected influences.',
      'Highlight debut albums or breakthrough records that defined an artist\'s sound.',
      'Recommend albums that are critically acclaimed deep cuts, not the artist\'s most popular work.',
      'Focus on albums from the last 5 years that push their genre forward.',
      'Recommend albums with strong thematic or conceptual cohesion.',
      'Lean toward collaborative albums, supergroups, or unexpected artist pairings.'
    ];
    const theme = varietyThemes[Math.floor(Math.random() * varietyThemes.length)];

    const systemPrompt = `You are a music recommendation engine. You MUST respond with ONLY a valid JSON object, no markdown, no explanations, no text before or after the JSON. The JSON must have exactly this structure:
{"albums":[{"title":"...","artist":"...","reason":"..."}],"artists":[{"name":"...","reason":"..."}]}
Provide exactly 12 albums and 20 artists. Each "reason" should be one short sentence explaining why this recommendation fits. Recommendations should be things the user has NOT already listened to — suggest new discoveries, not things already in their library or recent history. IMPORTANT: Only recommend full-length studio albums. Do NOT recommend singles, EPs, compilations, live albums, soundtracks, or remix albums. Every album must be a well-known, officially released studio album with a full tracklist.
Variety guidance: ${theme} Be creative and surprising — avoid defaulting to the most obvious or popular choices.`;

    const userPrompt = `Based on this listening profile, recommend 12 albums and 20 artists I should check out. For artists, go deep — suggest a wide variety spanning different genres, eras, and regions. Avoid defaulting to the most well-known names:\n\n${contextInfo}${exclusionNote}`;

    try {
      const response = await provider.chat(
        [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userPrompt }
        ],
        [], // No tools needed
        config
      );

      const content = response.content?.trim();
      if (!content) return null;

      // Extract JSON from response (handle markdown code blocks)
      let jsonStr = content;
      const jsonMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/);
      if (jsonMatch) {
        jsonStr = jsonMatch[1].trim();
      } else {
        // Try to find JSON object directly
        const braceMatch = content.match(/\{[\s\S]*\}/);
        if (braceMatch) jsonStr = braceMatch[0];
      }

      const parsed = JSON.parse(jsonStr);
      const notBlocked = (items, pick) => window.recommendationBlocklist
        ? window.recommendationBlocklist.filterBlocked(suggestionBlocklist, items, pick)
        : items;
      const candidateAlbums = notBlocked((parsed.albums || []).slice(0, 12).map(a => ({
        title: a.title || a.album || 'Unknown Album',
        artist: a.artist || 'Unknown Artist',
        reason: a.reason || '',
        art: null // Will be loaded asynchronously
      })));

      // Validate albums against MusicBrainz: must be a studio album (single API call per album)
      const mbHeaders = { 'User-Agent': 'Parachord/0.1 (https://parachord.com)' };
      const nonStudioTypes = ['live', 'compilation', 'remix', 'dj-mix', 'mixtape/street', 'demo', 'soundtrack'];
      const validateAlbum = async (album) => {
        try {
          const query = encodeURIComponent(`release-group:"${album.title}" AND artist:"${album.artist}" AND primarytype:album`);
          const searchResp = await fetch(
            `https://musicbrainz.org/ws/2/release-group?query=${query}&limit=5&fmt=json`,
            { headers: mbHeaders, mbBackground: true } // a refresh, not a click: background lane
          );
          if (!searchResp.ok) return null;
          const searchData = await searchResp.json();
          const results = searchData['release-groups'] || [];
          if (results.length === 0) return null;

          // Find a studio album match (primary-type=Album, no live/compilation/etc secondary types)
          const match = results.find(r => {
            const primaryType = r['primary-type']?.toLowerCase();
            const secondaryTypes = (r['secondary-types'] || []).map(t => t.toLowerCase());
            const artistMatch = r['artist-credit']?.[0]?.name?.toLowerCase() === album.artist.toLowerCase();
            return primaryType === 'album' && artistMatch && !secondaryTypes.some(t => nonStudioTypes.includes(t));
          });
          if (!match) return null;

          // Return the release-group ID so we can pre-seed the art cache
          return { releaseGroupId: match.id };
        } catch {
          return null;
        }
      };

      // Filter out albums that were already suggested in previous refreshes
      const prevAlbumKeys = new Set(
        previousAiSuggestions.current.albums.map(a => `${a.artist}-${a.title}`.toLowerCase())
      );
      const freshCandidates = candidateAlbums.filter(a =>
        !prevAlbumKeys.has(`${a.artist}-${a.title}`.toLowerCase())
      );

      // Artists don't need validation — emit them immediately
      // Filter out previously suggested artists at the code level (in case the LLM repeats)
      const prevArtistNames = new Set(
        previousAiSuggestions.current.artists.map(a => a.name.toLowerCase())
      );
      const artists = notBlocked((parsed.artists || []).map(a => ({
        name: a.name || a.artist || 'Unknown Artist',
        reason: a.reason || '',
        image: undefined // Will be loaded asynchronously
      })), a => ({ artist: a.name })).filter(a => !prevArtistNames.has(a.name.toLowerCase())).slice(0, 5);
      if (onUpdate) onUpdate({ artists });

      // Validate albums one at a time, respecting MusicBrainz rate limit (~1 req/sec).
      // Each valid album streams to the UI immediately as it passes validation.
      const validAlbums = [];
      for (let i = 0; i < freshCandidates.length && validAlbums.length < 5; i++) {
        const album = freshCandidates[i];
        const requestStart = Date.now();
        const result = await validateAlbum(album);
        if (result) {
          validAlbums.push({ album, result });
          const lookupKey = `${album.artist}-${album.title}`.toLowerCase();
          albumToReleaseIdCache.current[lookupKey] = { releaseId: null, releaseGroupId: result.releaseGroupId };
          if (onUpdate) onUpdate({ newAlbum: album });
        }
        // Respect MusicBrainz rate limit: ensure >= 1.1s between request starts
        if (i < freshCandidates.length - 1 && validAlbums.length < 5) {
          const elapsed = Date.now() - requestStart;
          const wait = 1100 - elapsed;
          if (wait > 0) await new Promise(r => setTimeout(r, wait));
        }
      }

      const albums = validAlbums.map(r => r.album);

      // Track these suggestions so we can exclude them on next refresh
      previousAiSuggestions.current = {
        albums: [...previousAiSuggestions.current.albums, ...albums].slice(-20),
        artists: [...previousAiSuggestions.current.artists, ...artists].slice(-50)
      };

      return { albums, artists };
    } catch (error) {
      console.error('Failed to load AI recommendations:', error);
      return null;
    }
  };

  // An album's track list for the album-card actions (Play, Add to Queue, Add
  // to Playlist) as playable track objects: MusicBrainz and the services'
  // catalogs race, and the first list with tracks wins (see
  // src/renderer/lib/album-track-list.js). Those actions used to wait on
  // MusicBrainz alone, two or three requests in its 1 req/s queue, and got
  // nothing when it failed.
  //   releaseGroupId: a MusicBrainz release-group id when the caller has one
  //     (one request instead of a search plus a browse)
  //   catalog / preferResolverId: a service album the caller already knows
  //   skipMusicBrainz: a service's album id MusicBrainz will never know
  // Returns { tracks, source: 'musicbrainz' | <resolverId>, artist, title },
  // or null. artist/title are MusicBrainz's names when it matched by search.
  const loadAlbumTrackList = async ({ artist, title, albumArt = null, releaseGroupId = null, catalog = null, preferResolverId = null, skipMusicBrainz = false }) => {
    const toTracks = (entries) => entries.map(e => ({
      id: trackSlug(artist || 'unknown', e.title || 'untitled', title || 'noalbum'),
      position: e.position,
      title: e.title,
      artist,
      album: title,
      albumArt: albumArt || null,
      length: e.length || 0,
      duration: e.length ? Math.round(e.length / 1000) : 0,
      recordingId: e.recordingId || undefined,
      sources: {} // Empty sources triggers on-demand resolution
    }));

    // An edition the user picked on the album page wins for the session
    // (#1238): the card actions (Play, Add to Queue, Add to Playlist) play
    // the picked edition, not the default. Both sides are cached from the
    // pick itself (releaseDetailsCache / lookupAlbumEditionCached), so this
    // costs no request; a failed pick falls through to the normal race.
    const pickEdition = editionPickFor({
      groupId: isMusicBrainzId(releaseGroupId) ? releaseGroupId : null,
      artist: artist || null,
      title: title || null
    });
    if (pickEdition?.kind === 'mb' && isMusicBrainzId(pickEdition.releaseId)) {
      try {
        const details = await releaseLookupRef.current.fetchReleaseDetails(pickEdition.releaseId);
        if (details.ok) {
          return { tracks: toTracks(entriesFromMusicBrainzRelease(await details.json())), source: 'musicbrainz', artist, title };
        }
      } catch (e) { /* fall through to the race */ }
    } else if (pickEdition?.kind === 'catalog' && pickEdition.resolverId && pickEdition.url) {
      try {
        const found = await lookupAlbumEditionCached(pickEdition.resolverId, pickEdition.url);
        if (found) {
          const release = catalogAlbumToRelease(found.album, {
            resolverId: found.resolverId,
            resolverName: found.resolverName,
            requested: { title, artistName: artist }
          });
          if (release.tracks.length > 0) {
            return { tracks: toTracks(entriesFromCatalogRelease(release)), source: found.resolverId, artist, title };
          }
        }
      } catch (e) { /* fall through to the race */ }
    }

    const fromMusicBrainz = async () => {
      let rgId = isMusicBrainzId(releaseGroupId) ? releaseGroupId : null;
      let matched = null;
      if (!rgId) {
        const known = releaseGroupPicksRef.current.get(artist, title);
        if (known?.id) {
          rgId = known.id;
        } else {
          const query = encodeURIComponent(`${artist} ${title}`);
          const searchResp = await fetch(
            `https://musicbrainz.org/ws/2/release-group?query=${query}&limit=5&fmt=json`,
            { headers: { 'User-Agent': 'Parachord/1.0.0 (https://github.com/harmonix)' } }
          );
          if (!searchResp.ok) return null;
          const match = pickReleaseGroup((await searchResp.json())['release-groups'], artist, title);
          if (!match) return null;
          // Opening this album later reuses the lookup (openAlbumForTrack,
          // handleCollectionAlbumClick, fetchReleaseData).
          releaseGroupPicksRef.current.set(artist, title, match);
          rgId = match.id;
          matched = { artist: match['artist-credit']?.[0]?.name || artist, title: match.title || title };
        }
      }
      // A group already opened answers from the cache; otherwise one request
      // (the browse carries the track list).
      const details = hasCurrentAlias(releaseDetailsCache.current[rgId])
        ? await fetchReleaseDetails(rgId)
        : await fetchReleaseGroupDetails(rgId);
      if (!details.ok) return null;
      return { tracks: toTracks(entriesFromMusicBrainzRelease(await details.json())), source: 'musicbrainz', ...(matched || {}) };
    };

    const fromCatalogs = async () => {
      const found = await loadAlbumFromCatalogs({ artist, title, catalog, preferResolverId });
      if (!found) return null;
      const release = catalogAlbumToRelease(found.album, {
        resolverId: found.resolverId,
        resolverName: found.resolverName,
        requested: { title, artistName: artist }
      });
      return { tracks: toTracks(entriesFromCatalogRelease(release)), source: found.resolverId };
    };

    const mbSide = () => fromMusicBrainz().catch(e => { console.warn(`📀 Album tracks: MusicBrainz failed for "${title}":`, e?.message || e); return null; });
    const catalogSide = () => fromCatalogs().catch(e => { console.warn(`📀 Album tracks: catalogs failed for "${title}":`, e?.message || e); return null; });
    // MusicBrainz's answer already cached: it lands at once, so the catalogs
    // are only asked if it turns out empty.
    const mbCached = !skipMusicBrainz && isMusicBrainzId(releaseGroupId) && !!cachedReleaseDetails(releaseGroupId);
    const winner = mbCached
      ? await firstNonEmptyList([mbSide()]) || await firstNonEmptyList([catalogSide()])
      : await firstNonEmptyList([skipMusicBrainz ? Promise.resolve(null) : mbSide(), catalogSide()]);
    if (!winner) return null;
    console.log(`📀 Album tracks: "${title}" by ${artist} from ${winner.source} (${winner.tracks.length} tracks)`);
    return { tracks: winner.tracks, source: winner.source, artist: winner.artist || artist, title: winner.title || title };
  };

  // Home's and Fresh Drops' album cards: the track list as playable tracks.
  const fetchAlbumTracksFromMusicBrainz = async (artistName, albumTitle, albumArt) => {
    const list = await loadAlbumTrackList({ artist: artistName, title: albumTitle, albumArt });
    return list ? list.tracks : [];
  };

  // Fetch a fresh batch of Shuffleupagus suggestions (the LLM's albums and
  // artists). Component scope (main inlined this in the effect below; the
  // Recommendations page's Refresh button calls it too, so the one body serves
  // both callers). By default the suggestions on screen stay until the user
  // presses Refresh; with "Refresh Shuffleupagus suggestions on every visit"
  // on, each visit to Home or the Recommendations page fetches a new batch,
  // keeping cached/previous results visible until it arrives. Either way the
  // view fetches when it has no albums to show.
  const fetchAiRecommendations = async () => {
    if (aiSuggestionsRefreshing.current) return; // Already fetching
    const chatServices = getChatServices();
    const hasEnabledChat = chatServices.some(isServiceEnabled);
    if (!hasEnabledChat || !aiIncludeHistoryRef.current) return;

    aiSuggestionsRefreshing.current = true;

    // Mark as loading but keep existing cached data visible on screen
    setHomeData(prev => ({
      ...prev,
      aiRecommendations: {
        albums: prev.aiRecommendations?.albums || [],
        artists: prev.aiRecommendations?.artists || [],
        loading: true
      }
    }));

    // Accumulate fresh albums in a local array — swap all at once when done
    // so cached albums (with art) stay visible the entire time instead of being
    // cleared on the first fresh album arrival.
    const freshAlbums = [];
    const onUpdate = ({ artists, newAlbum }) => {
      if (artists) {
        // Artists arrived — replace cached artists with fresh ones
        setHomeData(prev => ({
          ...prev,
          aiRecommendations: { ...(prev.aiRecommendations || { albums: [] }), artists }
        }));
      }
      if (newAlbum) {
        // Accumulate — don't push to state yet (cached albums stay visible)
        freshAlbums.push(newAlbum);
      }
    };

    const result = await loadAiRecommendations(onUpdate);
    aiSuggestionsRefreshing.current = false;
    if (result) {
      // Swap in the full fresh batch at once (with any art that loaded during validation)
      setHomeData(prev => ({
        ...prev,
        aiRecommendations: {
          ...(prev.aiRecommendations || { albums: [], artists: [] }),
          albums: freshAlbums.length > 0 ? freshAlbums : (prev.aiRecommendations?.albums || []),
          loading: false
        }
      }));
    } else {
      // LLM call failed — keep cached data visible if we have any, otherwise clear
      setHomeData(prev => {
        const existing = prev.aiRecommendations;
        if (existing?.albums?.length > 0 || existing?.artists?.length > 0) {
          return { ...prev, aiRecommendations: { ...existing, loading: false } };
        }
        return { ...prev, aiRecommendations: null };
      });
    }
  };

  // Load AI suggestions when HOME or the RECOMMENDATIONS view is active and an
  // AI plugin is enabled. By default the suggestions on screen stay until the
  // user presses Refresh; with "Refresh Shuffleupagus suggestions on every
  // visit" on, each visit fetches a new batch, keeping cached/previous results
  // visible until it arrives. Either way the view fetches when it has no
  // albums to show (no Refresh button).
  useEffect(() => {
    if ((activeView !== 'home' && activeView !== 'recommendations') || !cacheLoaded) return;
    if (!shouldAutoRefreshHomeSuggestions({
      autoRefresh: homeSuggestionsAutoRefreshRef.current,
      suggestions: homeData.aiRecommendations
    })) return;
    fetchAiRecommendations();
    // fetchAiRecommendations is recreated every render; the effect must not
    // key on it — its guards (refreshing, decision) make re-entry safe.
  }, [activeView, cacheLoaded, metaServices, homeVisitCount, recommendationsVisitCount]);

  // Load charts when navigating to discover page (Pop of the Tops), re-fetch if stale
  useEffect(() => {
    if (activeView === 'discover' && cacheLoaded) {
      const staleAfterMs = 4 * 60 * 60 * 1000; // 4 hours
      const isStale = chartsLastFetched && (Date.now() - chartsLastFetched) > staleAfterMs;
      // A failed load waits for Try again (or another pick), and nothing
      // loads before a plug-in with charts has (chartSourcesKey).
      if ((!chartsLoaded && !chartsError) || isStale) {
        loadCharts(isStale);
      }
    }
  }, [activeView, cacheLoaded, chartsLoaded, chartsError, chartSourcesKey]);

  // Load critics picks when navigating to critics-picks page (re-fetch if stale)
  useEffect(() => {
    if (activeView === 'critics-picks' && cacheLoaded) {
      const staleAfterMs = 4 * 60 * 60 * 1000; // 4 hours
      const isStale = criticsPicksLastFetched && (Date.now() - criticsPicksLastFetched) > staleAfterMs;
      if (!criticsPicksLoaded || isStale) {
        loadCriticsPicks(isStale);
      }
    }
  }, [activeView, cacheLoaded, criticsPicksLoaded]);

  // Load new releases lazily in background once cache is loaded (data updates at most daily)
  // This ensures Fresh Drops tab is ready when the user navigates to it
  // It waits for the collection too: the scan reads collectionData from the
  // render it starts in, so starting before the collection loaded found no
  // artists.
  useEffect(() => {
    if (cacheLoaded && !collectionLoading && !newReleasesLoaded && !newReleasesLoading) {
      loadNewReleases();
    }
  }, [cacheLoaded, collectionLoading, newReleasesLoaded, newReleasesLoading]);

  // Lazily pre-load concerts in the background after startup (lowest priority)
  // This ensures concert data is ready before the user navigates to the tab
  const concertsBackgroundLoaded = useRef(false);
  useEffect(() => {
    if (!cacheLoaded || concertsBackgroundLoaded.current) return;
    concertsBackgroundLoaded.current = true;
    const scheduleLoad = window.requestIdleCallback || ((cb) => setTimeout(cb, 200));
    // Delay to let higher-priority startup tasks finish first
    const timer = setTimeout(() => {
      scheduleLoad(() => {
        console.log('🎤 Background: pre-loading concerts...');
        loadConcerts();
      });
    }, 3 * 60 * 1000); // 3 min after cache loaded — lowest priority
    return () => clearTimeout(timer);
  }, [cacheLoaded]);

  // Also load concerts immediately when navigating to the tab (if not already loaded)
  useEffect(() => {
    if (activeView === 'concerts' && cacheLoaded) {
      loadConcerts();
    }
  }, [activeView, cacheLoaded]);

  // Load artist images for concerts when concert data changes
  useEffect(() => {
    if (concerts.length === 0) return;
    const uniqueArtists = [...new Set(concerts.map(e => e.artist).filter(Boolean))];
    // Only fetch images for artists we don't already have
    const toFetch = uniqueArtists.filter(name => {
      const key = name.trim().toLowerCase();
      return !concertsArtistImages[key];
    });
    if (toFetch.length === 0) return;

    let cancelled = false;
    (async () => {
      // Batch fetch in groups of 5 to avoid overloading
      for (let i = 0; i < toFetch.length && !cancelled; i += 5) {
        const batch = toFetch.slice(i, i + 5);
        const results = await Promise.allSettled(batch.map(name => getArtistImage(name)));
        if (cancelled) return;
        const updates = {};
        batch.forEach((name, idx) => {
          const result = results[idx];
          if (result.status === 'fulfilled' && result.value?.url) {
            updates[name.trim().toLowerCase()] = result.value;
          }
        });
        if (Object.keys(updates).length > 0) {
          setConcertsArtistImages(prev => ({ ...prev, ...updates }));
        }
      }
    })();
    return () => { cancelled = true; };
  }, [concerts]);

  // Load recommendations when navigating to the page or when config changes
  useEffect(() => {
    // Only load if we're on the recommendations page AND cache is loaded
    if (activeView === 'recommendations' && cacheLoaded) {
      loadRecommendations();
      // The page leaves Home's history mixes out of Playlists, so it needs
      // their ids even when Home hasn't been visited (throttled; usually
      // served from the cache).
      loadHomeHistoryMixes();
    }
  }, [activeView, cacheLoaded, metaServiceConfigs.lastfm?.username, metaServiceConfigs.listenbrainz?.username]);

  // The provider set changed while the page is open: the plugins finished
  // loading after the app reopened on Recommendations (the load above ran with
  // none, so the page showed only Shuffleupagus, or "Connect a music service",
  // until you left and came back), the saved active resolvers were restored
  // over the defaults, or a resolver was turned on or off. Declared after the
  // load-on-navigation effect so that one records its set first and a plain
  // navigation doesn't load twice.
  // Home too, once its own background load has run (the ref is set): the app
  // reopening on Home loads before the plugins, and Albums you might love
  // would otherwise wait for a visit to Recommendations.
  useEffect(() => {
    if (!cacheLoaded) return;
    if (activeView !== 'recommendations' && !(activeView === 'home' && recommendationProviderIdsRef.current !== null)) return;
    if (recommendationProviderKey(recommendationProviders()) === recommendationProviderIdsRef.current) return;
    loadRecommendations();
  }, [activeView, cacheLoaded, loadedResolvers, activeResolvers, metaServices, recommendationsOffResolvers]);

  // Home loads its own discovery data (recommendations, Fresh Drops,
  // Critical Darlings, concerts) in one idle-time effect in home-page.js.

  // Resolve recommendation tracks using the resolver pipeline
  // Fetch images for recommended artists
  // Recommendation item images are fetched by the effect below (keyed by item
  // id into the recommendationImages map) — the old per-artist loop wrote one
  // setRecommendations per image and was replaced by the coalesced writer.

  // Fetch images for search result artists
  const resolveSearchArtistImages = async (artists) => {
    console.log(`🔍 Fetching images for ${artists.length} search result artists...`);

    for (const artist of artists) {
      // Skip if already has image or is loading
      if (artist.image || artist.imageLoaded) continue;

      try {
        const result = await getArtistImage(artist.name);
        setSearchResults(prev => ({
          ...prev,
          artists: prev.artists.map(a =>
            a.id === artist.id ? { ...a, image: result?.url || null, imageLoaded: true } : a
          )
        }));
      } catch (err) {
        console.error(`Error fetching image for ${artist.name}:`, err);
        // Mark as loaded even on error so we show fallback icon instead of spinner
        setSearchResults(prev => ({
          ...prev,
          artists: prev.artists.map(a =>
            a.id === artist.id ? { ...a, imageLoaded: true } : a
          )
        }));
      }
    }
    console.log(`🔍 Finished fetching search result artist images`);
  };

  // Load Listening History from Last.fm and/or ListenBrainz (merged and de-duped)
  // Recently Played: every source you're signed in to, merged
  // (mergeRecentListens).
  const loadListeningHistory = async (forceRefresh = false) => {
    const sources = historySourcesFor();
    if (sources.length === 0) {
      setListeningHistory({ tracks: [], loading: false, error: historyNotConnected() });
      return;
    }

    // Check if we have valid cached data (cache for 5 minutes - recent history changes frequently)
    const now = Date.now();
    const cacheValid = !forceRefresh &&
                       listeningHistoryCache.current.tracks &&
                       (now - listeningHistoryCache.current.timestamp) < (5 * 60 * 1000);

    if (cacheValid) {
      console.log(`📜 Using cached listening history (${Math.round((now - listeningHistoryCache.current.timestamp) / 60000)}m old)`);
      setListeningHistory({
        tracks: listeningHistoryCache.current.tracks,
        loading: false,
        error: null
      });
      return;
    }

    setListeningHistory(prev => ({ ...prev, loading: true, error: null }));
    console.log('📜 Loading Listening History...');

    try {
      // Every source at once; one that fails is left out, and the load fails
      // only when none answered.
      const { answers, failed } = await askEach(sources, (p) => askRecentListens(p.id, { limit: 50 }));
      if (failed) throw userError('Your listening history didn’t load. Try again in a moment.');
      const tracks = mergeRecentListens(answers).map((t, index) => ({
        id: t.msid || `history-${t.source}-${index}-${t.playedAt || 'now'}-${t.title}`.replace(/\s+/g, '-'),
        title: t.title,
        artist: t.artist,
        album: t.album || null,
        albumArt: t.albumArt || null, // null → filled via getAlbumArt
        playedAt: t.playedAt,
        nowPlaying: !!t.nowPlaying,
        source: t.source,
        sources: {}, // Will be populated by resolver pipeline
        mbid: t.mbid || null
      }));
      console.log(`📜 ${answers.map(a => `${a.items.length} from ${pluginName(a.id)}`).join(' + ')} → ${tracks.length} unique listens`);

      // Cache the tracks
      listeningHistoryCache.current = { tracks, timestamp: Date.now() };

      // Set initial state with tracks (resolution handled by scheduler via IntersectionObserver)
      setListeningHistory({
        tracks,
        loading: false,
        error: null
      });

    } catch (error) {
      console.error('Failed to load Listening History:', error);
      setListeningHistory({
        tracks: [],
        loading: false,
        error: errorText(error, 'Your listening history didn’t load. Try again in a moment.')
      });
    }
  };


  // The History page's top lists come from one source (historyTopSource:
  // the Source menu's pick, else the first you're signed in to), for the
  // picked period (lib/listening-history.js maps the menu's values).
  const topListFailed = (source, what, error) => errorText(error, `${pluginName(source.id)} didn’t send your top ${what}. Try again in a moment.`);

  const loadTopTracks = async (period = historyPeriod, forceRefresh = false) => {
    const source = historyTopSource();
    if (!source) {
      setTopTracks({ tracks: [], loading: false, error: historyNotConnected() });
      return;
    }

    // Check if we have valid cached data for this source and period (cache for 30 minutes)
    const now = Date.now();
    const cacheKey = `${source.id}:${period}`;
    const cachedEntry = topTracksCache.current[cacheKey];
    const cacheValid = !forceRefresh &&
                       cachedEntry?.tracks &&
                       (now - cachedEntry.timestamp) < (30 * 60 * 1000);

    if (cacheValid) {
      console.log(`📊 Using cached top tracks for ${cacheKey} (${Math.round((now - cachedEntry.timestamp) / 60000)}m old)`);
      setTopTracks({ tracks: cachedEntry.tracks, loading: false, error: null });
      return;
    }

    setTopTracks(prev => ({ ...prev, loading: true, error: null }));
    console.log(`📊 Loading top tracks from ${pluginName(source.id)} (${period})…`);

    try {
      const items = await askTopItems(source.id, { kind: 'tracks', period: historyPeriodFor(period), limit: 50 });
      const tracks = (items || []).map((track, index) => ({
        id: `top-track-${index}-${track.title}`.replace(/\s+/g, '-'),
        title: track.title,
        artist: track.artist || 'Unknown Artist',
        album: track.album || null,
        // Only a cover the source matched itself; the art pipeline
        // (getAlbumArt / getTrackArt) fills in the rest.
        albumArt: track.albumArt || null,
        playCount: Number(track.plays) || 0,
        rank: index + 1,
        sources: {},
        mbid: track.mbid || null
      }));
      topTracksCache.current[cacheKey] = { tracks, timestamp: Date.now() };
      // Resolution handled by scheduler via IntersectionObserver
      setTopTracks({ tracks, loading: false, error: null });
    } catch (error) {
      console.error('Failed to load Top Tracks:', error);
      setTopTracks({ tracks: [], loading: false, error: topListFailed(source, 'tracks', error) });
    }
  };

  const loadTopArtists = async (period = historyPeriod) => {
    const source = historyTopSource();
    if (!source) {
      setTopArtists({ artists: [], loading: false, error: historyNotConnected() });
      return;
    }
    setTopArtists(prev => ({ ...prev, loading: true, error: null }));
    console.log(`📊 Loading top artists from ${pluginName(source.id)} (${period})…`);
    try {
      const items = await askTopItems(source.id, { kind: 'artists', period: historyPeriodFor(period), limit: 50 });
      const artists = (items || []).map((artist, index) => ({
        id: `top-artist-${index}-${artist.name}`.replace(/\s+/g, '-'),
        name: artist.name,
        image: null, // Filled in by resolveTopArtistImages
        playCount: Number(artist.plays) || 0,
        rank: index + 1
      }));
      setTopArtists({ artists, loading: false, error: null });
      resolveTopArtistImages(artists);
    } catch (error) {
      console.error('Failed to load Top Artists:', error);
      setTopArtists({ artists: [], loading: false, error: topListFailed(source, 'artists', error) });
    }
  };

  // Resolve artist images from Spotify
  const resolveTopArtistImages = async (artists) => {
    console.log(`📊 Fetching images for ${artists.length} top artists...`);

    for (const artist of artists) {
      try {
        const result = await getArtistImage(artist.name);
        setTopArtists(prev => ({
          ...prev,
          artists: prev.artists.map(a =>
            a.id === artist.id ? { ...a, image: result?.url || null, imageLoaded: true } : a
          )
        }));
      } catch (err) {
        console.error(`Error fetching image for ${artist.name}:`, err);
        // Mark as loaded even on error so we show the pattern fallback
        setTopArtists(prev => ({
          ...prev,
          artists: prev.artists.map(a =>
            a.id === artist.id ? { ...a, imageLoaded: true } : a
          )
        }));
      }
    }
    console.log(`📊 Finished fetching top artist images`);
  };

  const loadTopAlbums = async (period = historyPeriod) => {
    const source = historyTopSource();
    if (!source) {
      setTopAlbums({ albums: [], loading: false, error: historyNotConnected() });
      return;
    }
    setTopAlbums(prev => ({ ...prev, loading: true, error: null }));
    console.log(`📊 Loading top albums from ${pluginName(source.id)} (${period})…`);
    try {
      const items = await askTopItems(source.id, { kind: 'albums', period: historyPeriodFor(period), limit: 50 });
      const albums = (items || []).map((album, index) => ({
        id: `top-album-${index}-${album.title}`.replace(/\s+/g, '-'),
        name: album.title,
        artist: album.artist || 'Unknown Artist',
        image: album.albumArt || null,
        playCount: Number(album.plays) || 0,
        rank: index + 1
      }));
      setTopAlbums({ albums, loading: false, error: null });
    } catch (error) {
      console.error('Failed to load Top Albums:', error);
      setTopAlbums({ albums: [], loading: false, error: topListFailed(source, 'albums', error) });
    }
  };

  // Pick the source of the History page's top lists, and reload the open one.
  const pickHistorySource = (id) => {
    setHistorySource(id);
    historySourceRef.current = id;
    if (historyTab === 'topTracks') loadTopTracks(historyPeriod);
    else if (historyTab === 'topArtists') loadTopArtists(historyPeriod);
    else if (historyTab === 'topAlbums') loadTopAlbums(historyPeriod);
  };

  // Friends come from plug-ins with capabilities.friends (#1539 step 5):
  // finding a person (findUser), the people you follow (getFollowing), and
  // following or unfollowing where the service allows it. The providers are
  // active plug-ins and meta-services, minus one switched off, in your order;
  // the ones you're signed in to (a username) are whose follow graph the
  // sync pulls.
  const friendProvidersFor = () => similarProvidersFor('friends');
  const friendAccountsFor = () => signedInSources(friendProvidersFor(), metaServiceConfigsRef.current || {});
  const isFriendService = (id) => friendProvidersFor().some(r => r.id === id);
  const friendServiceNames = (joiner = 'or') => {
    const names = friendProvidersFor().map(r => pluginName(r.id));
    return names.length > 1 ? `${names.slice(0, -1).join(', ')} ${joiner} ${names[names.length - 1]}` : (names[0] || 'a friends service');
  };
  // Look someone up on one service: their username, display name and avatar,
  // or null when there's no one by that name there.
  const findFriendOn = async (service, query) =>
    resolverLoaderRef.current.findUser(service, { query }, await configForSimilar(service));

  // Per-friend backoff for accounts that always fail (private 403, deleted
  // 404) and rate limits, plus one weekly-stats attempt per 30 min.
  const friendPollBackoffRef = useRef(null);
  if (!friendPollBackoffRef.current) friendPollBackoffRef.current = createFriendPollBackoff();
  // A friend's listening comes from their own service's plug-in
  // (friend.service is its id; listeningHistory, #1539 step 5), asked about
  // their username. A plug-in that isn't loaded, or lacks the capability,
  // is a failure here, never an empty answer.
  const askFriend = async (friend, method, query = {}) => {
    const out = await resolverLoaderRef.current[method](friend.service, { ...query, user: friend.username }, await configForSimilar(friend.service));
    if (out == null && method !== 'getNowPlaying') throw userError(`${pluginName(friend.service)} isn’t available.`);
    return out;
  };

  const recordFriendPollStatus = (friend, status) => {
    const delay = friendPollBackoffRef.current.recordStatus(friend.id, status);
    if (delay > 0) {
      console.log(`👥 ${friend.username} (${friend.service}) answered ${status}; not polling for ${Math.round(delay / 60000)} min`);
    }
  };

  // Fetch friend's most recent track (for on-air status).
  // Returns { track, hidesListening }: track is null when there is none;
  // hidesListening is true when the Last.fm profile hides its recent
  // listening, false when the fetch succeeded, and null when unknown (an
  // error, or ListenBrainz, which has no such setting).
  const fetchFriendRecentTrack = async (friend) => {
    try {
      const listens = await askFriend(friend, 'getRecentListens', { limit: 1 });
      recordFriendPollStatus(friend, 200);
      const newest = listens[0];
      if (!newest) return { track: null, hidesListening: false };
      return {
        track: {
          name: newest.title,
          artist: newest.artist || 'Unknown Artist',
          album: newest.album || null,
          // Playing now has no date: it's now.
          timestamp: newest.nowPlaying ? Date.now() : (newest.playedAt || null),
          // The cover the service matched; without one, fetched via getAlbumArt
          albumArt: newest.albumArt || null
        },
        hidesListening: false
      };
    } catch (error) {
      // The plug-in's error carries the HTTP status (the backoff's input),
      // and says when the profile hides its recent listening.
      if (error && error.status) recordFriendPollStatus(friend, error.status);
      if (error && error.hidesListening) return { track: null, hidesListening: true };
      console.warn(`Couldn't fetch the recent track for ${friend.username}:`, error?.message || error);
      return { track: null, hidesListening: null };
    }
  };

  // Record on the friend whether their Last.fm profile hides its recent
  // listening (hidesListening from fetchFriendRecentTrack); null leaves it.
  const updateFriendHidesListening = (friend, hidesListening) => {
    if (hidesListening === null || hidesListening === !!friend.hidesListening) return;
    setFriends(prev => prev.map(f => f.id === friend.id ? { ...f, hidesListening } : f));
  };

  // Fetch friend's weekly stats (top artists + tracks) for AI context caching
  const fetchFriendWeeklyStats = async (friend) => {
    try {
      const [artists, tracks] = await Promise.all([
        askFriend(friend, 'getTopItems', { kind: 'artists', period: 'week', limit: 5 }).catch(() => []),
        askFriend(friend, 'getTopItems', { kind: 'tracks', period: 'week', limit: 5 }).catch(() => [])
      ]);
      const topArtists = artists.map(a => a.name);
      const topTracks = tracks.map(t => ({ title: t.title, artist: t.artist }));
      if (topArtists.length === 0 && topTracks.length === 0) return null;
      return { topArtists, topTracks, fetchedAt: Date.now() };
    } catch (error) {
      console.error(`Error fetching weekly stats for ${friend.username}:`, error);
      return null;
    }
  };

  // Check if friend is "on air" (listened within last 10 minutes)
  const isOnAir = (friend) => {
    if (!friend.cachedRecentTrack?.timestamp) return false;
    const tenMinutesAgo = Date.now() - (10 * 60 * 1000);
    return friend.cachedRecentTrack.timestamp > tenMinutesAgo;
  };

  // Add a friend from username or URL
  // Build `${service}:${username_lowercase}` key used in the hidden-friends
  // allowlist and dedup logic during sync.
  const friendKey = (service, username) => `${service}:${(username || '').toLowerCase()}`;

  // Follow a user on their service so other Parachord clients pick up the add.
  // ListenBrainz has a proper follow API; Last.fm's was deprecated in 2018.
  const followOnService = async (friend) => {
    try {
      // null: the service can't follow from here (Last.fm, pull-only);
      // false: you're not signed in to it with a token.
      const done = await resolverLoaderRef.current.setFollowing(friend.service, 'follow', { user: friend.username }, await configForSimilar(friend.service));
      if (done) console.log(`[Friends] Followed ${friend.username} on ${pluginName(friend.service)}`);
    } catch (err) {
      console.warn(`[Friends] Following ${friend.username} on ${pluginName(friend.service)} failed:`, err.message);
    }
  };

  // Unfollow a user on their service when removing locally, where its
  // plug-in can (ListenBrainz). Where it can't (Last.fm), the hidden-keys
  // allowlist is what keeps the removal durable across sync cycles.
  const unfollowOnService = async (friend) => {
    try {
      const done = await resolverLoaderRef.current.setFollowing(friend.service, 'unfollow', { user: friend.username }, await configForSimilar(friend.service));
      if (done) console.log(`[Friends] Unfollowed ${friend.username} on ${pluginName(friend.service)}`);
    } catch (err) {
      console.warn(`[Friends] Unfollowing ${friend.username} on ${pluginName(friend.service)} failed:`, err.message);
    }
  };

  // Sync friends from Last.fm and ListenBrainz into the local `friends` state.
  //
  // Inbound pull only — outbound follow/unfollow happens inline with
  // addFriend/removeFriend. Idempotent: dedups against existing friends AND
  // the hidden-keys allowlist so removed friends never creep back in.
  //
  // Returns the number of new friends added (for toast UX on manual trigger).
  // When the last friend-graph sync started (any trigger), so opening the
  // Friends tab (or the startup sync) skips one that just ran.
  const lastFriendSyncAtRef = useRef(0);
  const FRIEND_TAB_SYNC_MIN_GAP_MS = 5 * 60 * 1000;
  const syncFriendsFromServices = async ({ silent = true } = {}) => {
    if (friendSyncInProgress) return 0;
    lastFriendSyncAtRef.current = Date.now();
    setFriendSyncInProgress(true);
    try {
      const accounts = friendAccountsFor();
      // Build lookup sets against fresh refs (avoids stale closure during
      // the periodic sync, which fires from a setInterval callback).
      const existingKeys = new Set(
        friendsRef.current.map(f => friendKey(f.service, f.username))
      );
      const hiddenKeys = new Set(hiddenFriendKeysRef.current);
      const batch = [];
      // Per-service counts for the log: which side is short when someone
      // says sync missed a friend.
      const counts = [];
      let totalSeen = 0;

      // Every service you're signed in to, one after another: who you follow
      // there (the plug-in's getFollowing, all pages), minus who you already
      // have and who you removed (hidden_friend_keys: load-bearing where the
      // service can't unfollow).
      for (const account of accounts) {
        let seen = 0;
        let added = 0;
        try {
          const people = await resolverLoaderRef.current.getFollowing(account.id, {}, await configForSimilar(account.id)) || [];
          for (const person of people) {
            seen++;
            const key = friendKey(account.id, person.username);
            if (existingKeys.has(key) || hiddenKeys.has(key)) continue;
            batch.push({
              id: `friend-${Date.now()}-${Math.random().toString(36).substr(2, 9)}-${account.id}-${added}`,
              username: person.username,
              service: account.id,
              displayName: person.displayName || person.username,
              avatarUrl: person.avatarUrl || null,
              addedAt: Date.now(),
              lastFetched: 0,
              cachedRecentTrack: null,
              savedToCollection: false
            });
            existingKeys.add(key);
            added++;
          }
          console.log(`[Friends] ${pluginName(account.id)}: ${seen} friend(s) found, ${added} new after dedup/hide filter`);
        } catch (err) {
          console.warn(`[Friends] ${pluginName(account.id)} sync failed:`, err.message);
        }
        counts.push(`${account.id}=${seen}`);
        totalSeen += seen;
      }

      // Zero-returned path: the services gave us nothing at all. Usually
      // means the account is wrong, or you follow nobody there. Say so, so
      // it reads differently from "all already synced".
      if (totalSeen === 0) {
        if (!silent) {
          if (accounts.length === 0) {
            showToast(`No ${friendServiceNames()} account connected`, 'error');
          } else {
            showToast(`No friends returned from ${accounts.map(acc => pluginName(acc.id)).join(' or ')}. Check Settings.`, 'info');
          }
        }
        return 0;
      }

      // Apply-time dedup against the very latest friendsRef in case another
      // code path added a friend while we were fetching. Avoids duplicates
      // from two desktop instances syncing the same account concurrently.
      const currentKeys = new Set(
        friendsRef.current.map(f => friendKey(f.service, f.username))
      );
      const deduped = batch.filter(f => !currentKeys.has(friendKey(f.service, f.username)));

      if (deduped.length === 0) {
        // Distinguish "already had everyone" from "found nothing at all"
        if (!silent) {
          showToast(`All ${totalSeen} friend${totalSeen === 1 ? '' : 's'} already in your list`, 'info');
        }
        return 0;
      }

      setFriends(prev => [...prev, ...deduped]);
      console.log(`[Friends] Synced ${deduped.length} new friend(s); saw ${totalSeen} total across services (${counts.join(', ')})`);

      if (!silent) {
        const n = deduped.length;
        showToast(`Synced ${n} new friend${n === 1 ? '' : 's'} (${totalSeen} total across services)`, 'success');
      }
      return deduped.length;
    } finally {
      setFriendSyncInProgress(false);
    }
  };

  // Add one person on a known service: look them up on that exact service (no
  // fallback to the other one), add them, pin them to the sidebar, un-hide
  // them and follow on the service. Throws when they are already a friend or
  // can't be found. No modal, no toast: callers own their own UI.
  // `found` is a findUser answer the caller already has (Add Friend's
  // lookup), so it isn't asked twice.
  const addFriendCore = async ({ service, username, found = null }) => {
    // Exactly the friend services (plug-ins with capabilities.friends):
    // anything else used to fall through to a lookup of the same name
    // somewhere else.
    if (!isFriendService(service)) {
      throw userError(`You can follow people on ${friendServiceNames()}.`);
    }
    const person = found || await findFriendOn(service, username);
    if (!person) {
      throw userError(`There’s no ${pluginName(service)} user with that name. Check the spelling and try again.`);
    }
    const userInfo = { username: person.username, displayName: person.displayName || person.username, avatarUrl: person.avatarUrl || null };
    const finalService = service;

    // Check if already added
    const existingFriend = friendsRef.current.find(f =>
      f.username.toLowerCase() === userInfo.username.toLowerCase() &&
      f.service === finalService
    );
    if (existingFriend) {
      throw userError(`${userInfo.displayName} is already one of your friends.`);
    }

    // Create friend object
    const newFriend = {
      id: `friend-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      username: userInfo.username,
      service: finalService,
      displayName: userInfo.displayName,
      avatarUrl: userInfo.avatarUrl,
      addedAt: Date.now(),
      lastFetched: Date.now(),
      cachedRecentTrack: null,
      savedToCollection: false  // Friends added from sidebar are NOT saved to collection by default
    };

    // Fetch recent track for initial on-air status
    const { track: recentTrack, hidesListening } = await fetchFriendRecentTrack(newFriend);
    if (hidesListening) newFriend.hidesListening = true;
    if (recentTrack) {
      newFriend.cachedRecentTrack = recentTrack;
      // Resolve the track in background for instant playback
      resolveFriendTrack(recentTrack);
    }

    setFriends(prev => [...prev, newFriend]);
    // Auto-pin the friend to sidebar (they're not saved to collection yet)
    setPinnedFriendIds(prev => prev.includes(newFriend.id) ? prev : [...prev, newFriend.id]);
    // Slide them into the sidebar (the friend-entry animation), as a pin does:
    // that is what says they were added.
    setNewlyPinnedFriendIds(prev => new Set([...prev, newFriend.id]));
    setTimeout(() => {
      setNewlyPinnedFriendIds(prev => {
        const next = new Set(prev);
        next.delete(newFriend.id);
        return next;
      });
    }, 300);
    // Mark as auto-pinned so they get auto-unpinned when offline
    // (only manually pinned friends via context menu/drag stay permanently)
    setAutoPinnedFriendIds(prev => prev.includes(newFriend.id) ? prev : [...prev, newFriend.id]);

    // If the user previously hid this friend, un-hide so the next sync
    // doesn't skip them. Adding is the un-hide escape hatch.
    const key = friendKey(finalService, userInfo.username);
    if (hiddenFriendKeysRef.current.includes(key)) {
      setHiddenFriendKeys(prev => prev.filter(k => k !== key));
    }

    // Outbound push: follow on the service where its plug-in can (no-op where
    // it can't, as on Last.fm). Fire-and-forget.
    followOnService(newFriend);

    console.log(`👥 Added friend: ${newFriend.displayName} (${finalService})`);
    return newFriend;
  };

  // A profile link from the browser extension (the dialog adds through
  // addFriendCore with the service it shows).
  const addFriend = async (input) => {

    try {
      const query = String(input || '').trim();
      if (!query) {
        showToast('Enter a username or profile link', 'error');
        return;
      }

      // Each friend service in turn (askInTurn): the ones you're signed in
      // to first, then the rest, in your order. A profile link is only its
      // own service's (the others answer null without asking); a plain name
      // goes to the first service that has someone by it.
      const providers = friendProvidersFor();
      const signedIn = new Set(friendAccountsFor().map(r => r.id));
      const ordered = [...providers.filter(r => signedIn.has(r.id)), ...providers.filter(r => !signedIn.has(r.id))];
      const { answer } = await askInTurn(ordered, (p) => findFriendOn(p.id, query));
      if (!answer) throw userError(`There’s no one by that name on ${friendServiceNames()}. Check the spelling and try again.`);

      await addFriendCore({ service: answer.id, username: answer.value.username, found: answer.value });

    } catch (error) {
      console.error('Failed to add friend:', error);
      showToast(errorText(error, 'Couldn’t add that friend. Check the name and try again.'), 'error');
    }
  };

  // Follow a person opened from Recommendations (not yet in `friends`).
  const [followingRecommended, setFollowingRecommended] = useState(false);
  // A Listener card's Follow (its menu): add them as a friend where you are;
  // they slide into the sidebar.
  const followListener = async (person) => {
    try {
      await addFriendCore({ service: person.service, username: person.username });
    } catch (error) {
      console.error('Failed to follow:', error);
      showToast(errorText(error, 'Couldn’t follow them. Try again.'), 'error');
    }
  };
  followListenerRef.current = followListener;

  const followRecommendedFriend = async (person) => {
    if (followingRecommended) return;
    setFollowingRecommended(true);
    try {
      const newFriend = await addFriendCore({ service: person.service, username: person.username });
      setCurrentFriend(newFriend);
    } catch (error) {
      console.error('Failed to follow:', error);
      showToast(errorText(error, 'Couldn’t follow them. Try again.'), 'error');
    } finally {
      setFollowingRecommended(false);
    }
  };

  // Remove a friend completely (deletes from friends list and unpins).
  // Also records the `${service}:${username}` in the hidden-keys allowlist
  // so the next inbound sync doesn't re-add them, and pushes an unfollow to
  // the service (ListenBrainz only — Last.fm's friend API is deprecated).
  const removeFriend = (friendId) => {
    const friend = friends.find(f => f.id === friendId);
    setFriends(prev => prev.filter(f => f.id !== friendId));
    setPinnedFriendIds(prev => prev.filter(id => id !== friendId));
    if (friend) {
      const key = friendKey(friend.service, friend.username);
      setHiddenFriendKeys(prev => prev.includes(key) ? prev : [...prev, key]);
      // Outbound push: unfollow on ListenBrainz (no-op on Last.fm).
      // Fire-and-forget — local removal stands even if the API call fails.
      unfollowOnService(friend);
      showToast(`${friend.displayName} removed`);
    }
  };
  removeFriendRef.current = removeFriend;

  // Remove friend from collection (keeps them as temporary, stays pinned if pinned)
  const removeFriendFromCollection = (friendId) => {
    setFriends(prev => prev.map(f =>
      f.id === friendId ? { ...f, savedToCollection: false } : f
    ));
    const friend = friends.find(f => f.id === friendId);
    if (friend) {
      showToast(`${friend.displayName} removed from collection`);
    }
  };
  removeFriendFromCollectionRef.current = removeFriendFromCollection;

  // Pin a friend to the sidebar
  const pinFriend = (friendId) => {
    if (!pinnedFriendIds.includes(friendId)) {
      setPinnedFriendIds(prev => prev.includes(friendId) ? prev : [...prev, friendId]);
      // Track as newly pinned for entry animation
      setNewlyPinnedFriendIds(prev => new Set([...prev, friendId]));
      // Clear animation tracking after animation completes
      setTimeout(() => {
        setNewlyPinnedFriendIds(prev => {
          const next = new Set(prev);
          next.delete(friendId);
          return next;
        });
      }, 300); // Match animation duration
    }
    // If friend was auto-pinned, remove from auto-pinned list (now manually pinned)
    if (autoPinnedFriendIds.includes(friendId)) {
      setAutoPinnedFriendIds(prev => prev.filter(id => id !== friendId));
    }
  };
  pinFriendRef.current = pinFriend;

  // Unpin a friend from the sidebar (with warning for unsaved friends)
  const unpinFriend = (friendId) => {
    const friend = friends.find(f => f.id === friendId);

    // If friend is not saved to collection and warning not dismissed, show warning
    if (friend && !friend.savedToCollection && !skipUnsavedFriendWarning) {
      setPendingUnpinFriend(friend);
      setUnsavedFriendWarningOpen(true);
      return;
    }

    // Otherwise proceed with unpin
    setPinnedFriendIds(prev => prev.filter(id => id !== friendId));
    // Also clear from auto-pinned list if they were auto-pinned
    setAutoPinnedFriendIds(prev => prev.filter(id => id !== friendId));
    if (friend) {
      showToast(`${friend.displayName} unpinned from sidebar`);
    }
  };
  unpinFriendRef.current = unpinFriend;

  // Confirm unpin after warning dialog
  const confirmUnpinFriend = () => {
    if (pendingUnpinFriend) {
      setPinnedFriendIds(prev => prev.filter(id => id !== pendingUnpinFriend.id));
      setAutoPinnedFriendIds(prev => prev.filter(id => id !== pendingUnpinFriend.id));
      showToast(`${pendingUnpinFriend.displayName} unpinned from sidebar`);
      setUnsavedFriendWarningOpen(false);
      setPendingUnpinFriend(null);
    }
  };

  // Save friend to collection
  const saveFriendToCollection = (friendId) => {
    setFriends(prev => prev.map(f =>
      f.id === friendId ? { ...f, savedToCollection: true } : f
    ));
    const friend = friends.find(f => f.id === friendId);
    if (friend) {
      showSidebarBadge('collection');
    }
  };
  saveFriendToCollectionRef.current = saveFriendToCollection;

  // Reorder pinned friends in sidebar (for drag-drop)
  // Uses friend IDs instead of indices since the sidebar sorts by on-air status,
  // which means visual indices don't match the underlying array positions.
  const reorderPinnedFriends = (draggedFriendId, targetFriendId) => {
    setPinnedFriendIds(prev => {
      const fromIndex = prev.indexOf(draggedFriendId);
      const toIndex = prev.indexOf(targetFriendId);
      if (fromIndex === -1 || toIndex === -1) return prev;
      const newOrder = [...prev];
      const [removed] = newOrder.splice(fromIndex, 1);
      newOrder.splice(toIndex, 0, removed);
      // Track moved friend for animation
      setMovedFriendIds(new Set([removed]));
      setTimeout(() => {
        setMovedFriendIds(new Set());
      }, 400); // Match animation duration
      return newOrder;
    });
  };

  // Resolve a friend's current track in background (for instant playback)
  const resolveFriendTrack = async (track) => {
    if (!track || !track.name || !track.artist) return;

    const cacheKey = `${track.artist.toLowerCase()}|${track.name.toLowerCase()}`;
    const currentResolverHash = getResolverSettingsHash();

    // Check if already cached and valid
    const cachedData = trackSourcesCache.current[cacheKey];
    if (cachedData &&
        (Date.now() - cachedData.timestamp) < CACHE_TTL.trackSources &&
        cachedData.resolverHash === currentResolverHash) {
      console.log(`👥 Friend track already resolved: ${track.artist} - ${track.name}`);
      return;
    }

    console.log(`👥 Resolving friend track: ${track.artist} - ${track.name}`);

    const sources = {};

    for (const resolverId of activeResolvers) {
      const resolver = allResolvers.find(r => r.id === resolverId);
      if (!resolver || !resolver.capabilities.resolve) continue;

      try {
        const config = await getResolverConfig(resolverId);
        const resolved = await resolver.resolve(track.artist, track.name, null, config);

        if (resolved) {
          // Score the result the same way the rest of the resolution paths do.
          // Without this step the source has no `confidence` field, and
          // handlePlay's source-selection floor (`s.confidence >= 0.6`) drops
          // it as if it were a wrong-axis match. Symptom: clicking
          // listen-along on a friend whose now-playing was previously cached
          // would silently fail (handlePlay reaches "No Enabled Source" and
          // shows a dialog, but the source data is fine — it just lacks a
          // confidence value). All other resolution paths (resolveTrack,
          // resolveTracksInBackground, validateCachedSources) already do
          // this; resolveFriendTrack was the odd one out.
          const confidence = calculateConfidence({ artist: track.artist, title: track.name }, resolved);
          if (confidence < MIN_CONFIDENCE_THRESHOLD) {
            console.warn(`  ⚠️ ${resolver.name}: Rejecting friend-track match "${resolved.title}" by "${resolved.artist}" — does not match "${track.name}" by "${track.artist}"`);
            continue;
          }
          console.log(`  ✅ ${resolver.name}: Found match for friend track`);
          sources[resolverId] = { ...resolved, confidence };
        }
      } catch (error) {
        console.error(`  ❌ ${resolver.name} resolve error:`, error);
      }
    }

    // Cache the results
    if (Object.keys(sources).length > 0) {
      markTrackSourcesDirty();
      trackSourcesCache.current[cacheKey] = {
        sources,
        timestamp: Date.now(),
        resolverHash: currentResolverHash,
        v: CACHE_SCHEMA_VERSION
      };
      console.log(`👥 Friend track resolved with ${Object.keys(sources).length} sources`);
    }
  };

  // Refresh recent tracks for friends (for polling)
  // Polls: all pinned friends + all saved friends (to check if they become active)
  // Uses refs instead of closure variables to avoid stale state in setInterval callbacks
  // The friend's track as a playable track, tagged with the Listen Along
  // context (sources from the cache when it has them; the rest resolve when
  // it plays).
  const listenAlongTrackFor = (friend, recentTrack) => {
    const cacheKey = `${recentTrack.artist.toLowerCase()}|${recentTrack.name.toLowerCase()}`;
    const cachedSources = trackSourcesCache.current[cacheKey]?.sources || {};
    return {
      title: recentTrack.name,
      artist: recentTrack.artist,
      album: recentTrack.album,
      albumArt: recentTrack.albumArt,
      sources: cachedSources,
      _offLap: true, // a friend's track isn't the queue's: repeat all never wraps it (#1319)
      _playbackContext: {
        type: 'listenAlong',
        name: friend.displayName,
        friendId: friend.id
      }
    };
  };
  // Play the friend's track now: it becomes the track we're on, and the
  // session stops waiting.
  const playListenAlongTrack = (friend, recentTrack) => {
    listenAlongLastTrackRef.current = { name: recentTrack.name, artist: recentTrack.artist };
    listenAlongLastPollTrackRef.current = null;
    listenAlongWaitingRef.current = null;
    handlePlay(listenAlongTrackFor(friend, recentTrack));
  };
  // End the session and give the user's queue back (#1319). The ref is
  // cleared at once, not by its effect after the next render: handleNext
  // reads it, and would otherwise run its Listen Along branch again.
  // startPlayback false (a friend who stopped while the user had paused):
  // the queue comes back paused, its first track on screen for Play.
  const endListenAlongToQueue = (message, { startPlayback = true } = {}) => {
    abortSchedulerContext('listen-along');
    listenAlongFriendRef.current = null;
    setListenAlongFriend(null);
    listenAlongLastTrackRef.current = null;
    listenAlongPendingTrackRef.current = null;
    listenAlongUserPausedRef.current = false;
    listenAlongWaitingRef.current = null;
    listenAlongLastPollTrackRef.current = null;
    setPlaybackContext(null);
    showToast(message);
    if (currentQueueRef.current.length > 0) {
      if (startPlayback) handleNextRef.current?.();
      else holdNextQueueTrackRef.current?.();
    }
  };
  // The friend stopped listening (off air, a hidden profile, or a run of
  // failed polls). A song of theirs that's playing finishes first; otherwise
  // the session ends now, and a user who had paused gets their queue back
  // paused instead of starting by itself (#1319).
  const listenAlongFriendWentQuiet = (friend) => {
    console.log(`🎧 Listen-along: ${friend.displayName} is no longer active`);
    if (isPlayingRef.current) {
      console.log(`🎧 Listen-along: Deferring end until current song finishes`);
      abortSchedulerContext('listen-along');
      listenAlongLastTrackRef.current = null;
      listenAlongPendingTrackRef.current = null;
      listenAlongUserPausedRef.current = false;
      listenAlongWaitingRef.current = null;
      listenAlongEndAfterSongRef.current = friend.displayName;
      setListenAlongFriend(null);
      // Keep playbackContext so UI still shows "Listening along with..." until song ends
      return;
    }
    const userPaused = listenAlongUserPausedRef.current;
    endListenAlongToQueue(`${friend.displayName} stopped listening`, { startPlayback: !userPaused });
  };

  const refreshPinnedFriends = async () => {
    const listenAlongFriendNow = listenAlongFriendRef.current;
    const currentFriends = friendsRef.current;
    const currentPinnedIds = pinnedFriendIdsRef.current;

    // Get all friends we need to poll:
    // 1. All pinned friends (manual or auto-pinned)
    // 2. All saved friends (even if not pinned, to detect when they become active)
    const friendsToCheck = currentFriends.filter(f =>
      currentPinnedIds.includes(f.id) || f.savedToCollection
    );

    for (const friend of friendsToCheck) {
      if (friendPollBackoffRef.current.shouldSkip(friend.id)) continue;
      const { track: recentTrack, hidesListening } = await fetchFriendRecentTrack(friend);
      updateFriendHidesListening(friend, hidesListening);
      // The friend we're listening along with (#1319): a failed poll isn't
      // "they stopped", only LISTEN_ALONG_FAILED_POLLS_LIMIT in a row are; a
      // hidden profile can't be followed, so it counts as stopped at once.
      const isListenAlongFriend = listenAlongFriendRef.current?.id === friend.id;
      if (isListenAlongFriend && !recentTrack) {
        listenAlongLastPollTrackRef.current = null;
        if (hidesListening) {
          listenAlongFriendWentQuiet(friend);
          continue;
        }
        listenAlongFailedPollsRef.current += 1;
        console.log(`🎧 Listen-along: poll for ${friend.displayName} failed (${listenAlongFailedPollsRef.current} in a row)`);
        if (listenAlongFailedPollsRef.current >= LISTEN_ALONG_FAILED_POLLS_LIMIT) listenAlongFriendWentQuiet(friend);
        continue;
      }
      if (isListenAlongFriend) listenAlongFailedPollsRef.current = 0;
      if (recentTrack) {
        // Check if track changed before updating
        const previousTrack = friend.cachedRecentTrack;
        const trackChanged = !previousTrack ||
          previousTrack.name !== recentTrack.name ||
          previousTrack.artist !== recentTrack.artist;

        // Check if friend is on-air (track less than 10 minutes old)
        const isOnAirNow = recentTrack.timestamp && (Date.now() - recentTrack.timestamp) < 10 * 60 * 1000;
        const wasOnAir = previousTrack?.timestamp && (Date.now() - previousTrack.timestamp) < 10 * 60 * 1000;

        // Animate when a friend starts a new song (not just on-air status change from time passing)
        if (trackChanged && isOnAirNow && pinnedFriendIdsRef.current.includes(friend.id)) {
          setMovedFriendIds(prev => new Set([...prev, friend.id]));
          setTimeout(() => {
            setMovedFriendIds(prev => {
              const next = new Set(prev);
              next.delete(friend.id);
              return next;
            });
          }, 400);
        }

        // Refresh the weekly stats cache at most every 30 minutes, counting
        // failed and empty attempts too (they used to be retried every poll)
        const statsStale = friendPollBackoffRef.current.statsDue(friend.id, friend.cachedWeeklyStats?.fetchedAt);

        let newWeeklyStats = friend.cachedWeeklyStats;
        if (statsStale) {
          friendPollBackoffRef.current.recordStatsAttempt(friend.id);
          // Fetch in background, don't await to avoid slowing down polling
          fetchFriendWeeklyStats(friend).then(stats => {
            if (stats) {
              setFriends(prev => prev.map(f =>
                f.id === friend.id ? { ...f, cachedWeeklyStats: stats } : f
              ));
            }
          });
        }

        // Only update state when the track actually changed or timestamp meaningfully differs
        // This avoids unnecessary re-renders that cause sort reordering on every poll
        if (trackChanged || !previousTrack?.timestamp || Math.abs(recentTrack.timestamp - previousTrack.timestamp) > 30000) {
          setFriends(prev => prev.map(f =>
            f.id === friend.id
              ? { ...f, cachedRecentTrack: recentTrack, lastFetched: Date.now() }
              : f
          ));
        }

        // Auto-pin/unpin saved friends based on on-air status
        // Read from refs to get latest state (avoids stale closure in setInterval)
        const isPinned = pinnedFriendIdsRef.current.includes(friend.id);
        const isAutoPinned = autoPinnedFriendIdsRef.current.includes(friend.id);

        if (friend.savedToCollection && isOnAirNow && !isPinned) {
          // Saved friend became active - auto-pin them to sidebar
          console.log(`👥 Auto-pinning ${friend.displayName} (now active)`);
          setPinnedFriendIds(prev => prev.includes(friend.id) ? prev : [...prev, friend.id]);
          setAutoPinnedFriendIds(prev => prev.includes(friend.id) ? prev : [...prev, friend.id]);
          // Track as newly pinned for entry animation
          setNewlyPinnedFriendIds(prev => new Set([...prev, friend.id]));
          setTimeout(() => {
            setNewlyPinnedFriendIds(prev => {
              const next = new Set(prev);
              next.delete(friend.id);
              return next;
            });
          }, 300);
        } else if (isAutoPinned && !isOnAirNow) {
          // Auto-pinned friend is no longer active - auto-unpin them
          console.log(`👥 Auto-unpinning ${friend.displayName} (no longer active)`);
          setPinnedFriendIds(prev => prev.filter(id => id !== friend.id));
          setAutoPinnedFriendIds(prev => prev.filter(id => id !== friend.id));
        }

        // Check if the friend we're listening along to went inactive
        if (listenAlongFriendNow?.id === friend.id && !isOnAirNow) {
          listenAlongLastPollTrackRef.current = null;
          listenAlongFriendWentQuiet(friend);
          continue; // Skip further processing for this friend
        }

        // While the session waits (#1319: our song ended with the friend's
        // position unknown, or their track couldn't play here), this poll
        // decides, whether or not the cached track changed: another track
        // plays; after our song ended, the same one ends the session.
        if (listenAlongFriendNow?.id === friend.id && isOnAirNow) {
          listenAlongLastPollTrackRef.current = { name: recentTrack.name, artist: recentTrack.artist };
          const waiting = listenAlongWaitingRef.current;
          if (waiting && !isPlayingRef.current) {
            const decision = listenAlongWaitDecision({ waiting, playedTrack: listenAlongLastTrackRef.current, polledTrack: recentTrack });
            if (decision === 'not-moved-on') {
              console.log(`🎧 Listen-along: ${friend.displayName} hasn't moved on - ending listen-along`);
              endListenAlongToQueue(`${friend.displayName} hasn't moved on - resuming your queue`);
              continue;
            }
            if (decision === 'play') {
              console.log(`🎧 Listen-along: ${friend.displayName} is on "${recentTrack.name}" now; playing it`);
              if (trackChanged) resolveFriendTrack(recentTrack);
              playListenAlongTrack(friend, recentTrack);
              continue;
            }
          }
        }

        // Resolve the track in background if it's new/changed and friend is on-air
        if (trackChanged && isOnAirNow) {
          resolveFriendTrack(recentTrack);

          // If we're listening along to this friend and they changed tracks, queue or play the new one
          if (listenAlongFriendNow?.id === friend.id) {
            const lastTrack = listenAlongLastTrackRef.current;
            const isNewTrack = !lastTrack ||
              lastTrack.name !== recentTrack.name ||
              lastTrack.artist !== recentTrack.artist;

            if (isNewTrack) {
              console.log(`🎧 Listen-along: ${friend.displayName} started playing "${recentTrack.name}"`);

              // Wait a moment for track to resolve, then queue or play
              setTimeout(async () => {
                const cacheKey = `${recentTrack.artist.toLowerCase()}|${recentTrack.name.toLowerCase()}`;
                const cachedSources = trackSourcesCache.current[cacheKey]?.sources || {};
                const track = {
                  title: recentTrack.name,
                  artist: recentTrack.artist,
                  album: recentTrack.album,
                  albumArt: recentTrack.albumArt,
                  sources: cachedSources,
                  _offLap: true, // a friend's track isn't the queue's: repeat all never wraps it (#1319)
                  _playbackContext: {
                    type: 'listenAlong',
                    name: friend.displayName,
                    friendId: friend.id
                  }
                };

                // Check if we're currently playing - if so, queue as pending
                // Otherwise play immediately (our song already ended)
                if (isPlayingRef.current) {
                  console.log(`🎧 Listen-along: Queuing "${track.title}" to play when current track ends`);
                  listenAlongPendingTrackRef.current = track;

                  // Update pool visibility for resolution - the pending track
                  // Use track ID as key to avoid re-resolution
                  const poolTracks = [{
                    key: track.id || `${track.artist}-${track.title}`,
                    data: { track, artistName: track.artist || 'Unknown Artist' }
                  }];
                  updateSchedulerVisibility('listen-along', poolTracks);
                } else if (listenAlongUserPausedRef.current) {
                  // User explicitly paused - don't auto-resume, just store the pending track
                  console.log(`🎧 Listen-along: User is paused, storing "${track.title}" as pending`);
                  listenAlongPendingTrackRef.current = track;

                  const poolTracks = [{
                    key: track.id || `${track.artist}-${track.title}`,
                    data: { track, artistName: track.artist || 'Unknown Artist' }
                  }];
                  updateSchedulerVisibility('listen-along', poolTracks);
                } else {
                  // Not playing and not user-paused, so our track ended - play friend's track now
                  console.log(`🎧 Listen-along: Playing "${track.title}" immediately`);
                  listenAlongLastTrackRef.current = {
                    name: recentTrack.name,
                    artist: recentTrack.artist
                  };
                  listenAlongLastPollTrackRef.current = null;
                  listenAlongWaitingRef.current = null;
                  handlePlay(track);
                }
              }, 1000); // Wait 1 second for sources to resolve
            }
          }
        }
      }
    }
  };

  const fetchTransientFriendNowPlaying = async (service, user) => {
    const playing = await askFriend({ service, username: user }, 'getNowPlaying').catch(() => null);
    return playing
      ? { name: playing.title, artist: playing.artist, album: playing.album, timestamp: Date.now() }
      : null;
  };

  // Activate listen-along mode for a friend
  const activateListenAlong = (friend) => {
    if (!friend || !friend.cachedRecentTrack) return;

    console.log(`🎧 Starting listen-along with ${friend.displayName}`);

    // Register pool context for listen-along resolution
    registerPoolContext('listen-along', 1);

    setListenAlongFriend(friend);
    listenAlongLastTrackRef.current = {
      name: friend.cachedRecentTrack.name,
      artist: friend.cachedRecentTrack.artist
    };
    listenAlongUserPausedRef.current = false;
    listenAlongWaitingRef.current = null;
    listenAlongLastPollTrackRef.current = null;
    listenAlongFailedPollsRef.current = 0;

    // Set playback context to listen-along
    setPlaybackContext({
      type: 'listenAlong',
      name: friend.displayName,
      friendId: friend.id
    });

    // Play the friend's current track
    const cacheKey = `${friend.cachedRecentTrack.artist.toLowerCase()}|${friend.cachedRecentTrack.name.toLowerCase()}`;
    const cachedSources = trackSourcesCache.current[cacheKey]?.sources || {};
    const track = {
      title: friend.cachedRecentTrack.name,
      artist: friend.cachedRecentTrack.artist,
      album: friend.cachedRecentTrack.album,
      albumArt: friend.cachedRecentTrack.albumArt,
      sources: cachedSources,
      _offLap: true, // a friend's track isn't the queue's: repeat all never wraps it (#1319)
      _playbackContext: {
        type: 'listenAlong',
        name: friend.displayName,
        friendId: friend.id
      }
    };
    handlePlay(track);

    showToast(`Listening along with ${friend.displayName}`);
  };

  // Deactivate listen-along mode
  const deactivateListenAlong = () => {
    // Also handle deferred ending case (friend already went offline)
    if (!listenAlongFriend && !listenAlongEndAfterSongRef.current) return;

    // Abort and cleanup pool context
    abortSchedulerContext('listen-along');

    const friendName = listenAlongFriend?.displayName || listenAlongEndAfterSongRef.current;
    console.log(`🎧 Stopped listening along with ${friendName}`);
    setListenAlongFriend(null);
    listenAlongLastTrackRef.current = null;
    listenAlongUserPausedRef.current = false;
    listenAlongEndAfterSongRef.current = null;

    // Clear the listen-along context - will use queue's context when next track plays
    setPlaybackContext(null);

    showToast(`Stopped listening along with ${friendName}`);
  };

  // Assign listen-along functions to refs for context menu access
  activateListenAlongRef.current = activateListenAlong;
  deactivateListenAlongRef.current = deactivateListenAlong;

  // Poll friends for on-air status (pinned friends + saved friends for auto-pinning)
  const hasSavedFriends = friends.some(f => f.savedToCollection);
  useEffect(() => {
    if (pinnedFriendIds.length > 0 || hasSavedFriends) {
      // Initial refresh
      refreshPinnedFriends();

      // Set up polling interval - faster when listen-along is active
      const pollInterval = listenAlongFriend ? 15 * 1000 : 2 * 60 * 1000; // 15 seconds vs 2 minutes
      // NOT yield-wrapped intentionally — the 2-min cadence is already the
      // user-visible freshness budget for `cachedRecentTrack`, and any
      // yield-induced delay degrades the "click Listen Along → join the
      // track my friend is actually playing right now" path. The poll is
      // small enough (one HTTP/IPC call per pinned friend) that it doesn't
      // compete with foreground work meaningfully even mid-busy-tick. See
      // parachord#770 part 2 — hosted-XSPF poll is yielded; this one is not.
      friendPollIntervalRef.current = setInterval(() => {
        refreshPinnedFriends();
      }, pollInterval);

      return () => {
        if (friendPollIntervalRef.current) {
          clearInterval(friendPollIntervalRef.current);
        }
      };
    }
  }, [pinnedFriendIds.length, hasSavedFriends, listenAlongFriend]);

  // Startup sync: one-time inbound pull after the bulk cache load completes
  // and credentials are available. Fire-and-forget; activity poll fills
  // cachedRecentTrack for anyone newly synced in on the next 2-min tick.
  const friendStartupSyncDoneRef = useRef(false);
  // Every deferred sync trigger (startup timeout, periodic timer, Friends tab)
  // calls the LATEST syncFriendsFromServices through this ref: the function
  // reads metaServiceConfigs from its render, and a timer outlives that render.
  const syncFriendsFromServicesRef = useRef(null);
  syncFriendsFromServicesRef.current = syncFriendsFromServices;
  useEffect(() => {
    if (!cacheLoaded) return;
    if (friendStartupSyncDoneRef.current) return;
    // A friend service you're signed in to, and the plug-ins loaded (the
    // sync asks them, #1539 step 5).
    const hasCreds = Object.values(metaServiceConfigs || {}).some(c => c && c.username);
    if (!hasCreds || metaServices.length === 0) return;
    friendStartupSyncDoneRef.current = true;
    // Small delay so we don't thrash the network during startup. A launch
    // that restores onto the Friends tab has already synced by then.
    setTimeout(() => {
      if (Date.now() - lastFriendSyncAtRef.current < FRIEND_TAB_SYNC_MIN_GAP_MS) return;
      syncFriendsFromServicesRef.current?.({ silent: true });
    }, 5000);
  }, [cacheLoaded, metaServiceConfigs, metaServices]);

  // Periodic friend-graph sync: every 30 min while a friend service is set
  // up. It used to ride every 15th tick of the activity poll above,
  // which only runs once a friend is saved or pinned, so with no friends yet
  // someone followed mid-session never arrived until a restart. Friend graphs
  // change far less often than recent tracks, so this keeps its own slower
  // timer. It calls the latest syncFriendsFromServices through
  // syncFriendsFromServicesRef (above the startup sync).
  const FRIEND_GRAPH_SYNC_MS = 30 * 60 * 1000;
  // A friend service you're signed in to (a username in its plug-in's
  // settings). Read from state, so the timers start once one is set up.
  const hasFriendServiceAccount = Object.values(metaServiceConfigs || {}).some(c => c && c.username);
  useEffect(() => {
    if (!cacheLoaded || !hasFriendServiceAccount) return;
    const id = setInterval(() => {
      syncFriendsFromServicesRef.current?.({ silent: true });
    }, FRIEND_GRAPH_SYNC_MS);
    return () => clearInterval(id);
  }, [cacheLoaded, hasFriendServiceAccount]);

  // Opening the Collection's Friends tab syncs too, like mobile's Friends
  // screen (FriendsViewModel.init): it's where someone looks for a friend
  // they just followed. Tab switches are cheap on desktop and the Last.fm
  // friend list is paginated, so a sync that started in the last 5 minutes
  // (any trigger) counts.
  useEffect(() => {
    if (!cacheLoaded || !hasFriendServiceAccount) return;
    if (activeView !== 'library' || collectionTab !== 'friends') return;
    if (Date.now() - lastFriendSyncAtRef.current < FRIEND_TAB_SYNC_MIN_GAP_MS) return;
    syncFriendsFromServicesRef.current?.({ silent: true });
  }, [activeView, collectionTab, cacheLoaded, hasFriendServiceAccount]);

  // Load friend's recent listening history
  const loadFriendRecentTracks = async (friend) => {
    setFriendHistoryLoading(true);

    try {
      const listens = await askFriend(friend, 'getRecentListens', { limit: 50 });
      updateFriendHidesListening(friend, false);
      const tracks = listens.map((t, index) => ({
        id: `friend-recent-${index}-${t.title}`.replace(/\s+/g, '-'),
        title: t.title,
        artist: t.artist || 'Unknown Artist',
        album: t.album || null,
        albumArt: t.albumArt || null,
        timestamp: t.playedAt || Date.now(),
        nowPlaying: !!t.nowPlaying,
        sources: {}
      }));

      // Resolution handled by scheduler via IntersectionObserver
      setFriendHistoryData(prev => ({ ...prev, recent: tracks, recentHidden: false, errors: { ...(prev.errors || {}), recent: false } }));
    } catch (error) {
      if (error && error.hidesListening) {
        // Not a failure: the profile hides its recent listening, and the
        // Recent tab says so (the other tabs still load).
        updateFriendHidesListening(friend, true);
        setFriendHistoryData(prev => ({ ...prev, recent: [], recentHidden: true, errors: { ...(prev.errors || {}), recent: false } }));
        return;
      }
      console.error('Failed to load friend recent tracks:', error);
      // Shown in the tab, with Try again, instead of an empty list that
      // reads as "they have none" (renderer: friendTabError).
      setFriendHistoryData(prev => ({ ...prev, recent: [], errors: { ...(prev.errors || {}), recent: true } }));
    } finally {
      setFriendHistoryLoading(false);
    }
  };

  // Load friend's top tracks
  // A listener's top tracks for a period, most played first (Last.fm or
  // ListenBrainz). Throws when the service fails; [] when it has none. The
  // profile's Top tracks tab and the Listener cards' Play both use it.
  const fetchFriendTopTracksList = async (friend, period, limit = 50) => {
    const items = await askFriend(friend, 'getTopItems', { kind: 'tracks', period: historyPeriodFor(period), limit });
    return items.map((track, index) => ({
      id: `friend-top-track-${index}-${track.title}`.replace(/\s+/g, '-'),
      title: track.title,
      artist: track.artist || 'Unknown Artist',
      // Only a cover the service matched itself; the art pipeline
      // (getAlbumArt / getTrackArt) fills in the rest.
      albumArt: track.albumArt || null,
      playCount: Number(track.plays) || 0,
      rank: index + 1,
      sources: {}
    }));
  };

  const loadFriendTopTracks = async (friend, period = friendHistoryPeriod) => {
    setFriendHistoryLoading(true);
    try {
      const tracks = await fetchFriendTopTracksList(friend, period);
      // Resolution handled by scheduler via IntersectionObserver
      setFriendHistoryData(prev => ({ ...prev, topTracks: tracks, errors: { ...(prev.errors || {}), topTracks: false } }));
    } catch (error) {
      console.error('Failed to load friend top tracks:', error);
      // Shown in the tab, with Try again, instead of an empty list that
      // reads as "they have none" (renderer: friendTabError).
      setFriendHistoryData(prev => ({ ...prev, topTracks: [], errors: { ...(prev.errors || {}), topTracks: true } }));
    } finally {
      setFriendHistoryLoading(false);
    }
  };

  // A Listener card's Play: their top 10 of the past week (the past month
  // when the week has none), played like a top-tracks row.
  // `listener` is a Listener card's item ({ service, name }) or a saved
  // friend ({ service, username, displayName }).
  const playListenerTopTracks = async (listener) => {
    const friend = { service: listener.service, username: listener.username || listener.name };
    const name = listener.displayName || listener.name || friend.username;
    setTrackLoading(true);
    try {
      let tracks = await fetchFriendTopTracksList(friend, '7day', 10);
      if (tracks.length === 0) tracks = await fetchFriendTopTracksList(friend, '1month', 10);
      if (tracks.length === 0) {
        setTrackLoading(false);
        showToast(`${name} has no recent top tracks`, 'error');
        return;
      }
      const context = { type: 'friend', name, tab: 'topTracks' };
      const [first, ...rest] = tracks;
      setQueueWithContext(rest, context, true);
      handlePlay({ ...first, _playbackContext: context });
    } catch (error) {
      console.error('Failed to play listener top tracks:', error);
      setTrackLoading(false);
      showToast(`Couldn’t load ${name}’s top tracks. Try again in a moment.`, 'error');
    }
  };

  // Load friend's top artists
  const loadFriendTopArtists = async (friend, period = friendHistoryPeriod) => {
    setFriendHistoryLoading(true);

    try {
      const items = await askFriend(friend, 'getTopItems', { kind: 'artists', period: historyPeriodFor(period), limit: 50 });
      const artists = items.map((artist, index) => ({
        id: `friend-top-artist-${index}-${artist.name}`.replace(/\s+/g, '-'),
        name: artist.name || 'Unknown Artist',
        image: null,
        playCount: Number(artist.plays) || 0,
        rank: index + 1
      }));
      setFriendHistoryData(prev => ({ ...prev, topArtists: artists, errors: { ...(prev.errors || {}), topArtists: false } }));

      // Fetch artist images in background
      if (artists.length > 0) {
        resolveFriendTopArtistImages(artists);
      }
    } catch (error) {
      console.error('Failed to load friend top artists:', error);
      // Shown in the tab, with Try again, instead of an empty list that
      // reads as "they have none" (renderer: friendTabError).
      setFriendHistoryData(prev => ({ ...prev, topArtists: [], errors: { ...(prev.errors || {}), topArtists: true } }));
    } finally {
      setFriendHistoryLoading(false);
    }
  };

  // Resolve friend top artist images
  const resolveFriendTopArtistImages = async (artists) => {
    for (const artist of artists) {
      try {
        const result = await getArtistImage(artist.name);
        setFriendHistoryData(prev => ({
          ...prev,
          topArtists: prev.topArtists.map(a =>
            a.id === artist.id ? { ...a, image: result?.url || null, imageLoaded: true } : a
          )
        }));
      } catch (err) {
        console.error(`Error fetching image for ${artist.name}:`, err);
        // Mark as loaded even on error so we show the pattern fallback
        setFriendHistoryData(prev => ({
          ...prev,
          topArtists: prev.topArtists.map(a =>
            a.id === artist.id ? { ...a, imageLoaded: true } : a
          )
        }));
      }
    }
  };

  // Load friend's top albums
  const loadFriendTopAlbums = async (friend, period = friendHistoryPeriod) => {
    setFriendHistoryLoading(true);

    try {
      const items = await askFriend(friend, 'getTopItems', { kind: 'albums', period: historyPeriodFor(period), limit: 50 });
      const albums = items.map((album, index) => ({
        id: `friend-top-album-${index}-${album.title}`.replace(/\s+/g, '-'),
        name: album.title || 'Unknown Album',
        artist: album.artist || 'Unknown Artist',
        image: album.albumArt || null,
        playCount: Number(album.plays) || 0,
        rank: index + 1
      }));

      setFriendHistoryData(prev => ({
        ...prev,
        topAlbums: albums.map(a => (a.image ? { ...a, imageLoaded: true } : a)),
        errors: { ...(prev.errors || {}), topAlbums: false }
      }));

      // Covers for the albums that came without one, in the background
      if (albums.length > 0) {
        resolveFriendTopAlbumImages(albums);
      }
    } catch (error) {
      console.error('Failed to load friend top albums:', error);
      // Shown in the tab, with Try again, instead of an empty list that
      // reads as "they have none" (renderer: friendTabError).
      setFriendHistoryData(prev => ({ ...prev, topAlbums: [], errors: { ...(prev.errors || {}), topAlbums: true } }));
    } finally {
      setFriendHistoryLoading(false);
    }
  };

  // Covers for a friend's top albums that arrived without one (Last.fm had
  // none, or ListenBrainz named no cover). They go through getAlbumArt, THE
  // album-art pipeline, four albums in flight, and land in state in 250ms
  // batches. This used to be its own MusicBrainz name search plus a HEAD
  // request per album, with a full render per album (#1179). A newer load
  // (another friend or period) bumps the generation, and results from the
  // older one are dropped: album ids are rank+name, so they can repeat.
  const FRIEND_TOP_ALBUM_ART_CONCURRENCY = 4;
  const friendTopAlbumArtGenerationRef = useRef(0);
  const friendTopAlbumArtWriterRef = useRef(null);
  if (!friendTopAlbumArtWriterRef.current) {
    friendTopAlbumArtWriterRef.current = window.createCoalescedUpdater((batch) => {
      setFriendHistoryData(prev => ({
        ...prev,
        topAlbums: prev.topAlbums.map(a => {
          const ops = batch.get(a.id);
          if (!ops) return a;
          const result = window.applyCoalescedOps(undefined, ops);
          if (result.generation !== friendTopAlbumArtGenerationRef.current) return a;
          return { ...a, image: result.image || a.image, imageLoaded: true };
        })
      }));
    }, 250);
  }

  const resolveFriendTopAlbumImages = (albums) => {
    const generation = ++friendTopAlbumArtGenerationRef.current;
    const writer = friendTopAlbumArtWriterRef.current;
    const queue = albums.filter(a => !a.image);
    const worker = async () => {
      while (queue.length > 0) {
        if (friendTopAlbumArtGenerationRef.current !== generation) return;
        const album = queue.shift();
        let image = null;
        try {
          image = await getAlbumArt(album.artist, album.name);
        } catch (err) {
          console.error(`Error fetching image for album ${album.name}:`, err);
        }
        // Queued even without a cover, so the card stops shimmering
        writer.queue(album.id, { generation, image });
      }
    };
    Promise.all(Array.from({ length: Math.min(FRIEND_TOP_ALBUM_ART_CONCURRENCY, queue.length) }, worker))
      .then(() => writer.flush());
  };

  // Navigate to friend's history view. tabKey mirrors the tab bar of that
  // view ('recent' | 'topTracks' | 'topAlbums' | 'topArtists'); anything
  // else falls back to 'recent'. Loads the selected tab's data, same as a
  // tab click in the UI. A period (from a deep link) is set and passed to the
  // loader explicitly, as the period dropdown does: the loader's default
  // would read the state from before the update.
  const navigateToFriend = (friend, tabKey = 'recent', period = null) => {
    const tab = ['recent', 'topTracks', 'topAlbums', 'topArtists'].includes(tabKey) ? tabKey : 'recent';
    const topPeriod = period || friendHistoryPeriod;
    if (period) setFriendHistoryPeriod(period);
    setCurrentFriend(friend);
    setFriendHistoryTab(tab);
    setFriendHistoryData({ recent: [], topTracks: [], topAlbums: [], topArtists: [] });
    navigateTo('friendHistory');
    if (tab === 'recent') loadFriendRecentTracks(friend);
    else if (tab === 'topTracks') loadFriendTopTracks(friend, topPeriod);
    else if (tab === 'topAlbums') loadFriendTopAlbums(friend, topPeriod);
    else loadFriendTopArtists(friend, topPeriod);
  };
  navigateToFriendRef.current = navigateToFriend;

  // Helper function to search MusicBrainz with fallback for multi-artist names
  // If artist contains "&" or " and " and search fails, tries with just the first artist name
  // opts.background: queue in the MusicBrainz limiter's background lane
  // (hover prefetches), so the search never delays a user-initiated lookup.
  const searchMusicBrainzRelease = async (album, artist, opts = {}) => {
    const doSearch = async (artistQuery) => {
      const searchQuery = encodeURIComponent(`release:"${album}" AND artist:"${artistQuery}"`);
      const mbResponse = await fetch(
        `https://musicbrainz.org/ws/2/release/?query=${searchQuery}&fmt=json&limit=1`,
        { headers: { 'User-Agent': 'Parachord/1.0.0 (https://github.com/harmonix)' }, mbBackground: !!opts.background }
      );

      if (!mbResponse.ok) {
        throw new Error('MusicBrainz search failed');
      }

      const mbData = await mbResponse.json();
      return mbData.releases || [];
    };

    // Try with full artist name first
    let releases = await doSearch(artist);

    // If no results and artist contains "&" or " and ", try with just the first artist
    if (releases.length === 0) {
      let firstArtist = null;

      if (artist.includes(' & ')) {
        firstArtist = artist.split(' & ')[0].trim();
      } else if (artist.toLowerCase().includes(' and ')) {
        firstArtist = artist.split(/ and /i)[0].trim();
      }

      if (firstArtist) {
        console.log(`MusicBrainz: No results for "${artist}", trying with "${firstArtist}"`);
        releases = await doSearch(firstArtist);
      }
    }

    return releases;
  };

  // Prefetch album tracks on hover (for Top Albums)
  const prefetchTopAlbumTracks = (artistName, albumName, albumArt = null) => {
    const cacheKey = `${artistName}-${albumName}`.toLowerCase();

    // Skip if already cached or in progress
    if (topAlbumTracksCache.current[cacheKey] || topAlbumPrefetchInProgress.current.has(cacheKey)) {
      return;
    }

    // Mark as in progress
    topAlbumPrefetchInProgress.current.add(cacheKey);

    // Fetch asynchronously, in the limiter's background lane (a hover must
    // never delay a click's lookup)
    (async () => {
      try {
        const bgFetch = (url, init) => fetch(url, { ...(init || {}), mbBackground: true });
        const releases = await searchMusicBrainzRelease(albumName, artistName, { background: true });
        if (releases.length === 0) return;

        const releaseId = releases[0].id;
        const releaseDetailsResponse = await fetchReleaseDetails(releaseId, bgFetch);

        if (!releaseDetailsResponse.ok) return;

        const releaseData = await releaseDetailsResponse.json();
        const tracks = [];
        if (releaseData.media && releaseData.media.length > 0) {
          releaseData.media.forEach((medium) => {
            if (medium.tracks) {
              medium.tracks.forEach(track => {
                const trackId = trackSlug(artistName, track.title || 'untitled', albumName);
                tracks.push({
                  id: trackId,
                  position: track.position,
                  title: track.title || track.recording?.title || 'Unknown Track',
                  length: track.length,
                  duration: track.length ? Math.round(track.length / 1000) : 0,
                  recordingId: track.recording?.id,
                  artist: artistName,
                  album: albumName,
                  albumArt: albumArt,
                  sources: {}
                });
              });
            }
          });
        }

        // Cache the result
        topAlbumTracksCache.current[cacheKey] = tracks;
      } catch (error) {
        // Silently fail - prefetch is optional
      } finally {
        topAlbumPrefetchInProgress.current.delete(cacheKey);
      }
    })();
  };

  // Fetch album tracks by artist and album name (for Top Albums hover buttons)
  const fetchAlbumTracksByName = async (artistName, albumName, albumArt = null) => {
    const cacheKey = `${artistName}-${albumName}`.toLowerCase();

    // Check cache first
    if (topAlbumTracksCache.current[cacheKey]) {
      return topAlbumTracksCache.current[cacheKey];
    }

    try {
      // MusicBrainz and the services' catalogs race for the track list
      // (loadAlbumTrackList), which also records the release group it found.
      const list = await loadAlbumTrackList({ artist: artistName, title: albumName, albumArt });
      if (!list) {
        console.log(`No track list found for: ${artistName} - ${albumName}`);
        return [];
      }
      const tracks = list.tracks;

      // Cache the result
      topAlbumTracksCache.current[cacheKey] = tracks;

      return tracks;
    } catch (error) {
      console.error(`Error fetching album tracks for ${artistName} - ${albumName}:`, error);
      return [];
    }
  };

  // Keep fetchAlbumTracksByNameRef in sync for ChatCard
  useEffect(() => {
    fetchAlbumTracksByNameRef.current = fetchAlbumTracksByName;
  }, []);

  // Fetch album art for Critic's Picks in background
  const fetchCriticsPicksAlbumArt = async (albums) => {
    // First pass: check cache for all albums (instant, no network)
    const albumsNeedingFetch = [];
    const cachedUpdates = [];

    for (const album of albums) {
      // Same classification as the Charts pass: any cache shape hits, every
      // miss goes to getAlbumArt. A null in albumToReleaseIdCache used to be
      // read as "no art anywhere" and pinned the placeholder (persisted with
      // the picks), though it only means MusicBrainz had no match and the
      // resolvers and catalogs were never asked.
      const cachedArt = getCachedAlbumArt(album.artist, album.title);
      if (cachedArt) {
        cachedUpdates.push({ id: album.id, albumArt: cachedArt });
      } else {
        albumsNeedingFetch.push(album);
      }
    }

    // Apply cached updates immediately
    if (cachedUpdates.length > 0) {
      console.log(`📰 Using cached art for ${cachedUpdates.length} Critic's Picks albums`);
      setCriticsPicks(prev => prev.map(a => {
        const cached = cachedUpdates.find(u => u.id === a.id);
        return cached ? { ...a, albumArt: cached.albumArt } : a;
      }));
    }

    // Second pass: fetch art for albums not in cache
    for (const album of albumsNeedingFetch) {
      try {
        const artUrl = await getAlbumArt(album.artist, album.title);
        // Set to artUrl if found, or null if not (to show placeholder instead of shimmer)
        setCriticsPicks(prev => prev.map(a =>
          a.id === album.id ? { ...a, albumArt: artUrl || null } : a
        ));
      } catch (error) {
        console.log(`Could not fetch art for: ${album.artist} - ${album.title}`);
        // Set to null on error to show placeholder
        setCriticsPicks(prev => prev.map(a =>
          a.id === album.id ? { ...a, albumArt: null } : a
        ));
      }
      // Small delay to avoid rate limiting
      await new Promise(resolve => setTimeout(resolve, 200));
    }

    // Re-persist the picks now that art is resolved, so the cache (and thus the
    // instant restore + union base) carries cover URLs across restarts. Reads the
    // latest state via the updater and returns it unchanged (parachord#962).
    setCriticsPicks(prev => {
      persistCriticsPicksCache(prev);
      return prev;
    });
  };

  // Navigate to a Critic's Picks album release page
  // Critic's Picks cards: same navigate-first opener as the charts.
  const openCriticsPicksAlbum = (album) => openChartsAlbum({
    id: album.id,
    artist: album.artist,
    title: album.title,
    albumArt: album.albumArt
  });

  // Navigate to a Top Album from History page
  // Top Albums cards and the home hero cards ({ name, image } field names):
  // same navigate-first opener as the charts. A caller that knows the
  // release-group id (the home Fresh Drops hero) passes releaseGroupId so
  // the lookup is a direct one instead of a string search.
  const openTopAlbum = (album) => openChartsAlbum({
    id: album.id,
    artist: album.artist,
    title: album.name,
    albumArt: album.image,
    releaseGroupId: album.releaseGroupId,
    date: album.date,
    releaseType: album.releaseType
  });

  // Prefetch Critic's Picks album tracks on hover (for Add to Queue)
  // Resolves to the tracks, like prefetchChartsTracks (sharedReleasePrefetch).
  const prefetchCriticsPicksTracks = (album) => sharedReleasePrefetch(album.id, async () => {
    try {
      console.log('🔍 Prefetching Critic\'s Pick tracks for:', album.title);

      // Background lane of the MusicBrainz limiter (see prefetchChartsTracks).
      const bgFetch = (url, init) => fetch(url, { ...(init || {}), mbBackground: true });
      // Search MusicBrainz for the release
      const searchQuery = encodeURIComponent(`release:"${album.title}" AND artist:"${album.artist}"`);
      const mbResponse = await bgFetch(
        `https://musicbrainz.org/ws/2/release/?query=${searchQuery}&fmt=json&limit=1`,
        { headers: { 'User-Agent': 'Parachord/1.0.0 (https://github.com/harmonix)' } }
      );

      if (!mbResponse.ok) return null;

      const mbData = await mbResponse.json();
      if (!mbData.releases || mbData.releases.length === 0) return null;

      const releaseId = mbData.releases[0].id;

      // Fetch release details with tracks
      const releaseDetailsResponse = await fetchReleaseDetails(releaseId, bgFetch);

      if (!releaseDetailsResponse.ok) return null;

      const releaseData = await releaseDetailsResponse.json();

      // Extract tracks
      const tracks = [];
      if (releaseData.media && releaseData.media.length > 0) {
        releaseData.media.forEach((medium) => {
          if (medium.tracks) {
            medium.tracks.forEach(track => {
              const trackId = trackSlug(album.artist, track.title || 'untitled', album.title);
              tracks.push({
                id: trackId,
                position: track.position,
                title: track.title || track.recording?.title || 'Unknown Track',
                length: track.length,
                recordingId: track.recording?.id,
                artist: album.artist,
                album: album.title,
                albumArt: album.albumArt,
                sources: {}
              });
            });
          }
        });
      }

      // Cache the prefetched tracks
      setPrefetchedReleases(prev => ({
        ...prev,
        [album.id]: {
          tracks,
          title: album.title,
          albumArt: album.albumArt,
          artist: album.artist
        }
      }));

      console.log(`✅ Prefetched ${tracks.length} tracks for ${album.title}`);
      return tracks.length > 0 ? tracks : null;
    } catch (error) {
      console.error('Error prefetching Critic\'s Pick tracks:', error);
      return null;
    }
  });

  // Add Critic's Picks album to queue
  const addCriticsPicksToQueue = async (album) => {
    const context = { type: 'album', id: album.id, name: album.title, artist: album.artist };

    // Check if we have prefetched tracks
    const prefetched = prefetchedReleases[album.id];

    if (prefetched?.tracks?.length > 0) {
      addToQueue(prefetched.tracks, context);
      return;
    }

    // Otherwise, fetch and add
    const tracks = await prefetchCriticsPicksTracks(album);
    if (tracks?.length > 0) {
      addToQueue(tracks, context);
    }
  };

  // Cache for mapping artist+album -> MusicBrainz release ID (to avoid repeated searches)
  const albumToReleaseIdCache = useRef({});

  // Cache for resolver-based album art lookups
  const resolverArtCache = useRef({});

  // Adapters for the catalog art chain (album-art-catalog.js). iTunes goes
  // through the shared limiter (~20 req/min/IP); Deezer sends no CORS header
  // for file:// origins, so it goes through the main-process proxy.
  const catalogArtDeps = () => ({
    fetchItunes: (url) => window.iTunesRateLimiter.fetch(url, { background: true }), // covers wait behind resolution
    fetchDeezer: async (url) => {
      const r = await window.electron?.proxyFetch?.(url, { headers: { Accept: 'application/json' } });
      return { ok: !!(r && r.success), json: async () => JSON.parse(r.text || 'null') };
    }
  });

  // Steps 3 and 4 of the shared album-art pipeline (see getAlbumArt): the
  // enabled resolvers' search results, then the iTunes → Deezer catalog chain.
  // Called by getAlbumArt after MusicBrainz + Cover Art Archive miss. A miss is
  // remembered for the session (resolverArtCache null) only when every source
  // answered; a thrown search (network, throttle) is not cached, so the next
  // render tries again.
  const getAlbumArtFromResolvers = async (artist, album) => {
    if (!artist || !album) return null;

    const cacheKey = `${artist}-${album}`.toLowerCase();

    // Check resolver art cache first
    if (resolverArtCache.current[cacheKey] !== undefined) {
      return resolverArtCache.current[cacheKey]; // null = previously failed
    }

    const remember = (url, source) => {
      resolverArtCache.current[cacheKey] = url;
      // Also store in shared albumArtCache for cross-lookup (getCachedAlbumArt)
      albumArtCache.current[`${source}:${cacheKey}`] = { url, timestamp: Date.now() };
      return url;
    };

    try {
      // Walk resolvers in priority order until one returns a result WITH art;
      // stopping at the first resolver that returned anything (the old
      // behaviour) let an art-less hit from a higher-priority resolver hide
      // Spotify's or Bandcamp's cover.
      // Background lane: a cover waits behind track resolution.
      const results = await searchResolvers(`${artist} ${album}`, { earlyReturn: true, requireAlbumArt: true, lane: 'background' });

      // Find best match - prefer exact artist+album match
      const normalizedAlbum = album.toLowerCase();
      const normalizedArtist = artist.toLowerCase();

      const bestMatch = (results || []).find(r =>
        r.albumArt &&
        r.artist?.toLowerCase() === normalizedArtist &&
        r.album?.toLowerCase() === normalizedAlbum
      ) || (results || []).find(r =>
        r.albumArt &&
        r.artist?.toLowerCase() === normalizedArtist
      ) || (results || []).find(r => r.albumArt);

      if (bestMatch?.albumArt) return remember(bestMatch.albumArt, 'resolver');
    } catch (err) {
      console.error('Resolver album art lookup failed:', err);
      return null;
    }

    // Catalog fallback: iTunes Search, then Deezer (no auth, independent of
    // which resolvers are enabled). Validated hits only.
    if (window.albumArtCatalog) {
      const catalogUrl = await window.albumArtCatalog.getCatalogAlbumArtwork(artist, album, catalogArtDeps());
      if (catalogUrl) return remember(catalogUrl, 'catalog');
    }

    resolverArtCache.current[cacheKey] = null;
    return null;
  };

  // Track-level art for callers that have a title but no album name (chat
  // cards from prose): the catalog chain's song search, which returns the
  // matched track's album cover. Same validation as the album chain.
  // Session-cached by artist|title.
  const getTrackArt = async (artist, title) => {
    if (!artist || !title) return null;
    const cacheKey = `track:${artist}|${title}`.toLowerCase();
    if (resolverArtCache.current[cacheKey] !== undefined) return resolverArtCache.current[cacheKey];
    let url = null;
    if (window.albumArtCatalog) {
      url = await window.albumArtCatalog.getCatalogTrackArtwork(artist, title, catalogArtDeps());
    }
    resolverArtCache.current[cacheKey] = url;
    return url;
  };

  // Step 2 of the pipeline for known MusicBrainz ids: the cached cover, else
  // the Cover Art Archive's front image for the release group, then for the
  // release. A hit is cached under both ids. No MusicBrainz request.
  const fetchCoverArtByIds = async (releaseGroupId, releaseId) => {
    const cachedArt = (releaseGroupId && albumArtCache.current[releaseGroupId]?.url) ||
                      (releaseId && albumArtCache.current[releaseId]?.url);
    if (cachedArt) return cachedArt;
    const paths = [
      releaseGroupId && `release-group/${releaseGroupId}`,
      releaseId && `release/${releaseId}`
    ].filter(Boolean);
    for (const path of paths) {
      try {
        const response = await fetch(`https://coverartarchive.org/${path}/front-250`, { redirect: 'follow' });
        if (response.ok) {
          const artUrl = response.url;
          const cacheEntry = { url: artUrl, timestamp: Date.now() };
          if (releaseGroupId) albumArtCache.current[releaseGroupId] = cacheEntry;
          if (releaseId) albumArtCache.current[releaseId] = cacheEntry;
          return artUrl;
        }
      } catch (error) {
        console.log(`Cover art fetch failed for ${path}:`, error.message);
      }
    }
    return null;
  };

  // Fetch album art for a track by searching MusicBrainz first, then using the shared albumArtCache
  // THE album-art pipeline. Every surface that shows a cover (playbar, queue,
  // Recommendations, Fresh Drops, chat cards, playlist mosaics, ...) goes
  // through this one function so coverage and caching are identical:
  //   1. caches (albumArtCache by MB id, resolver:/catalog: keys)
  //   2. MusicBrainz release search → Cover Art Archive (release-group, then release)
  //   3. enabled resolvers' search results (getAlbumArtFromResolvers)
  //   4. iTunes Search → Deezer catalog chain (album-art-catalog.js)
  // Don't add a surface-specific shortcut; the chat card had one ("fast",
  // resolvers only) and it is why AI-recommended tracks rendered without art.
  //
  // opts.releaseGroupId / opts.releaseId: a caller that already knows the
  // MusicBrainz ids (a MusicBrainz search result) skips the name search in
  // step 2 and asks the Cover Art Archive for those ids. They are not written
  // to albumToReleaseIdCache: two release groups can share an artist and a
  // title, and the name key would then hand one album's cover to the other.
  // opts.background: step 2's MusicBrainz search waits in the background lane
  // unless a caller passes false. A cover is never what the user clicked for,
  // and covers used to take the foreground lane: on 2026-11-01 five cover
  // searches queued at launch (the queue's and the restored page's) made the
  // artist page's own lookup wait 11s.
  const getAlbumArt = async (artist, album, opts = {}) => {
    if (!album) return null;

    // Known ids need no artist: it's only for the name-based fallbacks.
    if (opts.releaseGroupId || opts.releaseId) {
      const known = await fetchCoverArtByIds(opts.releaseGroupId || null, opts.releaseId || null);
      return known || (artist ? getAlbumArtFromResolvers(artist, album) : null);
    }
    if (!artist) return null;

    const lookupKey = `${artist}-${album}`.toLowerCase();

    // Check if we've already looked up this artist+album combo
    if (albumToReleaseIdCache.current[lookupKey] !== undefined) {
      const cached = albumToReleaseIdCache.current[lookupKey];
      if (cached === null) return getAlbumArtFromResolvers(artist, album); // MusicBrainz failed, try resolvers

      // Support both old format (string) and new format ({ releaseId, releaseGroupId })
      const releaseId = typeof cached === 'string' ? cached : cached.releaseId;
      const releaseGroupId = typeof cached === 'object' ? cached.releaseGroupId : null;

      const artUrl = await fetchCoverArtByIds(releaseGroupId, releaseId);
      return artUrl || getAlbumArtFromResolvers(artist, album); // CAA failed, try resolvers
    }

    try {
      // Search MusicBrainz for the release (with fallback for multi-artist names)
      const releases = await searchMusicBrainzRelease(album, artist, { background: opts.background !== false });

      if (releases.length === 0) {
        albumToReleaseIdCache.current[lookupKey] = null;
        return getAlbumArtFromResolvers(artist, album);
      }

      const releaseId = releases[0].id;
      const releaseGroupId = releases[0]['release-group']?.id;
      // Store both IDs for cache lookups
      albumToReleaseIdCache.current[lookupKey] = { releaseId, releaseGroupId };

      // Check if we already have art for this release or release-group in the shared cache
      const cachedArt = (releaseGroupId && albumArtCache.current[releaseGroupId]?.url) ||
                        albumArtCache.current[releaseId]?.url;
      if (cachedArt) {
        return cachedArt;
      }

      // Fetch cover art from Cover Art Archive
      // Prefer release-group endpoint for consistency, fall back to release
      let artUrl = null;
      if (releaseGroupId) {
        try {
          const rgResponse = await fetch(
            `https://coverartarchive.org/release-group/${releaseGroupId}/front-250`,
            { redirect: 'follow' }
          );
          if (rgResponse.ok) {
            artUrl = rgResponse.url;
          }
        } catch (e) {
          // Fall through to release endpoint
        }
      }

      if (!artUrl) {
        const caaResponse = await fetch(
          `https://coverartarchive.org/release/${releaseId}/front-250`,
          { redirect: 'follow' }
        );
        if (caaResponse.ok) {
          artUrl = caaResponse.url;
        }
      }

      if (artUrl) {
        // Store in the shared albumArtCache under both IDs for cross-lookup
        const cacheEntry = { url: artUrl, timestamp: Date.now() };
        if (releaseGroupId) {
          albumArtCache.current[releaseGroupId] = cacheEntry;
        }
        albumArtCache.current[releaseId] = cacheEntry;
        return artUrl;
      }

      return getAlbumArtFromResolvers(artist, album);
    } catch (error) {
      console.log(`Cover art not found for: ${artist} - ${album}`);
      albumToReleaseIdCache.current[lookupKey] = null;
      return getAlbumArtFromResolvers(artist, album);
    }
  };

  // Synchronous check for cached album art (doesn't fetch, just checks existing cache)
  // Checks multiple cache keys: direct IDs, then albumToReleaseIdCache by artist+album name
  // This is the canonical lookup function - use it everywhere for consistency
  const getCachedAlbumArt = (artist, album, releaseGroupId = null, releaseId = null) => {
    // First check direct IDs if provided (fastest path)
    if (releaseGroupId && albumArtCache.current[releaseGroupId]?.url) {
      return albumArtCache.current[releaseGroupId].url;
    }
    if (releaseId && albumArtCache.current[releaseId]?.url) {
      return albumArtCache.current[releaseId].url;
    }

    // Then check albumToReleaseIdCache by artist+album name
    if (artist && album) {
      const lookupKey = `${artist}-${album}`.toLowerCase();
      // Resolver / catalog hits are stored under prefixed keys (no MB id)
      const fallbackHit = albumArtCache.current[`resolver:${lookupKey}`]?.url
        || albumArtCache.current[`catalog:${lookupKey}`]?.url;
      if (fallbackHit) return fallbackHit;
      const cachedLookup = albumToReleaseIdCache.current[lookupKey];
      if (cachedLookup) {
        // Handle both old format (string) and new format ({ releaseId, releaseGroupId })
        if (typeof cachedLookup === 'object') {
          if (cachedLookup.releaseGroupId && albumArtCache.current[cachedLookup.releaseGroupId]?.url) {
            return albumArtCache.current[cachedLookup.releaseGroupId].url;
          }
          if (cachedLookup.releaseId && albumArtCache.current[cachedLookup.releaseId]?.url) {
            return albumArtCache.current[cachedLookup.releaseId].url;
          }
        } else if (typeof cachedLookup === 'string' && albumArtCache.current[cachedLookup]?.url) {
          return albumArtCache.current[cachedLookup].url;
        }
      }
    }

    return null;
  };

  // A cached cover that fails to load (Bandcamp image ids change when an
  // artist replaces the cover; archive.org mirror hosts move) is dropped from
  // the caches and looked up again, once per album per session. Cards reach it
  // through window.reportBrokenAlbumArt from their <img> onError
  // (src/renderer/lib/broken-art.js).
  const getAlbumArtLatestRef = useRef(null);
  getAlbumArtLatestRef.current = getAlbumArt;
  const brokenArtRetryRef = useRef(null);
  if (!brokenArtRetryRef.current) {
    brokenArtRetryRef.current = createBrokenArtRetry({
      getCache: () => albumArtCache.current,
      getSessionCache: () => resolverArtCache.current,
      refetch: (artist, album) => getAlbumArtLatestRef.current(artist, album),
    });
  }
  useEffect(() => {
    window.reportBrokenAlbumArt = brokenArtRetryRef.current.report;
    return () => { delete window.reportBrokenAlbumArt; };
  }, []);
  // The same retry for the inline grids that keep the cover on the item in
  // their own list state (Fresh Drops, Pop of the Tops, Critical Darlings):
  // patch the item when a fresh cover turns up.
  const retryBrokenListArt = (url, { artist, album, id, cacheId }, apply) => {
    brokenArtRetryRef.current.report(url, { artist, album, releaseId: cacheId }).then((fresh) => {
      if (fresh) apply(id, fresh);
    });
  };
  const patchListArt = (setList) => (id, fresh) => setList(prev => prev.map(a => (a.id === id ? { ...a, albumArt: fresh } : a)));

  // Fetch album art for current track if missing
  useEffect(() => {
    if (currentTrack && !currentTrack.albumArt && currentTrack.artist && currentTrack.album) {
      const artKey = trackArtKey(currentTrack);
      getAlbumArt(currentTrack.artist, currentTrack.album).catch(() => null).then(artUrl => {
        if (!artUrl) {
          setPlaybarArtMissKey(artKey);
        } else {
          setCurrentTrack(prev => {
            // Only update if still the same track and still missing art
            if (prev && prev.artist === currentTrack.artist && prev.title === currentTrack.title && !prev.albumArt) {
              return { ...prev, albumArt: artUrl };
            }
            return prev;
          });
        }
      });
    }
  }, [currentTrack?.artist, currentTrack?.album, currentTrack?.albumArt]);

  // Stream-quality backfill for the PLAYING track (stream-quality.js contract).
  // This effect is the local-library path (capabilities.local, Local Files
  // today): the file is on disk, so we parse it at
  // play time (via the localFiles:stream-info IPC — main process caches by
  // path+mtime, so replays are free) instead of persisting codec/bit-depth
  // columns in the scan DB. The Amazon Music path attaches its measured
  // bitrate in the amazonmusic onProgress handler instead (the data arrives
  // as poll events, not an IPC the renderer can call); every other resolver
  // just has no record and the title renders exactly as before.
  //
  // No "already attached" early-return: the playing-track clone is serialized
  // into the saved queue, so a restored session can carry a record from a
  // previous session — re-reading (a cached stat+map hit) and comparing keeps
  // the record self-healing when the file changed while we were closed.
  //
  // Keyed to the resolver ACTUALLY playing (track._activeResolver via
  // determineResolverIdFromTrack), not a preferred source: a Spotify-played
  // track with a localfiles source attached streams through Spotify. Before
  // the registry loads (a restored track), the bundled Local Files answers.
  const streamInfoResolverId = currentTrack ? determineResolverIdFromTrack(currentTrack) : null;
  useEffect(() => {
    if (!currentTrack || !window.electron?.localFiles?.getStreamInfo) return;
    const playingResolverId = streamInfoResolverId;
    if (!isLocalResolver(playingResolverId)) return;
    const filePath = currentTrack.sources?.[playingResolverId]?.filePath || currentTrack.filePath;
    if (!filePath) return;
    let cancelled = false;
    window.electron.localFiles.getStreamInfo(filePath).then(info => {
      if (cancelled || !info) return;
      const next = { ...info, origin: 'measured' };
      setCurrentTrack(prev => {
        // Only touch the same track; skip when the attached record is already
        // identical (deep-compare — the IPC caches object identity, but a
        // restored-from-queue record is a different object with the same data).
        if (!prev
          || prev.id !== currentTrack.id
          || (prev.artist !== currentTrack.artist || prev.title !== currentTrack.title)) return prev;
        const existing = prev.sources?.[playingResolverId]?.streamQuality;
        if (existing && JSON.stringify(existing) === JSON.stringify(next)) return prev;
        return {
          ...prev,
          sources: {
            ...(prev.sources || {}),
            [playingResolverId]: {
              ...(prev.sources?.[playingResolverId] || {}),
              streamQuality: next
            }
          }
        };
      });
    });
    return () => { cancelled = true; };
  }, [currentTrack?.id, currentTrack?.artist, currentTrack?.title, currentTrack?._activeResolver, streamInfoResolverId, currentTrack?.sources?.[streamInfoResolverId]?.streamQuality]);

  // Fetch artist bio for playbar tooltip when track changes
  useEffect(() => {
    if (!currentTrack?.artist) {
      setPlaybarArtistBio(null);
      return;
    }

    // Check if we already have the bio for this artist
    if (playbarArtistBio?.artistName === currentTrack.artist) {
      return;
    }

    // Clear old bio and fetch new one
    setPlaybarArtistBio(null);

    (async () => {
      try {
        let mbid = null;

        // Fast path: use MBID Mapper if we have a track title (~4ms vs ~500ms+ for MB search)
        if (currentTrack.title) {
          const mapperResult = await lookupMbidMapper(currentTrack.artist, currentTrack.title, currentTrack.album);
          if (mapperResult?.artist_credit_mbids?.length > 0) {
            mbid = mapperResult.artist_credit_mbids[0];
          }
        }

        // Fallback: MusicBrainz artist search if mapper didn't return an MBID
        if (!mbid) {
          // Background lane: the playbar tooltip is never what the user clicked for
          const searchResponse = await fetch(
            `https://musicbrainz.org/ws/2/artist?query=${encodeURIComponent(currentTrack.artist)}&fmt=json&limit=1`,
            { headers: { 'User-Agent': 'Parachord/1.0.0 (https://parachord.app)' }, mbBackground: true }
          );
          if (searchResponse.ok) {
            const searchData = await searchResponse.json();
            mbid = searchData.artists?.[0]?.id;
          }
        }

        // Fetch bio using the existing function
        const bioData = await fetchArtistBio(currentTrack.artist, mbid);
        if (bioData) {
          setPlaybarArtistBio({ ...bioData, artistName: currentTrack.artist });
        }
      } catch (error) {
        console.error('Error fetching playbar artist bio:', error);
      }
    })();
  }, [currentTrack?.artist]);

  // Detect face position in an image using browser's FaceDetector API
  const detectFacePosition = async (imageUrl) => {
    // Check if FaceDetector API is available (Chromium/Electron)
    if (!('FaceDetector' in window)) {
      console.log('FaceDetector API not available');
      return null;
    }

    try {
      // Load image into an HTMLImageElement
      const img = new Image();
      img.crossOrigin = 'anonymous';
      await new Promise((resolve, reject) => {
        img.onload = resolve;
        img.onerror = reject;
        img.src = imageUrl;
      });

      // Detect faces
      const detector = new FaceDetector();
      const faces = await detector.detect(img);

      if (faces.length === 0) {
        console.log('No faces detected in image');
        return null;
      }

      // Find largest face (by bounding box area) - likely the main artist
      const largest = faces.reduce((a, b) =>
        (a.boundingBox.width * a.boundingBox.height) >
        (b.boundingBox.width * b.boundingBox.height) ? a : b
      );

      // Calculate vertical center of face as percentage
      const faceCenter = largest.boundingBox.y + (largest.boundingBox.height / 2);
      const percentage = Math.round((faceCenter / img.height) * 100);

      console.log(`Face detected at ${percentage}% from top`);
      return `center ${percentage}%`;
    } catch (error) {
      console.error('Face detection failed:', error);
      return null;
    }
  };

  // Artist photos for every surface (Home suggestions, recommendations,
  // related artists, Search, top artists, friends, chat cards, the artist
  // page), with caching and face detection. The sources, first photo wins
  // (src/renderer/lib/artist-image-chain.js has the reasons):
  //   Spotify (signed in) → Apple Music (MusicKit configured) → the active
  //   resolvers that declare capabilities.artistImage, in priority order →
  //   Deezer's public artist search → Wikipedia via Wikidata (options.mbid)
  //   → Discogs (with the user's Discogs token).
  // It used to ask only Spotify and Apple Music, and returned nothing for a
  // user signed in to neither. A miss is remembered for a few hours when
  // every source answered; a thrown or timed-out source isn't cached.
  // Track in-flight requests to prevent duplicate concurrent fetches
  const artistImageFetchPromises = useRef({});
  const artistImageMissesRef = useRef(null);
  if (!artistImageMissesRef.current) artistImageMissesRef.current = createArtistImageMissCache();
  useEffect(() => { artistImageMissesRef.current.clear(); }, [spotifyToken]);

  // Deezer sends no CORS header for file:// origins (see catalogArtDeps).
  const deezerArtistImage = async (artistName) => {
    const url = `https://api.deezer.com/search/artist?q=${encodeURIComponent(artistName)}&limit=10`;
    const r = await window.electron?.proxyFetch?.(url, { headers: { Accept: 'application/json' } });
    if (!r || !r.success) throw new Error(`Deezer artist search failed${r?.status ? `: ${r.status}` : ''}`);
    return deezerArtistImageFromSearch(JSON.parse(r.text || 'null'), artistName);
  };

  const getArtistImage = async (artistName, { mbid = null } = {}) => {
    if (!artistName) return null;

    const normalizedName = artistName.trim().toLowerCase();
    const cached = artistImageCache.current[normalizedName];
    const now = Date.now();

    // Check cache validity - return both url and facePosition
    if (cached && (now - cached.timestamp) < CACHE_TTL.artistImage) {
      return { url: cached.url, facePosition: cached.facePosition };
    }
    if (artistImageMissesRef.current.has(artistName)) return null;

    // Check if there's already a fetch in progress for this artist
    if (artistImageFetchPromises.current[normalizedName]) {
      return artistImageFetchPromises.current[normalizedName];
    }

    const musicKitWeb = window.getMusicKitWeb ? window.getMusicKitWeb() : null;
    const musicKitAvailable = musicKitWeb?.isConfigured;

    // Read the token from the ref, not the render's state. ChatCard is created
    // once, on the first render, so its copy of this function sees that
    // render's token state, which is always null: every Shuffleupagus artist
    // card came back without a photo. The fallback covers the commit before
    // the ref-sync effect runs. The other inputs below are refs for the same
    // reason.
    const token = spotifyTokenRef.current || spotifyToken;
    const discogsToken = metaServiceConfigsRef.current?.discogs?.personalAccessToken;

    // Only a service whose plug-in is on is asked, the same rule as the
    // plug-in steps below. A saved sign-in outlives turning the plug-in off,
    // so a token alone sent every uncached artist photo to Spotify while the
    // user had switched it off (and kept tripping its rate-limit pause).
    // Nor one whose metadata is switched off ("Use metadata from X", #1505).
    const activeIds = (activeResolversRef.current || []).filter(id => !metadataOffRef.current.includes(id));

    const steps = [];
    if (token && activeIds.includes('spotify')) {
      steps.push({ id: 'spotify', run: async () => {
        const searchUrl = `https://api.spotify.com/v1/search?q=artist:"${encodeURIComponent(artistName)}"&type=artist&limit=5`;
        const response = await fetch(searchUrl, {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        if (!response.ok) throw new Error(`Spotify artist search failed: ${response.status}`);
        const data = await response.json();
        // Find the artist with exact name match only (case-insensitive)
        const artists = data.artists?.items || [];
        const artist = artists.find(a => a.name.toLowerCase() === artistName.toLowerCase());
        return artist?.images?.[0]?.url || null;
      } });
    }
    if (musicKitAvailable && activeIds.includes('applemusic')) {
      steps.push({ id: 'applemusic', run: async () => (await musicKitWeb.getArtistImage(artistName))?.url || null });
    }
    const loader = resolverLoaderRef.current;
    if (loader?.getArtistImageResolvers) {
      const ordered = orderCatalogResolvers(loader.getArtistImageResolvers(), {
        activeIds,
        order: resolverOrderRef.current || []
      }).filter(r => activeIds.includes(r.id));
      for (const resolver of ordered) {
        steps.push({ id: resolver.id, run: async () => loader.searchArtistImage(resolver.id, artistName, await getResolverConfig(resolver.id)) });
      }
    }
    steps.push({ id: 'deezer', run: () => deezerArtistImage(artistName) });
    if (mbid) steps.push({ id: 'wikipedia', run: () => getWikipediaArtistImage(mbid) });
    if (discogsToken) steps.push({ id: 'discogs', run: () => getDiscogsArtistImage(mbid, artistName) });

    // Create the fetch promise and store it
    const fetchPromise = (async () => {
      try {
        const { url: imageUrl, source, complete } = await firstArtistImage(steps, {
          log: (msg) => console.warn(`🖼️ Artist image for "${artistName}": ${msg}`)
        });

        if (imageUrl) {
          if (source !== 'spotify') console.log(`🖼️ Artist image for "${artistName}" from ${source}`);
          // Detect face position for smart cropping
          const facePosition = await detectFacePosition(imageUrl);

          artistImageCache.current[normalizedName] = {
            url: imageUrl,
            facePosition: facePosition, // may be null
            timestamp: now
          };

          return { url: imageUrl, facePosition };
        }

        if (complete) artistImageMissesRef.current.add(artistName);
        return null;
      } catch (error) {
        console.error('Failed to fetch artist image:', error);
        return null; // Don't cache failures
      } finally {
        // Clean up the in-flight promise
        delete artistImageFetchPromises.current[normalizedName];
      }
    })();

    artistImageFetchPromises.current[normalizedName] = fetchPromise;
    return fetchPromise;
  };

  // Fetch artist image and bio for search preview pane
  useEffect(() => {
    // Only fetch for artist previews when we have a preview item
    if (searchDetailCategory !== 'artists' || !searchPreviewItem) {
      setSearchPreviewArtistImage(null);
      setSearchPreviewArtistBio(null);
      return;
    }

    const artistName = searchPreviewItem.name;
    if (!artistName) return;

    // Fetch artist image from Spotify (uses existing cache)
    const fetchArtistImage = async () => {
      const result = await getArtistImage(artistName);
      if (result?.url) {
        setSearchPreviewArtistImage(result);
      } else {
        setSearchPreviewArtistImage(null);
      }
    };

    // The artist's bio, short (no loading state): the same bio as the artist
    // page and the playbar (fetchArtistBio, any plug-in with
    // capabilities.biography, #1539 step 6), its summary when the plug-in
    // wrote one, cut to about 200 characters. A MusicBrainz row's id is the
    // artist's MBID, which the Wikipedia plug-in needs.
    const fetchArtistBioSnippet = async () => {
      const candidate = searchPreviewItem.mbid || searchPreviewItem.id;
      try {
        const bio = await fetchArtistBio(artistName, isMbid(candidate) ? candidate : undefined);
        const text = (bio && (bio.summary || bioPlainText(bio)) || '').trim();
        setSearchPreviewArtistBio(text ? (text.length > 200 ? text.substring(0, 200).trim() + '…' : text) : null);
      } catch (error) {
        console.error('Failed to fetch artist bio snippet:', error);
        setSearchPreviewArtistBio(null);
      }
    };

    fetchArtistImage();
    fetchArtistBioSnippet();
  }, [searchDetailCategory, searchPreviewItem?.id]);

  // Recommendation item images (LLM album art / artist photos — provider items
  // that carry their own imageUrl skip this): queue one fetch per item that is
  // on the page with no image yet and no fetch in flight, and write results
  // through the coalesced recommendationImagesWriterRef (one full render per
  // batch, not per image). Lives below getAlbumArt/getArtistImage — those are
  // declared above at module scope of the component and referenced from the
  // effect body, so they must not appear in the deps array below (the TDZ
  // trap: the array is evaluated during render).
  const recommendationImageFetchesRef = useRef(new Set());
  useEffect(() => {
    // Home resolves the covers it shows itself (home-page.js).
    if (activeView !== 'recommendations') return;
    for (const item of flattenRecommendationItems(recommendations.sections)) {
      if (item.type !== 'artist' && item.type !== 'album') continue;
      if (item.imageUrl || recommendationImages[item.id] || recommendationImageFetchesRef.current.has(item.id)) continue;
      recommendationImageFetchesRef.current.add(item.id);
      const write = (url) => recommendationImagesWriterRef.current.queue(item.id, { url: url || null, loaded: true }, { merge: true });
      // Album art / artist photos are decoration: getAlbumArt and
      // getArtistImage run their MusicBrainz requests in the background
      // lane, never holding a foreground slot.
      if (item.type === 'album') {
        getAlbumArt(item.artist || '', item.name).then(write).catch(() => write(null));
      } else {
        getArtistImage(item.name).then(result => write(result?.url || null)).catch(() => write(null));
      }
    }
  }, [activeView, recommendations.sections, recommendationImages]);

  // Album release dates for the "Coming <date>" badge: no provider sends one,
  // so each album card's first release date is looked up on MusicBrainz
  // (lib/release-date.js), in the background lane behind every request the
  // user made, in page order (the cards on screen come first), once per album
  // a week. A failed lookup stores nothing and is tried on a later visit.
  const recommendationReleaseDateFetchesRef = useRef(new Set());
  // Look up the first release date of each { artist, title } not known (or
  // stale) yet. One store for every page that shows album dates
  // (Recommendations, Critical Darlings), keyed by the album.
  const queueReleaseDateLookups = (albums) => {
    const now = Date.now();
    for (const { artist, title } of albums) {
      if (!artist || !title) continue;
      const key = releaseDateKey(artist, title);
      const known = recommendationReleaseDatesRef.current[key];
      if (known && (now - known.at) < RELEASE_DATE_TTL_MS) continue;
      if (recommendationReleaseDateFetchesRef.current.has(key)) continue;
      recommendationReleaseDateFetchesRef.current.add(key);
      fetch(releaseGroupSearchUrl(artist, title), { mbBackground: true, queuedTimeoutMs: 15000 })
        .then(res => (res && res.ok ? res.json() : Promise.reject(new Error(`MusicBrainz ${res && res.status}`))))
        .then(data => {
          const date = pickReleaseGroupDate(data && data['release-groups'], { artist, title });
          recommendationReleaseDatesWriterRef.current.queue(key, { date, at: Date.now() });
        })
        .catch(() => { /* nothing stored: a later visit asks again */ })
        .finally(() => recommendationReleaseDateFetchesRef.current.delete(key));
    }
  };
  useEffect(() => {
    if (activeView !== 'recommendations') return;
    // The provider sent the date (Apple Music does): no lookup.
    queueReleaseDateLookups(flattenRecommendationItems(recommendations.sections)
      .filter(item => item.type === 'album' && !item.releaseDate)
      .map(item => ({ artist: item.artist, title: item.name })));
  }, [activeView, recommendations.sections]);
  // Critical Darlings' release dates (the feed's date is when the pick was
  // published, not when the album came out).
  useEffect(() => {
    if (activeView !== 'critics-picks') return;
    queueReleaseDateLookups(criticsPicks.map(album => ({ artist: album.artist, title: album.title })));
  }, [activeView, criticsPicks.length]);

  // Fetch artist image from Wikipedia/Wikidata (fallback when Spotify has no image)
  const getWikipediaArtistImage = async (artistMbid) => {
    if (!artistMbid || metaServiceConfigsRef.current?.wikipedia?.enabled === false) return null;

    try {
      // Step 1: the artist's Wikidata id (lookupWikidataId, lib/artist-bio.js)
      const wikidataId = await lookupWikidataId(artistMbid);

      if (!wikidataId) return null;

      // Step 2: Get Wikipedia article title
      const wdUrl = `https://www.wikidata.org/w/api.php?action=wbgetentities&ids=${wikidataId}&props=sitelinks&sitefilter=enwiki&format=json&origin=*`;
      const wdResponse = await fetch(wdUrl);

      if (!wdResponse.ok) return null;

      const wdData = await wdResponse.json();
      const wikiTitle = wdData.entities?.[wikidataId]?.sitelinks?.enwiki?.title;

      if (!wikiTitle) return null;

      // Step 3: Fetch Wikipedia page summary (includes thumbnail)
      const wpUrl = `https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(wikiTitle)}`;
      const wpResponse = await fetch(wpUrl);

      if (!wpResponse.ok) return null;

      const wpData = await wpResponse.json();

      if (wpData.thumbnail?.source) {
        console.log('📚 Wikipedia artist image found');
        return wpData.thumbnail.source;
      }

      return null;
    } catch (error) {
      console.error('📚 Failed to fetch Wikipedia artist image:', error);
      return null;
    }
  };

  // Fetch artist image from Discogs (fallback when Spotify and Wikipedia have no image)
  const getDiscogsArtistImage = async (artistMbid, artistName) => {
    if (!artistName || metaServiceConfigsRef.current?.discogs?.enabled === false) return null;

    try {
      // The ref first: getArtistImage calls this from stale closures.
      const discogsConfig = metaServiceConfigsRef.current?.discogs || metaServiceConfigs?.discogs || {};
      const token = discogsConfig.personalAccessToken;

      const headers = {
        'User-Agent': 'Parachord/1.0 (https://parachord.app)'
      };
      if (token) {
        headers['Authorization'] = `Discogs token=${token}`;
      }

      // Search for artist
      const searchUrl = `https://api.discogs.com/database/search?q=${encodeURIComponent(artistName)}&type=artist&per_page=5`;
      const searchResponse = await fetch(searchUrl, { headers });

      if (!searchResponse.ok) return null;

      const searchData = await searchResponse.json();

      if (!searchData.results?.length) return null;

      // Find best match
      let artistResult = searchData.results.find(r =>
        r.title?.toLowerCase() === artistName.toLowerCase()
      ) || searchData.results[0];

      // Fetch full artist profile for images
      const artistResponse = await fetch(artistResult.resource_url, { headers });

      if (!artistResponse.ok) return null;

      const artistData = await artistResponse.json();

      // Discogs images array - first is primary
      if (artistData.images?.length > 0) {
        // Prefer primary image, fall back to first
        const primaryImage = artistData.images.find(img => img.type === 'primary');
        const imageUrl = primaryImage?.uri || artistData.images[0].uri;
        console.log('📀 Discogs artist image found');
        return imageUrl;
      }

      return null;
    } catch (error) {
      console.error('📀 Failed to fetch Discogs artist image:', error);
      return null;
    }
  };

  // An artist's bio from every plug-in that writes one (capabilities.biography,
  // #1539 step 6), all asked at once, in the user's order (similarProvidersFor):
  // the first plug-in's bio is shown and every bio found is kept in `sources`
  // for the Biography tab's Source menu (lib/artist-bio.js). A plug-in that
  // fails is left out; none with a bio is null, which the cache never keeps.
  const fetchArtistBioUncached = async (artistName, artistMbid) => {
    const loader = resolverLoaderRef.current;
    const artist = artistMbid ? { name: artistName, mbid: artistMbid } : { name: artistName };
    const { answers, failed } = await askEach(similarProvidersFor('biography'), async (p) => {
      const bio = await loader.getArtistBio(p.id, artist, await configForSimilar(p.id));
      return bio ? [bio] : [];
    });
    const bio = bioWithSources(answers);
    console.log(bio
      ? `🎤 Bio for "${artistName}" from ${bio.source} (${countOf(bio.sources.length, 'source')})`
      : `🎤 No biography for "${artistName}"${failed ? ': no plug-in answered' : ''}`);
    return bio;
  };

  // Shared by the playbar and the artist page; a bio found by one is reused
  // by the other. Touches no loading state. The bio shown is the user's last
  // pick when it has one for this artist, else a preferred plug-in's
  // (Wikipedia's manifest), else the first in the user's order (bioPreference).
  const fetchArtistBio = async (artistName, artistMbid) => {
    const bio = await artistBioCache.load(artistName, artistMbid, fetchArtistBioUncached);
    const resolvers = resolverLoaderRef.current?.getBiographyResolvers?.() || [];
    return preferredBio(bio, bioPreference(artistBioPickRef.current, resolvers));
  };

  // The Biography tab's Source picker: show that plug-in's bio, and remember
  // it (artist_bio_source) so it is shown first for every artist that has one.
  const pickArtistBioSource = (sourceId) => {
    if (!sourceId) return;
    artistBioPickRef.current = sourceId;
    window.electron?.store?.set('artist_bio_source', sourceId)
      ?.catch?.(err => console.error('[Bio] Could not save the bio source:', err));
    setArtistBio(prev => (prev && typeof prev === 'object' ? bioFromSource(prev, sourceId) : prev));
  };

  // The artist page's fetch: drives its Biography tab skeleton. The playbar
  // calls fetchArtistBio instead, so its fetch can't leave the tab's
  // loadingBio set (the tab skips fetching while it is) and blank.
  const getArtistBio = async (artistName, artistMbid) => {
    if (!artistName) return null;
    setLoadingBio(true);
    try {
      return await fetchArtistBio(artistName, artistMbid);
    } finally {
      setLoadingBio(false);
    }
  };

  // Fetch extended artist info from MusicBrainz (founded date, location, URLs, members)
  const fetchArtistExtendedInfo = async (artistMbid) => {
    if (!artistMbid) {
      console.log('🎵 Extended info skipped: no MBID');
      return null;
    }

    // Check cache first
    const cached = artistExtendedInfoCache.current[artistMbid];
    if (cached && (Date.now() - cached.timestamp) < CACHE_TTL.artistExtendedInfo) {
      console.log('📦 Using cached extended info for:', artistMbid);
      return cached.info;
    }

    setLoadingExtendedInfo(true);
    try {
      // Query MusicBrainz for artist with URL relations and artist relations (members)
      const mbUrl = `https://musicbrainz.org/ws/2/artist/${artistMbid}?inc=url-rels+artist-rels&fmt=json`;
      const response = await fetch(mbUrl, {
        headers: { 'User-Agent': 'Parachord/1.0 (https://parachord.app)' }
      });

      if (!response.ok) {
        console.log('🎵 MusicBrainz extended info fetch failed:', response.status);
        return null;
      }

      const data = await response.json();
      console.log('🎵 MusicBrainz extended info:', data);

      // Extract founded date and location
      const foundedDate = data['life-span']?.begin || null;
      const endedDate = data['life-span']?.end || null;
      const isActive = !data['life-span']?.ended;
      const foundedIn = data.area?.name || data['begin-area']?.name || null;

      // Extract URLs from relations
      const urls = {
        officialHomepage: null,
        wikipedia: null,
        twitter: null,
        instagram: null,
        facebook: null,
        youtube: null,
        bandcamp: null,
        soundcloud: null,
        spotify: null,
        appleMusic: null,
        discogs: null,
        allmusic: null
      };

      if (data.relations) {
        for (const rel of data.relations) {
          if (rel.type === 'official homepage' && rel.url?.resource) {
            urls.officialHomepage = rel.url.resource;
          } else if (rel.type === 'wikipedia' && rel.url?.resource) {
            urls.wikipedia = rel.url.resource;
          } else if (rel.type === 'social network' && rel.url?.resource) {
            const url = rel.url.resource.toLowerCase();
            if (url.includes('twitter.com') || url.includes('x.com')) {
              urls.twitter = rel.url.resource;
            } else if (url.includes('instagram.com')) {
              urls.instagram = rel.url.resource;
            } else if (url.includes('facebook.com')) {
              urls.facebook = rel.url.resource;
            }
          } else if (rel.type === 'youtube' && rel.url?.resource) {
            urls.youtube = rel.url.resource;
          } else if (rel.type === 'bandcamp' && rel.url?.resource) {
            urls.bandcamp = rel.url.resource;
          } else if (rel.type === 'soundcloud' && rel.url?.resource) {
            urls.soundcloud = rel.url.resource;
          } else if (rel.type === 'streaming' && rel.url?.resource) {
            const url = rel.url.resource.toLowerCase();
            if (url.includes('spotify.com')) {
              urls.spotify = rel.url.resource;
            } else if (url.includes('music.apple.com') || url.includes('itunes.apple.com')) {
              urls.appleMusic = rel.url.resource;
            }
          } else if (rel.type === 'discogs' && rel.url?.resource) {
            urls.discogs = rel.url.resource;
          } else if (rel.type === 'allmusic' && rel.url?.resource) {
            urls.allmusic = rel.url.resource;
          }
        }
      }

      // Extract members from artist relations
      const members = {
        current: [],
        former: []
      };

      if (data.relations) {
        for (const rel of data.relations) {
          // "member of band" relation means rel.artist is the band, current artist is the member
          // "has member" relation (type-id) means current artist is band, rel.artist is member
          if (rel.type === 'member of band' && rel.direction === 'backward' && rel.artist) {
            const member = {
              name: rel.artist.name,
              mbid: rel.artist.id,
              attributes: rel.attributes || [], // e.g., ["guitar", "vocals"]
              beginDate: rel.begin || null,
              endDate: rel.end || null
            };

            // If the relation has ended, it's a former member
            if (rel.ended) {
              members.former.push(member);
            } else {
              members.current.push(member);
            }
          }
        }
      }

      // Sort members by start date (oldest first)
      members.current.sort((a, b) => (a.beginDate || '').localeCompare(b.beginDate || ''));
      members.former.sort((a, b) => (a.beginDate || '').localeCompare(b.beginDate || ''));

      const info = {
        foundedDate,
        endedDate,
        isActive,
        foundedIn,
        type: data.type, // Person, Group, Orchestra, etc.
        gender: data.gender, // For solo artists
        urls,
        members
      };

      // Cache the result
      artistExtendedInfoCache.current[artistMbid] = {
        info,
        timestamp: Date.now()
      };

      console.log('🎵 Extended info parsed:', info);
      return info;
    } catch (error) {
      console.error('🎵 Failed to fetch extended info:', error);
      return null;
    } finally {
      setLoadingExtendedInfo(false);
    }
  };

  // Fetch top tracks for an artist from Last.fm API
  // An artist card's Play (components/artist-card.js): their top 10, with
  // the rest queued after the first, in the artist's context.
  // Track rows (components/track-lists.js TrackRow): what every page list
  // does with one. Play queues what follows the row in its list under the
  // list's context, then plays it (from one source when its icon was picked).
  const playTrackRow = (track, tracksAfter, context, resolverId) => {
    setQueueWithContext(tracksAfter, context);
    handlePlay(resolverId ? { ...track, preferredResolver: resolverId } : track);
  };
  // A row dragged onto a playlist in the sidebar or the queue.
  const trackRowDrag = (track, payload) => ({
    draggable: true,
    onDragStart: (e) => {
      setDraggingTrackForPlaylist(track);
      e.dataTransfer.effectAllowed = 'copy';
      e.dataTransfer.setData('text/plain', JSON.stringify({ type: 'track', track: payload || track }));
    },
    onDragEnd: () => handlePlaylistDragEnd()
  });
  // A row's ref, registered with its page's visibility observer (which
  // resolves the rows on screen).
  const observedRowRef = (rowRefs, observerRef, id) => (el) => {
    if (!id || !rowRefs.current) return;
    if (el) {
      rowRefs.current.set(id, el);
      if (observerRef.current) observerRef.current.observe(el);
    } else {
      rowRefs.current.delete(id);
    }
  };

  // A saved playlist card's overlay actions and drag (components/
  // playlist-card.js), the Playlists page's and Search's: play it from the
  // top, queue it, or add its tracks to another playlist.
  const playlistTracksWithIds = (playlist) => (playlist.tracks || []).map(track => ({
    ...track,
    id: trackSlug(track.artist || 'unknown', track.title || 'untitled'),
    sources: {}
  }));
  const playlistCardActions = (playlist) => ({
    onPlay: () => {
      const tracks = playlistTracksWithIds(playlist);
      if (tracks.length === 0) return;
      setTrackLoading(true);
      const context = { type: 'playlist', id: playlist.id, name: playlist.title };
      const [first, ...rest] = tracks;
      // The first track carries the context so queue navigation works.
      setQueueWithContext(rest, context, true);
      handlePlay({ ...first, _playbackContext: context });
    },
    onQueue: () => {
      const tracks = playlistTracksWithIds(playlist);
      if (tracks.length > 0) addToQueue(tracks, { type: 'playlist', id: playlist.id, name: playlist.title });
    },
    onAddToPlaylist: () => {
      const tracks = playlistTracksWithIds(playlist);
      if (tracks.length > 0) setAddToPlaylistPanel({ open: true, tracks, sourceName: playlist.title, sourceType: 'playlist' });
    }
  });
  const playlistCardDrag = (playlist) => () => ({
    type: 'playlist',
    playlist: {
      id: playlist.id,
      title: playlist.title,
      creator: playlist.creator,
      tracks: (playlist.tracks || []).map(track => ({ ...track, id: trackSlug(track.artist || 'unknown', track.title || 'untitled', track.album || 'noalbum'), sources: {} }))
    }
  });

  // An album card's overlay actions (components/album-card.js): get the
  // album's tracks (each grid says how), then play, queue or add them.
  const albumCardActions = ({ title, artist, id, getTracks, context }) => {
    const ctx = context || Object.assign({ type: 'album', name: title, artist }, id ? { id } : null);
    const load = async () => {
      const tracks = await getTracks();
      if (!tracks || tracks.length === 0) { showToast('Couldn’t load this album’s tracks. Try again.', 'error'); return null; }
      return tracks;
    };
    return {
      // The playbar shows loading while the tracks are fetched.
      onPlay: async () => {
        setTrackLoading(true);
        const t = await load();
        if (t) playTrackCollection(t, ctx); else setTrackLoading(false);
      },
      onQueue: async () => { const t = await load(); if (t) addToQueue(t, ctx); },
      onAddToPlaylist: async () => {
        const t = await load();
        if (t) setAddToPlaylistPanel({ open: true, tracks: t, sourceName: `${title} by ${artist}`, sourceType: 'album' });
      },
    };
  };

  // A plugin's colour (its manifest's color), any kind of plugin: playback,
  // metadata (Last.fm, ListenBrainz) or other. Null when unknown.
  const getServiceColor = (id) => {
    const r = (resolverLoaderRef.current?.getAllResolvers?.() || []).find(x => x.id === id);
    return r && r.color && r.color !== NO_PLUGIN_COLOR ? r.color : null;
  };
  // Ticket sellers take their plug-in's colour too (lib/ticket-sellers.js
  // asks this; it reads the loader at call time, so once is enough).
  useEffect(() => { setSellerColorLookup(getServiceColor); }, []);

  const playArtistTopTracks = async (artist) => {
    const name = typeof artist === 'string' ? artist : artist?.name;
    if (!name) return;
    setTrackLoading(true);
    const { tracks, failed } = await findArtistTopTracks(artist);
    if (tracks.length > 0) {
      const context = { type: 'artist', name };
      const [firstTrack, ...remainingTracks] = tracks;
      setQueueWithContext(remainingTracks, context, true);
      handlePlay({ ...firstTrack, _playbackContext: context });
    } else {
      setTrackLoading(false);
      showToast(failed ? `Couldn’t load ${name}’s top tracks. Try again.` : `No top tracks found for ${name}`, 'error');
    }
  };

  // An artist's top tracks from every plug-in that lists them
  // (capabilities.artistTopTracks, #1539 step 2): the first non-empty list in
  // the user's order, never a merge, since each is ranked by its own
  // service's plays. `artist` is a name or { name, mbid }; without an MBID the
  // MBID mapper's cache may know it (ListenBrainz asks by MBID).
  // Resolves to { tracks, source, failed }: `failed` when no plug-in answered.
  const findArtistTopTracks = async (artist, limit = 10) => {
    const name = typeof artist === 'string' ? artist : artist?.name;
    if (!name) return { tracks: [], source: null, failed: false };
    const mbid = (typeof artist === 'object' && artist?.mbid) || getArtistMbidFromMapperCache(name) || undefined;
    const loader = resolverLoaderRef.current;
    try {
      const { answers, failed } = await askEach(similarProvidersFor('artistTopTracks'),
        async (p) => loader.getArtistTopTracks(p.id, { name, mbid, limit }, await configForSimilar(p.id)));
      const first = firstAnswer(answers);
      if (!first) {
        console.log(`🎤 No top tracks for "${name}"${failed ? ': no plug-in answered' : ''}`);
        return { tracks: [], source: null, failed };
      }
      const slug = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
      const tracks = first.items.slice(0, limit).map((t, index) => ({
        id: `${first.id}-${slug(name)}-${slug(t.title)}-${index}`,
        title: t.title,
        artist: t.artist || name,
        album: t.album || '',
        duration: Number(t.duration) > 0 ? Number(t.duration) : 0, // ms
        playCount: Number(t.listens) || 0,
        position: index + 1,
        ...(t.mbid ? { mbid: t.mbid } : {}),
        sources: {} // Empty sources triggers on-demand resolution in handlePlay
      }));
      console.log(`🎤 ${tracks.length} top tracks for "${name}" from ${first.id}`);
      return { tracks, source: first.id, failed: false };
    } catch (error) {
      console.error('Failed to fetch artist top tracks:', error?.message || error);
      return { tracks: [], source: null, failed: true };
    }
  };

  // Just the tracks ([] when none or none could be had), for callers that
  // don't tell the two apart: Spinoff's top-up and an artist-only radio seed.
  const getArtistTopTracks = async (artist, limit = 10) => (await findArtistTopTracks(artist, limit)).tracks;

  // Check if similar tracks are available for spinoff (lightweight check)
  // The Spinoff button is enabled when a plug-in has any similar track, or
  // failing that any similar artist: spinoff tops the pool up from those
  // (#1281, #1539).
  const checkSpinoffAvailability = async (artistName, trackName) => {
    try {
      const available = await checkSpinoffAvailable({
        similarTracks: findSimilarTracks,
        similarArtists: findSimilarArtists,
        artist: artistName,
        title: trackName
      });
      console.log(`🔀 Spinoff availability for "${trackName}": ${available}`);
      return available;
    } catch (error) {
      console.error('Failed to check spinoff availability:', error);
      return false;
    }
  };

  // Refill spinoff pool from refillUrl (used by parachord://play-radio).
  // Fire-and-forget: callers should not await; this is rate-limited and self-stops after 3 empties.
  const keyForSpinoffDedup = (t) => {
    if (t.mbid) return `mbid:${t.mbid}`;
    if (t.isrc) return `isrc:${t.isrc}`;
    return `at:${(t.artist || '').toLowerCase()}|${(t.title || '').toLowerCase()}`;
  };


  // Activate spinoff from a pre-resolved track pool (parachord://play-radio path).

  // Start spinoff mode - play similar tracks based on current track,
  // OR play from a pre-resolved pool when called with { pool, displayName, refillUrl }.
  // Turn an artist-only seed into an artist+title seed (parachord#1005).
  // Similar tracks need a track, so `parachord://play/radio?artist=X`
  // used to clear the queue and then bail in startSpinoff with "missing track
  // info". Picks the artist's top track (findArtistTopTracks: any plug-in
  // with artistTopTracks, #1539). Returns { artist, title } or
  // null (after a toast) so callers can refuse before touching the queue.


  // Exit spinoff mode - return to normal queue playback

  // Similar artists and tracks come from every plug-in that can name them
  // (capabilities.similarArtists / similarTracks, lib/similar-music.js,
  // #1539): Related Artists and Spinoff ask them all in the user's order and
  // merge the answers, so one service failing never empties either.
  // Switched off (its Enable switch), or its "Use metadata from" switch is
  // off (#1505): similar music, top tracks, discographies and charts are
  // metadata.
  const pluginSwitchedOff = (id) => (metaServiceConfigsRef.current?.[id] || {}).enabled === false
    || (metadataOffRef.current || []).includes(id);
  const similarProvidersFor = (capability) => similarProviders(resolverLoaderRef.current, capability, {
    activeIds: activeResolversRef.current || [],
    order: resolverOrderRef.current || [],
    metaIds: (metaServicesRef.current || []).map(s => s.id),
    isOff: pluginSwitchedOff
  });
  // Your listening history (#1539 step 4): the plug-ins with
  // capabilities.listeningHistory that you've signed in to (a username in
  // their settings), in your order; and the one the History page's top lists
  // show (the pick, else the first).
  const historySourcesFor = () => signedInSources(similarProvidersFor('listeningHistory'), metaServiceConfigsRef.current || {});
  const historyTopSource = () => {
    const sources = historySourcesFor();
    return sources.find(r => r.id === historySourceRef.current) || sources[0] || null;
  };
  // Every plug-in that could keep it, for "Add your … username" when none is
  // set up.
  const historyNotConnected = () => {
    const names = similarProvidersFor('listeningHistory').map(r => pluginName(r.id));
    const list = names.length > 1 ? `${names.slice(0, -1).join(', ')} or ${names[names.length - 1]}` : (names[0] || 'a listening history plug-in');
    return `No listening history service connected. Add your ${list} username in Settings › Plug-Ins.`;
  };
  const askTopItems = async (id, query) => resolverLoaderRef.current.getTopItems(id, query, await configForSimilar(id));
  const askRecentListens = async (id, query) => resolverLoaderRef.current.getRecentListens(id, query, await configForSimilar(id));

  // A config whose key isn't ready yet (Last.fm before main's built-in pair
  // arrives) is a failure for this ask, never a keyless empty answer.
  const configForSimilar = async (id) => {
    const config = await getResolverConfig(id);
    if (config?.credentialsPending) throw new Error('credentials not ready');
    return config;
  };
  // { artists: [{ name, mbid?, url?, match, sources }], failed }
  const findSimilarArtists = async ({ name, mbid, limit = 20 }) => {
    const loader = resolverLoaderRef.current;
    const { answers, failed } = await askEach(similarProvidersFor('similarArtists'),
      async (p) => loader.getSimilarArtists(p.id, { name, mbid, limit }, await configForSimilar(p.id)));
    return { artists: mergeSimilarArtists(answers), failed };
  };
  // { tracks: [{ artist, title, mbid?, match, sources }], failed }
  const findSimilarTracks = async ({ artist, title, mbid, limit = 20 }) => {
    const loader = resolverLoaderRef.current;
    const { answers, failed } = await askEach(similarProvidersFor('similarTracks'),
      async (p) => loader.getSimilarTracks(p.id, { artist, title, mbid, limit }, await configForSimilar(p.id)));
    return { tracks: mergeSimilarTracks(answers), failed };
  };

  // Related Artists: every similar-artists plug-in's answer, merged by name
  // (each entry's `sources` names the plug-ins that listed it, for the tab's
  // filter chips). [] when none is found or no plug-in answered.
  const getRelatedArtists = async (artistName, artistMbid) => {
    if (!artistName) return [];

    setLoadingRelated(true);
    try {
      const { artists, failed } = await findSimilarArtists({ name: artistName, mbid: artistMbid });
      if (failed) console.warn(`🎸 No similar-artists plug-in answered for "${artistName}"`);
      console.log(`🎸 ${artists.length} related artists for "${artistName}" from ${sourcesIn(artists).join(', ') || 'no plug-in'}`);
      return artists.map(a => ({ ...a, imageLoaded: false }));
    } catch (error) {
      console.error('Failed to fetch related artists:', error);
      return [];
    } finally {
      setLoadingRelated(false);
    }
  };

  // Fetch images for related artists
  const resolveRelatedArtistImages = async (artists) => {
    console.log(`🎸 Fetching images for ${artists.length} related artists...`);

    for (const artist of artists) {
      try {
        const result = await getArtistImage(artist.name);
        // Update with image URL and mark as loaded
        setRelatedArtists(prev => prev.map(a =>
          a.name === artist.name ? { ...a, image: result?.url || null, imageLoaded: true } : a
        ));
      } catch (err) {
        console.error(`Error fetching image for ${artist.name}:`, err);
        // Mark as loaded even on error so we show the fallback icon
        setRelatedArtists(prev => prev.map(a =>
          a.name === artist.name ? { ...a, imageLoaded: true } : a
        ));
      }
    }
    console.log(`🎸 Finished fetching related artist images`);
  };

  // Get 4 unique covers for a playlist's 2x2 grid display
  // Prioritizes album art, falls back to artist images (from cache or Spotify)
  // Returns array of up to 4 image URLs, using cache when available
  const getPlaylistCovers = async (playlistId, tracks) => {
    // Check cache first - only use cache if we have all 4 covers
    const cached = playlistCoverCache.current[playlistId];
    if (cached && cached.covers.length >= 4 && Date.now() - cached.timestamp < CACHE_TTL.playlistCover) {
      return cached.covers;
    }
    // If cache has fewer than 4 covers, always try to get more - artist images may be
    // available from artistImageCache even if Spotify isn't currently connected

    // Up to four covers from the tracks (lib/playlist-cover-picks.js).
    const covers = await pickPlaylistCovers(tracks, { getAlbumArt, getArtistImage });

    // Cache the result
    if (covers.length > 0) {
      playlistCoverCache.current[playlistId] = {
        covers,
        timestamp: Date.now()
      };
    }

    return covers;
  };

  // Fetch and update covers for a single playlist (used after import)
  const fetchPlaylistCovers = async (playlistId, tracks) => {
    if (!tracks || tracks.length === 0) return;

    const covers = await getPlaylistCovers(playlistId, tracks);
    if (covers.length > 0) {
      setAllPlaylistCovers(prev => ({
        ...prev,
        [playlistId]: covers
      }));
    }
  };

  // State for current playlist's cover art grid
  const [playlistCoverArt, setPlaylistCoverArt] = useState([]);

  const loadPlaylist = async (playlistOrId, { skipNavigation = false } = {}) => {
    // Accept either a playlist object or an ID for backwards compatibility
    let playlist;
    if (typeof playlistOrId === 'string') {
      console.log('🖱️ Playlist clicked, ID:', playlistOrId);
      playlist = playlists.find(p => p.id === playlistOrId);
      if (!playlist) {
        console.error('❌ Playlist not found:', playlistOrId);
        return;
      }
    } else {
      playlist = playlistOrId;
      console.log('🖱️ Playlist clicked, ID:', playlist.id);
    }

    // Skip if already viewing this playlist (avoid unnecessary reloads)
    if (activeView === 'playlist-view' && selectedPlaylist?.id === playlist.id) {
      console.log('📋 Already viewing playlist:', playlist.title);
      return;
    }

    console.log('📋 Found playlist:', playlist.title);

    setSelectedPlaylist(playlist);
    setPlaylistCoverArt([]); // Reset cover art
    if (!skipNavigation) {
      navigateTo('playlist-view');
    }
    console.log(`📋 Loading playlist: ${playlist.title}`);

    // Parse XSPF if we have the content
    if (playlist.xspf) {
      const parsed = parseXSPF(playlist.xspf);
      if (parsed) {
        console.log(`🎵 Parsed ${parsed.tracks.length} tracks from XSPF`);

        // Step 1: Immediately display all tracks with metadata (no sources yet)
        const tracksWithIds = parsed.tracks.map(track => {
          const trackId = trackSlug(track.artist || 'unknown', track.title || 'untitled', track.album || 'noalbum');
          return { ...track, id: trackId, sources: {} };
        });
        setPlaylistTracks(tracksWithIds);
        if (tracksWithIds.length === 0) setEmptyPlaylistId(playlist.id);

        // Step 1.5: Fetch playlist cover art (4 unique album covers for 2x2 grid)
        getPlaylistCovers(playlist.id, tracksWithIds).then(covers => {
          setPlaylistCoverArt(covers);
        });

        // Step 1.6: Fetch album art for tracks that don't have it (background, non-blocking)
        tracksWithIds.forEach(async (track) => {
          if (!track.albumArt && track.album) {
            const artUrl = await getAlbumArt(track.artist, track.album);
            if (artUrl) {
              setPlaylistTracks(prevTracks =>
                prevTracks.map(t =>
                  t.id === track.id && !t.albumArt
                    ? { ...t, albumArt: artUrl }
                    : t
                )
              );
            }
          }
        });

        // Resolution handled by scheduler via IntersectionObserver
        console.log(`✅ Loaded ${tracksWithIds.length} tracks (resolution via scheduler)`);

        // Background-enrich playlist tracks with MBIDs
        enrichTracksWithMbids(tracksWithIds);
      }
    } else if (playlist.isEphemeral && typeof playlist.fetchTracks === 'function' && (!playlist.tracks || playlist.tracks.length === 0)) {
      // An ephemeral playlist whose tracks are still being looked up (a
      // recommended provider playlist): the view is already open on its
      // skeleton rows; fill them when the lookup lands, unless the user has
      // moved on to another playlist. A failed lookup says so and goes back.
      setPlaylistTracks([]);
      const playlistId = playlist.id;
      let tracks;
      try {
        tracks = await playlist.fetchTracks();
      } catch (error) {
        // Only while this playlist is still on screen, and through the
        // latest navigateBack (this closure's is from before the view opened).
        if (selectedPlaylistRef.current?.id === playlistId && activeViewNowRef.current === 'playlist-view') {
          showToast(error?.message || `Could not load ${playlist.title}`, 'error');
          navigateBackRef.current?.();
        }
        return;
      }
      if (selectedPlaylistRef.current?.id !== playlistId) return;
      const tracksWithIds = (tracks || []).map(track => {
        const trackId = track.id || trackSlug(track.artist || 'unknown', track.title || 'untitled', track.album || 'noalbum');
        return { ...track, id: trackId, sources: track.sources || {} };
      });
      setPlaylistTracks(tracksWithIds);
      setSelectedPlaylist(prev => (prev && prev.id === playlistId
        ? { ...prev, tracks: tracksWithIds, tracksLoaded: true, trackCount: tracksWithIds.length }
        : prev));
      getPlaylistCovers(playlistId, tracksWithIds).then(covers => {
        if (selectedPlaylistRef.current?.id === playlistId) setPlaylistCoverArt(covers);
      });
      enrichTracksWithMbids(tracksWithIds);
    } else if (playlist.isEphemeral && playlist.listenbrainzId && (!playlist.tracks || playlist.tracks.length === 0)) {
      // Handle ephemeral ListenBrainz playlists - load tracks from API
      console.log(`🎵 Loading ephemeral playlist tracks from ListenBrainz: ${playlist.listenbrainzId}`);

      const tracks = await loadWeeklyJamTracks(playlist.listenbrainzId);
      if (tracks.length > 0) {
        // Add IDs and sources to tracks
        const tracksWithIds = tracks.map(track => {
          const trackId = track.id || trackSlug(track.artist || 'unknown', track.title || 'untitled', track.album || 'noalbum');
          return { ...track, id: trackId, sources: track.sources || {} };
        });
        setPlaylistTracks(tracksWithIds);

        // Update the selected playlist with loaded tracks
        setSelectedPlaylist(prev => ({ ...prev, tracks: tracksWithIds, tracksLoaded: true }));

        // Fetch playlist cover art
        getPlaylistCovers(playlist.id, tracksWithIds).then(covers => {
          setPlaylistCoverArt(covers);
        });

        // Fetch album art for tracks that don't have it
        tracksWithIds.forEach(async (track) => {
          if (!track.albumArt && track.album) {
            const artUrl = await getAlbumArt(track.artist, track.album);
            if (artUrl) {
              setPlaylistTracks(prevTracks =>
                prevTracks.map(t =>
                  t.id === track.id && !t.albumArt
                    ? { ...t, albumArt: artUrl }
                    : t
                )
              );
            }
          }
        });

        console.log(`✅ Loaded ${tracksWithIds.length} tracks from ListenBrainz`);

        // Background-enrich ListenBrainz playlist tracks with MBIDs
        enrichTracksWithMbids(tracksWithIds);
      } else {
        console.log('⚠️ No tracks found in ListenBrainz playlist');
        setPlaylistTracks([]);
        setEmptyPlaylistId(playlist.id);
      }
    } else if (playlist.tracks && playlist.tracks.length > 0) {
      // Handle playlists with tracks array directly (e.g., newly created playlists)
      console.log(`🎵 Loading ${playlist.tracks.length} tracks from playlist object`);

      // Add IDs and sources to tracks if not present
      const tracksWithIds = playlist.tracks.map(track => {
        const trackId = track.id || trackSlug(track.artist || 'unknown', track.title || 'untitled', track.album || 'noalbum');
        return { ...track, id: trackId, sources: track.sources || {} };
      });
      setPlaylistTracks(tracksWithIds);

      // Fetch playlist cover art
      getPlaylistCovers(playlist.id, tracksWithIds).then(covers => {
        setPlaylistCoverArt(covers);
      });

      // Fetch album art for tracks that don't have it
      tracksWithIds.forEach(async (track) => {
        if (!track.albumArt && track.album) {
          const artUrl = await getAlbumArt(track.artist, track.album);
          if (artUrl) {
            setPlaylistTracks(prevTracks =>
              prevTracks.map(t =>
                t.id === track.id && !t.albumArt
                  ? { ...t, albumArt: artUrl }
                  : t
              )
            );
          }
        }
      });

      // Resolution handled by scheduler via IntersectionObserver
      console.log(`✅ Loaded ${tracksWithIds.length} tracks (resolution via scheduler)`);

      // Background-enrich playlist tracks with MBIDs
      enrichTracksWithMbids(tracksWithIds);
    } else {
      // No tracks to display
      console.log('⚠️ Playlist has no tracks');
      setPlaylistTracks([]);
      setEmptyPlaylistId(playlist.id);
    }
  };
  loadPlaylistRef.current = loadPlaylist;

  // Keep queue in sync with playlistTracks as they get resolved
  // This ensures queue items get their sources updated without re-setting the entire queue
  useEffect(() => {
    if (currentQueue.length === 0 || playlistTracks.length === 0) return;

    // Check if queue tracks match playlist tracks (by id)
    const queueIds = new Set(currentQueue.map(t => t.id));
    const playlistIds = new Set(playlistTracks.map(t => t.id));

    // Only sync if the queue was created from this playlist
    const isQueueFromPlaylist = currentQueue.every(t => playlistIds.has(t.id));
    if (!isQueueFromPlaylist) return;

    // Update queue items with resolved sources and duration from playlistTracks
    setCurrentQueue(prevQueue =>
      prevQueue.map(queueTrack => {
        const playlistTrack = playlistTracks.find(t => t.id === queueTrack.id);
        if (playlistTrack) {
          const hasMoreSources = Object.keys(playlistTrack.sources || {}).length > Object.keys(queueTrack.sources || {}).length;
          const hasDuration = playlistTrack.duration && !queueTrack.duration;

          if (hasMoreSources || hasDuration) {
            // Update queue track with new sources and/or duration
            return {
              ...queueTrack,
              sources: { ...queueTrack.sources, ...playlistTrack.sources },
              duration: queueTrack.duration || playlistTrack.duration || 0
            };
          }
        }
        return queueTrack;
      })
    );
  }, [playlistTracks]);

  // Sync queue tracks with trackSources updates (for release/album tracks)
  // This ensures queue items get their sources updated when resolution completes
  useEffect(() => {
    if (currentQueue.length === 0 || Object.keys(trackSources).length === 0) return;

    // Check if any queue tracks need source updates from trackSources
    // trackSources uses track.id as the key
    let hasUpdates = false;
    const updatedQueue = currentQueue.map(queueTrack => {
      // Try to find matching sources in trackSources using track.id
      if (queueTrack.id) {
        const resolvedSources = trackSources[queueTrack.id];

        if (resolvedSources && Object.keys(resolvedSources).length > Object.keys(queueTrack.sources || {}).length) {
          hasUpdates = true;
          return { ...queueTrack, sources: { ...queueTrack.sources, ...resolvedSources } };
        }
      }
      return queueTrack;
    });

    if (hasUpdates) {
      setCurrentQueue(updatedQueue);
    }
  }, [trackSources]);

  // Queue track resolution is now handled by ResolutionScheduler via queue context visibility
  // The scheduler monitors queue tracks and resolves them based on priority

  // Navigation helpers
  // Go to Search and put the cursor in its box (the Find menu item). A ref,
  // because the menu listener is registered once and would otherwise see
  // the first render's page.
  const openSearchRef = useRef(null);
  openSearchRef.current = () => {
    if (activeView !== 'search') navigateTo('search');
    // The box mounts with the page; focus it once it has painted.
    requestAnimationFrame(() => requestAnimationFrame(() => searchInputRef.current?.focus()));
  };

  const navigateTo = (view) => {
    if (view === 'home') {
      setHomeVisitCount(c => c + 1); // Trigger AI suggestions refresh
    }
    if (view === 'recommendations') {
      setRecommendationsVisitCount(c => c + 1); // Trigger Shuffleupagus suggestions refresh
    }
    if (view !== activeView) {
      // Clear search state when leaving search view
      if (activeView === 'search') {
        setSearchQuery('');
        setSearchResults({ artists: [], albums: [], tracks: [], playlists: [] });
        setIsSearching(false);
        setDisplayLimits({ artists: 5, albums: 5, tracks: 8, playlists: 5 });
        setSearchDetailCategory(null);
        setSearchPreviewItem(null);
      }
      setViewHistory(prev => [...prev, view]);
      setForwardHistory([]); // Clear forward history when navigating to a new view
      setActiveView(view);
      if (view === 'settings') {
        setSettingsTab('plugins');
      }
    }
  };

  // Build a parachord:// deep link for the current page and tab
  const getParachordLink = () => {
    switch (activeView) {
      case 'home':
        return 'parachord://home';
      case 'artist':
        if (currentArtist?.name) {
          const encoded = encodeURIComponent(currentArtist.name);
          if (currentRelease) {
            return `parachord://album/${encoded}/${encodeURIComponent(currentRelease.title)}`;
          }
          if (artistPageTab && artistPageTab !== 'music') {
            return `parachord://artist/${encoded}/${artistPageTab}`;
          }
          return `parachord://artist/${encoded}`;
        }
        return 'parachord://home';
      case 'library':
        return collectionTab ? `parachord://library/${collectionTab}` : 'parachord://library';
      case 'history': {
        const tabMap = { topTracks: 'top-tracks', topAlbums: 'top-albums', topArtists: 'top-artists', recent: 'recent' };
        const seg = tabMap[historyTab] || '';
        const period = historyPeriod && historyPeriod !== '7day' ? `?period=${historyPeriod}` : '';
        return `parachord://history${seg ? '/' + seg : ''}${period}`;
      }
      case 'friendHistory': {
        if (currentFriend) {
          const id = currentFriend.username || currentFriend.id || currentFriend.name;
          return buildFriendLink(id, friendHistoryTab, friendHistoryPeriod);
        }
        return 'parachord://home';
      }
      case 'recommendations':
        return 'parachord://recommendations';
      case 'discover':
        return 'parachord://charts';
      case 'critics-picks':
        return 'parachord://critics-picks';
      case 'new-releases':
        return 'parachord://new-releases';
      case 'concerts':
        return 'parachord://concerts';
      case 'search':
        return searchQuery ? `parachord://search?q=${encodeURIComponent(searchQuery)}` : 'parachord://search';
      case 'playlists':
        return 'parachord://playlists';
      case 'playlist-view':
        if (selectedPlaylist) {
          return `parachord://playlist/${encodeURIComponent(selectedPlaylist.id || selectedPlaylist.name)}`;
        }
        return 'parachord://playlists';
      case 'settings':
        return settingsTab ? `parachord://settings/${settingsTab}` : 'parachord://settings';
      default:
        return 'parachord://home';
    }
  };

  // Right-click handler for page headers — shows a tooltip-styled context menu.
  // Always offers "Copy parachord:// link" (the power-user deep link). When the
  // current view has an Achordion-mappable entity (artist page, optionally with
  // a release drilldown), also offers "Copy link" up front, which routes to
  // the standard Achordion entity URL via publishArtist/CollectionSmartLink —
  // so right-click here gives the same result as right-clicking the entity in
  // a list and choosing Copy link.
  const copyParachordLink = (e) => {
    e.preventDefault();
    e.stopPropagation();
    const link = getParachordLink();
    let achordionShare = null;
    if (activeView === 'artist') {
      if (currentRelease && currentArtist?.name) {
        const collection = {
          title: currentRelease.title,
          artist: currentArtist.name,
          albumArt: currentRelease.albumArt || null,
          type: 'album',
          // Achordion's album pages are release groups and it does NOT map a
          // release MBID to its group (a release id under /release-group/
          // 404s), so the group id fetchReleaseData records comes first.
          // currentRelease.id is the release once MusicBrainz's list loads.
          mbid: currentRelease.releaseGroupMbid || currentRelease.mbid || currentRelease.id || null
        };
        achordionShare = {
          run: () => publishCollectionSmartLink(collection),
          runView: () => publishCollectionSmartLink(collection, { openInBrowser: true })
        };
      } else if (currentArtist?.name) {
        const artist = {
          id: slug(currentArtist.name || 'unknown'),
          name: currentArtist.name,
          image: artistImage
        };
        achordionShare = {
          run: () => publishArtistSmartLink(artist),
          runView: () => publishArtistSmartLink(artist, { openInBrowser: true })
        };
      }
    }
    // A ListenBrainz user's profile, and a playlist that's on ListenBrainz,
    // are on Achordion too.
    if (activeView === 'friendHistory' && currentFriend?.service === 'listenbrainz' && currentFriend.username) {
      const url = achordionUserUrl(currentFriend.username);
      achordionShare = {
        run: () => navigator.clipboard.writeText(url).then(() => showToast('Link copied to clipboard!')),
        runView: () => window.electron?.shell?.openExternal?.(url)
      };
    } else if (activeView === 'playlist-view' && selectedPlaylist && lbMbidOf(selectedPlaylist)) {
      const collection = {
        playlistId: selectedPlaylist.id,
        listenbrainzMbid: lbMbidOf(selectedPlaylist),
        title: selectedPlaylist.title,
        creator: selectedPlaylist.creator || null,
        type: 'playlist',
        tracks: []
      };
      achordionShare = {
        run: () => publishCollectionSmartLink(collection),
        runView: () => publishCollectionSmartLink(collection, { openInBrowser: true })
      };
    }
    setParachordLinkMenu({ x: e.clientX, y: e.clientY, link, achordionShare });
  };

  const navigateBack = () => {
    // If we're viewing a release/album opened directly (not from artist browsing),
    // close it and navigate back in one step.
    // Only do this when no discography is loaded — if artistReleases exist, the user
    // was browsing the artist's discography and BACK should just close the release.
    if (activeView === 'artist' && currentRelease && artistHistory.length === 0 && artistReleases.length === 0 && viewHistory.length > 1) {
      setCurrentRelease(null);
      // Also navigate back to previous view (e.g., HOME or Collection)
      const newHistory = [...viewHistory];
      const currentView = newHistory.pop();
      const previousView = newHistory[newHistory.length - 1];
      setViewHistory(newHistory);
      setForwardHistory(prev => [...prev, currentView]);
      setActiveView(previousView);
      // Clear artist state since we're leaving artist view
      setCurrentArtist(null);
      setArtistImage(null);
      setArtistImagePosition('center 25%');
      setArtistReleases([]);
      resetReleaseTypeFilter();
      albumArtQueue.current = [];
      visibleAlbumIds.current.clear();
      return;
    }

    // If we're viewing a release/album from artist browsing, close it first
    if (activeView === 'artist' && currentRelease) {
      setCurrentRelease(null);
      return;
    }

    // If we're on artist page and have artist history, go to previous artist
    if (activeView === 'artist' && artistHistory.length > 0) {
      const newArtistHistory = [...artistHistory];
      const previousArtist = newArtistHistory.pop();
      setArtistHistory(newArtistHistory);
      startReleaseTypeFilterFor(previousArtist);

      // Fetch the previous artist's data
      const loadPreviousArtist = async () => {
        const cacheKey = previousArtist.toLowerCase();
        const cachedData = artistDataCache.current[cacheKey];
        const now = Date.now();

        // Check if artist image is in cache
        const normalizedName = previousArtist.trim().toLowerCase();
        const cachedImage = artistImageCache.current[normalizedName];
        const imageCacheValid = cachedImage && (now - cachedImage.timestamp) < CACHE_TTL.artistImage;

        // Cache is valid if data exists and not expired. The releases array is
        // REQUIRED — the MBID warmup path writes partial entries
        // ({artist:{name,mbid}, timestamp}) with no releases, and treating
        // those as valid crashed on cachedData.releases.map (same guard as
        // fetchArtistData).
        const cacheValid = cachedData &&
                          Array.isArray(cachedData.releases) &&
                          (now - cachedData.timestamp) < CACHE_TTL.artistData;

        if (cacheValid) {
          // Set artist image immediately from cache if available
          if (imageCacheValid) {
            setArtistImage(cachedImage.url);
            setArtistImagePosition(cachedImage.facePosition || 'center 25%');
          } else {
            setArtistImage(null);
            setArtistImagePosition('center 25%');
            getArtistImage(previousArtist).then(result => {
              if (result) {
                setArtistImage(result.url);
                setArtistImagePosition(result.facePosition || 'center 25%');
              }
            });
          }

          setCurrentArtist(cachedData.artist);
          const releasesWithCache = cachedData.releases.map(release => ({
            ...release,
            // Use cached URL if available, undefined if needs fetch (shows shimmer)
            albumArt: albumArtCache.current[release.id]?.url !== undefined
              ? albumArtCache.current[release.id]?.url
              : undefined
          }));
          setArtistReleases(releasesWithCache);
          setSmartReleaseTypeFilter(releasesWithCache);
          setLoadingArtist(false);
          // Queue album art fetches for releases without cached art (viewport-prioritized)
          const releasesNeedingArt = withArtArtist(
            cachedData.releases.filter(r => !albumArtCache.current[r.id]), cachedData.artist?.name || previousArtist);
          albumArtFetchId.current++; // Cancel any previous fetch session
          isAlbumArtFetching.current = false;
          albumArtQueue.current = releasesNeedingArt;
          visibleAlbumIds.current.clear();
          processAlbumArtQueue();
        } else {
          // No valid cache - show loading state
          setLoadingArtist(true);
          setArtistImage(null);
          setArtistImagePosition('center 25%');

          // Refetch if not in cache (rare case)
          const searchResponse = await fetch(
            `https://musicbrainz.org/ws/2/artist?query=${encodeURIComponent(previousArtist)}&fmt=json&limit=1`,
            { headers: { 'User-Agent': 'Parachord/1.0.0 (https://github.com/harmonix)' } }
          );
          const searchData = await searchResponse.json();
          if (searchData.artists?.[0]) {
            const artist = searchData.artists[0];
            setCurrentArtist(artist);
            getArtistImage(previousArtist).then(result => {
              if (result) {
                setArtistImage(result.url);
                setArtistImagePosition(result.facePosition || 'center 25%');
              }
            });
          }
          setLoadingArtist(false);
        }
      };
      loadPreviousArtist();
      return;
    }

    if (viewHistory.length > 1) {
      const newHistory = [...viewHistory];
      const activeView = newHistory.pop(); // Remove current view
      let previousView = newHistory[newHistory.length - 1];

      // Safety guard: if previousView is a data-dependent view without its
      // required data (e.g. after an app relaunch where only the last page
      // was fully restored), fall back to a safe parent view.
      if (previousView === 'artist' && !currentArtist) {
        previousView = 'home';
        newHistory[newHistory.length - 1] = 'home';
      } else if (previousView === 'playlist-view' && !selectedPlaylist) {
        previousView = 'playlists';
        newHistory[newHistory.length - 1] = 'playlists';
      } else if (previousView === 'friendHistory' && !currentFriend) {
        previousView = 'friends';
        newHistory[newHistory.length - 1] = 'friends';
      } else if (!previousView) {
        // History stack was corrupted or empty — reset to home
        previousView = 'home';
        newHistory.length = 0;
        newHistory.push('home');
      }

      setViewHistory(newHistory);
      setForwardHistory(prev => [...prev, activeView]); // Add current view to forward history
      setActiveView(previousView);

      // Clear associated state when leaving certain views
      if (activeView === 'artist') {
        setCurrentArtist(null);
        setArtistImage(null);
        setArtistImagePosition('center 25%');
        setArtistReleases([]);
        resetReleaseTypeFilter();
        setArtistHistory([]); // Clear artist history when leaving artist view
        // Clear album art loading queue
        albumArtQueue.current = [];
        visibleAlbumIds.current.clear();
      }
      if (activeView === 'release') {
        setCurrentRelease(null);
      }
      if (activeView === 'playlist-view') {
        setSelectedPlaylist(null);
        setPlaylistTracks([]);
      }
    }
  };
  navigateBackRef.current = navigateBack;
  activeViewNowRef.current = activeView;

  const navigateForward = () => {
    if (forwardHistory.length > 0) {
      const newForwardHistory = [...forwardHistory];
      const nextView = newForwardHistory.pop();
      setForwardHistory(newForwardHistory);
      setViewHistory(prev => [...prev, nextView]);
      setActiveView(nextView);
    }
  };

  // Playlist import/export functions
  const handleImportPlaylist = async () => {
    try {
      console.log('📥 Importing playlist...');
      const result = await window.electron.playlists.import();
      
      if (!result) {
        console.log('Import cancelled');
        return;
      }
      
      if (result.error) {
        showConfirmDialog({
          type: 'error',
          title: 'Import failed',
          message: result.error
        });
        return;
      }

      const { content, filename } = result;

      // Parse to get playlist info
      const parsed = parseXSPF(content);
      if (!parsed) {
        showConfirmDialog({
          type: 'error',
          title: 'Couldn’t import the playlist',
          message: 'Parachord can’t read that file. Choose an .xspf playlist file.'
        });
        return;
      }
      
      // Generate unique ID for imported playlist
      const id = `imported-${Date.now()}`;

      // Create playlist object
      const newPlaylist = {
        id: id,
        title: parsed.title,
        creator: parsed.creator,
        tracks: parsed.tracks || [],
        xspf: content,
        source: 'imported-xspf',
        createdAt: parsed.date || Date.now(), // Use XSPF date (original creation) or import time
        addedAt: Date.now(), // When added to library
        lastModified: Date.now()
      };

      // Save to electron-store
      const saveResult = await window.electron.playlists.save(newPlaylist);

      if (!saveResult.success) {
        showConfirmDialog({
          type: 'error',
          title: 'Save failed',
          message: saveResult.error
        });
        return;
      }

      // Add to state (prepend so it appears at top immediately)
      setPlaylists(prev => [newPlaylist, ...prev]);

      // Fetch covers for the 2x2 grid display immediately
      fetchPlaylistCovers(id, parsed.tracks || []);

      console.log(`✅ Imported playlist: ${parsed.title} (${newPlaylist.tracks.length} tracks)`);
      showSidebarBadge('playlists');
      showToast(`Imported “${parsed.title}”`, 'success');
    } catch (error) {
      console.error('Import error:', error);
      showConfirmDialog({
        type: 'error',
        title: 'Couldn’t import the playlist',
        message: errorText(error, 'Check that the file is an XSPF playlist, then try again.')
      });
    }
  };

  // SSRF-protected tracklist parser. Used by parachord://play-album, play-playlist,
  // play-radio when fetching XSPF or JSPF/JSON endpoints.
  // SYNC: tests/helpers/tracklist-parser.js — keep the JSON branch byte-identical.
  // (XSPF branches diverge intentionally: this uses DOMParser; the test helper uses regex.)
  window.parseProtocolTracklist = (body, contentType) => {
    const MAX_TRACKS = 500;
    const ct = (contentType || '').toLowerCase();

    if (ct.includes('xml')) {
      const doc = new DOMParser().parseFromString(body, 'application/xml');
      if (doc.querySelector('parsererror')) return { displayName: 'Tracks', tracks: [] };
      const displayName = doc.querySelector('playlist > title')?.textContent?.trim() || 'Tracks';
      const tracks = Array.from(doc.querySelectorAll('trackList > track')).map(tEl => {
        const title = tEl.querySelector('title')?.textContent?.trim();
        const creator = tEl.querySelector('creator')?.textContent?.trim();
        const album = tEl.querySelector('album')?.textContent?.trim();
        if (!title || !creator) return null;
        const t = { artist: creator, title };
        if (album) t.album = album;
        return t;
      }).filter(Boolean);
      return { displayName, tracks: tracks.slice(0, MAX_TRACKS) };
    }

    // === SYNC START: JSON branch — byte-identical with tests/helpers/tracklist-parser.js ===
    const extractMbid = (identifier) => {
      if (!identifier) return null;
      const arr = Array.isArray(identifier) ? identifier : [identifier];
      for (const id of arr) {
        if (typeof id !== 'string') continue;
        const m = id.match(/musicbrainz\.org\/(?:recording|track)\/([a-f0-9-]{36})/i);
        if (m) return m[1];
        if (/^[a-f0-9-]{36}$/i.test(id)) return id;
      }
      return null;
    };
    const parseJspfTrack = (t) => {
      if (!t || typeof t !== 'object') return null;
      const rawArtist = t.creator || t.artist;
      const artist = Array.isArray(rawArtist) ? rawArtist.filter(x => typeof x === 'string').join(', ') : rawArtist;
      const title = t.title;
      if (!artist || !String(artist).trim() || !title || !String(title).trim()) return null;
      const out = { artist: String(artist).trim(), title: String(title).trim() };
      if (t.album && String(t.album).trim()) out.album = String(t.album).trim();
      const mbid = extractMbid(t.identifier);
      if (mbid) out.mbid = mbid;
      return out;
    };

    let parsed;
    try { parsed = JSON.parse(body); } catch { return { displayName: 'Tracks', tracks: [] }; }
    // ListenBrainz lb-radio wraps the JSPF in `{payload: {jspf: {playlist}}}`.
    // Unwrap to the bare JSPF shape so the existing JSPF branch handles it.
    const jspfRoot = parsed.payload?.jspf || parsed;
    if (jspfRoot.playlist && Array.isArray(jspfRoot.playlist.track)) {
      const displayName = jspfRoot.playlist.title || 'Tracks';
      const tracks = jspfRoot.playlist.track.map(parseJspfTrack).filter(Boolean);
      return { displayName, tracks: tracks.slice(0, MAX_TRACKS) };
    }
    if (Array.isArray(parsed.tracks)) {
      const tracks = parsed.tracks
        .filter(t => t && t.artist && String(t.artist).trim() && t.title && String(t.title).trim())
        .map(t => {
          const out = { artist: String(t.artist).trim(), title: String(t.title).trim() };
          if (t.album && String(t.album).trim()) out.album = String(t.album).trim();
          if (t.mbid && /^[a-f0-9-]{36}$/i.test(t.mbid)) out.mbid = t.mbid;
          if (t.isrc && String(t.isrc).trim()) out.isrc = String(t.isrc).trim();
          return out;
        });
      return { displayName: parsed.title || 'Tracks', tracks: tracks.slice(0, MAX_TRACKS) };
    }
    return { displayName: 'Tracks', tracks: [] };
    // === SYNC END ===
  };

  // Fetch a hosted playlist document with the public-URL guard and body cap
  // (parachord#1011). Shared by the URL import below and the 5-minute poller
  // so neither can fetch a private address or parse an unbounded body.
  // Through the main process (main-process/public-fetch.js): each redirect
  // hop is checked before it is requested and the body stops at the cap. A
  // renderer fetch could only check afterwards, once the redirect to a
  // private address had been requested and the whole body read.
  const fetchHostedPlaylistText = async (url) => {
    const problem = window.hostedPlaylistFetchProblem(url, null, 0);
    if (problem) throw new Error(problem);
    const result = await window.electron.publicFetch(url, 'hosted-playlist');
    if (!result || !result.success) throw new Error(result?.error || 'Failed to fetch the playlist');
    if (!result.ok) throw new Error(`Failed to fetch: ${result.status}`);
    // Belt and braces: the main process already enforced both.
    const afterProblem = window.hostedPlaylistFetchProblem(url, result.finalUrl, result.text.length);
    if (afterProblem) throw new Error(afterProblem);
    return result.text;
  };

  // background: true from the startup reload list and the 5-minute poller —
  // a zero-track parse throws (logged by the caller) instead of showing a
  // modal dialog. Background work must never modal-error.
  // metadataOverrides: { title?, creator?, coverArt? } — local edits (title /
  // creator) or the cover the ephemeral view is showing (coverArt; wins over
  // the resolver's own so the image never swaps on save).
  const handleImportPlaylistFromUrl = async (url, skipStorageUpdate = false, storedAddedAt = null, metadataOverrides = null, { background = false, quiet = false, provider = false, autoUpdate } = {}) => {
    try {
      console.log('🌐 Importing playlist from URL:', url);

      // Check if a resolver can handle this URL as a playlist (e.g. Spotify, Apple Music)
      const resolverId = resolverLoaderRef.current?.findResolverForUrl(url);
      const urlType = resolverId ? resolverLoaderRef.current.getUrlType(url) : 'unknown';

      let parsed = null;
      let content = null;

      if (resolverId && urlType === 'playlist') {
        // Use resolver API to fetch playlist tracks (Spotify, Apple Music, etc.)
        console.log(`🔌 Using resolver "${resolverId}" to import playlist`);
        const config = await getResolverConfig(resolverId);
        const result = await resolverLoaderRef.current.lookupPlaylist(url, config);

        if (!result || !result.playlist || !result.playlist.tracks?.length) {
          throw new Error(`Could not load playlist from ${resolverId}. Make sure the service is connected and the playlist is accessible.`);
        }

        const playlist = result.playlist;
        console.log(`🎵 Loaded ${playlist.tracks.length} tracks via ${resolverId}`);

        // The playlist's own cover, as the resolver reported it (the
        // `albumArt` field of the lookupPlaylist contract — Spotify, Amazon
        // and Apple Music all fill it; `image`/`artwork` are accepted
        // aliases). It rides on the saved record so the Playlists page, the
        // playlist view and the share link show the provider's cover instead
        // of a mosaic generated from the tracks — the same image the
        // Recommendations page showed for a recommended playlist. It is NOT
        // written onto any track (that is the 4×-tiled-mosaic bug) and not
        // into albumArtCache (it is playlist art, not album art).
        const playlistCoverArt = [playlist.albumArt, playlist.image, playlist.artwork]
          .find(a => typeof a === 'string' && a.trim()) || null;

        // Convert resolver result to internal format
        parsed = {
          title: playlist.name || 'Untitled Playlist',
          creator: playlist.owner || playlist.artist || resolverId,
          date: null,
          ...(playlistCoverArt ? { coverArt: playlistCoverArt } : {}),
          tracks: playlist.tracks.map(t => ({
            title: t.title || 'Unknown Track',
            artist: t.artist || 'Unknown Artist',
            album: t.album || '',
            duration: t.duration || 0,
            location: ''
          }))
        };

        // Generate XSPF for storage so the playlist can be reloaded without the service
        content = generateXSPF({ ...parsed, createdAt: Date.now() });
      } else if (provider || window.isProviderPlaylistUrl(url, resolverLoaderRef.current)) {
        // Never fetch a provider playlist page and parse it as XSPF. That is
        // the launch dialog: Electron's file:// renderer does not enforce CORS,
        // the HTML comes back 200, and parseXSPF yields zero tracks. A refresh
        // that raced resolver init, or a plugin that is no longer loaded,
        // fails here instead of touching the page.
        throw new Error('Could not refresh this playlist — music services are still loading, or the service that imported it is not available');
      } else {
        // Hosted XSPF — fetch (guarded + capped) and parse directly
        content = await fetchHostedPlaylistText(url);
        parsed = parseXSPF(content);
      }

      if (!parsed || !parsed.tracks?.length) {
        // Background reloads (the startup hosted list, the 5-minute poller)
        // and the manual Refresh button must never modal-error. Throw so the
        // caller can log or toast; a user-initiated import keeps the dialog.
        if (background || quiet) {
          throw new Error(resolverId
            ? `No tracks found for ${resolverId} playlist`
            : 'Failed to parse XSPF file from URL');
        }
        showConfirmDialog({
          type: 'error',
          title: 'Import failed',
          message: resolverId
            ? `No tracks found. Make sure ${resolverId} is connected and the playlist URL is correct.`
            : 'Failed to parse XSPF file from URL'
        });
        return;
      }

      // Generate ID from URL using a simple hash for uniqueness
      // Using full URL hash instead of truncated base64 to avoid collisions
      const hashCode = (str) => {
        let hash = 0;
        for (let i = 0; i < str.length; i++) {
          const char = str.charCodeAt(i);
          hash = ((hash << 5) - hash) + char;
          hash = hash & hash; // Convert to 32bit integer
        }
        return Math.abs(hash).toString(36);
      };
      const id = 'hosted-' + hashCode(url);

      // Apply metadata overrides if provided (from stored local edits, or the
      // playlist being saved — the ephemeral SAVE passes the cover it is
      // showing so the saved record never swaps the image the user was
      // looking at)
      const playlistTitle = metadataOverrides?.title || parsed.title;
      const playlistCreator = metadataOverrides?.creator ?? parsed.creator;
      // The cover for the saved record: the override (what the view is
      // showing), else the resolver's, else whatever the existing record
      // already carries (a hosted-XSPF re-import parses no cover, so the
      // previous one survives). Null means no playlist cover — the mosaic.
      const playlistCover = (typeof metadataOverrides?.coverArt === 'string' && metadataOverrides.coverArt.trim())
        || parsed.coverArt
        || null;

      // Look up the on-disk record FIRST — disk is the source of truth for
      // `syncedTo` / `syncedFrom` / `syncSources` even when React state is
      // temporarily stale (e.g. background-sync reload race, or any other
      // setPlaylists path that hasn't observed the latest hosted-import
      // write yet). Without this, a hosted-XSPF re-import where the React
      // state lookup misses falls into the "add new" branch below and
      // produces a fresh record with NO sync state — next sync push loop
      // then treats it as needing create-on-each-provider. main.js's
      // three-layer dedup saves us from duplicate remote creation, but
      // each cycle would still pay the full clear-and-add cost without
      // the inline-content short-circuit (parachord#832) AND without
      // this state-preservation fix routing through the correct push
      // path. The per-provider mutex (parachord#831) is the last layer:
      // even when one provider's push DOES have legitimate work, sibling
      // providers' playlist-diff phases now proceed in parallel rather
      // than getting starved.
      let existingOnDisk = null;
      try {
        const onDisk = await window.electron.playlists.load();
        existingOnDisk = onDisk.find(p => p.sourceUrl === url || p.id === id);
      } catch (e) {
        console.warn('Failed to load on-disk playlists for hosted-import dedup:', e);
      }

      // Check if playlist already exists (use updater form to avoid stale closure)
      let didUpdate = false;
      let updatedPlaylist = null;
      setPlaylists(prev => {
        const existingIndex = prev.findIndex(p => p.sourceUrl === url || p.id === id);
        // React state takes precedence when present (it's the freshest write
        // path); fall back to the on-disk record when React state is stale.
        // The branch reached either way preserves `syncedTo` / `syncedFrom`
        // / `syncSources` via the `...existing` spread.
        const existing = existingIndex >= 0 ? prev[existingIndex] : existingOnDisk;
        if (existing) {
          didUpdate = true;
          // Keep the local tracks (edits included) unless the link's
          // tracklist changed since the last import; a change replaces them
          // and is flagged so the sync loop pushes it to the mirrors. An
          // unchanged reload or poll leaves the edits, and their flag, alone
          // (lib/hosted-refresh.js).
          let previousLinkTracks = null;
          try { previousLinkTracks = existing.xspf ? (parseXSPF(existing.xspf)?.tracks || null) : null; } catch { previousLinkTracks = null; }
          const refreshed = refreshedTracks(existing, { previousLinkTracks, linkTracks: parsed.tracks || [] });
          const contentChanged = refreshed.changed;
          // Freshness: a refresh that brought different tracks is a change
          // (tracksChangedAt, lastChangeAdded); a re-poll with the same
          // tracks keeps the existing stamp.
          updatedPlaylist = stampPlaylist(existing, {
            ...existing,
            xspf: content,
            title: playlistTitle,
            creator: playlistCreator,
            ...(playlistCover ? { coverArt: playlistCover } : {}),
            tracks: refreshed.tracks,
            lastUpdated: Date.now(),
            ...(contentChanged ? { locallyModified: true, lastModified: Date.now() } : {})
          }, Date.now());
          if (existingIndex >= 0) {
            return prev.map((p, i) => i === existingIndex ? updatedPlaylist : p);
          }
          // Existed on disk but not in React state — restore it. Without
          // this, the "add new" branch below would create a duplicate
          // playlist entry on next save, and the sync push loop would still
          // see the fresh entry (no sync state) and re-push everything.
          return [updatedPlaylist, ...prev];
        }
        return prev;
      });

      if (didUpdate) {
        // Persist updated hosted playlist to disk so it survives sync reloads and can be synced to providers
        try {
          await window.electron.playlists.save(updatedPlaylist);
        } catch (e) {
          console.warn('Failed to persist updated hosted playlist:', e);
        }
        console.log(`🔄 Updated hosted playlist: ${playlistTitle} (${updatedPlaylist?.tracks?.length || 0} tracks)`);
        // The tracks the record kept, so an open playlist shows the edits
        // when the link hadn't changed.
        return { updated: true, playlist: { ...parsed, tracks: updatedPlaylist?.tracks || parsed.tracks || [], title: playlistTitle, creator: playlistCreator, ...(playlistCover ? { coverArt: playlistCover } : {}) } };
      }

      // Add new hosted playlist
      // Set source based on how the playlist was imported
      const importSource = resolverId ? `${resolverId}-import` : 'hosted-xspf';
      const newPlaylist = stampPlaylist(null, {
        id: id,
        filename: null,  // No local file for hosted playlists
        title: playlistTitle,
        creator: playlistCreator,
        ...(playlistCover ? { coverArt: playlistCover } : {}),
        tracks: parsed.tracks || [],
        xspf: content,
        source: importSource,
        sourceUrl: url,  // Track the source URL for updates
        // Keep it updated from the link, or a snapshot (the person's answer;
        // lib/playlist-update-mode.js). Absent means the old behaviour.
        ...(typeof autoUpdate === 'boolean' ? { autoUpdate } : {}),
        createdAt: parsed.date || Date.now(), // Use XSPF date (original creation) or import time
        addedAt: storedAddedAt || Date.now(), // When added to library (use stored value on reload)
        lastModified: Date.now()
      }, Date.now());

      // Persist to disk so sync reloads and sync-to-provider pick it up
      try {
        await window.electron.playlists.save(newPlaylist);
      } catch (e) {
        console.warn('Failed to persist hosted playlist:', e);
      }

      // Add to state (prepend so it appears at top immediately, unless loading from storage)
      setPlaylists(prev => {
        // Guard against double-add if another path already inserted it
        if (prev.some(p => p.sourceUrl === url)) return prev;
        return skipStorageUpdate ? [...prev, newPlaylist] : [newPlaylist, ...prev];
      });

      // Fetch covers for the 2x2 grid display immediately
      fetchPlaylistCovers(id, parsed.tracks || []);

      // Save URL to persistent storage for reload on app start — hosted
      // tracklist DOCUMENTS only. A resolver import is a snapshot: it keeps its
      // sourceUrl for provenance and on-demand refresh, but enrolling it here
      // would put a provider playlist PAGE into the hosted machinery — the
      // startup reload would re-run a full resolver import every launch (and
      // race resolver init into "Failed to parse XSPF"), and the 5-minute
      // poller would fetch the page HTML forever.
      // A snapshot of an XSPF isn't reloaded or polled either.
      if (!skipStorageUpdate && !resolverId && autoUpdate !== false) {
        const hostedPlaylists = await window.electron?.store?.get('hosted_playlists') || [];
        hostedPlaylists.push({ url, id, addedAt: Date.now() });
        await window.electron?.store?.set('hosted_playlists', hostedPlaylists);
      }

      console.log(`✅ Imported hosted playlist: ${parsed.title}`);
      // A new playlist (not the startup reload of a saved one) badges the
      // sidebar, like every other way a playlist arrives.
      if (!skipStorageUpdate) showSidebarBadge('playlists');
      return { updated: false, playlist: parsed };
    } catch (error) {
      console.error('URL import error:', error);
      throw error;
    }
  };

  // Handle drop on playlists sidebar / playlists tab — import playlist from URL
  const handlePlaylistDrop = async (e) => {
    e.preventDefault();
    setPlaylistDropHighlight(false);

    const url = extractUrlFromDrop(e.dataTransfer);
    if (!url) return;

    // Check if this is a playlist URL (Spotify, Apple Music, hosted XSPF)
    const resolverId = resolverLoaderRef.current?.findResolverForUrl(url);
    const urlType = resolverId ? resolverLoaderRef.current.getUrlType(url) : 'unknown';

    // Accept playlist URLs from resolvers, or any URL that could be a hosted XSPF
    if ((resolverId && urlType === 'playlist') || (!resolverId && isValidUrl(url))) {
      // A new link: keep it updated, or a snapshot? (lib/playlist-update-mode.js)
      let autoUpdate;
      if (!isPlaylistLinkImported(url)) {
        const mode = await askPlaylistUpdateMode(url);
        if (!mode) return;
        autoUpdate = mode === 'auto';
      }
      try {
        const result = await handleImportPlaylistFromUrl(url, false, null, null, { autoUpdate });
        if (result?.updated) {
          showToast(`Updated playlist: ${result.playlist?.title || 'Untitled'}`);
        } else if (result?.playlist) {
          showToast(`Imported playlist: ${result.playlist?.title || 'Untitled'}`);
          navigateTo('playlists');
        }
      } catch (err) {
        console.error('Import failed:', err); showToast(errorText(err, 'Couldn’t import the playlist. Check the link and try again.'), 'error');
      }
    }
  };

  // Refresh a hosted XSPF or a provider-imported snapshot. Provider imports
  // are not on the startup reload list — this button is the only update path.
  // It goes through lookupPlaylist (never parseXSPF of the provider page) and
  // toasts on failure instead of opening the import dialog.
  const refreshHostedPlaylist = async (playlistId, { background = false } = {}) => {
    const playlist = (playlistsRef.current || []).find(p => p.id === playlistId);
    if (!playlist?.sourceUrl) {
      console.log('Not a hosted playlist, cannot refresh');
      return false;
    }
    const provider = window.isProviderImportedPlaylist(playlist, resolverLoaderRef.current);

    try {
      if (provider && resolversInitRef.current) {
        await Promise.race([
          resolversInitRef.current,
          new Promise(resolve => setTimeout(resolve, 15000))
        ]);
      }
      console.log(`🔄 Refreshing playlist: ${playlist.title}`);
      const result = await handleImportPlaylistFromUrl(playlist.sourceUrl, false, null, null, { quiet: true, provider });

      if (selectedPlaylistRef.current?.id === playlistId && result?.playlist?.tracks) {
        const tracksWithIds = result.playlist.tracks.map(track => {
          const trackId = trackSlug(track.artist || 'unknown', track.title || 'untitled', track.album || 'noalbum');
          return { ...track, id: trackId, sources: {} };
        });
        setPlaylistTracks(tracksWithIds);
        setSelectedPlaylist(prev => prev && prev.id === playlistId
          ? {
              ...prev,
              title: result.playlist.title,
              creator: result.playlist.creator,
              // A refreshed playlist cover swaps in when the lookup returned
              // one (a hosted-XSPF refresh parses no cover, so the existing
              // one survives — never blanked by a refresh).
              ...(result.playlist.coverArt ? { coverArt: result.playlist.coverArt } : {}),
              tracks: tracksWithIds
            }
          : prev);
      }

      if (!background) showToast(`Updated ${result?.playlist?.title || playlist.title}`);
      return true;
    } catch (error) {
      console.error('Refresh error:', error);
      if (!background) showToast(error?.message || 'Could not refresh playlist', 'error');
      return false;
    }
  };

  // How a playlist imported from a link updates: 'auto' | 'snapshot', or null
  // for one that wasn't (lib/playlist-update-mode.js). The guard is the one
  // the refresh buttons always used.
  const linkUpdateMode = (playlist) => {
    if (!playlist?.sourceUrl || playlist.isEphemeral) return null;
    const providerImported = window.isProviderImportedPlaylist(playlist, resolverLoaderRef.current);
    if (playlist.source !== 'hosted-xspf' && !providerImported) return null;
    return playlistUpdateMode(playlist, { providerImported });
  };

  // The service a playlist link belongs to, for the question's wording.
  const playlistLinkService = (url) => {
    const resolverId = resolverLoaderRef.current?.findResolverForUrl(url);
    if (!resolverId || resolverLoaderRef.current.getUrlType(url) !== 'playlist') return { isService: false, sourceLabel: null };
    return { isService: true, sourceLabel: resolverLoaderRef.current.getResolver(resolverId)?.name || null };
  };

  // Ask how a new playlist link should update. Resolves 'auto' | 'snapshot',
  // or null when the person cancels.
  const askPlaylistUpdateMode = (url, description) => new Promise((resolve) => {
    setUpdateModeAsk({ url, description, ...playlistLinkService(url), resolve });
  });
  // Called from the dialog this render drew, so updateModeAsk is current.
  const answerUpdateModeAsk = (mode) => {
    const ask = updateModeAsk;
    setUpdateModeAsk(null);
    if (ask?.resolve) ask.resolve(mode);
  };

  // Already imported from this link: importing it again refreshes it, as
  // before, and doesn't ask.
  const isPlaylistLinkImported = (url) => (playlistsRef.current || []).some(p => p.sourceUrl === url);

  // Switch a link-imported playlist between kept updated and a snapshot.
  // Keeping it updated also brings it up to date now.
  const setPlaylistUpdateMode = async (playlistId, mode) => {
    const playlist = (playlistsRef.current || []).find(p => p.id === playlistId);
    if (!playlist?.sourceUrl) return;
    const providerImported = window.isProviderImportedPlaylist(playlist, resolverLoaderRef.current);
    const updated = { ...playlist, autoUpdate: mode === 'auto' };
    setPlaylists(prev => prev.map(p => (p.id === playlistId ? { ...p, autoUpdate: updated.autoUpdate } : p)));
    setSelectedPlaylist(prev => (prev && prev.id === playlistId ? { ...prev, autoUpdate: updated.autoUpdate } : prev));
    try {
      // Straight to the store: the hosted save path only keeps the title.
      await window.electron.playlists.save(window.buildPlaylistSavePayload(updated));
      const hostedList = await window.electron?.store?.get('hosted_playlists') || [];
      const nextList = hostedListForMode(hostedList, updated, mode, { providerImported });
      if (nextList !== hostedList) await window.electron?.store?.set('hosted_playlists', nextList);
    } catch (error) {
      console.error('Could not save the playlist’s update setting:', error);
      showToast('Couldn’t change how this playlist updates. Try again.', 'error');
      return;
    }
    if (mode === 'auto') {
      // playlistsRef catches up on the next render; refresh reads it.
      playlistsRef.current = (playlistsRef.current || []).map(p => (p.id === playlistId ? updated : p));
      await refreshHostedPlaylist(playlistId);
    } else {
      showToast(`“${playlist.title}” is now a snapshot`);
    }
  };

  // Poll hosted playlists for updates
  const hostedPlaylistPollInterval = useRef(null);

  useEffect(() => {
    // Start polling for hosted playlist updates (every 5 minutes)
    const pollHostedPlaylists = async () => {
      // Hosted tracklist documents only. A provider playlist page (Spotify,
      // Apple Music, Amazon — kept via sourceUrl for provenance/refresh) is
      // not an XSPF: its fetched HTML never matches the stored XSPF, so every
      // poll would re-run a full resolver import.
      // A snapshot of an XSPF (autoUpdate: false) isn't polled.
      const hostedPlaylists = playlists.filter(p => p.sourceUrl && !window.isProviderPlaylistUrl(p.sourceUrl, resolverLoaderRef.current)
        && isPolledHostedXspf(p, { providerImported: window.isProviderImportedPlaylist(p, resolverLoaderRef.current) }));
      if (hostedPlaylists.length === 0) return;

      console.log(`🔄 Checking ${hostedPlaylists.length} hosted playlist(s) for updates...`);

      for (const playlist of hostedPlaylists) {
        try {
          // Same guard + cap as the import path (parachord#1011): a stored
          // URL that now fails the check (or has grown past the cap) is
          // skipped this tick instead of being parsed.
          const content = await fetchHostedPlaylistText(playlist.sourceUrl);

          // Check if content changed
          if (content !== playlist.xspf) {
            console.log(`📝 Hosted playlist changed: ${playlist.title}`);
            await handleImportPlaylistFromUrl(playlist.sourceUrl, false, null, null, { background: true });
          }
        } catch (error) {
          console.error(`Failed to check playlist ${playlist.title}:`, error);
        }
      }
    };

    // Poll every 5 minutes. Wrap each tick in yieldToIdle so the work
    // doesn't fight the main thread when other background jobs (sync,
    // resolver enrichment, friend activity poll) happen to fire in the
    // same window. The 10s timeout is generous — there's no urgency to
    // a hosted-XSPF refresh, and the 5min cadence means a single delayed
    // tick costs us nothing. parachord#770 part 2.
    const idlePollHostedPlaylists = async () => {
      await yieldToIdle(10000);
      await pollHostedPlaylists();
    };
    hostedPlaylistPollInterval.current = setInterval(idlePollHostedPlaylists, 5 * 60 * 1000);

    // Also poll on mount (after a short delay to let playlists load)
    const initialPoll = setTimeout(idlePollHostedPlaylists, 10000);

    return () => {
      clearInterval(hostedPlaylistPollInterval.current);
      clearTimeout(initialPoll);
    };
  }, [playlists.filter(p => p.sourceUrl).length]); // Re-run when hosted playlist count changes

  // Kept-updated service links (a Spotify, Apple Music, … playlist link the
  // person chose to keep updated) are looked up again once an hour
  // (serviceRefreshDue, lib/playlist-update-mode.js). Not the hosted poller:
  // a service's page is not an XSPF. A failed lookup (signed out, offline)
  // waits an hour too, so it doesn't retry every tick.
  const refreshHostedPlaylistRef = useRef(null);
  refreshHostedPlaylistRef.current = refreshHostedPlaylist;
  const serviceLinkFailedAtRef = useRef(new Map());
  useEffect(() => {
    let running = false;
    const refreshServiceLinks = async () => {
      if (running) return;
      running = true;
      try {
        if (resolversInitRef.current) {
          await Promise.race([resolversInitRef.current, new Promise(resolve => setTimeout(resolve, 15000))]);
        }
        const now = Date.now();
        const failedAt = serviceLinkFailedAtRef.current;
        const due = (playlistsRef.current || []).filter(p =>
          serviceRefreshDue(p, { providerImported: window.isProviderImportedPlaylist(p, resolverLoaderRef.current), now })
          && !(now - (failedAt.get(p.id) || 0) < SERVICE_REFRESH_MS));
        for (const p of due) {
          await yieldToIdle(10000);
          console.log(`🔄 Checking kept-updated playlist link: ${p.title}`);
          const ok = await refreshHostedPlaylistRef.current(p.id, { background: true });
          if (ok) failedAt.delete(p.id); else failedAt.set(p.id, Date.now());
        }
      } finally {
        running = false;
      }
    };
    const interval = setInterval(refreshServiceLinks, 10 * 60 * 1000);
    const initial = setTimeout(refreshServiceLinks, 60 * 1000);
    return () => { clearInterval(interval); clearTimeout(initial); };
  }, []);

  // Load hosted playlists on app start
  useEffect(() => {
    const loadHostedPlaylists = async () => {
      let hostedPlaylistUrls = await window.electron?.store?.get('hosted_playlists') || [];
      if (hostedPlaylistUrls.length === 0) {
        setPlaylistsLoading(false);
        return;
      }

      // Deduplicate by URL (in case duplicates accumulated from previous bug)
      const seenUrls = new Set();
      const deduped = hostedPlaylistUrls.filter(item => {
        if (seenUrls.has(item.url)) return false;
        seenUrls.add(item.url);
        return true;
      });

      // Save deduped list back to storage if we removed duplicates
      if (deduped.length < hostedPlaylistUrls.length) {
        console.log(`🧹 Cleaned up ${hostedPlaylistUrls.length - deduped.length} duplicate hosted playlist entries`);
        await window.electron?.store?.set('hosted_playlists', deduped);
        hostedPlaylistUrls = deduped;
      }

      console.log(`📦 Loading ${hostedPlaylistUrls.length} hosted playlist(s)...`);

      // Wait for resolver init (bounded) before dispatching: the import below
      // depends on findResolverForUrl, which returns null until resolvers load.
      // A provider playlist URL dispatched before that races into the
      // hosted-XSPF branch: the provider page's HTML parses to zero tracks
      // and startup showed "Failed to parse XSPF" for a playlist that
      // imported fine (observed with an Amazon playlist import).
      if (resolversInitRef.current) {
        await Promise.race([
          resolversInitRef.current,
          new Promise(resolve => setTimeout(resolve, 15000))
        ]);
      }

      // Self-heal: provider playlist URLs enrolled by the pre-fix import path
      // are snapshots, not hosted documents — drop them from the reload list.
      // The playlist object keeps its sourceUrl (provenance + the refresh
      // button, which re-runs the resolver import on demand), and the poller
      // skips provider URLs too, so nothing re-imports them automatically.
      const kept = [];
      const dropped = [];
      for (const item of hostedPlaylistUrls) {
        (window.isProviderPlaylistUrl(item.url, resolverLoaderRef.current) ? dropped : kept).push(item);
      }
      if (dropped.length > 0) {
        console.log(`🧹 Dropped ${dropped.length} provider playlist URL(s) from the hosted reload list (resolver imports are snapshots, not hosted XSPF):`, dropped.map(d => d.url).join(', '));
        hostedPlaylistUrls = kept;
        await window.electron?.store?.set('hosted_playlists', kept);
      }
      if (hostedPlaylistUrls.length === 0) {
        setPlaylistsLoading(false);
        return;
      }

      for (const { url, addedAt, title, creator } of hostedPlaylistUrls) {
        try {
          // Pass true to skip storage update (already in storage), and stored metadata to preserve overrides
          await handleImportPlaylistFromUrl(url, true, addedAt, { title, creator }, { background: true });
        } catch (error) {
          console.error(`Failed to load hosted playlist from ${url}:`, error);
        }
      }

      // All hosted playlists loaded
      setPlaylistsLoading(false);
    };

    // Delay to allow local playlists to load first
    const timer = setTimeout(loadHostedPlaylists, 2000);
    return () => clearTimeout(timer);
  }, []);

  // Export a playlist to an .xspf file via the main-process save dialog.
  // Reachable from the playlist header's Share menu, the playlist row context
  // menu ("Export as XSPF…") and the queue save dialog ("Save to file")
  // (parachord#1010; the handler and IPC existed with no caller). Playlists
  // created in-app (queue-*, ai-chat-*, playlist-*) carry no `xspf` field, so
  // the document is generated from `tracks` when it is missing.
  const handleExportPlaylist = async (playlist) => {
    try {
      console.log(`📤 Exporting playlist: ${playlist.id}`);

      const tracks = playlist.tracks || [];
      if (!playlist.xspf && tracks.length === 0) {
        showToast('Nothing to export: this playlist has no tracks', 'error');
        return;
      }
      // Every exported playlist carries its cover (#1410): a stored document
      // that doesn't name one gets the record's coverArt added.
      const content = withPlaylistImage(playlist.xspf || generateXSPF({
        title: playlist.title || playlist.name || 'Playlist',
        creator: playlist.creator,
        createdAt: playlist.createdAt,
        coverArt: playlist.coverArt,
        tracks
      }), playlist.coverArt, window.isPublicHttpUrl);
      const slug = String(playlist.title || playlist.name || playlist.id || 'playlist')
        .trim().replace(/[\\/:*?"<>|]+/g, '-').replace(/\s+/g, ' ').slice(0, 80) || 'playlist';
      const defaultFilename = playlist.filename || `${slug}.xspf`;
      const result = await window.electron.playlists.export(defaultFilename, content);
      
      if (!result) {
        console.log('Export cancelled');
        return;
      }
      
      if (!result.success) {
        showConfirmDialog({
          type: 'error',
          title: 'Export failed',
          message: result.error
        });
        return;
      }

      console.log(`✅ Exported to: ${result.filepath}`);
      showConfirmDialog({
        type: 'success',
        title: 'Playlist exported',
        message: 'Successfully saved to disk'
      });
    } catch (error) {
      console.error('Export error:', error);
      showConfirmDialog({
        type: 'error',
        title: 'Couldn’t export the playlist',
        message: 'Try again, or save it to a different folder.'
      });
    }
  };

  // Add Spotify authentication functions

  // Take a plug-in out of play when its account signs out (#1522): its
  // sources leave every track, and it leaves the active list and the saved
  // one, so reEnableResolver (below) treats the sign-out as the person's
  // choice. Every sign-out that turns its plug-in off calls this one path
  // (lib/deactivate-resolver.js).
  const deactivateResolver = (resolverId) => deactivateResolverFrom({ removeResolverSources, setActiveResolvers, savedActiveResolversRef }, resolverId);

  // Re-enable a resolver that was removed by a failed startup auth check,
  // restoring it to its saved position in the user's priority order.
  // Only re-enables if the resolver was in the user's saved active_resolvers list
  // (i.e. the user had it explicitly enabled before the auth check removed it).
  const reEnableResolver = (resolverId) => {
    // Don't re-add if the user never had it enabled — respect explicit disable
    const savedActive = savedActiveResolversRef.current;
    if (!savedActive || !savedActive.includes(resolverId)) return;

    setActiveResolvers(prev => {
      if (prev.includes(resolverId)) return prev;
      console.log(`🔄 Re-enabling ${resolverId} resolver (restoring saved position)`);
      // Restore to saved position from the user's persisted priority order
      const savedOrder = savedResolverOrderRef.current;
      if (savedOrder && savedOrder.includes(resolverId)) {
        const savedIndex = savedOrder.indexOf(resolverId);
        const newList = [...prev];
        let insertAt = newList.length;
        for (let i = 0; i < newList.length; i++) {
          const savedPos = savedOrder.indexOf(newList[i]);
          if (savedPos !== -1 && savedPos > savedIndex) {
            insertAt = i;
            break;
          }
        }
        newList.splice(insertAt, 0, resolverId);
        return newList;
      }
      return [...prev, resolverId];
    });
  };

  // Refresh the Spotify token and return the new token (or null if refresh failed)
  // This is called when a 401 is detected to get a fresh token
  const refreshSpotifyToken = async () => {
    console.log('🔄 Refreshing Spotify token...');
    if (!window.electron?.spotify) {
      console.log('window.electron.spotify not available');
      return null;
    }

    const tokenData = await window.electron.spotify.checkToken();
    if (tokenData && tokenData.token) {
      console.log('✅ Token refreshed successfully');
      setSpotifyToken(tokenData.token);
      setSpotifyConnected(true);
      reEnableResolver('spotify');
      return tokenData.token;
    } else {
      console.log('❌ Token refresh failed - no valid token returned');
      setSpotifyToken(null);
      setSpotifyConnected(false);
      return null;
    }
  };

  const checkSpotifyToken = async () => {
    console.log('Checking Spotify token...');
    if (window.electron?.spotify) {
      const tokenData = await window.electron.spotify.checkToken();
      console.log('Token data received:', {
        hasData: !!tokenData,
        hasToken: !!tokenData?.token,
        tokenLength: tokenData?.token?.length,
        tokenPreview: tokenData?.token ? tokenData.token.substring(0, 20) + '…' : 'null',
        expiry: tokenData?.expiry,
        hasRefresh: !!tokenData?.refreshToken
      });
      if (tokenData && tokenData.token) {
        console.log('Valid token found, setting connected state');
        setSpotifyToken(tokenData.token);
        setSpotifyConnected(true);
        reEnableResolver('spotify');
      } else {
        console.log('No valid token found');
      }
    } else {
      console.log('window.electron.spotify not available');
    }
  };

  const connectSpotify = async () => {
    console.log('=== Connect Spotify Clicked ===');
    console.log('window.electron:', !!window.electron);
    console.log('window.electron.spotify:', !!window.electron?.spotify);

    if (window.electron?.spotify) {
      try {
        console.log('Calling authenticate...');
        const result = await window.electron.spotify.authenticate();
        console.log('Authenticate result:', result);
        if (!result.success) {
          if (result.error === 'no_client_id') {
            showConfirmDialog({
              type: 'info',
              title: 'Spotify client ID required',
              message: 'To use Spotify, you need to create a free Spotify Developer app and enter your Client ID below.\n\n' +
                '1. Go to developer.spotify.com/dashboard\n' +
                '2. Create an app (name it anything)\n' +
                '3. Add both redirect URIs:\n' +
                `   http://127.0.0.1:${authPort}/callback\n` +
                `   http://[::1]:${authPort}/callback\n` +
                '4. Under "APIs used", tick both Web API and Web Playback SDK\n' +
                '5. Copy your Client ID and paste it in Settings'
            });
          } else {
            showConfirmDialog({
              type: 'error',
              title: 'Authentication failed',
              message: result.error || 'Spotify authentication failed. Please check your configuration.'
            });
          }
        }
      } catch (error) {
        console.error('Spotify auth error:', error);
        showConfirmDialog({
          type: 'error',
          title: 'Authentication failed',
          message: 'Spotify authentication failed. Check console for details.'
        });
      }
    } else {
      console.error('window.electron.spotify not available!');
      showConfirmDialog({
        type: 'error',
        title: 'Something went wrong',
        message: 'Parachord didn’t start correctly. Restart it and try again.'
      });
    }
  };

  const disconnectSpotify = async () => {
    if (window.electron?.spotify) {
      await window.electron.spotify.disconnect();
      setSpotifyToken(null);
      setSpotifyConnected(false);
      // Its sources leave every track, and it leaves both active lists.
      deactivateResolver('spotify');
    }
  };

  // Open Spotify at startup (the plug-in dialog's startup row): Spotify songs
  // play through the Spotify app (Spotify Connect), so a device is there.
  const toggleAutoLaunchSpotify = async () => {
    const newValue = !autoLaunchSpotify;
    setAutoLaunchSpotify(newValue);
    if (window.electron?.store) {
      await window.electron.store.set('auto_launch_spotify', newValue);
    }
    // If enabling, launch Spotify now
    if (newValue && window.electron?.spotify?.launchInBackground) {
      window.electron.spotify.launchInBackground();
      showToast('Spotify launched in background', 'success');
    }
  };

  // Save Spotify credentials (client ID only — PKCE flow doesn't need a secret)
  const saveSpotifyCredentials = async (clientIdOverride) => {
    if (!window.electron?.spotify?.setCredentials) {
      console.error('Spotify setCredentials not available');
      return;
    }

    const clientId = (typeof clientIdOverride === 'string' ? clientIdOverride : spotifyClientIdInput).trim();

    const result = await window.electron.spotify.setCredentials({
      clientId
    });

    if (result.success) {
      setSpotifyCredentialsSource(result.source);
      // If user had a token, they need to reconnect with new credentials
      if (spotifyConnected && clientId) {
        showConfirmDialog({
          type: 'info',
          title: 'Credentials updated',
          message: 'Your Spotify Client ID has been saved. Please disconnect and reconnect to use your new credentials.'
        });
      } else if (!clientId) {
        showToast('Spotify Client ID removed', 'info');
      } else {
        showToast('Spotify Client ID saved', 'success');
      }
    } else {
      showConfirmDialog({
        type: 'error',
        title: 'Error',
        message: result.error || 'Failed to save Spotify Client ID'
      });
    }
  };

  // SoundCloud authentication functions
  const checkSoundcloudToken = async () => {
    console.log('Checking SoundCloud token...');
    if (window.electron?.soundcloud) {
      const tokenData = await window.electron.soundcloud.checkToken();
      console.log('SoundCloud token data received:', {
        hasData: !!tokenData,
        hasToken: !!tokenData?.token,
        tokenLength: tokenData?.token?.length,
        tokenPreview: tokenData?.token ? tokenData.token.substring(0, 20) + '…' : 'null',
        expiry: tokenData?.expiresAt
      });
      if (tokenData && tokenData.token) {
        console.log('Valid SoundCloud token found, setting connected state');
        setSoundcloudToken(tokenData.token);
        setSoundcloudConnected(true);
        // Re-enable if it was in the user's saved active resolvers (restores priority position)
        reEnableResolver('soundcloud');
      } else {
        console.log('No valid SoundCloud token found');
      }
    } else {
      console.log('window.electron.soundcloud not available');
    }
  };

  // Save SoundCloud credentials (client ID and secret)
  const saveSoundcloudCredentials = async () => {
    if (!window.electron?.soundcloud?.setCredentials) {
      console.error('SoundCloud setCredentials not available');
      return;
    }

    const clientId = soundcloudClientIdInput.trim();
    const clientSecret = soundcloudClientSecretInput.trim();

    const result = await window.electron.soundcloud.setCredentials({
      clientId,
      clientSecret
    });

    if (result.success) {
      setSoundcloudCredentialsSource(result.source);
      if (soundcloudConnected && clientId && clientSecret) {
        showConfirmDialog({
          type: 'info',
          title: 'Credentials updated',
          message: 'Your SoundCloud credentials have been saved. Please disconnect and reconnect to use your new credentials.'
        });
      } else if (!clientId && !clientSecret) {
        showToast('SoundCloud credentials cleared', 'info');
      } else {
        showToast('SoundCloud credentials saved', 'success');
      }
    } else {
      showConfirmDialog({
        type: 'error',
        title: 'Error',
        message: result.error || 'Failed to save SoundCloud credentials'
      });
    }
  };

  // Back to the built-in SoundCloud credentials (the plug-in dialog's Clear).
  const clearSoundcloudCredentials = async () => {
    if (!window.electron?.soundcloud?.setCredentials) return;
    const result = await window.electron.soundcloud.setCredentials({ clientId: '', clientSecret: '' });
    if (result.success) {
      setSoundcloudClientIdInput('');
      setSoundcloudClientSecretInput('');
      setSoundcloudCredentialsSource(result.source);
      showToast('Custom credentials cleared. Using default credentials.', 'info');
    }
  };

  const connectSoundcloud = async () => {
    console.log('=== Connect SoundCloud Clicked ===');
    console.log('window.electron:', !!window.electron);
    console.log('window.electron.soundcloud:', !!window.electron?.soundcloud);

    if (window.electron?.soundcloud) {
      try {
        console.log('Calling SoundCloud authenticate...');
        const result = await window.electron.soundcloud.authenticate();
        console.log('SoundCloud authenticate result:', result);
        if (!result.success && result.error) {
          // If no credentials, guide user to Advanced section
          if (result.error.includes('API credentials')) {
            showToast('SoundCloud requires API credentials. Enter them below.', 'error');
            setSoundcloudAdvancedOpen(true);
          } else {
            showConfirmDialog({
              type: 'error',
              title: 'Authentication failed',
              message: result.error
            });
          }
        }
      } catch (error) {
        console.error('SoundCloud auth error:', error);
        showConfirmDialog({
          type: 'error',
          title: 'Authentication failed',
          message: 'SoundCloud authentication failed. Check console for details.'
        });
      }
    } else {
      console.error('window.electron.soundcloud not available!');
      showConfirmDialog({
        type: 'error',
        title: 'Something went wrong',
        message: 'Parachord didn’t start correctly. Restart it and try again.'
      });
    }
  };

  const disconnectSoundcloud = async () => {
    if (window.electron?.soundcloud) {
      await window.electron.soundcloud.disconnect();
      setSoundcloudToken(null);
      setSoundcloudConnected(false);
      // Its sources leave every track, and it leaves both active lists.
      deactivateResolver('soundcloud');
    }
  };

  // Apple Music / MusicKit functions (Native bridge for macOS)
  const [appleMusicNativeAvailable, setAppleMusicNativeAvailable] = useState(false);

  // Check if native MusicKit is available on startup
  useEffect(() => {
    const checkMusicKitAvailable = async () => {
      // Whether this check ended with Apple Music usable (MusicKit JS or native).
      let connected = false;
      const markConnected = () => {
        connected = true;
        setAppleMusicConnected(true);
        // Re-enable if it was in the user's saved active resolvers (restores priority position)
        reEnableResolver('applemusic');
      };
      try {
      // Check for MusicKit JS first (cross-platform)
      const musicKitWeb = window.getMusicKitWeb ? window.getMusicKitWeb() : null;

      // Load the developer token (the main process picks it)
      const developerToken = await getMusicKitDeveloperToken();

      // Ask Apple whether a stored user token still works before trusting it
      // (2026-11). A token Apple refuses used to be restored by MusicKit JS
      // over every fresh sign-in, and the app showed "connected" while every
      // /v1/me call got a 403. checkAppleMusicUserToken adopts any stored token
      // that works (the harvested sign-in cookie, for one) as the app's copy.
      let tokenCheck = { verdict: 'none', token: null, status: null };
      if (developerToken && AppleMusicUserToken.userTokenCandidates(localStorage).length > 0) {
        tokenCheck = await checkAppleMusicUserToken(developerToken);
      }
      if (tokenCheck.verdict === 'rejected') {
        // Every stored token is dead: drop them all, so MusicKit JS starts
        // signed out and nothing counts the account as connected on them.
        AppleMusicUserToken.clearMusicKitTokenSlots(localStorage);
        localStorage.removeItem('musickit_user_token');
        if (window.electron?.store) {
          await window.electron.store.delete('applemusic_user_token').catch(() => {});
        }
      }
      const userToken = localStorage.getItem('musickit_user_token') || '';
      // The app's copy is the one of record: put it in MusicKit JS's own slot
      // too, or configure restores whatever MusicKit stored last.
      if (userToken) AppleMusicUserToken.syncMusicKitTokenSlots(localStorage, userToken);

      if (musicKitWeb && developerToken) {
        try {
          console.log(`🍎 Initializing MusicKit JS (have stored userToken: ${!!userToken})`);
          // parachord#834 — pass userToken so configure() can try to inject
          // it post-MusicKit.configure(). This is the path the Cider-style
          // auth window flow uses: cookies + token were harvested in the
          // auth window, written to localStorage, app reloaded, and now we
          // want MusicKit to start already-authorized rather than pop the
          // (broken-on-Linux) sign-in window.
          await musicKitWeb.configure(developerToken, 'Parachord', '1.0.0', userToken);

          const status = musicKitWeb.getAuthStatus();
          console.log('🍎 MusicKit JS status post-configure:', status);

          // If MusicKit JS is already authorized (from previous session), mark as connected
          if (status.authorized) {
            console.log('🍎 MusicKit JS already authorized');

            // Ensure user token is persisted to electron-store for sync. The
            // app's copy first: MusicKit's own is only a fallback for an
            // install that never had one.
            const currentToken = userToken || musicKitWeb.getUserToken();
            if (currentToken && window.electron?.store) {
              await window.electron.store.set('applemusic_user_token', currentToken);
              localStorage.setItem('musickit_user_token', currentToken);
              console.log('🍎 Ensured user token is persisted to store on startup');
            } else if (!currentToken) {
              console.log('🍎 MusicKit JS reports authorized but no user token available — skipping auto-connect');
              // Clear stale auth flag since we can't actually use the connection
              if (window.electron?.store) {
                await window.electron.store.set('applemusic_authorized', false);
              }
              return;
            }

            markConnected();
          } else if (userToken) {
            // parachord#834 — MusicKit JS configure() didn't auto-authorize
            // even though we passed a userToken. This is the path moop250
            // hit on Arch: the CDN musickit.js bundle apparently doesn't
            // accept the userToken injection paths we tried (musicUserToken
            // property, setMusicUserToken, setUserToken). The token IS
            // valid though — main-process sync code uses it directly via
            // Music-User-Token header, and Apple recognizes it.
            //
            // Check the stored applemusic_authorized flag from the recv-
            // cookies handler. If we had a successful auth window flow
            // recently, trust the stored state and treat the user as
            // connected for UI purposes. Sync + main-side playback paths
            // will work because they use the token directly; only the
            // MusicKit JS in-process playback would be affected, and even
            // that may succeed since the cookies are in the shared session.
            const storedAuthFlag = window.electron?.store
              ? await window.electron.store.get('applemusic_authorized')
              : false;
            if (storedAuthFlag === true) {
              console.log('🍎 MusicKit JS reports unauthorized but stored auth flag + userToken present → treating as connected (parachord#834)');
              markConnected();
              // Also persist the userToken to electron-store if not already
              // there, so sync has it.
              if (window.electron?.store) {
                const existing = await window.electron.store.get('applemusic_user_token');
                if (!existing) {
                  await window.electron.store.set('applemusic_user_token', userToken);
                  console.log('🍎 Backfilled applemusic_user_token in electron-store');
                }
              }
            } else {
              console.log('🍎 Stored user token available but no auth flag — skipping auto-connect');
            }
          }
        } catch (error) {
          console.log('🍎 MusicKit JS init failed:', error.message);
        }
      }

      // Also check native MusicKit availability (macOS)
      if (window.electron?.musicKit) {
        const available = await window.electron.musicKit.isAvailable();
        setAppleMusicNativeAvailable(available);
        console.log('🍎 Native MusicKit available:', available);

        // Only auto-reconnect native MusicKit if the user has previously connected
        // in this app. macOS system auth persists in the keychain even after
        // uninstall (and may exist from the system Music app), so we require an
        // explicit opt-in flag rather than trusting keychain state alone.
        if (available) {
          const savedAuthFlag = window.electron?.store
            ? await window.electron.store.get('applemusic_authorized')
            : null;
          if (savedAuthFlag === true) {
            const authStatus = await window.electron.musicKit.checkAuth();
            if (authStatus.success && authStatus.authorized) {
              console.log('🍎 Native MusicKit already authorized - auto-reconnecting');

              // Native MusicKit doesn't need a user token for search/playback —
              // it uses the system Apple Music subscription directly. Always
              // reconnect if native auth is valid. Fetch a user token in the
              // background for sync features, but don't gate connection on it.
              markConnected();

              // Best-effort: fetch and persist a user token for sync features.
              // After Apple refused every stored token, bypass the native
              // cache (it may hold the same dead token) and keep the new one
              // only if Apple accepts it.
              const hasToken = !!(await window.electron?.store?.get('applemusic_user_token'));
              if (!hasToken && window.electron.musicKit.fetchUserToken) {
                try {
                  const tokenResult = await window.electron.musicKit.fetchUserToken({ ignoreCache: tokenCheck.verdict === 'rejected' });
                  if (tokenResult.success && tokenResult.userToken) {
                    const nativeCheck = developerToken
                      ? await checkAppleMusicUserToken(developerToken, [tokenResult.userToken])
                      : { verdict: 'unknown' };
                    if (nativeCheck.verdict !== 'rejected') {
                      await window.electron.store.set('applemusic_user_token', tokenResult.userToken);
                      localStorage.setItem('musickit_user_token', tokenResult.userToken);
                      console.log('🍎 Fetched and stored user token from native MusicKit on startup');
                    } else {
                      console.warn('🍎 Native MusicKit returned a user token Apple refuses; sync needs a fresh sign-in');
                    }
                  }
                } catch (e) {
                  console.log('🍎 Failed to fetch user token from native MusicKit (sync features may be limited):', e.message);
                }
              }
            }
          } else {
            console.log('🍎 Native MusicKit available but no prior connection - skipping auto-reconnect');
          }
        }
      }

      // Apple refused the sign-in and nothing else connected: say so and
      // offer to sign in again, instead of showing Apple Music as connected.
      if (tokenCheck.verdict === 'rejected' && !connected) {
        if (window.electron?.store) {
          await window.electron.store.set('applemusic_authorized', false).catch(() => {});
        }
        showToast(
          'Apple Music signed you out. Reconnect to play and sync from Apple Music.',
          'warning',
          { label: 'Reconnect', onClick: () => { connectAppleMusic(); } },
          { persistent: true }
        );
      }
      } finally {
        setAppleMusicAuthChecked(true);
      }
    };
    // Run AM init eagerly. We previously deferred this to idle (#765) for a
    // ~3s startup win, but the deferral broke resolver-badge confidence: the
    // queue's restored tracks resolve before AM is in the active-resolvers
    // list, attaching fresh fuzzy-match (0.95) sources that overwrite the
    // cached direct-ID (1.0) sources. With Spotify at 1.0 and AM/SC/YT at
    // 0.95, the relative-to-best dim logic dims everything except Spotify.
    // The bigger startup cost is elsewhere (~11s renderer block from large
    // IPC payloads); keep AM init synchronous until that's addressed in a
    // way that doesn't regress badge state.
    checkMusicKitAvailable();
  }, []);

  const appleMusicConnectingRef = useRef(false);
  const connectAppleMusic = async () => {
    // Guard against multiple simultaneous connection attempts
    if (appleMusicConnectingRef.current) {
      console.log('[AppleMusic] Connection already in progress, ignoring click');
      return;
    }
    appleMusicConnectingRef.current = true;
    console.log('=== Connect Apple Music Clicked ===');

    try {

    // Determine available auth methods
    const musicKitWeb = window.getMusicKitWeb ? window.getMusicKitWeb() : null;
    const developerToken = await getMusicKitDeveloperToken();

    const hasNativeMusicKit = window.electron?.musicKit && await window.electron.musicKit.isAvailable().catch(() => false);
    const hasMusicKitWeb = !!(musicKitWeb && developerToken);

    // On macOS, prefer native MusicKit auth — the OS handles Touch ID, passkeys,
    // and all the system sheets natively. On other platforms (and as a fallback
    // when the native helper is unavailable), use the Cider-style auth window
    // (parachord#834): a dedicated BrowserWindow at beta.music.apple.com where
    // the user signs in on Apple's real origin so cookies set normally; main
    // harvests them and pushes to the renderer via the `recv-cookies` IPC
    // listener registered above. MusicKit's own popup flow is intentionally
    // NOT used here — Electron's third-party-cookie partitioning blocks the
    // popup → parent handshake even with the storage-partitioning flag
    // disabled, so MusicKit JS reports `isAuthorized: false` regardless.
    const tryNativeFirst = hasNativeMusicKit;

    // Cider-style auth-window flow. The window opens, the user signs in, main
    // harvests the apple.com auth cookies, the recv-cookies listener (in the
    // useEffect above) writes them to localStorage and reloads. The post-
    // reload startup pre-check picks up the now-authorized MusicKit JS state
    // and finishes wiring connected=true, activeResolvers, etc. This function
    // returns true to signal "auth flow kicked off, reload imminent" — there's
    // no further work for the caller to do here.
    const tryAuthWindowFlow = async () => {
      if (!window.electron?.musicKit?.openAuthWindow) return false;
      try {
        console.log('[AppleMusic] Opening auth window (Cider-style flow)...');
        const result = await window.electron.musicKit.openAuthWindow();
        console.log('[AppleMusic] Auth window returned:', result);
        if (result?.success) {
          // recv-cookies listener handles localStorage + reload. Toast for
          // the brief window between resolve-here and the reload tearing
          // down the renderer.
          showToast('Apple Music connected — finishing setup…', 'success');
          return true;
        }
        if (result?.cancelled) {
          // User closed the auth window without completing sign-in. Silent.
          return false;
        }
        showToast(result?.error || 'Apple Music sign-in failed', 'error');
        return false;
      } catch (error) {
        console.log('[AppleMusic] Auth window flow failed:', error.message);
        showToast(errorText(error, 'Couldn’t sign in to Apple Music. Try again.'), 'error');
        return false;
      }
    };

    if (!tryNativeFirst) {
      // Non-macOS, or no native helper available. Use the auth-window flow.
      if (await tryAuthWindowFlow()) return;
      // Fell through — the user cancelled or there was an error; the helper
      // already toasted. Don't error-dialog over that.
      return;
    }

    // Native MusicKit path (macOS) — or fallback after MusicKit JS failure
    if (!hasNativeMusicKit) {
      showConfirmDialog({
        type: 'error',
        title: 'Couldn’t connect to Apple Music',
        message: developerToken
          ? 'Apple Music didn’t accept your developer token. Check it in Settings › Plug-Ins › Apple Music.'
          : 'Apple Music needs either a developer token (Settings › Plug-Ins › Apple Music) or macOS native integration.'
      });
      return;
    }

    try {
      // Start the MusicKit helper if needed
      console.log('Starting MusicKit helper...');
      const startResult = await window.electron.musicKit.start();
      if (!startResult.success) {
        throw new Error('Failed to start MusicKit helper');
      }

      // Request authorization (will show system dialog for Apple ID sign-in)
      console.log('Requesting MusicKit authorization...');
      const authResult = await window.electron.musicKit.authorize();

      if (!authResult.success) {
        throw new Error(authResult.error || 'Authorization failed');
      }

      if (authResult.authorized) {
        console.log('🍎 MusicKit authorized successfully');

        // Fetch and store user token for sync (native MusicKit doesn't
        // return it from authorize(), so we need a separate fetch)
        // The account token (library, sync, recommendations) must be one
        // Apple's REST API accepts. Measured 2026-11-12: tokens the native
        // helper mints, cached or fresh, were refused with 403 code 40300
        // ("Invalid authentication") while the web sign-in's token worked
        // with the same developer token; the helper carries no MusicKit
        // provisioning profile. So: keep a stored token Apple accepts, else
        // try the native one, and store nothing Apple refuses.
        let accountTokenOk = false;
        if (developerToken) {
          const stored = await checkAppleMusicUserToken(developerToken);
          accountTokenOk = stored.verdict === 'ok';
        }
        if (!accountTokenOk && window.electron.musicKit.fetchUserToken) {
          const { probeUserToken } = AppleMusicUserToken.makeAppleProbes(window.fetch.bind(window), developerToken);
          for (const opts of [undefined, { ignoreCache: true }]) {
            try {
              const tokenResult = await window.electron.musicKit.fetchUserToken(opts);
              if (!tokenResult.success || !tokenResult.userToken) {
                console.warn('🍎 Native MusicKit authorized but could not fetch user token:', tokenResult.error);
                break;
              }
              const status = developerToken ? await probeUserToken(tokenResult.userToken) : null;
              if (AppleMusicUserToken.classifyStatus(status) === 'rejected') {
                console.warn(`🍎 Apple refuses the native MusicKit user token${opts ? ' (fresh)' : ''} (HTTP ${status})`);
                continue;
              }
              localStorage.setItem('musickit_user_token', tokenResult.userToken);
              if (window.electron?.store) {
                await window.electron.store.set('applemusic_user_token', tokenResult.userToken);
              }
              accountTokenOk = true;
              console.log('🍎 Native MusicKit user token stored');
              break;
            } catch (e) {
              console.warn('🍎 Failed to fetch user token after native auth:', e.message);
              break;
            }
          }
        }

        if (!accountTokenOk) {
          // Playback works natively; the library, sync and recommendations
          // need the web sign-in's token.
          showConfirmDialog({
            type: 'info',
            title: 'Apple Music',
            message: developerToken
              ? 'Apple Music playback is connected.\n\nYour library, playlist sync and recommendations need one more sign-in, on Apple\'s site. Sign in now?'
              : 'Apple Music authorized but could not obtain a sync token. Library sync will not be available.\n\nThis usually means the MusicKit developer token is missing from this build.',
            ...(developerToken && window.electron?.musicKit?.openAuthWindow
              ? { confirmLabel: 'Sign in', onConfirm: () => { tryAuthWindowFlow(); } }
              : {})
          });
        }

        setAppleMusicConnected(true);

        // Save auth state
        if (window.electron?.store) {
          await window.electron.store.set('applemusic_authorized', true);
        }

        // Automatically enable Apple Music resolver after successful auth
        setActiveResolvers(prev => {
          if (!prev.includes('applemusic')) {
            return [...prev, 'applemusic'];
          }
          return prev;
        });
        setResolverOrder(prev => {
          if (!prev.includes('applemusic')) {
            return insertRemembered(prev, 'applemusic', savedResolverOrderRef.current);
          }
          return prev;
        });

        showToast('Apple Music connected successfully', 'success');

        // If library sync was previously enabled for Apple Music, trigger an
        // immediate sync now that we have a valid token (same rationale as Spotify).
        if (window.electron?.sync?.start) {
          window.electron.syncSettings?.load().then(syncSettings => {
            if (syncSettings?.applemusic?.enabled) {
              console.log('[Sync] Apple Music re-authenticated with sync enabled, triggering immediate sync');
              // Re-auth catch-up — user just reconnected, treat as full sync
              // so they don't have to wait 4-5 background cycles (parachord#800).
              window.electron.sync.start('applemusic', { settings: syncSettings.applemusic, fullSync: true }).then(result => {
                if (result?.success && result.collection) {
                  const incoming = {
                    tracks: result.collection.tracks || [],
                    albums: result.collection.albums || [],
                    artists: result.collection.artists || []
                  };
                  setCollectionData(prev => {
                    const netLoss = (prev.tracks?.length || 0) - incoming.tracks.length;
                    const lossRatio = prev.tracks?.length > 0 ? netLoss / prev.tracks.length : 0;
                    if (netLoss > 50 && lossRatio > 0.1) {
                      console.warn(`[Sync] Skipping UI update after re-auth: likely incomplete API response`);
                      return prev;
                    }
                    return incoming;
                  });
                }
              }).catch(err => console.error('[Sync] Post-auth Apple Music sync failed:', err));
            }
          }).catch(() => {});
        }

      } else if (authResult.needsSystemSettings) {
        // Previously denied — user must toggle permission in System Settings
        showConfirmDialog({
          type: 'info',
          title: 'Apple Music access denied',
          message: 'Apple Music access was previously denied. Please enable it in System Settings → Privacy & Security → Media & Apple Music, then try again.',
          confirmLabel: 'Open System Settings',
          onConfirm: () => {
            if (window.electron?.shell?.openExternal) {
              window.electron.shell.openExternal('x-apple.systempreferences:com.apple.preference.security?Privacy_MediaAppleMusic');
            }
          }
        });
      } else {
        // User denied or other status
        showConfirmDialog({
          type: 'info',
          title: 'Authorization required',
          message: 'Apple Music access was not granted. Status: ' + authResult.status
        });
      }
    } catch (error) {
      console.error('Apple Music auth error:', error);
      let message = error.message || 'Apple Music authentication failed. Please try again.';

      // The crash is typically a transient AppKit assertion during the
      // activation-policy switch.  The retries in the bridge handle most
      // cases, but if they all failed the user can bypass the system dialog
      // entirely by toggling the permission on manually in Settings.
      if (message.includes('MusicKit helper exited') || message.includes('authorization failed after multiple')) {
        message = 'Apple Music authorization could not complete automatically. ' +
          'You can enable it manually: open System Settings \u2192 Privacy & Security \u2192 ' +
          'Media & Apple Music, toggle Parachord on, then click Connect again.';
      }

      showConfirmDialog({
        type: 'error',
        title: 'Authentication failed',
        message,
        confirmLabel: 'Open System Settings',
        onConfirm: () => {
          if (window.electron?.shell?.openExternal) {
            window.electron.shell.openExternal('x-apple.systempreferences:com.apple.preference.security?Privacy_MediaAppleMusic');
          }
        }
      });
    }

    } finally {
      appleMusicConnectingRef.current = false;
    }
  };

  const disconnectAppleMusic = async () => {
    setAppleMusicConnected(false);

    // Clear MusicKit JS user token
    localStorage.removeItem('musickit_user_token');

    // Sign out of MusicKit JS
    const musicKitWeb = window.getMusicKitWeb ? window.getMusicKitWeb() : null;
    if (musicKitWeb) {
      try {
        await musicKitWeb.unauthorize();
      } catch (e) {
        console.log('[AppleMusic] MusicKit JS sign out error:', e);
      }
    }

    // Clear native MusicKit auth (macOS)
    if (window.electron?.musicKit) {
      try {
        await window.electron.musicKit.unauthorize();
      } catch (e) {
        console.log('[AppleMusic] Native MusicKit sign out error:', e);
      }
    }

    // Clear user auth from persistent storage. Set authorized to false (not delete) so
    // startup can distinguish "user disconnected" from "never connected" and won't
    // auto-reconnect based on macOS system keychain auth that persists across installs.
    // Keep developer token intact — it's the app credential users authenticate against.
    if (window.electron?.store) {
      await window.electron.store.set('applemusic_authorized', false);
      await window.electron.store.delete('applemusic_user_token');
    }

    // Its sources leave every track, and it leaves both active lists.
    deactivateResolver('applemusic');

    showToast('Apple Music disconnected', 'info');
  };

  const saveAppleMusicDeveloperToken = async () => {
    console.log('=== Save Apple Music Developer Token ===');
    const token = appleMusicDeveloperToken.trim();
    console.log('Token length:', token.length);

    // Save to localStorage for MusicKit JS
    localStorage.setItem('musickit_developer_token', token);
    console.log('Token saved to localStorage');

    // Also save to electron store for persistence
    if (window.electron?.store) {
      try {
        await window.electron.store.set('applemusic_developer_token', token);
        console.log('Token saved to electron store');
      } catch (error) {
        console.error('Failed to save token to electron store:', error);
      }
    }

    setAppleMusicTokenSaved(true);
    // Reset the saved state after 3 seconds
    setTimeout(() => setAppleMusicTokenSaved(false), 3000);

    // Try to configure MusicKit JS immediately with the new token
    const musicKitWeb = window.getMusicKitWeb ? window.getMusicKitWeb() : null;
    if (musicKitWeb && token) {
      try {
        console.log('🍎 Configuring MusicKit JS with new token...');
        await musicKitWeb.configure(token, 'Parachord', '1.0.0');
        console.log('🍎 MusicKit JS configured');
        showToast('MusicKit token saved. Click "Connect" to sign in with Apple ID.', 'success');
      } catch (error) {
        console.error('🍎 Failed to configure MusicKit JS:', error);
        showToast('Token saved, but Apple Music couldn’t start. Restart Parachord and try again.', 'warning');
      }
    } else {
      showToast('Token saved', 'success');
    }
  };

  // Meta Service config helpers
  const saveMetaServiceConfig = async (serviceId, config) => {
    const newConfigs = { ...metaServiceConfigs, [serviceId]: config };
    setMetaServiceConfigs(newConfigs);
    if (window.electron?.store) {
      await window.electron.store.set('meta_service_configs', newConfigs);
      console.log(`💾 Saved ${serviceId} config`);
    }
  };

  const clearMetaServiceConfig = async (serviceId) => {
    const newConfigs = { ...metaServiceConfigs };
    delete newConfigs[serviceId];
    setMetaServiceConfigs(newConfigs);
    if (window.electron?.store) {
      await window.electron.store.set('meta_service_configs', newConfigs);
      console.log(`🗑️ Cleared ${serviceId} config`);
    }
  };

  // Fetch models dynamically for plugins with dynamic-select model setting
  const fetchDynamicModels = async (resolver, config) => {
    const modelSetting = resolver.settings?.configurable?.model || resolver.configurable?.model;
    if (modelSetting?.type !== 'dynamic-select') return;

    // Look up the full resolver from the loader (has implementation functions like listModels)
    // metaServices state only stores metadata, not implementation functions
    const fullResolver = resolverLoaderRef.current?.getResolver(resolver.id) || resolver;
    if (!fullResolver.listModels) return;

    const resolverId = resolver.id;
    setDynamicModelOptions(prev => ({
      ...prev,
      [resolverId]: { loading: true, options: [], error: null }
    }));

    try {
      const options = await fullResolver.listModels(config || metaServiceConfigs[resolverId] || {});
      setDynamicModelOptions(prev => ({
        ...prev,
        [resolverId]: { loading: false, options: options || [], error: null }
      }));
    } catch (error) {
      console.error(`Failed to fetch models for ${resolverId}:`, error);
      setDynamicModelOptions(prev => ({
        ...prev,
        [resolverId]: { loading: false, options: [], error: error.message }
      }));
    }
  };

  // Last.fm specific helpers
  const connectLastfm = async (username, apiKey, apiSecret) => {
    if (!username?.trim()) {
      showConfirmDialog({
        type: 'error',
        title: 'Username required',
        message: 'Please enter your Last.fm username.'
      });
      return false;
    }

    // Validate username exists by checking the recommendations endpoint
    try {
      const response = await fetch(`https://www.last.fm/player/station/user/${encodeURIComponent(username.trim())}/recommended`);
      if (!response.ok) {
        showConfirmDialog({
          type: 'error',
          title: 'Invalid username',
          message: `Could not find Last.fm user "${username}". Please check the username and try again.`
        });
        return false;
      }
    } catch (error) {
      console.error('Last.fm validation error:', error);
      showConfirmDialog({
        type: 'error',
        title: 'Connection error',
        message: 'Could not connect to Last.fm. Please check your internet connection.'
      });
      return false;
    }

    await saveMetaServiceConfig('lastfm', {
      username: username.trim(),
      apiKey: apiKey?.trim() || null,
      apiSecret: apiSecret?.trim() || null
    });
    // Keys saved again are tried again at once, even one Last.fm turned down
    // earlier this session (lib/lastfm-key.js).
    window.lastfmKeys?.clearRefusal();

    // The scrobbler picks the saved key and secret up from window.lastfmKeys
    // (lib/lastfm-key.js). Scrobbling also needs its own sign-in
    // (ScrobblerSettingsCard).

    console.log(`🎧 Connected to Last.fm as ${username}`);
    return true;
  };

  // Remove (the username row): forget the username only. It used to
  // delete the plug-in's whole settings record, which also switched
  // "Enable" off and wiped the Advanced API keys (2026-11-17). Enable stays
  // as it was (a username counted as on), and the scrobbling session is the
  // Scrobbling section's own.
  const disconnectLastfm = async () => {
    const { username: _username, ...rest } = metaServiceConfigs.lastfm || {};
    await saveMetaServiceConfig('lastfm', { ...rest, enabled: rest.enabled !== false });
    console.log('🎧 Disconnected from Last.fm');
  };

  // Your own Last.fm API key and secret, once a username is saved (the
  // plug-in dialog's Advanced section): saved as typed, so saving empty
  // fields clears them.
  const saveLastfmApiKeys = async ({ apiKey: keyInput, apiSecret: secretInput } = {}) => {
    const apiKey = keyInput?.trim() || null;
    const apiSecret = secretInput?.trim() || null;
    await saveMetaServiceConfig('lastfm', { ...metaServiceConfigs.lastfm, apiKey, apiSecret });
    // Saving the keys again (say after buying Last.fm Pro) tries them again
    // at once, without a relaunch (lib/lastfm-key.js).
    window.lastfmKeys?.clearRefusal();
    showToast(apiKey ? 'API credentials saved' : 'API credentials cleared', 'success');
  };
  const clearLastfmApiKeys = async () => {
    await saveMetaServiceConfig('lastfm', { ...metaServiceConfigs.lastfm, apiKey: null, apiSecret: null });
    window.lastfmKeys?.clearRefusal();
    showToast('Custom credentials cleared. Using default credentials.', 'info');
  };

  // ListenBrainz specific helpers
  const connectListenbrainz = async (username, userToken) => {
    if (!username?.trim()) {
      showConfirmDialog({
        type: 'error',
        title: 'Username required',
        message: 'Please enter your ListenBrainz username.'
      });
      return false;
    }

    // Validate username exists by checking the user endpoint
    try {
      const response = await fetch(`https://api.listenbrainz.org/1/user/${encodeURIComponent(username.trim())}/listen-count`);
      if (!response.ok) {
        showConfirmDialog({
          type: 'error',
          title: 'Invalid username',
          message: `Could not find ListenBrainz user "${username}". Please check the username and try again.`
        });
        return false;
      }
    } catch (error) {
      console.error('ListenBrainz validation error:', error);
      showConfirmDialog({
        type: 'error',
        title: 'Connection error',
        message: 'Could not connect to ListenBrainz. Please check your internet connection.'
      });
      return false;
    }

    // If token provided, validate it
    if (userToken?.trim()) {
      try {
        const tokenResponse = await fetch('https://api.listenbrainz.org/1/validate-token', {
          headers: {
            'Authorization': `Token ${userToken.trim()}`
          }
        });
        const tokenData = await tokenResponse.json();
        if (!tokenData.valid) {
            showConfirmDialog({
            type: 'error',
            title: 'Invalid token',
            message: 'The user token is invalid. Please check and try again, or leave it blank to connect without a token.'
          });
          return false;
        }
      } catch (error) {
        console.error('ListenBrainz token validation error:', error);
        // Non-fatal - continue without token
      }
    }

    await saveMetaServiceConfig('listenbrainz', {
      username: username.trim(),
      userToken: userToken?.trim() || null
    });

    // Also connect the scrobbler if token is provided
    if (userToken?.trim() && window.listenbrainzScrobbler) {
      try {
        await window.listenbrainzScrobbler.connect(userToken.trim());
        // Update scrobbler configs state
        const newConfig = await window.listenbrainzScrobbler.getConfig();
        setScrobblerConfigs(prev => ({ ...prev, listenbrainz: newConfig }));
        console.log('🎵 ListenBrainz scrobbler connected');
      } catch (err) {
        console.error('Failed to connect ListenBrainz scrobbler:', err);
        // Non-fatal - meta service still works for recommendations
      }
    }

    console.log(`🎵 Connected to ListenBrainz as ${username}`);
    return true;
  };

  // Remove (the username row): forget the username only. It used to
  // delete the plug-in's whole settings record, which also switched
  // "Enable" off and wiped the Advanced API keys (2026-11-17). Enable stays
  // as it was (a username counted as on), and the scrobbling session is the
  // Scrobbling section's own.
  const disconnectListenbrainz = async () => {
    const { username: _username, ...rest } = metaServiceConfigs.listenbrainz || {};
    await saveMetaServiceConfig('listenbrainz', { ...rest, enabled: rest.enabled !== false });
    console.log('🎵 Disconnected from ListenBrainz');
  };

// Listen for Spotify auth events
useEffect(() => {
  checkSpotifyToken();

  // Load Spotify credentials info
  if (window.electron?.spotify?.getCredentials) {
    window.electron.spotify.getCredentials().then((creds) => {
      if (creds) {
        setSpotifyClientIdInput(creds.clientId || '');
        setSpotifyCredentialsSource(creds.source || 'fallback');
        console.log('🔑 Spotify credentials source:', creds.source);
      }
    });
  }

  let cleanupAuthSuccess, cleanupAuthError;
  if (window.electron?.spotify) {
    cleanupAuthSuccess = window.electron.spotify.onAuthSuccess((data) => {
      console.log('Spotify auth success!', {
        hasToken: !!data.token,
        tokenLength: data.token?.length,
        tokenPreview: data.token ? data.token.substring(0, 20) + '…' : 'null'
      });
      setSpotifyToken(data.token);
      setSpotifyConnected(true);
      spotifyAuthSucceededAtRef.current = Date.now();
      // Automatically enable Spotify resolver after successful auth
      setActiveResolvers(prev => {
        if (!prev.includes('spotify')) {
          return [...prev, 'spotify'];
        }
        return prev;
      });
      console.log('Spotify connected and enabled!');

      // If sync setup was pending (user clicked "Set Up Library Sync" which triggered auth),
      // automatically continue by opening the sync setup modal now that auth is complete
      if (pendingSyncSetupRef.current === 'spotify') {
        pendingSyncSetupRef.current = null;
        // Short delay to let React process the state updates above before opening the modal
        setTimeout(() => {
          if (openSyncSetupModalRef.current) {
            openSyncSetupModalRef.current('spotify');
          }
        }, 300);
      }

      // If library sync was previously enabled for Spotify, trigger an immediate
      // sync now that we have a valid token. This handles the case where the user
      // switches API keys or re-authenticates — the background sync timer won't
      // fire until the next 15-minute interval, leaving the collection stale/empty.
      if (window.electron?.sync?.start) {
        window.electron.syncSettings?.load().then(syncSettings => {
          if (syncSettings?.spotify?.enabled) {
            console.log('[Sync] Spotify re-authenticated with sync enabled, triggering immediate sync');
            // Re-auth catch-up — user just reconnected, treat as full sync
            // (parachord#800).
            window.electron.sync.start('spotify', { settings: syncSettings.spotify, fullSync: true }).then(result => {
              if (result?.success && result.collection) {
                const incoming = {
                  tracks: result.collection.tracks || [],
                  albums: result.collection.albums || [],
                  artists: result.collection.artists || []
                };
                setCollectionData(prev => {
                  const netLoss = (prev.tracks?.length || 0) - incoming.tracks.length;
                  const lossRatio = prev.tracks?.length > 0 ? netLoss / prev.tracks.length : 0;
                  if (netLoss > 50 && lossRatio > 0.1) {
                    console.warn(`[Sync] Skipping UI update after re-auth: likely incomplete API response`);
                    return prev;
                  }
                  return incoming;
                });
              }
            }).catch(err => console.error('[Sync] Post-auth sync failed:', err));
          }
        }).catch(() => {});
      }
    });
    cleanupAuthError = window.electron.spotify.onAuthError((error) => {
      console.error('Spotify auth failed:', error);
      pendingSyncSetupRef.current = null; // Clear pending sync setup on auth failure
      showConfirmDialog({
        type: 'error',
        title: 'Spotify authentication failed',
        message: error
      });
    });
  }

  // Periodically check and refresh token every 5 minutes
  const tokenRefreshInterval = setInterval(() => {
    console.log('⏰ Periodic token refresh check...');
    checkSpotifyToken();
  }, 5 * 60 * 1000); // 5 minutes

  return () => {
    clearInterval(tokenRefreshInterval);
    cleanupAuthSuccess?.();
    cleanupAuthError?.();
  };
}, []);

